import{O as e,U as t,W as n}from"./CYYkGqRJ.js";var r=[`en`,`tl`,`pa`,`fr`,`es`,`ar`,`zh-Hant`,`zh-Hans`,`de`,`uk`],i={en:{native:`English`,english:`English`,htmlLang:`en`,dir:`ltr`},tl:{native:`Tagalog`,english:`Tagalog`,htmlLang:`tl`,dir:`ltr`},pa:{native:`ਪੰਜਾਬੀ`,english:`Punjabi`,htmlLang:`pa`,dir:`ltr`},fr:{native:`Français`,english:`French (Canadian)`,htmlLang:`fr-CA`,dir:`ltr`},es:{native:`Español`,english:`Spanish`,htmlLang:`es`,dir:`ltr`},ar:{native:`العربية`,english:`Arabic`,htmlLang:`ar`,dir:`rtl`},"zh-Hant":{native:`繁體中文`,english:`Chinese (Traditional)`,htmlLang:`zh-Hant`,dir:`ltr`},"zh-Hans":{native:`简体中文`,english:`Chinese (Simplified)`,htmlLang:`zh-Hans`,dir:`ltr`},de:{native:`Deutsch`,english:`German`,htmlLang:`de`,dir:`ltr`},uk:{native:`Українська`,english:`Ukrainian`,htmlLang:`uk`,dir:`ltr`}},a=`audit_lang`,o=`lang`;function s(e){return!!e&&r.includes(e)}function c(e){let t=e.toLowerCase();if(t.startsWith(`zh`))return t.includes(`hant`)||t.startsWith(`zh-hk`)||t.startsWith(`zh-tw`)||t.startsWith(`zh-mo`)?`zh-Hant`:`zh-Hans`;let n=t.split(`-`)[0];return s(n)?n:null}function l(){let e=new URL(window.location.href).searchParams.get(o);if(s(e))return e;try{let e=localStorage.getItem(a);if(s(e))return e}catch{}let t=navigator.languages??[navigator.language];for(let e of t){let t=c(e);if(t)return t}return`en`}var u=n(`en`);{let e=l();t(u,e,!0);let n=new URL(window.location.href);n.searchParams.get(o)!==e&&(n.searchParams.set(o,e),window.history.replaceState({},``,n.toString()))}function d(e){if(!s(e))return;t(u,e,!0);try{localStorage.setItem(a,e)}catch{}let n=new URL(window.location.href);n.searchParams.set(o,e),window.history.replaceState({},``,n.toString())}var f={get current(){return e(u)}},p={selector:{label:`Choose language`},disclaimer:{text:`This site has been translated by AI. Some content may still appear in English while translations are in progress. If you notice errors or would like to help translate this project, please %s.`,link_label:`contact us`,word_count:`For scale: the English prose runs about {count} words.`},opener:{heading:`Who's this for?`,body:`Us. All of us. Rural, Urban, curious, wonk, journalist, lawyer, academic, politician — all of us. Because it impacts all of us. Whether or not you like the party in power, what the split commission produced has never been done before. And it's given us the opportunity to peer inside the machine in ways we never could before. Now we can establish a baseline — a series of tests, and everything that comes after can be graded on it. Let me show you what I found.`},stakes:{q1:{heading:`Is the proposed map a gerrymander?`,body:`"Gerrymander" is not a term Canadian courts use. But if it were — in the everyday sense most people mean by it — the evidence in this audit would reasonably support calling the <em>minority proposal</em>, if enacted, a heavily gerrymandered map. Four of the five structural tests this audit runs flag the <em>minority proposal</em> and none flag the alternative (the <em>majority proposal</em>); the fifth test is neutral for both.`,footnote:`The "majority" and "minority" names come from a 3–2 split among the Electoral Boundaries Commission (chaired by Justice Miller), which produced two competing proposals rather than a single recommendation. The legislature has since set both aside and referred redistricting to a five-MLA committee chaired by Brandon Lunty (a Premier-appointed MLA); the committee oversees a separate four-person Independent Advisory Panel — two members nominated by the Premier (Hon. Monte Solberg and Darwin Durnie), two by the Leader of the Opposition (Dr. Gerard Kennedy and Brent Robinson) — tasked with producing a new 91-seat boundary proposal before the November 2026 deadline.`},q2:{heading:`What does "gerrymander" mean in Canadian law?`,body:`There isn't one. The Canadian test is different: whether the boundaries give voters <em>effective representation</em> under section 3 of the Charter. The minority proposal raises serious questions under the effective-representation standard; only a judge can answer them definitively, and no one has asked one yet.`},q3:{heading:`What's at stake for Albertans?`,body:`At a 50/50 provincial vote, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. That imbalance matters because at 58 of 87 seats (a two-thirds supermajority) the governing party unlocks extraordinary procedural powers. It can waive standard notice periods and push public bills through multiple legislative stages in a single day, bypassing the deliberation checks the legislature normally relies on. Whether the minority proposal's tilt is large enough to push one party past that 58-seat threshold at vote shares <em>other</em> than 50/50 is a question this audit has not yet tested. Whether that imbalance is acceptable is a question for Albertans, not for this audit.`},cta_law:`Read the legal context →`,cta_methods:`See how we tested →`,scorecard_h:`The scorecard`,scorecard_fig_alt:`Scatter plot: efficiency gap on the horizontal axis, count of structural tests failed on the vertical axis. The 2019 enacted map and the 2026 majority map cluster in the safe lower-left corner. The 2026 minority map appears alone in the upper-right outlier region.`,scorecard_fig_caption:`Both lanes on one picture. Horizontal: how skewed the partisan-fairness number is (right = more UCP-favoured). Vertical: how many of five structural-fairness tests the map fails. Bottom-left is the safe corner where neutral procedures routinely land; the upper-right is the outlier region. The 2019 enacted map and the 2026 majority sit in the safe corner. The 2026 minority sits alone in the outlier region.`,scorecard_intro:`Two independent measurements applied to both maps under the same pre-registered thresholds. Structure uses only the shape of the lines — no election results. Numbers tests how the lines convert votes into seats. Both lanes reach the same conclusion.`,scorecard_close:`Two independent measurements, one answer. The convergence is the audit's strongest single signal.`},head:{title:`Alberta Electoral Boundary Audit`,meta_description:`Statistical audit of Alberta's 2026 electoral boundary commission — 1,010,000 neutral maps, official Elections Alberta shapefiles, pre-registered tests.`},nav:{skip_to_content:`Skip to content`,home_aria:`Back to top`,theme_aria:`Toggle dark/light mode`,theme_title:`Toggle dark mode`,nav_aria:`Open table of contents`,drawer_top:`↑ Top`,stakes:`Stakes`,findings:`Findings`,history:`History`,reform:`Reform`,notes:`Notes`,group_overview:`Overview`,group_audit:`The audit`,group_context:`Context`,group_forward:`Going forward`,group_apparatus:`Apparatus`,why:`Why does this matter?`,map:`The map at a glance`,split:`How the commission broke`,litmus:`1,010,000-Map Litmus Test`,crack_pack:`Cracking, packing, draining`,for_you:`What this means for you`,impact:`Impact on the ground`,gerrymanders:`Clean gerrymanders`,history_full:`A history of gerrymandering`,canada:`Canada's different`,november:`November`,lunty:`Lunty`,invisible:`Invisible`,suggestions:`Reform suggestions`,retractions:`Retractions`,references:`References`,resources:`Resources`,technical:`Technical resources`},hero:{h1:`Alberta Electoral Boundary Audit`,subtitle:`Alberta's commission produced two riding maps in 2026. This audit compared them — using the same tests, applied equally to both — to ask whether they treat voters the same way.`,badge:`Official Elections Alberta maps — Published May 2026`,cover_note:`Click to zoom and explore all three boundary proposals simultaneously. Pin the viewport and flip between maps — boundaries shift, voters stay put. Scroll down for the analysis.`,cover_note_1:`This map is the best way in. Click it to zoom and explore. The buttons at the top switch between the minority map, the majority map, and the 2019 enacted boundaries — or layer all three to see exactly where they diverge. <strong>Detail</strong> colours each polling area by how people voted in 2023; <strong>Trend</strong> adds partisan shading by district (blue UCP, orange NDP); <strong>Lines</strong> toggles boundaries on and off. <strong>Find</strong> jumps to any riding by name.`,cover_note_2:`Try locking the viewport and flipping between maps — watch a boundary shift while the voters underneath stay still. The whole question, in one gesture.`,cover_note_3:`When you're done exploring, scroll down for the summary. For the full technical analysis, see the Resources section. All data is official Elections Alberta shapefiles and other government and open-source records.`,image_alt:`Alberta electoral district maps — minority commission proposal, coloured by 2023 vote`,map_hint:`Click to explore interactively`,btn_title:`Click to open interactive map`,btn_aria:`Click to explore interactively`},boundary:{heading:`What this audit can and can't tell you`,can_1:`The minority map's geometry crosses 4 of 5 pre-registered structural thresholds <em>without using any election data at all</em>. The fifth (anchoring) is neutral. The majority crosses 0 of the 4 firing. These tests measure properties of the boundary lines themselves — district shape, municipal anchoring, population spread — and reach the conclusion before any vote is counted.`,can_2:`Separately, when election data is brought in, the minority map sits at the 99.99th percentile of 1.01 million algorithmically-drawn comparison maps held to the same statutory rules. Fewer than 100 of those 1.01 million neutral maps reach the same seat imbalance. The combined statistical signal is approximately 1 in 14.5 million under a neutral drawing process. Two independent instruments — geometric and statistical — reach the same conclusion.`,can_3:`Three of the configurations the minority proposal contains were flagged in writing by Commission Chair Justice Miller in §5.8.2 of the majority report and Appendix C. The audit's tests were run with no knowledge of his flags and surface the same regions. A third independent instrument — judicial — converges on the same boundaries.`,cant_1:`The audit does <strong>not</strong> establish that any commissioner intended the partisan effects it measures. Boundary geometry cannot reveal intent.`,cant_2:`The audit does <strong>not</strong> predict what the Lunty committee will choose, what the November 2026 vote will be, or how Albertans will react.`,cant_3:`The audit does <strong>not</strong> predict how a court would rule if a Charter challenge were brought against either proposal.`,cant_4:`The audit does <strong>not</strong> claim the 1-in-14.5-million figure is the probability that a gerrymander occurred. That number is the tail probability of the minority's geometry under a neutral algorithmic null. It is evidence the neutral null is implausible. It is not a posterior probability of partisan intent — that question requires evidence the geometry cannot supply.`,cant_5:`The audit does <strong>not</strong> tell any individual voter what position to take or what to do with this information. The choice is yours.`},editorial_intro:{heading:`What is redistricting, and why it matters`,p1:`Every voter in Alberta lives in an <em>electoral district</em> — a slice of the province that elects one person to the legislature. There are 87 districts. Each district elects one MLA. When you cast a ballot in a provincial election, you are choosing the MLA for the district you live in. For most Albertans, that is the whole connection to the legislature: one MLA, one district, one vote.`,p2:`Those district lines are not permanent. People move, neighbourhoods grow, rural areas thin out, cities sprawl. Every eight to ten years, Alberta is supposed to redraw the lines so each district is roughly the right size and reflects the way Albertans actually live now. The body that does the redrawing is the <em>Electoral Boundaries Commission</em> — an independent commission with judges, lawyers, and public members, not politicians.`,p3:`This is the standard process. This time, the standard process produced something unusual. The commission's five members split 3–2 on what the map should look like, and rather than settling on one recommendation they produced two: a <em>majority proposal</em> (backed by three commissioners) and a <em>minority proposal</em> (backed by two). Both are sitting on the table — and the legislature has set both aside. A separate committee of MLAs chaired by Brandon Lunty — appointed by the Premier for this specific decision — now oversees a four-person Independent Advisory Panel, constituted under Government Motion 37 (passed April 21, 2026), tasked with producing a new 91-seat map. The legislature must approve whatever the committee delivers before November 2026.`,p4:`Why it matters to you: the lines decide who your MLA is. They decide which neighbourhoods, towns, and concerns get represented together. If your city is split across four MLAs instead of one, no single representative is accountable for the city as a whole. If your community of interest — a small town, a rural region, a downtown core — is divided between districts, your voice on provincial decisions is diluted. The map also shapes which party can form a government, and at what margins. The audit's specific finding (the minority proposal sits at a structural extreme) is the reason you are reading this site, but the broader question is older and applies to every redistricting cycle: do the lines reflect the way Albertans live, or do they shape the politics following?`,p5:`The rest of this page walks through what the two proposed maps actually do.`,key_terms_lead:`Key terms in this section — click to read:`},editorial_reflect:{heading:`Interlude: What this means for you and your community`,intro_p1:`Set aside, for a moment, the question of which party gains or loses seats. Politicians and parties tend to frame this as a fight over power concentration in the legislature, and at the legislative scale it is. But power concentration in the legislature is not where you experience these maps. You experience them through three concrete questions about your own district:`,intro_q1:`Where does your MLA live?`,intro_q2:`Are they invested in your community?`,intro_q3:`Will the demands of the head dominate the demands of the tails?`,intro_p2:`Every other framing — partisan advantage, supermajority threshold, statistical extreme — eventually points back to those three. The five rungs below walk through how each proposed map answers them, at five scales.`,you_h:`You.`,you_p:`Your electoral district decides who represents you in the legislature. Right now you live in one of 87 districts. Under both proposed maps you may live in a different one — possibly with a different MLA, possibly anchored to different neighbouring communities. If you don't know what district you're in right now, or who your MLA is, you're not alone: most Albertans couldn't name their MLA. But the boundary lines are not abstract. They decide whose phone number is on your local representative's office wall, whose neighbourhood petition gets your name attached to it, whose concerns your MLA hears about first. The postal-code lookup on this site shows which district you sit in under each proposal. If your district changes, your representative changes — and your representative's relationship to your community changes with it.`,community_h:`Your community.`,community_p:`Communities are not abstract either. A high school's catchment area, a chamber of commerce, a faith community, a neighbourhood association — these are real groupings of people with shared local concerns. When a boundary line cuts through them, no single MLA is responsible for the whole. Take Airdrie under the minority proposal: a city of roughly 85,800 people sliced into four electoral districts, each anchored to a different rural hinterland. No single representative is accountable for Airdrie as a city. The same dynamic plays out anywhere a town, neighbourhood, or recognised community of interest is split — the bigger the split, the weaker the representation. The audit measures <em>municipal anchoring</em> (what fraction of each district's perimeter follows existing municipal lines), and the minority proposal scores notably lower than the majority on the anchoring test.`,municipality_h:`Your municipality.`,municipality_p:`When a city is fractured across many representatives, its ability to bargain on provincial decisions weakens. A council asking for transit funding, a school board negotiating a new school, a mayor lobbying for highway extensions — each of those goes better when the city can point to a few MLAs who owe accountability to the city as a whole. The minority proposal splits Calgary's northwest quadrant across multiple districts whose vote-share patterns suggest <em>packing</em> (concentrating one party's voters into a few high-margin seats) on top of <em>cracking</em> (splitting the other party's voters across many low-margin seats). Whether the pattern is intentional is a question the audit cannot answer — boundary geometry doesn't reveal intent. What it can say is that the four statistical measures flag the same districts the structural tests flag, and that the alternative proposal does not produce the same fingerprint.`,region_h:`Your region.`,region_p1:`If you live outside Alberta's cities you have probably noticed political conversations about boundaries always seem to centre the cities. It's a fair complaint, so let's be direct about what this audit does and does not say about rural Alberta.`,region_p2:`What it does <strong>not</strong> say: rural Alberta has too many seats. The EBCA allows district populations to vary by up to 25% so one rural MLA isn't representing a geography the size of southern France. Canadian courts treat the variance as legitimate. Both proposed maps preserve it. Nothing in this audit changes it.`,region_p3:`What it <strong>does</strong> say: in several places on the minority proposal, rural communities are being attached as the <em>tail</em> of a district whose population centre sits in a city. Look at how the minority proposal handles Airdrie — a city of about 85,800 sliced into four districts, each one extended out into a different stretch of rural countryside. The population centre of each new district is the urban slice, not the rural tail. An MLA elected from that kind of district is most likely to live, campaign, and prioritise where the votes are — which means rural communities formerly represented by a dedicated rural MLA become the back half of an urban-led seat. That pattern repeats on the minority proposal in ways it does not on the majority proposal.`,region_p4:`The audit doesn't propose taking seats away from rural Alberta. It asks whether the lines respect the rural communities those seats are meant to represent, or whether rural geography is being used as ballast to absorb urban votes into districts whose centre is somewhere else. If you live in one of those rural tails, the question of which map gets enacted decides whether your MLA represents the rural community you actually live in, or an urban district whose lines happen to include your land.`,province_h:`Your province.`,province_p:`The legislature is what you get when you sum every district's answers to the three questions above. If most districts are anchored to communities whose MLAs actually live in them, the legislature represents those communities. If most districts have rural tails attached to urban heads, the legislature represents the heads — and the tails get whatever attention is left over. The partisan question — which party wins a majority — is downstream of that. The supermajority question — whether one party crosses 58 of 87 seats and unlocks procedural shortcuts like waiving notice periods or accelerating bills through multiple stages in a single day — is downstream of <em>that</em>. At a hypothetical 50/50 provincial split, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. Whether that imbalance pushes a party past 58 seats at the vote shares Albertans actually deliver is a question this audit has not yet directly tested; the opening questions at the top of this page are honest about that gap. Whether the answer to any of these questions matters enough to act on is, again, a question for you.`},editorial_history:{heading:`Context: A short history of gerrymandering`,p1:`The word comes from 1812. Massachusetts governor Elbridge Gerry signed off on a state-senate map whose districts were so contorted in his party's favour that a Boston cartoonist drew one of them as a salamander — wings, claws, a forked tongue. The cartoonist's pun, <em>Gerry-mander</em>, stuck. The shape stuck too: two centuries later, the word still means drawing electoral lines to engineer a partisan outcome.`,p2:`The term endures because the problem endures. Anywhere voters choose representatives from geographic districts, someone has to draw the lines, and the lines can be drawn many ways. Different countries have arrived at different answers about who should do the drawing and what should constrain them.`,p3:`<strong>The United States</strong> treats partisan gerrymandering as a problem the federal courts mostly cannot fix. In <em>Rucho v. Common Cause</em> (2019), the U.S. Supreme Court ruled that partisan gerrymanders are "political questions" outside its jurisdiction. Some states (California, Michigan) have responded by creating independent citizen commissions to draw their own lines; others (Texas, North Carolina) have continued to draw openly partisan maps and defended them on the basis that <em>Rucho</em> permits it.`,p4:`<strong>The United Kingdom</strong> uses four permanent Boundary Commissions — one each for England, Scotland, Wales, and Northern Ireland — staffed by judges and senior civil servants. They redraw lines roughly every eight years against fixed rules (population equality, geographic coherence, respect for local government boundaries). Parliament can in theory reject the commissions' recommendations, but in practice virtually never does; by convention, the commissions' judgment stands.`,p5:`<strong>Australia</strong> delegates the work to the Australian Electoral Commission, a federal independent agency with full authority over both election administration and boundaries. Redistributions happen automatically when a state's seat count changes or seven years pass since the last one. The commissioners' decisions are reviewable on procedural grounds but not on partisan ones. As in the U.K., gerrymandering as Americans know it is virtually unheard of.`,p6:`These three cases bracket the spectrum: courts staying out (U.S.), independent commissions with strong parliamentary deference (U.K.), and a permanent independent agency with full authority (Australia). Canada sits somewhere different again — which is what the next section takes up.`},glossary:{more_link:`Learn more →`,"electoral-district":{term:`Electoral district (ED)`,definition:`The geographic area that elects one member to the provincial legislature. Often shortened to "ED" after first use. Each ED has one MLA. (The word "riding" usually refers to federal districts; in the provincial context the proper term is electoral district.)`},riding:{term:`Riding`,definition:`In Canadian usage, this most often refers to a federal electoral district. The Alberta provincial equivalent is called an "electoral district" (ED). The audit uses the provincial term throughout.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly — the person elected from one electoral district to represent it in the Alberta legislature.`},ucp:{term:`UCP`,definition:`United Conservative Party — Alberta's current governing provincial party. Formed in 2017 from the merger of the Progressive Conservatives and the Wildrose Party; has held government since 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party (Alberta NDP) — Alberta's current official opposition. The Alberta NDP held government from 2015 to 2019.`},gerrymander:{term:`Gerrymander`,definition:`A map drawn so one political party wins more seats than its share of the vote would suggest. The word comes from an 1812 Massachusetts district shaped like a salamander. It is not a legal term in Canada, but the concept is widely studied.`},cracking:{term:`Cracking`,definition:`A gerrymandering technique that splits a voting bloc across many districts so it never reaches a majority in any single one. For example, dividing a city across four ridings so its voters are outnumbered in each.`},packing:{term:`Packing`,definition:`A gerrymandering technique that concentrates one party's voters into a small number of districts. The party wins those districts overwhelmingly but "wastes" many votes — leaving fewer of its voters available to compete in other districts.`},draining:{term:`Draining`,definition:`A term this audit uses for a follow-on effect of cracking and packing: the wasted votes those techniques produce get pushed into strategically chosen places, altering the political character of nearby electoral districts. It is the audit's own framing rather than an established concept in the redistricting literature — the audit tests for the effect and finds results consistent with it, but treats it as exploratory rather than a settled methodology.`},anchoring:{term:`Anchoring`,definition:`How firmly the proposed boundaries follow existing municipal lines (city limits, town boundaries). A highly anchored map mostly respects those lines; a loosely anchored map departs from them often — especially at politically meaningful spots, which is a structural warning sign.`},"charter-s3":{term:`Section 3 of the Charter`,definition:`The section of the Canadian Charter of Rights and Freedoms that guarantees citizens the right to vote. Canadian courts have interpreted it not as a strict "one person, one vote" rule but as a right to "effective representation."`},"effective-representation":{term:`Effective representation`,definition:`The standard Canadian courts apply when judging electoral boundaries. It means voters should have a meaningful voice — not just numerical equality of riding populations, but also recognition of community ties, geography, and minority representation. The leading statement is from the Supreme Court of Canada's 1991 Saskatchewan Reference.`},ebc:{term:`Electoral Boundaries Commission (EBC)`,definition:`The body that draws Alberta's provincial electoral boundaries under the EBCA. The 2026 commission was chaired by Justice Miller and split 3–2 among its commissioners, producing two competing proposals (the majority and minority proposals) rather than a single recommendation.`},"lunty-committee":{term:`Lunty committee`,definition:`A five-MLA Select Special Committee on Electoral Boundaries chaired by Brandon Lunty — a Premier-appointed MLA — established by the Legislative Assembly's Motion 19 (April 16, 2026), which set aside both commission reports. The committee oversees a separate four-person Independent Advisory Panel, constituted under Government Motion 37 (passed April 21, 2026), that draws the actual map; the committee then reports to the Legislature before the November 2026 deadline. Both bodies are separate from the EBC and are not part of the standard EBCA process.`},"advisory-panel":{term:`Independent Advisory Panel`,definition:`The four-person panel appointed by the Lunty committee under clause C(d)(ii) of Government Motion 37 to draw a 91-seat boundary recommendation. The Premier nominated the Hon. Monte Solberg and Darwin Durnie; the Leader of the Opposition nominated Dr. Gerard Kennedy and Brent Robinson. A fifth seat — a sitting or retired judge to serve as chair — went unfilled after Alberta's acting chief justice declined to nominate one.`},ebca:{term:`EBCA`,definition:`The Alberta Electoral Boundaries Commission Act — the law that governs how electoral boundaries are drawn in the province. It sets up the commission, the public-hearing process, and the rules for when a new map takes effect.`},fsa:{term:`Forward sortation area (FSA)`,definition:`The first three characters of a Canadian postal code (the letter-digit-letter part). About 270 FSAs cover Alberta. Most fall entirely within a single electoral district.`}},body:{section_link_aria:`Link to section`,the_map:{heading:`1: The Map`,p1:`The cover map is the best single image in this audit. Here is how to read it.`,p2:`Alberta is divided into 4,765 Voting Areas — small geographic zones Elections Alberta uses to count polling-station ballots. Each one is coloured by how people in it actually voted in 2023: orange where NDP votes are concentrated, blue where UCP votes are concentrated. But the colour only becomes dark and saturated where a lot of people live. A Voting Area that covers hundreds of square kilometres of parkland or farmland stays pale — nearly invisible. The map lights up where people are, and fades where they aren't.`,p3:`This is very different from the Alberta you see on election night. Most election maps colour entire ridings solid blue or orange based on who won. Rural ridings are geographically large and the UCP wins most of them, so election-night Alberta looks like a wall of blue with small orange pockets in Edmonton and Calgary. The cover map uses the same votes and the same geography — but shows them weighted by where people actually live. What appears is a province where most of the population is concentrated in a dense arc of cities, and those cities vote very differently from the rural map that normally represents them.`,p4:`The boundary lines drawn over the colour are the minority commission's 89 proposed electoral districts — the map this audit ends up critiquing. The audit's work is to ask what those lines do to the people underneath them.`,p5:`This image is what makes the stakes plain. A province that looks like it votes one way on a standard map is actually a province where most of the people live in areas that vote the other way. Once the population is visible underneath the boundary choices, those choices stop looking random.`},structural_results:{heading:`Structural audit results — before any statistics:`,body:`The majority map crosses <strong>zero of five</strong> pre-registered structural thresholds. The minority map crosses <strong>four of the five</strong>; the fifth (anchoring) is neutral — both maps fall within the 70–85% Canadian norm. These are geometric measurements — population spread, <button class="vocab-term" data-def="how closely a district's borders follow pre-existing city and municipal limits, rather than cutting through them" aria-expanded="false">municipal anchoring</button>, Airdrie split count, NW Calgary population excess, and the seven boundary configurations Commission Chair Justice Miller himself flagged in writing (§5.8.2 of the majority report and Appendix C) — requiring no election data and no statistical sampler. The next section tests both maps against 1,010,000 computer-generated neutral maps and reaches the same conclusion through a completely different instrument. Three independent instruments — geometric, judicial, and statistical — converge.`},clean:{heading:`6: When a fair-looking map isn't`,legal_label:`A NOTE ON LEGAL TERMINOLOGY`,legal_body:`"Gerrymandering" has no legal definition in Canadian law. The word is used throughout this report in its everyday political sense — manipulating electoral boundaries for partisan advantage. The legal tests actually applying in Canada are different: whether boundaries provide "effective representation" under s.3 of the <em>Charter of Rights and Freedoms</em> (the constitutional standard the Supreme Court of Canada set in the 1991 <em>Saskatchewan Reference</em>), and whether the commission followed the rules of Alberta's <em>Electoral Boundaries Commission Act</em>. The audit's findings are evidence bearing on those legal questions. They are not proof of a legally-defined wrong, and this report does not describe them in those terms.`,intro_p1:`The cleanest single question to ask of any electoral map is this: if the province's vote split exactly evenly between the two main parties, what seat count would the map produce? This holds the electorate constant and asks the map alone what it does.`,intro_p2:`To answer this, the audit generated 1,010,000 computer-simulated, mathematically neutral Alberta maps. The simulation used the official Elections Alberta shapefiles and held to the exact same statutory rules and geographic boundaries the commission used. The commission's two 2026 maps were then placed into that distribution to see how normal they are. The simulation ran four independent chains of 252,500 steps each, with the base seed drawn from the Cloudflare drand beacon and pre-registered at OSF before execution.`,howmcmc_label:`HOW THE SIMULATION WORKS`,howmcmc_mcmc:`<strong>MCMC (Markov Chain Monte Carlo)</strong> is a method for exploring a large space — here, the space of all legal Alberta maps — by taking random steps from a starting point. Each step proposes a small swap between adjacent districts; if the result stays within the statutory rules, it becomes the new starting point. After enough steps, the visited maps form a representative sample of legal plans. The simulation is seeded from the Cloudflare drand public randomness beacon to prevent any cherry-picking of starting conditions.`,howmcmc_recom:`<strong>ReCom (Redistricting Compiler)</strong> is the specific algorithm used here. Each step merges two adjacent districts into one region and re-splits it randomly into two new valid districts, preserving contiguity and population balance by construction — so the algorithm never needs to reject an invalid proposal.`,prereg_label:`PRE-REGISTRATION`,prereg_body:`Pre-registration means writing down the exact tests, thresholds, and predicted directions before looking at any data, and locking those commitments into a public time-stamped record. The Open Science Framework (OSF) is the public repository where this audit's commitments are filed. It prevents retrofitting: if a result doesn't emerge cleanly, the threshold cannot be changed after the fact and then presented as always having been the test. All five structural tests and four partisan-fairness metrics in this audit were registered at OSF before any simulation was run.`,neutral_p:`In Alberta, the neutral answer is not 50/50. <em>Across 1,010,000 computer-simulated legal Alberta maps, the median map gives the UCP only 44.8% of the seats at 50/50 votes</em> — a typical Alberta map under neutral votes hands the NDP a small seat majority. This is counterintuitive but mechanical: rural UCP voters win their ridings by 60-40 margins (wasting many "extra" UCP votes), while urban NDP voters win their ridings by tighter 51-49 margins (wasting fewer NDP votes per win). At neutrality, NDP comes out ahead on seat efficiency.`,full_dist:`The full distribution from the canonical 1,010,000-map simulation:`,t1_col_a:`Where the map sits`,t1_col_b:`UCP seats at 50/50 votes`,t1_r1_a:`Median Alberta map`,t1_r1_b:`44.8% — NDP slight seat majority`,t1_r2_a:`95th-percentile map`,t1_r2_b:`47.1%`,t1_r3_a:`99th-percentile map`,t1_r3_b:`48.4%`,t1_r4_a:`<strong>Maximum across 1,010,000 maps</strong>`,t1_r4_b:`<strong>below 51.7% (fewer than 100 plans reach this value)</strong>`,seat_count_note:`A note on seat counts. The 2026 commission maps each have <strong>89</strong> districts; the audit's computer simulation runs on the <strong>87</strong>-district 2019 map (its starting substrate); the November Lunty committee will produce <strong>91</strong>. All percentages are seat <em>shares</em>, comparable across these denominators. The simulation uses the 2019 map as its starting point because the ReCom algorithm needs a legally enacted map to propose swaps from — the 2019 map is the last enacted Alberta electoral map. Using either commission proposal as the substrate would be circular: we would be measuring whether a map is extreme compared to maps derived from itself.`,pattern_intro:`The results — placing the three real maps in this distribution — point to a specific, surgical pattern of boundary drawing.`,sub1_h:`All four statistical measures fire simultaneously`,sub1_p:`When the official Elections Alberta shapefiles are used, the minority map is a statistical outlier on every partisan-fairness metric — not just the tipping-point one.`,t2_col_a:`Map`,t2_col_b:`Efficiency gap`,t2_col_c:`Mean-median`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Declination measures the angular difference between the seats-votes curve for each party. Negative values favour the UCP; positive favour the NDP.">Declination</a>`,t2_col_e:`Seats at 50/50`,t2_r1_a:`Majority 2026`,t2_r1_b:`+0.04% (p15.5)`,t2_r1_c:`−3.6% (p2)`,t2_r1_d:`+0.027 (p81)`,t2_r1_e:`46.1% (p83)`,t2_r2_a:`Minority 2026`,t2_r2_b:`<strong>+3.96% (p94.4)</strong>`,t2_r2_c:`<strong>+1.0% (p99.98)</strong>`,t2_r2_d:`<strong>−0.077 (p1.2)</strong>`,t2_r2_e:`<strong>51.7% (p99.99)</strong>`,sub1_close:`The majority map sits comfortably inside the normal range on three of four metrics. Its mean-median sits at p2 in the NDP-favourable direction — an unusual result but pointing the wrong way to help the UCP. The majority map's close adherence to municipal boundaries places NDP-heavy urban cores into their own compact districts, where NDP votes win by efficient margins while UCP rural wins tend to be by larger margins; this mild structural NDP efficiency advantage is what shows up in the mean-median measure. The minority map is in the tail on all four, each pointing in the same partisan direction.`,sub2_h:`The 50/50 tipping point: fewer than 100 of 1,010,000 neutral maps reach it`,sub2_p:`The tipping-point metric introduced above — UCP seats at a 50/50 provincial vote — is the most intuitive way to compare the three maps.`,t3_col_a:`Map`,t3_col_b:`UCP seats at 50/50 votes`,t3_col_c:`Where it sits`,t3_r1_a:`2019 enacted`,t3_r1_b:`46.0%`,t3_r1_c:`83rd percentile — inside the normal range`,t3_r2_a:`<strong>Majority 2026</strong>`,t3_r2_b:`<strong>46.1%</strong>`,t3_r2_c:`<strong>83rd percentile — well within bounds</strong>`,t3_r3_a:`<strong>Minority 2026</strong>`,t3_r3_b:`<strong>51.7% (46 seats)</strong>`,t3_r3_c:`<strong>99.99th percentile — fewer than 100 of 1,010,000 neutral draws reach this</strong>`,sub2_close:`Fewer than 100 of 1,010,000 computer-simulated neutral Alberta maps produced a <code>seats@50/50</code> value as high as the minority proposal's. Based on actual recent voting patterns, it would award the UCP 60 seats (compared to 55 in the majority proposal). The majority proposal is the kind of map a neutral procedure routinely generates. The minority proposal is the kind of map you have to specifically aim to draw.`,sub3_h:`What this means in plain language`,sub3_p:`The official shapefiles reveal a map statistically extreme in the same partisan direction on all four measures at once. The joint probability of a neutral drawing process producing a map this extreme across all four measures simultaneously is roughly one in 15 million (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>, <a href="https://osf.io/6pt83" rel="noopener">pre-registered Fisher combined test</a>). This is not a rounding error or a measurement artefact — it is the same answer from four independent statistical instruments read in the same room.`,details_summary:`What this p-value means — and what it doesn't`,details_p1:`A p-value answers one question: if the map were drawn by a neutral process, how often would we see a result this extreme or more extreme? At p&nbsp;=&nbsp;6.87×10<sup>−8</sup>, the answer is about once in 14.5 million trials.`,details_p2:`This is a frequentist hypothesis test, not a measurement of intent. It does not say the commission intended to gerrymander, and it does not quantify how unfair the map is in practical terms. It says the boundary pattern is statistically inconsistent with a neutral drawing process — the same conclusion a randomized audit would reach regardless of who drew the map or why.`,details_p3:`The test was pre-registered before the data were analyzed (<a href="https://osf.io/w2s8k" rel="noopener">OSF registration w2s8k</a>). The pre-registration specifies the null hypothesis, the metrics, and the rejection threshold in advance, so the result cannot be attributed to choosing a favorable framing after seeing the numbers.`,szat_label:`SWING-ZONE ALLOCATION TEST (SZAT)`,szat_body:`SZAT is the audit's second independent test, and it asks a different question from the simulation: not "is this map extreme overall?" but "are the specific line choices partisan-neutral?" It works by isolating only the Voting Areas where the minority's map differs from the majority's — the contested re-draws — and testing whether those particular choices, taken together, shift vote efficiency in one party's direction. Because it compares only the points of departure, it automatically controls for everything the two maps share: the same geography, population targets, and statutory rules. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Technical details and bootstrap results →</a>`,two_q:`<strong>Two questions, one answer.</strong> The 1,010,000-map simulation asks: <em>is this map extreme compared to neutral maps drawn on the same Alberta geography?</em> A second, separate test — called the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Swing-Zone Allocation Test</a> — asks a different question: <em>are the specific lines on the map partisan-neutral?</em> It works by looking only at the Voting Areas where the minority drew differently from the majority and asking whether those particular choices, taken together, shifted vote efficiency in one party's direction. Because it compares only the places where the two maps differ, it automatically controls for everything they share — the same provincial geography, the same population targets, the same statutory rules. Both questions return the same answer. This is why the one-in-15-million figure is a combined result rather than a single test: it is two independent lines of evidence converging.`,super_lead:`This explains why the minority proposal had to be such an extreme statistical outlier (p99.99) against 1,010,000 neutral simulations. In an 89-seat legislature, a two-thirds supermajority requires exactly 60 seats. Neutral procedures do not produce 60-seat outcomes on Alberta's geography at neutral votes; reaching the threshold requires deliberate boundary choices departing from the neutral baseline.`,super_label:`WHY A SUPERMAJORITY MATTERS`,super_body:`Under Canada's Westminster parliamentary system, a simple majority (45 seats) is enough to pass routine laws and budgets. A two-thirds supermajority (60 seats) does more. It lets the governing party invoke "closure" to shut down debate, rewrite procedural rules without opposition consent, and control the composition of every legislative committee. It also insulates the government from internal dissent: even with half a dozen backbenchers crossing the floor, the government still holds a working majority. A simple majority lets you drive the car; a 60-seat supermajority lets you rewrite the traffic laws.`,super_close:`By strategically diluting urban voters into surrounding rural-edge districts (the "urban hybridization" pattern identified in Lane 2), the minority proposal engineers the exact structural firewall needed to secure those 60 seats. The Lane 2 structural finding and the Lane 1 statistical finding converge on the same proposal, the same direction, and the same communities.`,sub4_h:`Confirmation from the targeted-procedure test`,sub4_p:`To be sure this isn't a quirk of the neutral simulation's known compactness preference, the audit ran a targeted hill-climbing procedure (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et al. 2022 — cited and described in the technical report</a>) in both directions: maximising UCP seats and maximising NDP seats. Same number of steps (40,000) in each direction, same statutory constraints, same provincial geometry.`,t4_col_a:`Procedure`,t4_col_b:`Most-extreme value reached`,t4_col_c:`What it tells us`,t4_r1_a:`Neutral MCMC, max produced`,t4_r1_b:`below 51.7% UCP seats @ 50/50`,t4_r1_c:`The natural ceiling under neutral drawing`,t4_r2_a:`Neutral MCMC, min produced`,t4_r2_b:`~39% UCP seats @ 50/50`,t4_r2_c:`The natural floor under neutral drawing`,t4_r3_a:`Targeted hill-climb, UCP-maximizing`,t4_r3_b:`<strong>52.9%</strong>`,t4_r3_c:`What a procedure deliberately aiming for UCP advantage can reach`,t4_r4_a:`Targeted hill-climb, NDP-maximizing`,t4_r4_b:`<strong>37.9%</strong>`,t4_r4_c:`What a procedure deliberately aiming for NDP advantage can reach (below the neutral floor)`,sub4_close:`The minority map's 51.7% sits closer to the targeted-UCP ceiling (52.9%) than to the neutral median (44.8%). The majority map's 46.1% sits at the neutral median. Both the 2019 enacted map and the 2026 majority fall comfortably within what neutral procedure routinely produces — different vote shares, same zone of unremarkable outcomes. The majority continues 2019 Alberta practice on the partisan-fairness axis the same way it continues 2019 practice on municipal anchoring (80.0% vs 2019's 75.2%). Two maps drawn under the same Alberta rules, by the same five commissioners, in the same room: one lands where neutral procedures routinely produce, the other lands where you have to specifically aim to land.`,sub4_quote:`<em>This</em> is the shape of the finding, and it is also the framing a court would actually apply.`,sub5_h:`Ruling Out Alternative Explanations`,sub5_p:`When presented with a statistical outlier of this magnitude, a rigorous audit must rule out innocent explanations before attributing these patterns to deliberate design. The structural data (Lane 2) systematically dismantles the standard alternative defenses:`,defense1:`<strong>The "Natural Political Geography" Defense:</strong> <em>("Urban voters are naturally packed; the map just reflects Alberta's geography.")</em> The 1,010,000 simulations already account for Alberta's natural geography. The simulation proves: while geography gives the UCP a baseline efficiency advantage, it naturally caps around the 83rd to 90th percentile. The minority map sits at the 99.99th percentile — an extreme outlier <em>even when compared to Alberta's naturally skewed baseline</em>.`,defense2:`<strong>The "Communities of Interest" Defense:</strong> <em>("The odd shapes were drawn to keep specific communities together.")</em> If you are trying to keep communities together, you follow municipal borders. The majority map followed existing city limits 80% of the time. The minority map followed them 72% of the time — both within the 70–85% Canadian norm. What the minority map does do is actively split the unified city of Airdrie into four separate pieces, and place three of its boundary decisions precisely in the urban-edge zones the commission chair flagged as geometrically anomalous — choices not explainable by community-of-interest logic.`,defense3:`<strong>The "Population Equality" Defense:</strong> <em>("They had to draw weird boundaries to make sure every district had the exact same population.")</em> The minority map is actually much <em>worse</em> at population equality. Its Population Mean Absolute Deviation (MAD) was 4,707 — 48% wider than the majority map's 3,180 — placing it at the 99th percentile of the canonical ensemble (only 1 in 100 neutral maps produces a worse spread). It sacrificed population equality to achieve its shape.`,defense4:`<strong>The "Incompetence or Bad Luck" Defense:</strong> <em>("They just drew a sloppy map and got unlucky with the numbers.")</em> Hitting exactly 60 seats for a supermajority while also splitting Airdrie into four pieces and placing three boundaries in the exact zones the commission's own chair flagged as anomalous requires surgical precision. The joint probability of accidentally drawing a map hitting the extreme statistical tail across four independent partisan metrics simultaneously is roughly <strong>1 in 15 million</strong> (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>). You cannot blunder your way into the 99.99th percentile.`,sub5_close:`What the data shows is that the minority proposal worsened both population parity and community coherence relative to what the same five commissioners produced simultaneously under identical statutory rules. The audit does not determine what the minority commissioners intended — boundary geometry cannot reveal intent — but the structural departure from both the neutral ensemble and the majority proposal's output stands regardless of intention.`,sub6_h:`A note on the R cross-validation`,sub6_p1:`An earlier version of this audit (using approximated rather than official shapefiles) cross-validated the Python ReCom ensemble against the R <code>redist</code> package's Sequential Monte Carlo sampler. The cross-check produced unstable results: across three runs with the same nominal seed, the fraction of plans reaching the old minority value (48.3% on the approximated geometry) was 5.6%, then 28%, then 58% — a sampler-convergence failure, not a discovery. The full write-up is at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`With official Elections Alberta shapefiles, the minority map's <code>seats@50/50</code> rises to 51.7% — a value fewer than 100 of 1,010,000 neutral plans reach. The R cross-validation question becomes moot: zero plans from either sampler reach the canonical value at comparable sample sizes.`,sub6_asymm:`<strong>The asymmetry around 50/50 is more telling than the inversion itself.</strong> A precision sweep of the seat-vote curve at 0.01-percentage-point resolution finds the minority map keeps the UCP at or above the 45-seat legislative-majority threshold down to a UCP provincial vote share of about <strong>49.7%</strong>. This is technically a vote-seat inversion — the UCP would form government on the minority map while losing the popular vote by 0.3 percentage points — but 0.3 points is well within ordinary polling noise, so on its own this is not a dramatic finding. What <em>is</em> dramatic is the contrast: on the <strong>majority</strong> map, the UCP would need to <em>win</em> the popular vote by about 4 percentage points to reach the same 45-seat threshold. Both maps face the same Alberta geography and the same statutory rules; the gap between them — 0.3pp vs +4pp — is structural difference, not noise.`,sub6_close:`This is the structural-bias finding the audit holds with confidence. It is geometry-only; it does not depend on any election result; it does not move when polls do.`,sub6_caveat:`<strong>One caveat the audit takes seriously.</strong> A real electorate is not a uniform 50/50. Voters can swamp any map's structural lean with enough swing — a particularly upset or inspired electorate will tip the result regardless of how the boundaries are drawn. The 50/50 test isolates <em>the map's contribution to the outcome</em>, not the outcome itself. What it shows is what the map does when the electorate doesn't decide for it.`,sub7_h:`The bottom line`,sub7_p1:`The audit's central finding is geometric. <strong>Lane 2 — the structural-irregularity scorecard — is the foundation; Lane 1 is the proof that the geometry is doing partisan work.</strong>`,sub7_p2:`The chart below puts both lanes on a single picture. The horizontal axis is Lane 1 (the partisan-fairness efficiency gap, where further right means more UCP-favoured); the vertical axis is Lane 2 (the count of structural-fairness tests the proposal fails, out of five, where higher means more structural problems).`,stakes_fig_alt:`Scatter plot with efficiency gap on the horizontal axis and count of structural tests failed on the vertical axis. The 2019 enacted map and the majority 2026 map cluster in the safe lower-left corner. The minority 2026 map appears in the upper-right outlier region.`,stakes_fig_caption:`The two ways of measuring the two commission proposals, plotted together. Left-to-right: how skewed the proposal looks on the partisan-fairness number — the further right, the more it favours the UCP. Bottom-to-top: how many of five structural-fairness tests the proposal fails — the higher, the worse. The 2019 enacted map sits in the safe corner: low on both. The majority 2026 proposal stays flat at zero structural problems and near-zero partisan skew (+0.1%). The minority 2026 proposal is a structural outlier on every test that distinguishes the two maps (4 of 5; the fifth, anchoring, is neutral for both); its efficiency gap (+4.0%) sits just below the Alberta threshold line.`,stakes_table_intro:`The same findings in plain summary form, leading with the structural finding because the cross-validated evidence supports it most strongly:`,t5_col_b:`Lane 2: Structure (geometry-only, no votes)`,t5_col_c:`Lane 1: Numbers (vote-dependent)`,t5_r1_a:`<strong>Majority 2026</strong>`,t5_r1_b:`clean — crosses <em>no</em> structural threshold`,t5_r1_c:`inside the normal range on every metric (<code>seats@50/50</code> 46.1% — p83; efficiency gap +0.04%)`,t5_r2_a:`<strong>Minority 2026</strong>`,t5_r2_b:`<strong>crosses 4 of 5 structural thresholds</strong> by a wide margin (anchoring neutral — both maps within Canadian norm)`,t5_r2_c:`statistical outlier on all four partisan-fairness measures simultaneously — <code>seats@50/50</code> 51.7% (p99.99, fewer than 100 of 1,010,000 reach it); efficiency gap +3.96% (p94.4); all four pre-registered; Fisher combined p&nbsp;=&nbsp;6.87×10<sup>−8</sup>`,details2_summary:`Why Lane 2 carries the case — technical detail`,details2_p:`The audit pre-registered five structural-irregularity tests on April 24, 2026 before the final simulation results were compiled. Anchoring is neutral for both maps; on the remaining four tests the minority crosses every one and the majority crosses none. Those measurements are geometric — they don't depend on any statistical sampler or any vote attribution. Lane 1 (the partisan-fairness numbers) corroborates Lane 2 strongly under canonical official shapefiles: the minority is a statistical outlier on all four pre-registered metrics simultaneously, with a joint neutral-null probability of p&nbsp;=&nbsp;6.87×10<sup>−8</sup> (pre-registered Fisher combined test — a method that combines four independent test results into a single probability by multiplying their individual tail probabilities; the combined figure is far smaller than any single test's because all four point the same direction; OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>). The question of whether Lane 2's unusual geometry is the specific <em>mechanism</em> behind the Lane 1 numbers was tested and the answer is no — see <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>. The Swing-Zone Allocation Test shows the contested boundary choices are partisan-skewed, but the tested question was whether the boundary shapes themselves — the lasso corridor, the park extension — are the direct cause of the seat swing; they are not. The seat effect comes from how redrawn Voting Area assignments shift vote efficiency across districts, not from the shapes per se. Both lanes flag the minority map; they reach it through independent instruments. Lane 2 is the central finding. Lane 1 corroborates without carrying.`},impact:{heading:`5: Effects on Representation`,lanes_label:`LANE 1 AND LANE 2`,lanes_body:`<strong>Lane 1 (numbers)</strong> uses election results to test whether the map converts votes into seats fairly — it asks how the map performs across different vote splits. <strong>Lane 2 (structure)</strong> examines only the drawn lines — city splits, population spread, boundary shapes — with no election data at all. Each lane is independent: a map can fail one while passing the other. The minority proposal fails both; the majority passes both.`,intro:`Lane 1 depends on which election results you score the maps against. Lane 2 does not. The structural evidence is in the maps themselves — drawn lines, split cities, where the boundaries do and don't follow administrative lines that exist for other reasons. On these tests, the two maps are not close.`,fig_alt:`Bar chart comparing five structural-fairness tests side by side. The majority map bars sit at zero or well inside safe ranges. The minority map bars cross the threshold on four of the five tests by a wide margin; the fifth (anchoring) is neutral for both maps.`,fig_caption:`The five structural-fairness tests, side by side. Teal bars are the majority map; purple bars are the minority map. The dashed line in each row marks the failing threshold. The minority bars cross the threshold on four of the five tests by a wide margin; the fifth (anchoring) is neutral for both maps. The majority bars sit flat at zero or well inside the safe range.`,table_intro:`The same five tests in tabular form, with each test's threshold stated alongside the result. The bottom row is the audit's <em>summary</em> — the count of tests each map fails out of the five.`,table_col_test:`Test`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Border follows existing municipal lines (70–85% Canadian norm)`,table_r1_b:`80% — within norm`,table_r1_c:`72% — within norm`,table_r1_d:`N/A — both within Canadian norm`,table_r2_a:`Population spread (tighter is better)`,table_r2_b:`3,180`,table_r2_c:`4,707 — 48% wider`,table_r2_d:`Structural (Reduces vote equality)`,table_r3_a:`NW Calgary population excess above average`,table_r3_b:`2.8%`,table_r3_c:`11.5%`,table_r3_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r4_a:`Boundaries flagged by the commission's own chair`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`N/A`,table_r5_a:`Airdrie split (constraint minimum: 2)`,table_r5_b:`2 pieces`,table_r5_c:`4 pieces`,table_r5_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r6_a:`<strong>Pre-registered summary</strong> (&ge; 4 of 5 = outlier)`,table_r6_b:`<strong>0 of 5 fired</strong>`,table_r6_c:`<strong>4 of 5 fired</strong> (anchoring test neutral — both maps within Canadian norm; remaining 4 tests all fire)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`A separate finding, applied only to the minority: <strong>five of six of the minority commissioners' published rationales fail under independent check</strong>. The test runs against the minority only because the majority did not publish a contested-redraw rationale list — the audit cannot apply it symmetrically, and it is reported here as a single flag rather than as additional rows in the structural-irregularity count. (A seventh redraw the audit had previously listed turned out to rest on a federal-boundary claim untraceable in the minority report; it has been removed rather than left as a weak claim.)`,chair_appendix_p:`The audit also tested the chair's separate, blanket assertion in Appendix C that the minority's seven contested hybrid configurations had <strong>no public support</strong> in the 1,140+ public submissions. A keyword search across the full submission archive (94% machine-parsed, 6% image-only and excluded; methodology and per-configuration evidence at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) returned a more nuanced picture than either the chair's blanket claim or its blanket dismissal: the chair was right on three of seven (Airdrie 4-way split, Calgary–Nolan-Hill–Cochrane hybrid, and the St. Albert minority alternative each lack any documented support), wrong on three of seven (Rocky Mountain House–Banff Park drew an explicit, detailed proposal from at least one Clearwater-area submission plus several aligned ones; Olds–Three-Hills–Didsbury was supported by Beiseker residents in writing; Chestermere drew multiple submissions opposing a Calgary merger that materially align with the minority's intent), and partially wrong on one (Red Deer hybrids drew a peri-Red-Deer hybrid proposal from a sitting Red Deer councillor, with directional but not configuration-exact alignment). The chair's Appendix C "no public support" sweep is therefore demonstrably overbroad — three of seven are demonstrably false — but it is not invented out of whole cloth, since three of seven do hold up. <strong>This finding cuts against the chair, not against the minority.</strong>`,summary_p:`<strong>On Lane 2, the majority crosses zero structural thresholds. The minority crosses every one of them by a wide margin.</strong> The count is a raw tally rather than a calibrated family-wise probability — its weight comes from directional unanimity (every firing test pointing the same way), not from a joint null-distribution calculation. The statistical lane (§3) supplies the joint probability through a different instrument.`},cpd:{heading:`4: Cracking, Packing, and Draining`,vocab_label:`Three moves, one playbook`,vocab_packing:`<strong>Packing</strong> means cramming one party's voters into districts the party wins by landslides — each packed ballot still counts, but it contributes nothing beyond victory. Large, lopsided wins. Wasted votes.`,vocab_cracking:`<strong>Cracking</strong> means splitting a community across multiple districts so it wins none of them outright. A city strong enough to carry two seats gets carved into four, each tethered to a different rural area. Diluted votes. No seat for anyone.`,vocab_draining:`<strong>Draining</strong> is the spatial companion: packed and cracked districts are placed next to each other so over-concentrated supporters on one side "drain" voting power away from the contested districts nearby. The adjacency pattern amplifies both effects — packing and cracking reinforce each other across district lines.`,vocab_disclaimer:`All three can occur without any explicit partisan intent. What the audit measures is whether the pattern — and its statistical magnitude — is consistent with what a neutral map-drawing process produces. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Full methodology at §5 of the technical report.</a>`,fig_alt:`Map showing the division of Airdrie into four separate districts under the minority map`,fig_caption:`The division of Airdrie into four separate districts under the minority map, diluting its urban voting power.`,intro:`The five commissioners worked from the same statutory rules, the same provincial geography, the same archive of 1,140 public submissions, and the same demographic data. Their two competing drafts agree on most of Alberta. Where the drafts diverge, they diverge on choices someone in the room had to make. Three of those choices are worth seeing as choices, not numbers.`,airdrie_p:`<strong>It splits the City of Airdrie into four pieces.</strong> The law caps each electoral division at one-and-a-quarter times the provincial average, so Airdrie needs at least two divisions. The majority map gives it two. The minority gives it four — north to Calgary-Nolan Hill-Cochrane, east to Airdrie East, west to Calgary-Foothills-Airdrie West, and centre-south to Calgary-Airdrie — each one stapled to a different rural or Calgary-edge district. An Airdrie resident with a question for her MLA has to know which quarter of the city she lives in before she can call the right office. Her neighbours two blocks over will give her three different answers. The PTA at her child's school cannot send a single delegation to one MLA on a school-funding question; they have to coordinate four delegations to four offices, each MLA primarily accountable to a different rural or suburban constituency. The minor-hockey association, the food bank, the Chamber of Commerce — every organization that operates citywide now operates across four provincial ridings.`,airdrie_callout_label:`WHY AIRDRIE MATTERS`,airdrie_callout_p1:`Airdrie is the largest Alberta city without its own MLA. At 85,805 people (2024 municipal census) it is bigger than Red Deer; it has one council, one tax bill, one school division — every civic system treats it as a unit.`,airdrie_callout_p2:`Splitting it across four provincial divisions — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Calgary-Nolan Hill-Cochrane, and Airdrie East — each primarily identified with a different surrounding jurisdiction, removes Airdrie from the political map at the level of government that draws it. The city has 85,805 residents and zero seats in the legislature where a majority of voters call the place home.`,airdrie_callout_p3:`A four-way split is invisible to every partisan-fairness test except the one that asks: can a voter find their MLA?`,airdrie_callout_summary:`Both maps are legal. The four-way split is a choice.`,airdrie_btn:`Show flagged districts on map`,anchoring_p:`<strong>Where it departs from municipal lines, it departs at strategically important places.</strong> When electoral maps follow the edge of a city or town, voters recognize where their division begins and ends — the property-tax line, the school-division line, the local-election ward line, and the provincial-election line all coincide. Statistics Canada publishes these boundaries for free. On official Elections Alberta shapefiles, both maps follow municipal lines at comparable overall rates: the majority at 80%, the minority at 72%, both within Canada's 70–85% norm (Quebec: 78%, Ontario: 82%, BC: 71%; comparator commissions documented in the monograph). (The audit's initial provisional analysis showed the minority anchoring at only 15%; the figure did not survive recomputation on official shapefiles — see the correction note below.) The striking observation is not the overall rate but where the minority's departures are concentrated: the three boundaries the commission's own chair flagged as anomalous — Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">show ↗</button>'s extension into uninhabited national-park land, the Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">show ↗</button> lasso corridor, and the Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">show ↗</button> reach — are each departures from pre-existing civic geography in the exact urban-edge zones where pairing urban and rural voters most directly affects which party wins the seat.`,anchoring_followup:`The minority commissioners gave reasons for each of the three flagged boundaries. For Rocky Mountain House–Banff Park, they cited geographic size, the Highway 22 corridor, and the proximity of First Nations reserves to Rocky Mountain House; the commission chair called the extension into uninhabited national park land "a bad faith effort" to satisfy the area criterion, and the phrase appears in the commission's official final report. For Nolan Hill–Cochrane, they cited shared transportation and employment ties between northwest Calgary and Cochrane; Statistics Canada journey-to-work data shows only 35.8% of Cochrane workers travel to Calgary at all, with most working within Cochrane itself. For the Olds–North Airdrie reach, they cited Highway 2 corridor continuity; the audit found the specific Airdrie extension fails on population grounds. Independent check found five of the minority's six published sub-rationales fail or only partially hold against primary data.`,packing_p:`<strong>One area of Calgary is carved up to concentrate NDP voters into larger-than-average divisions.</strong> In Calgary's northwest quadrant <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">show ↗</button>, the minority map's divisions average 11.5% above the province-wide population — versus 2.8% on the majority. The same geographic zone, drawn by the same commission under the same constraints, produces districts a quarter larger on one map than on the other. This fits the structural signature of <em>packing</em>: concentrating one party's voters into fewer, larger districts so each of their ballots weighs less. Packing and <em>cracking</em> (splitting a party's voters thinly across districts they narrowly lose) are the two classic gerrymandering moves; both shrink a party's seat count below its vote share.`,chair_p:`The commission chair — appointed under the same Act, working from the same submissions — flagged three boundaries on the minority map as geographically anomalous: Rocky Mountain House–Banff Park's extension into uninhabited national park land; the Calgary-Nolan Hill–Cochrane lasso-shaped corridor; the Olds–Three Hills–Didsbury reach into north Airdrie. The majority received zero such flags from the same chair. (The chair's published criticism covers seven boundary configurations in total — four geometric flags in the main report and three in Appendix C. This audit independently confirmed anomalous geometry for three of the four geometric flags; the fourth, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">show ↗</button>, did not meet the audit's confirmation threshold.)`},litmus:{heading:`3: The 1,010,000-Map Litmus Test`,fig_alt:`Histogram showing the distribution of efficiency gaps across 250,000 neutral Alberta maps. Most maps cluster near zero. The minority commission map (purple line) sits at the 94th percentile (+3.96%), in the shaded right tail. The majority map (teal line) sits at +0.04%, well within the normal range.`,fig_caption:`Distribution of <button class="vocab-term" data-def="a measure of how lopsidedly votes are converted into seats — positive values favour the UCP, negative values favour the NDP" aria-expanded="false">efficiency gaps</button> across 250,000 neutral Alberta maps drawn from the same geography. Most neutral maps cluster near zero; the shaded right tail marks the top 10%. The minority proposal&rsquo;s +3.96% sits at the 94th <button class="vocab-term" data-def="the percentage of maps that scored lower — p94 means 94 out of 100 neutral maps were less partisan than this" aria-expanded="false">percentile</button> — a region fewer than 6 in 100 neutral maps ever reach. The majority proposal&rsquo;s +0.04% is indistinguishable from what a neutral process typically produces.`,table_intro:`The table compares the two maps. The first five rows use no election results — they're properties of the lines themselves. The last two depend on how votes were attributed to each district.`,table_col_measured:`What was measured`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Population spread across districts (tighter is better)`,table_r1_b:`3,180`,table_r1_c:`4,707 — 48% wider`,table_r1_d:`Structural (Reduces vote equality)`,table_r2_a:`NW Calgary population excess above average`,table_r2_b:`2.8%`,table_r2_c:`11.5%`,table_r2_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r3_a:`Airdrie split`,table_r3_b:`2 divisions`,table_r3_c:`4 divisions`,table_r3_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r4_a:`Borders that follow existing municipal lines`,table_r4_b:`80% — within norm`,table_r4_c:`72% — within norm`,table_r4_d:`N/A — both within Canadian norm (70–85%)`,table_r5_a:`Boundaries flagged by the commission chair`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`N/A`,table_r6_a:`Seats at 50/50 votes (percentile in 1,010,000-map simulation)`,table_r6_b:`46.1% — p83 (normal range)`,table_r6_c:`51.7% — p99.99 (fewer than 100 of 1,010,000 reach this)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Efficiency Gap (percentile in 1,010,000-map simulation)`,table_r7_b:`+0.04% — p15.5 (normal range)`,table_r7_c:`+3.96% — p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Packing-cracking neighbourhood pattern`,table_r8_b:`6 coupled chain signals`,table_r8_c:`2 (pre-registered PASS)`,table_r8_d:`Neutral — minority achieves partisan effect via hybridization, not adjacency drain (§5.3.5)`,vocab_label:`VOCABULARY`,vocab_eg:`<strong>Efficiency gap.</strong> A single number that measures how lopsidedly a party's votes are translated into seats. Positive numbers favour the UCP; negative favour the NDP. The audit uses ~5% as Alberta's outlier line — the value exceeded by only 5% of the 1,010,000 neutral Alberta-specific simulations. This threshold is not borrowed from US or general literature; a threshold calibrated to another jurisdiction would be wrong because Alberta's natural geography produces a different neutral range.`,vocab_mm:`<strong>Mean-median difference.</strong> The gap between a party's median district vote share and its mean district vote share. When one party wins many close races, the median sits above the mean — those votes are distributed efficiently. When a party wins many races by large margins, the mean sits above the median — votes are being wasted. A large mean-median gap in one direction flags structural inefficiency in how one side's votes are spread across districts.`,vocab_percentile:`<strong>Percentile ranking.</strong> In this audit, a "percentile" is a rank within the 1,010,000 neutral simulated maps. "p94" means 94% of neutral maps score lower — the real map is more extreme than 94% of neutral draws. "p99.99" means fewer than 1 in 10,000 neutral maps reach the level.`,vocab_anchoring:`<strong>Anchoring.</strong> The fraction of an electoral border that lies on a pre-existing administrative line — a city limit, a school-division boundary, a Statistics Canada census line.`,closing_p1:`The bottom rows depend on election results. The <em>seats@50/50</em> test holds the electorate at perfect parity (UCP and NDP each win exactly half the votes province-wide) and asks how many seats the map awards the UCP. A neutral Alberta map produces a median around 44.8% UCP seats. Alberta's geography — NDP voters concentrated in city cores, UCP voters spread across rural ridings — gives the NDP a small efficiency advantage at neutrality. The majority map at 46.1% sits at the 83rd percentile of the 1,010,000-map simulation, well inside the normal range. The minority map at 51.7% sits at the 99.99th percentile: fewer than 100 of 1,010,000 neutral draws reach that value. The <em>efficiency gap</em> number measures how lopsidedly each party's votes get translated into seats. On the official Elections Alberta shapefiles the minority's efficiency gap is +3.96%, placing it at the 94.4th percentile — just below the audit's 95th-percentile outlier line. The opening questions at the top of this page unpack the consequences.`,closing_p2:`The last row is where the minority map has fewer coupled chain signals than the majority on the neighbour-drain test: 2 against the majority's 6 (and the 2019 enacted map's 5). The audit pre-registered this test before measuring, and the minority's lower count is a genuine pre-registered PASS — the minority does not show the classic pack-and-drain adjacency pattern. It is the single test where the minority numerically outperforms the majority. §5.3.5 of the academic report explains why: the minority achieves its partisan effect through hybridization (city-splitting that internalises packing and cracking within individual EDs), which is invisible to an adjacency-chain test that only measures how packed districts cluster next to cracked ones.`},commission_split:{heading:`2: How the Commission Split`,intro:`Alberta's Electoral Boundary Commission finished its work on March 23, 2026 and could not agree. Three commissioners produced one map; the other two produced a different one. Commission Chair Justice Dallas K. Miller and two opposition-nominated commissioners wrote the majority report; two government-nominated commissioners — Dr. Julian Martin and John D. Evans — wrote the minority report. The split centred on how to draw boundaries in fast-growing urban-edge communities. The majority gave Airdrie two districts; the minority four. The majority drew northwest Calgary's divisions close to the provincial average; the minority drew them 11.5% above it. Both maps follow the same statute. Both are legal under the <em>Electoral Boundaries Commission Act</em>. The disagreement was about which specific geographic configurations best served the communities being drawn. Alberta's governing party is the United Conservative Party (UCP); its main opposition is the New Democratic Party (NDP). Smaller parties — the Alberta Party, the Liberal Party of Alberta, and others — contest seats too, but their combined provincial vote share has been low enough in recent elections that it does not materially affect the audit's partisan-fairness calculations, which are grounded in the 2023 UCP–NDP split. This audit measured both maps using the same methods, applied identically. Three findings stand out.`,finding1:`<strong>The two maps differ on six things you can measure without looking at any election results:</strong> how evenly people are spread across districts, whether voters are concentrated, how badly cities are cut up, whether borders follow city limits, the shape of the districts, and how many boundaries Commission Chair Justice Miller himself flagged as anomalous in writing (§5.8.2 of the majority report and Appendix C). The minority map differs from the majority on every one of them.`,finding2:`<strong>Every measured difference moves in the same direction.</strong> Everywhere the two maps diverge — northwest Calgary, Airdrie, urban areas with clear city limits — the minority map draws boundaries that spread NDP votes thinner and let UCP votes count more efficiently. The communities most reshaped by the minority map are the same communities where the NDP is strongest. The audit cannot determine intent. It can measure effect.`,finding3:`<strong>The process now promoting the minority map has no precedent in Canada.</strong> No other province lets a cabinet hand redistricting to a committee its own party controls partway through a redistribution cycle. Most provinces either require the legislature to debate the commissioners' map first, or give the commission's map automatic effect unless overridden. Alberta does neither. On April 16, the government set both commission maps aside and assigned the work to an MLA committee a majority of whose members come from the governing United Conservative Party (UCP); the committee's full composition and mandate are detailed in §7. Alberta's <em>Electoral Boundaries Commission Act</em> requires the legislature to pass a separate Electoral Districts Act to give a commission report legal effect — the commission report itself changes nothing. Most other provinces make a commission's report legally effective unless the legislature actively overrides it; Alberta's default reverses it, meaning the governing party controls whether any commission map ever becomes law. The government's stated justification was to implement Commission Chair Justice Miller's Recommendation 5. But Miller had written the recommendation specifically to dissuade the legislature from accepting the minority map, and his majority colleagues did not endorse it. Recommendation 5 was also geographically specific: one additional rural seat south of Edmonton, and one in Clearwater County and western Mountain View County — both far from the fast-growing Calgary and Edmonton urban-edge communities where the commission actually split. It was not an invitation to redesign those contested boundaries. The government adopted the seat count while handing a committee it controls authority over exactly the lines the commission disagreed on.`,closing:`<strong>The process is its own finding, separate from the maps.</strong>`},november:{heading:`7: The Lunty Committee`,context_label:`CONTEXT`,context_body:` — This section describes the process that replaced the commission and the legal framework that applies to it. It is not part of the statistical findings. The findings are in §3–§6 above.`,intro:`Neither commission map is in force. On April 16, 2026 the Legislative Assembly passed Motion 19, setting both aside and referring redistricting to a Select Special Committee of five MLAs — three UCP, two NDP — chaired by Brandon Lunty (UCP, Leduc-Beaumont). The committee itself does not draw the map. It oversees a separate Independent Advisory Panel, constituted under Government Motion 37 (passed April 21, 2026), tasked with producing a 91-seat boundary proposal. Motion 37 contemplated five panel members — a sitting or retired judge as chair, two members nominated by the Premier, and two by the Leader of the Opposition — but Alberta's acting chief justice declined to nominate a judge to the chair, and the panel now operates with the four appointees the committee confirmed: the Hon. Monte Solberg and Darwin Durnie (Premier's nominees) and Dr. Gerard Kennedy and Brent Robinson (Opposition nominees). The committee must deliver its report to the Legislature by November 2, 2026. Unlike the original commission, neither the committee nor the panel is required to hold public hearings; the panel draws on submissions the original commission gathered. When the committee's map is released, this audit will apply the same methodology to evaluate it.`,h_anomalous:`Why the Committee Is Anomalous`,anomalous_p1:`Canadian redistricting practice has, since the 1960s, settled on a single model: an independent commission, insulated from government direction, produces boundary recommendations; the legislature may debate them but cannot easily override them without a formal legislative vote. Alberta's statutory process under the <em>Electoral Boundaries Commission Act</em> follows this template — but with one structural difference from most provinces: Alberta's commission report has no automatic legal effect. Under the Act, a separate Electoral Districts Act must be passed by the legislature to give any commission map force of law. This means the government of the day controls not only whether the commission map is debated, but whether it ever becomes law at all. Other Canadian jurisdictions take the opposite default: the commission's recommendations take effect unless the legislature affirmatively votes to override them.`,anomalous_p2:`What the government did in April 2026 has no recorded precedent in post-Confederation redistricting: it allowed a completed, published commission process to conclude — both majority and minority reports filed — and then referred the redistricting task to a five-member committee of MLAs whose majority (three of five) is held by the governing party, without bringing either commission report to a vote. The Lunty committee is not a commission. It has no statutory independence from the government's legislative direction. Its three-member UCP majority mirrors the government's control of the legislature. No other Canadian province has transferred redistricting authority, mid-cycle, to a government-controlled legislative committee after an independent commission had completed its work.`,h_framework:`The Constitutional Framework`,framework_p1:`Section 3 of the <em>Charter of Rights and Freedoms</em> — "Every citizen of Canada has the right to vote in an election of members of the House of Commons or of a legislative assembly" — has been interpreted by the Supreme Court of Canada to guarantee not merely the act of casting a ballot but <em>effective representation</em>. The leading authority is <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, in which McLachlin J. (as she then was) wrote for the majority that the purpose of s.3 "is not equality of voting power per se, but the right to effective representation." Population parity is the primary consideration; departures are permitted when justified by community of interest, geography, history, or minority-representation objectives.`,framework_p2:`The Saskatchewan framework does not categorically prohibit partisan considerations in redistricting. What it establishes is that boundary maps must, on the whole, provide effective representation to voters — and that systematic impairment of one identifiable group's ability to elect proportionate representation is the pattern that s.3 challenges target. The audit's statistical and structural findings — the minority map's position at the 99.99th percentile of 1,010,000 neutral draws, its crossing of four of five structural thresholds (the fifth, anchoring, is neutral for both maps), the identified communities affected — are the evidentiary record a s.3 applicant would need to assemble. On the community-of-interest side of that record, the Federal Court's decision in <em>Raîche v. Canada</em> (2004 FC 679) is the leading Canadian authority: the court there required the federal Electoral Boundaries Commission to revisit boundaries that had ignored Acadian community of interest in New Brunswick. The audit's municipal-anchoring measurements and its specific community findings — Airdrie split into four districts, the chair-flagged urban-edge anomalies in northwest Calgary — are the same kind of evidence the Federal Court treated as legally cognizable. Whether that record meets the constitutional threshold is a legal question this audit does not decide; the audit reports the measurement.`,framework_p3:`The committee's legality as a process is a separate question. Alberta's <em>Electoral Boundaries Commission Act</em> does not expressly prohibit the legislature from constituting a parallel redistricting body, because the Act contemplates that the legislature will enact the final boundaries through ordinary legislation regardless. Whether the committee process, if it produces a map with the structural and statistical profile of the minority proposal, could survive a s.3 Charter challenge turns on whether effective representation is achievable under the resulting boundaries — the same test that would apply to any commission-produced map.`,h_quebec:`The Quebec Contrast`,quebec_p1:`Quebec offers the comparison most relevant to Alberta's situation. Quebec's Commission de la représentation électorale (CRE) is a permanent, independent electoral boundaries body, not an ad hoc commission constituted per redistribution cycle. The CRE operates continuously and cannot be dissolved or bypassed by cabinet action. Under Quebec's <em>Loi électorale</em>, the National Assembly must adopt the CRE's recommendations unless it votes to deviate — and deviations require a two-thirds majority of all members of the Assembly, not a bare legislative majority. The practical effect is that a governing party cannot, acting alone with its own majority, substitute its preferred map for the commission's. Cross-party agreement is constitutionally required to override the independent body's judgment.`,quebec_p2:`Quebec's model emerged partly from lessons about what happens when redistricting is not insulated from partisan control. The contrast with Alberta's current process — where a majority-controlled committee has replaced the commission's work before the legislature has voted on either commission report — illustrates the structural difference between redistricting systems that assume partisan pressure and design against it, versus systems where that pressure has a clearer path to the outcome.`,closing:`The audit will apply the same tests to the Lunty committee's map when it is released. The constitutional and comparative observations above are contextual; the methodology does not change.`},references:{heading:`10: References and Methodology`,heading_aria:`Link to references`,intro:`The underlying methodology draws on established political science, statistics, and legal literature. Full citations follow American Political Science Association (APSA) style; court cases follow Canadian legal convention. The complete reference list appears in the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">technical report</a>. Key sources are listed here.`,h_academic:`Academic literature`,h_cases:`Court cases`,h_statutes:`Statutes`},resources:{heading:`11: Technical Appendix`,heading_aria:`Link to technical`,tag_plain:`Plain Language`,plain_label:`Full public report`,plain_desc:`Long-form, with maps, for general readers`,tag_summary:`Summary`,summary_label:`Summary of findings`,summary_desc:`Plain-language overview, explains every concept from scratch`,tag_academic:`Academic`,academic_label:`Technical report`,academic_desc:`Full methods and citations for researchers`,tag_notebook:`Notebook`,notebook_label:`Interactive notebook`,notebook_desc:`Run the charts yourself in your browser, no install needed`,tag_code:`Code`},about_me:{heading:`About me`,p1:`I'm a student at Mount Royal University. I did this research on my own — it was not assigned as coursework and the university did not commission it. My views are my own and do not represent the university. I have no connection to Elections Alberta, the commission, or any political party.`,p2:`I have voted for different parties in different elections, across the political spectrum. I'm telling you because my political history could affect how I look at this issue. The main protection against it is the method: I tested both maps the same way, wrote down my predictions before looking at the results, and put everything online so anyone can check my work. I paid for this research myself. If you find something I got wrong, I genuinely want to know.`,p3:`Pre-registration records (written before results were examined): <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451.`,p4:`Questions or corrections: <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9: Retractions and Corrections`,heading_aria:`Link to retractions`,conditions_label:`RETRACTION CONDITIONS`,conditions_intro:`Every finding is pre-committed to a specific falsification condition. If any condition below materialises, the finding it names is retracted publicly within 30 days. The overall directional conclusion — that the minority map sits outside the neutral range on multiple independent tests — is retracted only if at least three of the five tests fail.`,c1_title:`Condition 1 — A counter-map exists`,c1_what:`<em>What gets retracted:</em> The structural finding that the Airdrie four-way split and the three chair-flagged boundaries cannot be explained by the minority's stated community-of-interest rationale.`,c1_cond:`Condition: someone produces a legal Alberta map satisfying the minority's own stated reasons — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — and anchors on municipal lines at majority-comparable rates. Open challenge at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,c2_title:`Condition 2 — The Neighbour-Drain pre-registered pass is reversed`,c2_what:`<em>What gets retracted:</em> The Section 3 table entry recording the minority map as a pre-registered PASS on the neighbour-drain adjacency test.`,c2_cond:`Condition: the v2 continuous drain score falls in the extreme upper tail (p &lt; 0.05) of random permutations across the fixed contiguity graph, meaning the pass was a measurement artefact of the v1 binary scoring method rather than a genuine null result.`,c3_title:`Condition 3 — A pre-2026 commission document surfaces`,c3_what:`<em>What gets retracted:</em> The inference that the minority's boundary choices were drafting decisions rather than responses to documented community submissions.`,c3_cond:`Condition: an internal commission document dated before the minority's final boundary choices shows those choices were explicitly driven by community submissions the audit has not seen — not by the six published sub-rationales the audit tested.`,c4_title:`Condition 4 — The 2027 election result contradicts the simulation`,c4_what:`<em>What gets retracted:</em> The Lane 1 finding — that the minority map's seats@50/50 score sits at the 99.99th percentile of 1,010,000 neutral draws.`,c4_cond:`Condition: if the 2027 provincial election is fought on either commission map and the actual partisan seat split contradicts the directional projection from 2023 votes, the Lane 1 percentile findings are revisited against actual results.`,c5_title:`Condition 5 — An Alberta court distinguishes the Quebec SCC ruling`,c5_what:`<em>What gets retracted:</em> The Section 7 procedural argument that the April 16 motion to replace the commission with the Lunty committee sits in the same constitutional class as Quebec's 2024 redistricting freeze.`,c5_cond:`Background: on April 22, 2026 — six days after Alberta's April 16 motion — the Supreme Court of Canada upheld, 7–2 and from the bench, a Quebec Court of Appeal ruling that the Legault government's legislative freeze on its redistricting commission violated the Charter's s.3 democratic-representation guarantee. Condition: a court reviewing the Alberta motion finds it constitutionally distinct — for example, because reassigning the work to an MLA committee differs structurally from a legislative freeze, or because Alberta's effective-representation analysis under s.3 comes out differently than Quebec's.`,corr_label:`DOCUMENTED CORRECTIONS (canonical recomputation, 2026-05-11)`,corr_intro:`The following early finding did not survive reanalysis against official Elections Alberta shapefiles (received 2026-05-06). It is retained here per the audit's pre-committed policy of never deleting failed findings.`,corr_municipal:`<strong>Municipal anchoring (retracted).</strong> Early analysis using provisional map boundaries showed the minority map anchored to municipal lines only 15% of the time — 4.9&times; below the 70–85% Canadian norm. This figure was an artefact of the provisional (DPG-era) boundary reconstructions. On official Elections Alberta canonical shapefiles, both maps anchor within the Canadian norm: majority 80%, minority 72%. The municipal-anchoring <em>divergence</em> between the two maps is not a signal that survives canonical recomputation. The three boundary anomalies flagged by the commission chair (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie) remain and are not affected by this correction.`},suggestions:{heading:`8: Suggestions`,heading_aria:`Link to section 8`,intro:`This audit ran into two data problems that have nothing to do with the commission's work and everything to do with how Alberta's electoral system is designed. Both are fixable.`,advance_p1:`<strong>About half of all Alberta votes now arrive before election day</strong> — advance polls, mobile polls, special ballots. Elections Alberta reports these results as totals for each electoral division, not by specific Voting Area. This means roughly 395,000 NDP and UCP votes cast in 2023 cannot be pinned to any neighbourhood on a map. They are counted; they just can't be located. Every advance voter is checked against a voters list before receiving their ballot, and the list links each voter to their specific Voting Area. Publishing VA-level advance-vote totals would not require any change to the voting process — only to what EA reports.`,advance_p2:`This affects the commissioners too, not just outside analysts. When a commission decides whether to keep Airdrie whole or split it, whether a corridor between two communities makes sense, whether a proposed boundary divides a natural constituency — those are judgments that depend on knowing where voters live. Commissioners work from the same published dataset as everyone else. Half the geographic signal about the communities they are drawing boundaries around is missing for them as well.`,lesser_slave_p1:`There is at least one community in northern Alberta where this gap is total. In the northern part of the Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">show ↗</button> division, there is a Voting Area covering 4,832 km&#178; — larger than Prince Edward Island — where every single vote in 2023 was cast through Elections Alberta's mobile polling team. Those 844 residents' choices are counted in the divisional total but cannot be pinned to any location on a map. The community is entirely invisible in the published election results.`,lesser_slave_p2:`When the commission initially considered eliminating the Lesser Slave Lake division and merging it into a larger riding, it was working without geographic vote data from those communities. The commission eventually preserved the division — after 80+ public submissions, many from the Indigenous communities in the northern part of the riding — invoking a provincial law that allows ridings with First Nations and M&#233;tis communities to have smaller populations than the provincial average. They got there. But the data they were working with didn't show them who was voting in the communities they were deciding to protect.`,ebca_label:`SECTION 15(2) EBCA`,ebca_body:`Section 15(2) of Alberta's <em>Electoral Boundaries Commission Act</em> is a discretionary provision that allows commissions to protect undersize ridings — those more than 25% below the provincial population average — when the riding meets at least three of five specific criteria: (a) geographic area exceeding 20,000 km², (b) distance more than 150 km from the Legislature Building by most direct highway route, (c) absence of any town with more than 8,000 residents, (d) presence of an Indian reserve or a Métis settlement, and (e) whether the riding is coterminous with a boundary of the Province of Alberta. The provision is not automatic; the commission must judge whether the criteria are met. Lesser Slave Lake independently meets four of the five.`,rationale_p1:`The interim rationale for eliminating the riding was population: at roughly 27,000 residents, Lesser Slave Lake sits about 45% below the provincial average, approaching the legal floor. This reads as a straightforward application of the rules. It isn't. Alberta law gives commissions explicit discretion to protect undersize ridings when at least three of five specific criteria apply, and Lesser Slave Lake meets four of them independently. Its area is 69,566 km² (criterion a, threshold 20,000 km²). Its nearest boundary is more than 150 km from the Legislature by highway (criterion b). No town in the riding has a population over 8,000 (criterion c). And the riding contains fourteen Indian reserves and M&#233;tis settlements whose communities share a common northern geography, a common dependence on mobile polling to vote at all, and a collective interest in having a representative primarily accountable to northern Alberta (criterion d).`,rationale_p2:`Under the proposed Mackenzie merger, the collective voice would have been permanently absorbed into a riding where the other party wins by more than two to one, not because those communities changed but because the lines around them did. Each of those four criteria is an objective fact about the riding's geography, not a judgment call. Together they describe a constituency the provision was written to protect: remote, large, sparsely populated, and containing communities whose representation interest cannot be read from raw population numbers. You need three to qualify; Lesser Slave Lake has four. Treating the population shortfall as if it compelled elimination misreads the statute. The commission's reversal was the correct application of the law, not a concession to political pressure.`,banff_p:`Here is the other side of the story: while the Indigenous communities in Lesser Slave Lake were fighting to be counted, the dissenting commissioners proposed protecting a different riding by drawing its boundary through Banff National Park, where no one lives. The commission's own chair called it "a bad faith effort" to claim the legal protection. The phrase is in the commission's official final report. The protection designed for remote communities with Indigenous populations was used, in the minority's map, to defend a boundary through uninhabited wilderness. The communities it was designed to help had to fight for it through public submissions. The Lunty committee will face the same §&#x2009;15(2) decision in November — with no statutory requirement to hold public hearings, and no guarantee the 80 submissions reversing the commission's interim position will carry the same weight a second time.`,census_p1:`<strong>Alberta should wait for the 2026 census before drawing the next map.</strong> Canada counts its population every ten years. The 2026 census enumeration happens in spring 2026; Statistics Canada releases usable sub-provincial data roughly two years later, in 2027 or 2028. The commission that drew the maps assessed in this audit had to use the 2021 census — already four years old when the maps were drawn, and potentially fourteen years old by the time those boundaries retire. Fast-growing cities like Airdrie and Chestermere will change by 40% or more over that window. Rural communities will shrink. The map will be wrong from the day it is used. A straightforward change to the <em>Electoral Boundaries Commission Act</em> could require that any new commission be appointed only after Statistics Canada releases the most current dissemination-area data from the preceding census. The result: maps that reflect where Albertans actually live, not where they lived a decade ago.`,census_p2:`The Lunty committee is operating under the existing statute, which sets no census-timing requirement, and cannot unilaterally delay past its November 2026 deadline. This recommendation applies to a future amendment to the <em>Electoral Boundaries Commission Act</em>, not to the current process. The tension is real: a committee required to deliver a map by November is working from data already five years old by then — naming the constraint is more useful than pretending it does not exist.`,closing:`Neither of these is a finding about the current commission's maps. They are observations about a system that makes accurate electoral analysis harder than it needs to be. They are offered here as practical suggestions, not conclusions. Both are genuinely fixable, and fixing them would make every future commission — and every future audit — work from better ground.`}},editorial_canada:{heading:`Context: Canada is different — and similar`,p1:`Canada belongs to the same family as the U.S., the U.K., and Australia. We elect single members from geographic districts under first-past-the-post. We redraw the lines periodically — federally after each decennial census, provincially on staggered schedules. We inherited the basic machinery from the same Westminster roots. So far, no surprises.`,p2:`What sets Canada apart is the test the lines have to pass.`,p3:`In American constitutional law, the binding rule is <em>one person, one vote</em> — districts must have populations as nearly equal as practicable, and large departures require strict justification. In Canadian constitutional law, the binding rule is different. Section 3 of the <em>Canadian Charter of Rights and Freedoms</em> guarantees every citizen the right to vote. In <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — the 1991 Saskatchewan Reference, the leading case — the Supreme Court of Canada interpreted the right as a right to <em>effective representation</em>, not a right to mathematical equality of district populations.`,p4:`That distinction matters. Effective representation allows district populations to vary, sometimes substantially, when there are good reasons: vast rural geographies one MLA cannot reasonably serve at standard population density, communities of interest that should be kept together, minority representation that mathematical equality would dilute. The Saskatchewan Reference made that flexibility constitutional. The EBCA's 25% population variance — the rule that protects rural Alberta seats — flows directly from it.`,p5:`The catch is that flexibility cuts both ways. If a commission can legitimately depart from population equality for the right reasons, it can also depart from population equality for the wrong ones. Canadian law has no American-style mathematical floor to fall back on. It has the effective-representation test, applied by judges, after the fact, in litigation. Most jurisdictions guard against the wrong reasons with structural protections: federal redistricting commissions are insulated by statute and their recommendations take effect automatically if Parliament does not act on them within a deadline. Quebec uses a permanent independent commission whose work the National Assembly can override only with a two-thirds supermajority. British Columbia operates under a similar default-adopt rule.`,p6:`Alberta is the exception. Under the <em>Electoral Boundaries Commission Act</em>, the commission's report is a recommendation only — the legislature must vote to enact it. Approval is normally a formality. In the 2026 cycle, the commission split 3–2 and produced two competing proposals; the legislature created a separate MLA committee, chaired by a Premier-appointed MLA, to choose between them. Nothing in Canadian constitutional law required the committee to exist. Nothing requires its choice to follow the commission's process. This is the structural gap this audit is examining.`,p7:`So when Canadian courts say "gerrymander" isn't their legal vocabulary, they are not saying the underlying concept does not apply here. They are saying the test is different — effective representation, not mathematical equality. Whether the minority proposal meets that test is exactly the question this audit has measured the geometry against, and exactly the question only a judge can answer definitively. The <em>Saskatchewan Reference</em> reasoning in full, the contrast with other provinces, the standing question, and the available reform pathways are treated in <a href="#references">the references section below</a>.`},chrome:{back_to_top:`Back to top`,license_title:`Creative Commons Attribution-NonCommercial-ShareAlike 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Back to Stakes`,lightbox:{fig_aria:`Figure enlarged view`,fig_close_aria:`Close enlarged figure (Esc)`,map_aria:`Map zoom viewer`,map_close_aria:`Close map viewer`,close_title:`Close (Esc)`},participation:{heading:`Help us refine MapExplorer`,body:`As you explore, we track which maps and districts you visit and periodically send the data to our research database. Sharing a view also saves where you ended up. The goal: understand what's useful and make the tool better.`,no_collect:`We never collect your name, IP address, or precise location. Everything is anonymized in your browser before it leaves. We couldn't identify you from the data even if ordered to.`,dnt:`Your browser has Do Not Track enabled. No is pre-selected on your behalf. You can still choose Yes.`,no_thanks:`No thanks`,yes_help:`Yes, I'll help`,privacy_policy:`Privacy policy`},share:{button:`Share`,button_title:`Share or load a map configuration`,dialog_aria:`Share map configuration`,close_aria:`Close share panel`,share_label:`Share this configuration`,share_hint:`Type this code into any browser running the audit to load this configuration. The code is never placed in a URL.`,load_label:`Load a configuration`,load_btn:`Load`,load_placeholder:`alpine-eagle-banff`,copy:`Copy`,copied:`Copied!`,copy_failed:`Failed`,unrecognised:`Unrecognised code — check spelling.`},map:{minority:`Minority`,majority:`Majority`,current:`Current`,wasted:`Wasted`,wasted_title:`Efficiency-gap contribution per district`,partisan:`Partisan`,partisan_title:`Colour each district by partisan outcome (UCP blue / NDP orange)`,borders:`Borders`,flagged:`Flagged`,flagged_title:`All 7 configurations flagged by commission chair Justice Miller — switches to minority map automatically`,help_aria:`Map help`,help_title:`How to use the map`,pin_aria:`Pin Map`,pin_title:`Pin Map — prevent auto-pan on district click`,search_placeholder:`Find district…`,zoom_aria:`Map zoom`,clear_aria:`Clear district selection`,clear_title:`Clear selection`,va_hint:`Click within this district to see polling station results`,va_close_aria:`Close polling station detail`,va_close_title:`Close`,object_title:`Alberta electoral district map — full resolution`,ea_credit:`Map data:`,cc_title:`Text content: CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`,votes_suffix:`votes`,total_votes_suffix:`total votes`,pop_prefix:`Pop.`,voting_areas_suffix:`voting areas`,other_maps:`Other maps`,unique_boundary:`Boundary unique to this map`,in_person_votes:`in-person votes (excl. Vote Anywhere)`,load_error_generic:`Could not load the boundary map. Try reloading the page.`,load_error_map:`Could not load the {key} map — check your connection.`,context_minority:`2026 minority proposal · 2023 election results`,context_majority:`2026 majority proposal · 2023 election results`,context_2019:`2019 enacted boundaries · 2023 election results`,tag_min:`Min`,tag_maj:`Maj`,tag_2019:`2019`,skel_1:`Loading Map Explorer…`,skel_2:`drawing Alberta…`,skel_3:`crunching the numbers…`,skel_4:`counting every vote…`,skel_5:`plotting the boundaries…`,skel_6:`almost there…`},map_intro:{heading:`How to use the map`,click_district:`Click any district`,click_district_desc:`see 2023 election results and snap to it`,click_within:`Click within a selected district`,click_within_desc:`see individual polling station results (colour = vote split)`,dblclick:`Double-click a district`,dblclick_desc:`zoom to fill screen; double-click empty space to zoom out`,layers_primary:`Minority / Majority / Current`,layers_primary_desc:`switch the active boundary map`,layers_data:`Partisan / Wasted / Borders`,layers_data_desc:`toggle data layers`,search:`Find district`,search_desc:`jump by name; arrow keys pan, + / − zoom`,escape:`Escape`,escape_desc:`close this viewer`,s4_tip:`In §4, click <em>Show flagged districts on map</em> to highlight the Airdrie split and NW Calgary zone.`,got_it:`Got it`},footer:{title:`Alberta Electoral Boundary Audit — May 2026`,copyright:`© Will Conner 2026 —`,text_label:`Text:`,code_label:`Code:`,translation_label:`Translations:`,translation_credit:`Anthropic Fable 5 (AI) — awaiting native-speaker review`}}},m={en:p,fr:{selector:{label:`Choisir la langue`},disclaimer:{text:`Ce site a été traduit par IA. Certains contenus peuvent encore apparaître en anglais pendant que les traductions sont en cours. Si vous remarquez des erreurs ou souhaitez aider à traduire ce projet, n'hésitez pas à %s.`,link_label:`nous contacter`},opener:{heading:`À qui s'adresse ce document ?`,body:`À nous. À nous tous. Aux ruraux, aux urbains, aux curieux, aux mordus de politique, aux journalistes, aux avocats, aux universitaires, aux élus — à nous tous. Parce que cela nous touche tous. Que vous aimiez ou non le parti au pouvoir, ce que la commission divisée a produit ne s'était jamais vu auparavant. Et cela nous donne l'occasion d'observer la mécanique de l'intérieur comme nous n'avions jamais pu le faire. Nous pouvons maintenant établir un point de repère — une série de tests, et tout ce qui suivra pourra être évalué à cette aune. Laissez-moi vous montrer ce que j'ai trouvé.`},stakes:{q1:{heading:`La carte proposée est-elle un découpage partisan ?`,body:`« Gerrymander » n'est pas un terme employé par les tribunaux canadiens. Mais s'il l'était — au sens courant que la plupart des gens lui donnent — les éléments de cet audit appuieraient raisonnablement la qualification de la <em>proposition minoritaire</em>, si elle était adoptée, comme une carte fortement remaniée à des fins partisanes. Quatre des cinq tests structurels de cet audit signalent la <em>proposition minoritaire</em> et aucun ne signale l'autre (la <em>proposition majoritaire</em>) ; le cinquième test est neutre pour les deux cartes.`,footnote:`Les noms « majorité » et « minorité » proviennent d'une division 3 contre 2 au sein de la Commission de délimitation des circonscriptions électorales (présidée par le juge Miller), qui a produit deux propositions concurrentes plutôt qu'une seule recommandation. L'assemblée législative a depuis écarté les deux et confié le redécoupage à un comité de cinq MLA (députés provinciaux) présidé par Brandon Lunty (un MLA nommé par le Premier ministre) ; ce comité supervise un Comité consultatif indépendant de quatre membres — deux nommés par le Premier ministre (l'hon. Monte Solberg et Darwin Durnie) et deux par le chef de l'opposition (le D<sup>r</sup> Gerard Kennedy et Brent Robinson) — chargé de produire une nouvelle proposition de 91 circonscriptions avant l'échéance de novembre 2026.`},q2:{heading:`Que signifie « gerrymander » en droit canadien ?`,body:`Rien. Le critère canadien est différent : il s'agit de savoir si les limites garantissent aux électeurs une <em>représentation effective</em> au sens de l'article 3 de la Charte. La proposition minoritaire soulève de sérieuses questions sous ce critère ; seul un juge peut y répondre de façon définitive, et personne n'en a saisi un.`},q3:{heading:`Qu'est-ce qui est en jeu pour les Albertains ?`,body:`Lors d'un vote provincial à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel : moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Ce déséquilibre compte parce qu'à 58 sièges sur 87 (une majorité des deux tiers) le parti au pouvoir débloque des pouvoirs procéduraux exceptionnels. Il peut écarter les délais d'avis habituels et faire franchir à un projet de loi public plusieurs étapes législatives en une seule journée, contournant les freins délibératifs qui le contraignent normalement. Savoir si l'inclinaison de la proposition minoritaire est assez forte pour porter un parti au-delà de ce seuil de 58 sièges à des parts de vote <em>autres</em> que 50/50 est une question que cet audit n'a pas encore examinée. Savoir si ce déséquilibre est acceptable est une question pour les Albertains, et non pour cet audit.`},cta_law:`Lire le contexte juridique →`,cta_methods:`Voir notre méthodologie →`,scorecard_h:`Le tableau de bord`,scorecard_fig_alt:`Diagramme de dispersion : l'écart d'efficacité sur l'axe horizontal, le nombre de tests structurels échoués sur l'axe vertical. La carte adoptée en 2019 et la carte majoritaire de 2026 se regroupent dans le coin sécuritaire en bas à gauche. La carte minoritaire de 2026 apparaît seule dans la région des valeurs aberrantes en haut à droite.`,scorecard_fig_caption:`Les deux voies sur une seule image. Horizontal : l'ampleur du biais sur l'indice d'équité partisane (à droite = plus favorable au UCP). Vertical : combien des cinq tests d'équité structurelle la carte échoue. Le coin inférieur gauche est la zone sécuritaire où les procédures neutres aboutissent régulièrement ; le coin supérieur droit est la région des valeurs aberrantes. La carte adoptée en 2019 et la majoritaire de 2026 se trouvent dans le coin sécuritaire. La minoritaire de 2026 se trouve seule dans la région des valeurs aberrantes.`,scorecard_intro:`Deux mesures indépendantes appliquées aux deux cartes selon les mêmes seuils pré-enregistrés. La structure n'utilise que la forme des lignes — aucun résultat électoral. Les chiffres testent comment les lignes convertissent les votes en sièges. Les deux voies aboutissent à la même conclusion.`,scorecard_close:`Deux mesures indépendantes, une seule réponse. La convergence est le signal unique le plus fort de l'audit.`},head:{title:`Audit des limites électorales de l'Alberta`,meta_description:`Audit statistique de la commission albertaine de délimitation électorale de 2026 — 1 010 000 cartes neutres, fichiers officiels d'Elections Alberta, tests pré-enregistrés.`},nav:{skip_to_content:`Aller au contenu`,home_aria:`Retour en haut`,theme_aria:`Basculer le mode sombre / clair`,theme_title:`Basculer le mode sombre`,nav_aria:`Ouvrir la table des matières`,drawer_top:`↑ Haut`,stakes:`Enjeux`,findings:`Constats`,history:`Histoire`,reform:`Réforme`,notes:`Notes`,group_overview:`Vue d'ensemble`,group_audit:`L'audit`,group_context:`Contexte`,group_forward:`Aller de l'avant`,group_apparatus:`Appareil`,why:`Pourquoi est-ce important ?`,map:`La carte en un coup d'œil`,split:`Comment la commission s'est divisée`,litmus:`Test décisif de 1 010 000 cartes`,crack_pack:`Fractionner, entasser, drainer`,for_you:`Ce que cela signifie pour vous`,impact:`Conséquences sur le terrain`,gerrymanders:`Découpages partisans nets`,history_full:`Une histoire du découpage partisan`,canada:`Le Canada est différent`,november:`Novembre`,lunty:`Lunty`,invisible:`L'invisible`,suggestions:`Suggestions de réforme`,retractions:`Rétractations`,references:`Références`,resources:`Ressources`,technical:`Ressources techniques`},hero:{h1:`Audit des limites électorales de l'Alberta`,subtitle:`La commission albertaine a produit deux cartes de circonscriptions en 2026. Cet audit les a comparées — en appliquant les mêmes tests, également aux deux — pour déterminer si elles traitent les électeurs de la même manière.`,badge:`Cartes officielles d'Elections Alberta — publiées en mai 2026`,cover_note:`Cliquez pour zoomer et explorer les trois propositions de limites simultanément. Verrouillez la vue et passez d'une carte à l'autre — les frontières bougent, les électeurs restent. Faites défiler pour voir l'analyse.`,cover_note_1:`Cette carte est la meilleure porte d'entrée. Cliquez pour zoomer et explorer. Les boutons en haut permettent de basculer entre la carte minoritaire, la carte majoritaire et les limites adoptées en 2019 — ou de superposer les trois pour voir exactement où elles divergent. <strong>Detail</strong> colore chaque zone de vote selon le résultat de 2023 ; <strong>Trend</strong> ajoute un ombrage partisan par circonscription (bleu UCP, orange NDP) ; <strong>Lines</strong> active ou désactive les limites. <strong>Find</strong> permet de sauter à une circonscription par son nom.`,cover_note_2:`Essayez de verrouiller l'affichage et de passer d'une carte à l'autre — observez une limite se déplacer tandis que les électeurs en dessous restent en place. C'est toute la question en un seul geste.`,cover_note_3:`Quand vous avez fini d'explorer, faites défiler vers le bas pour le résumé. Pour l'analyse technique complète, voir la section Ressources. Toutes les données proviennent des fichiers officiels d'Elections Alberta et d'autres dossiers gouvernementaux et libres.`,image_alt:`Cartes des circonscriptions électorales de l'Alberta — proposition minoritaire de la commission, coloriée selon les votes de 2023`,map_hint:`Cliquer pour explorer de façon interactive`,btn_title:`Cliquer pour ouvrir la carte interactive`,btn_aria:`Cliquer pour explorer de façon interactive`},boundary:{heading:`Ce que cet audit peut et ne peut pas vous dire`,can_1:`La géométrie de la carte minoritaire franchit 4 des 5 seuils structurels pré-enregistrés <em>sans utiliser aucune donnée électorale</em>. Le cinquième (l'ancrage) est neutre. La majoritaire n'en franchit aucun des 4 déclenchés. Ces tests mesurent des propriétés des lignes de limites elles-mêmes — forme des circonscriptions, ancrage municipal, étalement de la population — et atteignent la conclusion avant qu'un seul vote ne soit compté.`,can_2:`Séparément, quand les données électorales sont prises en compte, la carte minoritaire se situe au 99,99<sup>e</sup> centile de 1,01 million de cartes de comparaison tracées algorithmiquement selon les mêmes règles statutaires. Moins de 100 de ces 1,01 million de cartes neutres atteignent le même déséquilibre de sièges. Le signal statistique combiné est d'environ 1 sur 14,5 millions sous un processus de tracé neutre. Deux instruments indépendants — géométrique et statistique — aboutissent à la même conclusion.`,can_3:`Trois des configurations que contient la proposition minoritaire ont été signalées par écrit par le président de la Commission, le juge Miller, au §5.8.2 du rapport majoritaire et à l'annexe C. Les tests de l'audit ont été menés sans connaissance de ses signalements et font ressortir les mêmes régions. Un troisième instrument indépendant — judiciaire — converge sur les mêmes limites.`,cant_1:`L'audit n'établit <strong>pas</strong> qu'un commissaire ait eu l'intention de produire les effets partisans qu'il mesure. La géométrie des limites ne peut révéler l'intention.`,cant_2:`L'audit ne prédit <strong>pas</strong> ce que le comité Lunty choisira, ce que sera le vote de novembre 2026, ni comment les Albertains réagiront.`,cant_3:`L'audit ne prédit <strong>pas</strong> comment un tribunal trancherait si une contestation fondée sur la Charte était intentée contre l'une ou l'autre proposition.`,cant_4:`L'audit n'affirme <strong>pas</strong> que le chiffre de 1 sur 14,5 millions est la probabilité qu'un découpage partisan se soit produit. Ce chiffre est la probabilité de queue de la géométrie minoritaire sous une hypothèse nulle algorithmique neutre. C'est une preuve que l'hypothèse nulle neutre est implausible. Ce n'est pas une probabilité a posteriori d'intention partisane — cette question exige des éléments que la géométrie ne peut fournir.`,cant_5:`L'audit ne dit <strong>pas</strong> à un électeur quelle position adopter ni quoi faire de cette information. Le choix vous appartient.`},editorial_intro:{heading:`Qu'est-ce que le redécoupage et pourquoi cela compte`,p1:`Chaque électeur de l'Alberta vit dans une <em>circonscription électorale</em> — une portion de la province qui élit une personne à l'assemblée législative. Il y a 87 circonscriptions. Chaque circonscription élit un MLA. Quand vous votez à une élection provinciale, vous choisissez le MLA de la circonscription où vous habitez. C'est tout le lien que la plupart des Albertains entretiennent avec l'assemblée législative : un MLA, une circonscription, un vote.`,p2:`Ces limites ne sont pas permanentes. Les gens déménagent, les quartiers grandissent, les régions rurales se vident, les villes s'étendent. Tous les huit à dix ans, l'Alberta est censée redessiner les limites pour que chaque circonscription soit à peu près de la bonne taille et reflète la façon dont les Albertains vivent réellement aujourd'hui. L'organisme qui s'en charge est la <em>Commission de délimitation des circonscriptions électorales</em> — une commission indépendante composée de juges, d'avocats et de membres du public, et non de politiciens.`,p3:`C'est le processus standard. Cette fois, le processus standard a produit quelque chose d'inhabituel. Les cinq membres de la commission se sont divisés 3 contre 2 sur ce à quoi la carte devait ressembler et, plutôt que de s'entendre sur une seule recommandation, ils en ont produit deux : une <em>proposition majoritaire</em> (appuyée par trois commissaires) et une <em>proposition minoritaire</em> (appuyée par deux). Les deux sont sur la table — et l'assemblée législative les a toutes deux écartées. Un comité distinct de MLA présidé par Brandon Lunty — nommé par le Premier ministre pour cette décision précise — supervise désormais un Comité consultatif indépendant de quatre membres, constitué en vertu de la Motion gouvernementale 37 (adoptée le 21 avril 2026), chargé de produire une nouvelle carte de 91 circonscriptions. L'assemblée législative doit approuver ce que le comité livrera avant novembre 2026.`,p4:`Pourquoi cela compte pour vous : les limites décident qui est votre MLA. Elles décident quels quartiers, quelles villes et quelles préoccupations sont représentés ensemble. Si votre ville est divisée entre quatre MLA plutôt qu'un seul, aucun représentant unique n'est responsable de la ville dans son ensemble. Si votre communauté d'intérêts — une petite ville, une région rurale, un centre-ville — est divisée entre plusieurs circonscriptions, votre voix sur les décisions provinciales est diluée. La carte façonne aussi quel parti peut former un gouvernement, et à quelle marge. La conclusion précise de l'audit (que la proposition minoritaire se situe dans un extrême structurel) est la raison pour laquelle vous lisez ce site, mais la question plus large est plus ancienne et s'applique à chaque cycle de redécoupage : les limites reflètent-elles la façon dont les Albertains vivent, ou façonnent-elles la politique qui suit ?`,p5:`Le reste de cette page parcourt ce que les deux cartes proposées font réellement.`,key_terms_lead:`Termes clés dans cette section — cliquez pour lire :`},editorial_reflect:{heading:`Interlude : ce que cela signifie pour vous et votre communauté`,intro_p1:`Mettons de côté, pour un instant, la question de savoir quel parti gagne ou perd des sièges. Les politiciens et les partis tendent à présenter cela comme une lutte pour la concentration du pouvoir à l'assemblée législative, et à cette échelle c'en est une. Mais la concentration du pouvoir à l'assemblée n'est pas là où vous vivez ces cartes. Vous les vivez à travers trois questions concrètes sur votre propre circonscription :`,intro_q1:`Où vit votre MLA ?`,intro_q2:`Est-il investi dans votre communauté ?`,intro_q3:`Les exigences de la tête vont-elles dominer celles de la queue ?`,intro_p2:`Tout autre cadrage — avantage partisan, seuil de supermajorité, extrême statistique — renvoie en fin de compte à ces trois questions. Les cinq échelons ci-dessous parcourent la manière dont chaque carte proposée y répond, à cinq échelles.`,you_h:`Vous.`,you_p:`Votre circonscription électorale décide qui vous représente à l'assemblée législative. En ce moment, vous vivez dans l'une des 87 circonscriptions. Sous les deux cartes proposées, vous pourriez vous retrouver dans une autre — possiblement avec un autre MLA, possiblement rattaché à des communautés voisines différentes. Si vous ne savez pas dans quelle circonscription vous êtes en ce moment, ou qui est votre MLA, vous n'êtes pas seul : la plupart des Albertains ne sauraient nommer leur MLA. Mais les limites ne sont pas abstraites. Elles décident dont le numéro de téléphone est sur le mur du bureau de votre représentant local, dont la pétition de quartier porte votre nom, dont les préoccupations votre MLA entend en premier. La recherche par code postal sur ce site indique dans quelle circonscription vous vous trouvez sous chaque proposition. Si votre circonscription change, votre représentant change — et la relation de votre représentant avec votre communauté change avec lui.`,community_h:`Votre communauté.`,community_p:`Les communautés ne sont pas abstraites non plus. La zone de fréquentation d'une école secondaire, une chambre de commerce, une communauté religieuse, une association de quartier — ce sont de véritables regroupements de personnes ayant des préoccupations locales communes. Lorsqu'une limite coupe à travers eux, aucun MLA unique n'est responsable de l'ensemble. Prenez Airdrie sous la proposition minoritaire : une ville d'environ 85 800 habitants découpée en quatre circonscriptions, chacune ancrée à un arrière-pays rural différent. Aucun représentant unique n'est responsable d'Airdrie comme ville. La même dynamique se joue partout où une ville, un quartier ou une communauté d'intérêts reconnue est divisée — plus la division est grande, plus la représentation est faible. L'audit mesure l'<em>ancrage municipal</em> (la fraction du périmètre de chaque circonscription qui suit les limites municipales existantes), et la proposition minoritaire obtient un score nettement inférieur à la majoritaire sur ce test.`,municipality_h:`Votre municipalité.`,municipality_p:`Lorsqu'une ville est fragmentée entre de nombreux représentants, sa capacité à négocier sur les décisions provinciales s'affaiblit. Un conseil qui demande du financement pour le transport en commun, une commission scolaire qui négocie une nouvelle école, un maire qui fait pression pour des prolongements d'autoroute — chacun de ces dossiers progresse mieux quand la ville peut s'appuyer sur quelques MLA qui doivent rendre des comptes à la ville dans son ensemble. La proposition minoritaire divise le quadrant nord-ouest de Calgary entre plusieurs circonscriptions dont les schémas de répartition des voix suggèrent l'<em>entassement</em> (concentrer les électeurs d'un parti dans quelques sièges à forte marge) en plus du <em>fractionnement</em> (répartir les électeurs de l'autre parti dans plusieurs sièges à faible marge). Savoir si ce schéma est intentionnel est une question à laquelle l'audit ne peut pas répondre — la géométrie des limites ne révèle pas l'intention. Ce qu'il peut dire, c'est que les quatre mesures statistiques signalent les mêmes circonscriptions que les tests structurels signalent, et que la proposition alternative ne produit pas la même empreinte.`,region_h:`Votre région.`,region_p1:`Si vous vivez en dehors des villes de l'Alberta, vous avez probablement remarqué que les conversations politiques sur les limites semblent toujours centrer les villes. C'est une plainte légitime, alors soyons directs sur ce que cet audit dit et ne dit pas sur l'Alberta rurale.`,region_p2:`Ce qu'il <strong>ne dit pas</strong> : que l'Alberta rurale a trop de sièges. L'EBCA permet aux populations des circonscriptions de varier jusqu'à 25 % afin qu'un MLA rural ne représente pas une géographie de la taille du sud de la France. Les tribunaux canadiens traitent cette variance comme légitime. Les deux cartes proposées la préservent. Rien dans cet audit ne change cela.`,region_p3:`Ce qu'il <strong>dit</strong> : en plusieurs endroits sur la proposition minoritaire, des communautés rurales sont rattachées comme <em>queue</em> d'une circonscription dont le centre de population se trouve dans une ville. Regardez comment la proposition minoritaire traite Airdrie — une ville d'environ 85 800 habitants découpée en quatre circonscriptions, chacune prolongée dans un tronçon différent de la campagne rurale. Le centre de population de chaque nouvelle circonscription est la portion urbaine, pas la queue rurale. Un MLA élu d'une telle circonscription est le plus susceptible d'habiter, de faire campagne et de prioriser là où sont les voix — ce qui signifie que les communautés rurales autrefois représentées par un MLA rural dédié deviennent l'arrière d'un siège dirigé par la ville. Ce schéma se répète sur la proposition minoritaire d'une manière qu'il ne se répète pas sur la proposition majoritaire.`,region_p4:`L'audit ne propose pas de retirer des sièges à l'Alberta rurale. Il demande si les limites respectent les communautés rurales que ces sièges sont censés représenter, ou si la géographie rurale est utilisée comme ballast pour absorber les votes urbains dans des circonscriptions dont le centre est ailleurs. Si vous vivez dans l'une de ces queues rurales, la question de savoir laquelle des cartes sera adoptée décide si votre MLA représente la communauté rurale où vous vivez réellement, ou un district urbain dont les limites incluent simplement votre terrain.`,province_h:`Votre province.`,province_p:`L'assemblée législative est ce que vous obtenez quand vous additionnez les réponses de chaque circonscription aux trois questions ci-dessus. Si la plupart des circonscriptions sont ancrées à des communautés dont les MLA y vivent réellement, l'assemblée représente ces communautés. Si la plupart des circonscriptions ont des queues rurales rattachées à des têtes urbaines, l'assemblée représente les têtes — et les queues obtiennent l'attention qui reste. La question partisane — quel parti remporte la majorité — est en aval de cela. La question de la supermajorité — savoir si un parti franchit 58 des 87 sièges et débloque des raccourcis procéduraux comme la levée des délais d'avis ou l'accélération de projets de loi à travers plusieurs étapes en une seule journée — est en aval de <em>cela</em>. Lors d'un vote provincial hypothétique à 50/50, les mesures de l'audit placent la proposition minoritaire dans un extrême structurel : moins de 100 des 1,01 million de cartes neutres de comparaison produisent un déséquilibre de sièges comparable. Savoir si ce déséquilibre porte un parti au-delà de 58 sièges aux parts de vote que les Albertains livrent réellement est une question que cet audit n'a pas encore directement examinée ; les questions d'ouverture en haut de cette page sont honnêtes sur cette lacune. Savoir si la réponse à l'une de ces questions compte assez pour agir est, encore une fois, une question pour vous.`},editorial_history:{heading:`Contexte : une brève histoire du découpage partisan`,p1:`Le mot vient de 1812. Le gouverneur du Massachusetts Elbridge Gerry a approuvé une carte sénatoriale dont les circonscriptions étaient si tordues pour favoriser son parti qu'un caricaturiste bostonien en a dessiné une comme une salamandre — ailes, griffes, langue fourchue. Le jeu de mots du caricaturiste, <em>Gerry-mander</em>, est resté. La forme aussi : deux siècles plus tard, le mot signifie toujours tracer des limites électorales pour produire un résultat partisan.`,p2:`Le terme perdure parce que le problème perdure. Partout où les électeurs choisissent des représentants à partir de circonscriptions géographiques, quelqu'un doit tracer les limites, et les limites peuvent être tracées de plusieurs façons. Différents pays sont arrivés à différentes réponses sur qui devrait faire le tracé et ce qui devrait l'encadrer.`,p3:`<strong>Les États-Unis</strong> traitent le découpage partisan comme un problème que les tribunaux fédéraux ne peuvent généralement pas régler. Dans <em>Rucho v. Common Cause</em> (2019), la Cour suprême des États-Unis a statué que les découpages partisans sont des « questions politiques » qui échappent à sa compétence. Certains États (Californie, Michigan) ont réagi en créant des commissions citoyennes indépendantes pour tracer leurs propres limites ; d'autres (Texas, Caroline du Nord) ont continué à tracer des cartes ouvertement partisanes et les ont défendues en s'appuyant sur le fait que <em>Rucho</em> le permet.`,p4:`<strong>Le Royaume-Uni</strong> utilise quatre Commissions permanentes de délimitation — une pour l'Angleterre, l'Écosse, le Pays de Galles et l'Irlande du Nord — composées de juges et de hauts fonctionnaires. Elles retracent les limites tous les huit ans environ selon des règles fixes (égalité de population, cohérence géographique, respect des limites des administrations locales). Le Parlement peut en théorie rejeter les recommandations des commissions, mais en pratique ne le fait pratiquement jamais ; par convention, le jugement des commissions tient.`,p5:`<strong>L'Australie</strong> délègue le travail à la Commission électorale australienne, une agence fédérale indépendante avec pleine autorité sur l'administration des élections et sur les limites. Les redécoupages ont lieu automatiquement quand le nombre de sièges d'un État change ou que sept ans se sont écoulés depuis le dernier. Les décisions des commissaires peuvent être révisées sur des motifs procéduraux mais pas sur des motifs partisans. Comme au Royaume-Uni, le découpage partisan tel que les Américains le connaissent est pratiquement inconnu.`,p6:`Ces trois cas encadrent le spectre : tribunaux qui restent à l'écart (États-Unis), commissions indépendantes avec forte déférence parlementaire (Royaume-Uni), et agence indépendante permanente avec pleine autorité (Australie). Le Canada se situe encore ailleurs — ce que la prochaine section aborde.`},glossary:{more_link:`En savoir plus →`,"electoral-district":{term:`Circonscription électorale (ED)`,definition:`La zone géographique qui élit un membre à l'assemblée législative provinciale. Souvent abrégée en « ED » (electoral district) après la première mention. Chaque ED a un MLA. (Le mot « riding » désigne habituellement les circonscriptions fédérales ; dans le contexte provincial, le terme propre est circonscription électorale.)`},riding:{term:`Riding`,definition:`Dans l'usage canadien, ce terme désigne le plus souvent une circonscription électorale fédérale. L'équivalent provincial albertain est appelé « circonscription électorale » (ED). L'audit emploie le terme provincial tout au long.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly (député provincial) — la personne élue d'une circonscription électorale pour la représenter à l'assemblée législative de l'Alberta.`},ucp:{term:`UCP`,definition:`United Conservative Party (Parti conservateur uni) — le parti provincial actuellement au pouvoir en Alberta. Formé en 2017 par la fusion des progressistes-conservateurs et du Wildrose Party ; au gouvernement depuis 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party (Nouveau Parti démocratique de l'Alberta) — l'opposition officielle actuelle de l'Alberta. Le NDP de l'Alberta a formé le gouvernement de 2015 à 2019.`},gerrymander:{term:`Gerrymander (découpage partisan)`,definition:`Une carte tracée de telle façon qu'un parti politique remporte plus de sièges que sa part du vote ne le suggérerait. Le mot vient d'une circonscription du Massachusetts de 1812 en forme de salamandre. Ce n'est pas un terme juridique au Canada, mais le concept est largement étudié.`},cracking:{term:`Fractionnement (cracking)`,definition:`Technique de découpage partisan qui divise un bloc d'électeurs entre plusieurs circonscriptions de sorte qu'il n'atteint jamais la majorité dans aucune. Par exemple, diviser une ville entre quatre circonscriptions pour que ses électeurs y soient minoritaires.`},packing:{term:`Entassement (packing)`,definition:`Technique de découpage partisan qui concentre les électeurs d'un parti dans un petit nombre de circonscriptions. Le parti remporte ces circonscriptions de manière écrasante mais « gaspille » beaucoup de votes — laissant moins de ses électeurs disponibles pour concurrencer dans d'autres circonscriptions.`},draining:{term:`Drainage (draining)`,definition:`Terme employé par cet audit pour un effet secondaire du fractionnement et de l'entassement : les votes gaspillés que ces techniques produisent sont poussés dans des endroits stratégiquement choisis, modifiant le caractère politique des circonscriptions électorales voisines. C'est un cadrage propre à l'audit plutôt qu'un concept établi dans la littérature sur le redécoupage — l'audit teste cet effet et trouve des résultats compatibles avec lui, mais le traite comme exploratoire plutôt que comme une méthodologie consolidée.`},anchoring:{term:`Ancrage (anchoring)`,definition:`À quel point les limites proposées suivent fermement les lignes municipales existantes (limites de ville, de village). Une carte fortement ancrée respecte la plupart de ces lignes ; une carte faiblement ancrée s'en écarte souvent — surtout aux endroits politiquement importants, ce qui est un signal structurel d'alerte.`},"charter-s3":{term:`Article 3 de la Charte`,definition:`L'article de la Charte canadienne des droits et libertés qui garantit aux citoyens le droit de vote. Les tribunaux canadiens l'ont interprété non comme une règle stricte « une personne, un vote », mais comme un droit à une « représentation effective ».`},"effective-representation":{term:`Représentation effective`,definition:`Le critère que les tribunaux canadiens appliquent quand ils jugent des limites électorales. Cela signifie que les électeurs doivent avoir une voix significative — non pas seulement l'égalité numérique des populations des circonscriptions, mais aussi la reconnaissance des liens communautaires, de la géographie et de la représentation des minorités. L'énoncé de référence vient du Renvoi de la Saskatchewan de 1991 de la Cour suprême du Canada.`},ebc:{term:`Commission de délimitation des circonscriptions électorales (EBC)`,definition:`L'organisme qui trace les limites électorales provinciales de l'Alberta en vertu de l'EBCA. La commission de 2026 était présidée par le juge Miller et s'est divisée 3 contre 2 parmi ses commissaires, produisant deux propositions concurrentes (les propositions majoritaire et minoritaire) plutôt qu'une seule recommandation.`},"lunty-committee":{term:`Comité Lunty`,definition:`Un comité spécial restreint sur les limites électorales composé de cinq MLA, présidé par Brandon Lunty — un MLA nommé par le Premier ministre — établi par la Motion 19 de l'assemblée législative (16 avril 2026), qui a écarté les deux rapports de la commission. Le comité supervise un Comité consultatif indépendant distinct de quatre membres, constitué en vertu de la Motion gouvernementale 37 (adoptée le 21 avril 2026), qui trace la carte réelle ; le comité fait ensuite rapport à l'assemblée législative avant l'échéance de novembre 2026. Les deux organes sont distincts de l'EBC et ne font pas partie du processus standard de l'EBCA.`},"advisory-panel":{term:`Comité consultatif indépendant`,definition:`Le comité de quatre membres nommé par le comité Lunty en vertu de l'alinéa C(d)(ii) de la Motion gouvernementale 37 pour tracer une recommandation de limites à 91 sièges. Le Premier ministre a nommé l'hon. Monte Solberg et Darwin Durnie ; le chef de l'opposition a nommé le D<sup>r</sup> Gerard Kennedy et Brent Robinson. Un cinquième siège — un juge en exercice ou à la retraite pour agir comme président — est resté vacant après que la juge en chef par intérim de l'Alberta a refusé d'en nommer un.`},ebca:{term:`EBCA`,definition:`L'Alberta Electoral Boundaries Commission Act (Loi sur la délimitation des circonscriptions électorales de l'Alberta) — la loi qui régit la manière dont les limites électorales sont tracées dans la province. Elle institue la commission, le processus d'audiences publiques et les règles d'entrée en vigueur d'une nouvelle carte.`},fsa:{term:`Région de tri d'acheminement (FSA)`,definition:`Les trois premiers caractères d'un code postal canadien (la partie lettre-chiffre-lettre). Environ 270 FSA couvrent l'Alberta. La plupart se trouvent entièrement dans une seule circonscription électorale.`}},body:{section_link_aria:`Lien vers la section`,the_map:{heading:`1 : La carte`,p1:`La carte de couverture est la meilleure image unique de cet audit. Voici comment la lire.`,p2:`L'Alberta est divisée en 4 765 zones de vote — de petites zones géographiques qu'Elections Alberta utilise pour compter les bulletins des bureaux de scrutin. Chacune est coloriée selon la façon dont les gens ont réellement voté en 2023 : orange là où les votes NDP sont concentrés, bleu là où les votes UCP sont concentrés. Mais la couleur ne devient sombre et saturée que là où beaucoup de gens vivent. Une zone de vote couvrant des centaines de kilomètres carrés de parc ou de terre agricole reste pâle — presque invisible. La carte s'illumine là où sont les gens, et s'éteint là où ils ne sont pas.`,p3:`C'est très différent de l'Alberta que vous voyez le soir des élections. La plupart des cartes électorales colorient des circonscriptions entières en bleu ou orange uni selon le vainqueur. Les circonscriptions rurales sont géographiquement vastes et le UCP en remporte la plupart, alors l'Alberta du soir d'élection ressemble à un mur de bleu avec de petites poches orange à Edmonton et Calgary. La carte de couverture utilise les mêmes votes et la même géographie — mais les montre pondérés par l'endroit où les gens vivent réellement. Ce qui apparaît est une province où la majeure partie de la population est concentrée dans un arc dense de villes, et ces villes votent très différemment de la carte rurale qui les représente normalement.`,p4:`Les lignes de limites tracées sur la couleur sont les 89 circonscriptions électorales proposées par la commission minoritaire — la carte que cet audit finit par critiquer. Le travail de l'audit est de demander ce que ces lignes font aux personnes en dessous.`,p5:`Cette image est ce qui rend les enjeux clairs. Une province qui semble voter d'une certaine façon sur une carte standard est en réalité une province où la plupart des gens vivent dans des zones qui votent autrement. Une fois la population visible sous les choix de limites, ces choix cessent de paraître aléatoires.`},structural_results:{heading:`Résultats de l'audit structurel — avant toute statistique :`,body:`La carte majoritaire franchit <strong>zéro des cinq</strong> seuils structurels pré-enregistrés. La carte minoritaire en franchit <strong>quatre sur cinq</strong> ; le cinquième (l'ancrage) est neutre — les deux cartes se situent dans la norme canadienne de 70 à 85 %. Ce sont des mesures géométriques — étalement de la population, <button class="vocab-term" data-def="à quel point les frontières d'une circonscription suivent les limites municipales préexistantes, plutôt que de les traverser" aria-expanded="false">ancrage municipal</button>, nombre de divisions d'Airdrie, excédent de population du nord-ouest de Calgary, et les sept configurations de limites que le président de la Commission, le juge Miller, a lui-même signalées par écrit (§5.8.2 du rapport majoritaire et annexe C) — qui ne nécessitent aucune donnée électorale ni aucun échantillonneur statistique. La prochaine section teste les deux cartes contre 1 010 000 cartes neutres générées par ordinateur et aboutit à la même conclusion par un instrument complètement différent. Trois instruments indépendants — géométrique, judiciaire et statistique — convergent.`},clean:{heading:`6 : Quand une carte d'apparence équitable ne l'est pas`,legal_label:`NOTE SUR LA TERMINOLOGIE JURIDIQUE`,legal_body:`« Gerrymandering » n'a pas de définition juridique en droit canadien. Le mot est utilisé partout dans ce rapport au sens politique courant — manipuler les limites électorales pour un avantage partisan. Les critères juridiques qui s'appliquent réellement au Canada sont différents : si les limites assurent une « représentation effective » au sens de l'article 3 de la <em>Charte des droits et libertés</em> (la norme constitutionnelle fixée par la Cour suprême du Canada dans le <em>Renvoi : Circonscriptions électorales provinciales (Sask.)</em> de 1991), et si la commission a suivi les règles de la <em>Electoral Boundaries Commission Act</em> (Loi sur la délimitation des circonscriptions électorales) de l'Alberta. Les constats de l'audit constituent des éléments de preuve pertinents à ces questions juridiques. Ce ne sont pas une preuve d'un tort défini juridiquement, et ce rapport ne les décrit pas en ces termes.`,intro_p1:`La question la plus nette qu'on puisse poser à toute carte électorale est : si la province votait exactement à parts égales entre les deux principaux partis, combien de sièges la carte produirait-elle ? Cela tient l'électorat constant et interroge la carte seule sur ce qu'elle fait.`,intro_p2:`Pour y répondre, l'audit a généré 1 010 000 cartes de l'Alberta neutres mathématiquement, simulées par ordinateur. La simulation a utilisé les fichiers officiels d'Elections Alberta et s'est tenue exactement aux mêmes règles statutaires et limites géographiques que la commission. Les deux cartes de la commission de 2026 ont ensuite été placées dans cette distribution pour voir à quel point elles sont normales. La simulation a fait tourner quatre chaînes indépendantes de 252 500 étapes chacune, avec la graine de base tirée du beacon drand de Cloudflare et pré-enregistrée à l'OSF avant l'exécution.`,howmcmc_label:`COMMENT FONCTIONNE LA SIMULATION`,howmcmc_mcmc:`<strong>MCMC (Markov Chain Monte Carlo)</strong> est une méthode pour explorer un grand espace — ici, l'espace de toutes les cartes légales de l'Alberta — en faisant des pas aléatoires à partir d'un point de départ. Chaque pas propose un petit échange entre circonscriptions adjacentes ; si le résultat reste dans les règles statutaires, il devient le nouveau point de départ. Après suffisamment de pas, les cartes visitées forment un échantillon représentatif des plans légaux. La simulation est amorcée à partir du beacon de hasard public drand de Cloudflare pour empêcher tout tri sélectif des conditions de départ.`,howmcmc_recom:`<strong>ReCom (Redistricting Compiler)</strong> est l'algorithme spécifique utilisé ici. Chaque pas fusionne deux circonscriptions adjacentes en une seule région et la rescindle aléatoirement en deux nouvelles circonscriptions valides, préservant la contiguïté et l'équilibre de population par construction — l'algorithme n'a donc jamais besoin de rejeter une proposition invalide.`,prereg_label:`PRÉ-ENREGISTREMENT`,prereg_body:`Le pré-enregistrement consiste à inscrire les tests exacts, les seuils et les directions prévues avant de regarder les données, et à verrouiller ces engagements dans un dossier public horodaté. L'Open Science Framework (OSF) est le dépôt public où les engagements de cet audit sont déposés. Cela empêche le rétroajustement : si un résultat n'apparaît pas nettement, on ne peut pas modifier le seuil après coup pour le présenter comme étant le test depuis toujours. Les cinq tests structurels et quatre mesures d'équité partisane de cet audit ont été enregistrés à l'OSF avant qu'aucune simulation n'ait été exécutée.`,neutral_p:`En Alberta, la réponse neutre n'est pas 50/50. <em>À travers 1 010 000 cartes légales de l'Alberta simulées par ordinateur, la carte médiane donne au UCP seulement 44,8 % des sièges à un vote de 50/50</em> — une carte typique de l'Alberta sous vote neutre remet au NDP une légère majorité de sièges. C'est contre-intuitif mais mécanique : les électeurs UCP ruraux remportent leurs circonscriptions par des marges de 60-40 (gaspillant beaucoup de votes UCP « excédentaires »), tandis que les électeurs NDP urbains remportent les leurs par des marges plus serrées de 51-49 (gaspillant moins de votes NDP par victoire). En neutralité, le NDP sort gagnant sur l'efficacité des sièges.`,full_dist:`La distribution complète issue de la simulation canonique de 1 010 000 cartes :`,t1_col_a:`Où se situe la carte`,t1_col_b:`Sièges UCP à un vote de 50/50`,t1_r1_a:`Carte médiane de l'Alberta`,t1_r1_b:`44,8 % — légère majorité de sièges NDP`,t1_r2_a:`Carte au 95<sup>e</sup> centile`,t1_r2_b:`47,1 %`,t1_r3_a:`Carte au 99<sup>e</sup> centile`,t1_r3_b:`48,4 %`,t1_r4_a:`<strong>Maximum sur 1 010 000 cartes</strong>`,t1_r4_b:`<strong>sous 51,7 % (moins de 100 plans atteignent cette valeur)</strong>`,seat_count_note:`Note sur les nombres de sièges. Les cartes de la commission de 2026 comptent chacune <strong>89</strong> circonscriptions ; la simulation informatique de l'audit roule sur la carte 2019 à <strong>87</strong> circonscriptions (son substrat de départ) ; le comité Lunty en novembre produira <strong>91</strong>. Tous les pourcentages sont des <em>parts</em> de sièges, comparables d'un dénominateur à l'autre. La simulation utilise la carte 2019 comme point de départ parce que l'algorithme ReCom a besoin d'une carte légalement adoptée pour proposer des échanges — la carte 2019 est la dernière carte électorale de l'Alberta adoptée. Utiliser l'une ou l'autre proposition de commission comme substrat serait circulaire : nous mesurerions si une carte est extrême par rapport à des cartes dérivées d'elle-même.`,pattern_intro:`Les résultats — placer les trois cartes réelles dans cette distribution — pointent vers un schéma de tracé de limites précis et chirurgical.`,sub1_h:`Les quatre mesures statistiques se déclenchent simultanément`,sub1_p:`Quand les fichiers officiels d'Elections Alberta sont utilisés, la carte minoritaire est une valeur aberrante statistique sur chaque mesure d'équité partisane — pas seulement le point de bascule.`,t2_col_a:`Carte`,t2_col_b:`Écart d'efficacité`,t2_col_c:`Moyenne-médiane`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="La déclinaison mesure la différence angulaire entre la courbe sièges-votes pour chaque parti. Les valeurs négatives favorisent le UCP ; les positives favorisent le NDP.">Déclinaison</a>`,t2_col_e:`Sièges à 50/50`,t2_r1_a:`Majoritaire 2026`,t2_r1_b:`+0,04 % (p15,5)`,t2_r1_c:`−3,6 % (p2)`,t2_r1_d:`+0,027 (p81)`,t2_r1_e:`46,1 % (p83)`,t2_r2_a:`Minoritaire 2026`,t2_r2_b:`<strong>+3,96 % (p94,4)</strong>`,t2_r2_c:`<strong>+1,0 % (p99,98)</strong>`,t2_r2_d:`<strong>−0,077 (p1,2)</strong>`,t2_r2_e:`<strong>51,7 % (p99,99)</strong>`,sub1_close:`La carte majoritaire se situe confortablement dans la plage normale sur trois des quatre mesures. Sa différence moyenne-médiane est à p2 dans la direction favorable au NDP — un résultat inhabituel mais qui pointe dans le mauvais sens pour aider le UCP. L'adhésion étroite de la carte majoritaire aux limites municipales place les noyaux urbains à forte présence NDP dans leurs propres circonscriptions compactes, où les votes NDP remportent à des marges efficaces tandis que les victoires UCP rurales tendent à se faire par marges plus larges ; ce léger avantage structurel d'efficacité NDP est ce qui apparaît dans la mesure moyenne-médiane. La carte minoritaire est dans la queue sur les quatre, chacune pointant dans la même direction partisane.`,sub2_h:`Le point de bascule 50/50 : moins de 100 sur 1 010 000 cartes neutres l'atteignent`,sub2_p:`La mesure du point de bascule introduite ci-dessus — sièges UCP à un vote provincial de 50/50 — est la façon la plus intuitive de comparer les trois cartes.`,t3_col_a:`Carte`,t3_col_b:`Sièges UCP à un vote de 50/50`,t3_col_c:`Où elle se situe`,t3_r1_a:`2019 adoptée`,t3_r1_b:`46,0 %`,t3_r1_c:`83<sup>e</sup> centile — dans la plage normale`,t3_r2_a:`<strong>Majoritaire 2026</strong>`,t3_r2_b:`<strong>46,1 %</strong>`,t3_r2_c:`<strong>83<sup>e</sup> centile — bien dans les limites</strong>`,t3_r3_a:`<strong>Minoritaire 2026</strong>`,t3_r3_b:`<strong>51,7 % (46 sièges)</strong>`,t3_r3_c:`<strong>99,99<sup>e</sup> centile — moins de 100 sur 1 010 000 tirages neutres l'atteignent</strong>`,sub2_close:`Moins de 100 sur 1 010 000 cartes neutres simulées par ordinateur ont produit une valeur de <code>seats@50/50</code> aussi élevée que celle de la proposition minoritaire. Sur la base des schémas de vote récents, elle attribuerait au UCP 60 sièges (contre 55 dans la proposition majoritaire). La proposition majoritaire est le genre de carte qu'une procédure neutre génère régulièrement. La proposition minoritaire est le genre de carte qu'il faut viser spécifiquement pour la tracer.`,sub3_h:`Ce que cela signifie en langage clair`,sub3_p:`Les fichiers officiels révèlent une carte statistiquement extrême dans la même direction partisane sur les quatre mesures simultanément. La probabilité conjointe qu'un processus de tracé neutre produise une carte aussi extrême sur les quatre mesures simultanément est d'environ une sur 15 millions (p&nbsp;=&nbsp;6,87×10<sup>−8</sup>, <a href="https://osf.io/6pt83" rel="noopener">test de Fisher combiné pré-enregistré</a>). Ce n'est pas une erreur d'arrondi ni un artéfact de mesure — c'est la même réponse de quatre instruments statistiques indépendants lus dans la même pièce.`,details_summary:`Ce que cette valeur p signifie — et ce qu'elle ne signifie pas`,details_p1:`Une valeur p répond à une question : si la carte avait été tracée par un processus neutre, à quelle fréquence verrions-nous un résultat aussi extrême ou plus extrême ? À p&nbsp;=&nbsp;6,87×10<sup>−8</sup>, la réponse est environ une fois sur 14,5 millions d'essais.`,details_p2:`C'est un test d'hypothèse fréquentiste, et non une mesure d'intention. Il ne dit pas que la commission avait l'intention de pratiquer un découpage partisan, et il ne quantifie pas à quel point la carte est injuste en termes pratiques. Il dit que le motif des limites est statistiquement incompatible avec un processus de tracé neutre — la même conclusion qu'atteindrait un audit randomisé peu importe qui a tracé la carte ou pourquoi.`,details_p3:`Le test a été pré-enregistré avant l'analyse des données (<a href="https://osf.io/w2s8k" rel="noopener">Enregistrement OSF w2s8k</a>). Le pré-enregistrement précise à l'avance l'hypothèse nulle, les mesures et le seuil de rejet, de sorte que le résultat ne peut pas être attribué au choix d'un cadrage favorable après avoir vu les chiffres.`,szat_label:`TEST D'ATTRIBUTION DE LA ZONE DE BASCULE (SZAT)`,szat_body:`Le SZAT est le deuxième test indépendant de l'audit, et il pose une question différente de la simulation : non pas « cette carte est-elle extrême dans l'ensemble ? » mais « les choix de lignes spécifiques sont-ils partisans neutres ? ». Il isole uniquement les zones de vote où la carte minoritaire diffère de la majoritaire — les redessins contestés — et teste si ces choix particuliers, pris ensemble, font basculer l'efficacité des votes dans la direction d'un parti. Parce qu'il ne compare que les points de départ, il contrôle automatiquement tout ce que les deux cartes partagent : la même géographie, les mêmes cibles de population et les mêmes règles statutaires. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Détails techniques et résultats du bootstrap →</a>`,two_q:`<strong>Deux questions, une réponse.</strong> La simulation de 1 010 000 cartes demande : <em>cette carte est-elle extrême comparée à des cartes neutres tracées sur la même géographie albertaine ?</em> Un deuxième test séparé — appelé le <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">test d'attribution de la zone de bascule</a> — pose une question différente : <em>les lignes spécifiques sur la carte sont-elles partisanes neutres ?</em> Il fonctionne en regardant uniquement les zones de vote où la minoritaire a tracé différemment de la majoritaire et en demandant si ces choix particuliers, pris ensemble, ont fait basculer l'efficacité du vote dans la direction d'un parti. Parce qu'il ne compare que les endroits où les deux cartes diffèrent, il contrôle automatiquement tout ce qu'elles partagent — la même géographie provinciale, les mêmes cibles de population, les mêmes règles statutaires. Les deux questions reçoivent la même réponse. C'est pourquoi le chiffre d'un sur 15 millions est un résultat combiné plutôt qu'un seul test : ce sont deux lignes de preuves indépendantes qui convergent.`,super_lead:`Cela explique pourquoi la proposition minoritaire devait être une valeur aberrante statistique aussi extrême (p99,99) contre 1 010 000 simulations neutres. Dans une assemblée de 89 sièges, une supermajorité des deux tiers exige exactement 60 sièges. Les procédures neutres ne produisent pas de résultats à 60 sièges sur la géographie de l'Alberta avec des votes neutres ; atteindre le seuil exige des choix de limites délibérés qui s'écartent de la référence neutre.`,super_label:`POURQUOI UNE SUPERMAJORITÉ COMPTE`,super_body:`Sous le système parlementaire de Westminster canadien, une majorité simple (45 sièges) suffit pour adopter les lois et budgets ordinaires. Une supermajorité des deux tiers (60 sièges) fait davantage. Elle permet au parti au pouvoir d'invoquer la « clôture » pour mettre fin au débat, de réécrire les règles procédurales sans le consentement de l'opposition, et de contrôler la composition de chaque comité législatif. Elle isole également le gouvernement de la dissidence interne : même avec une demi-douzaine de députés d'arrière-ban traversant le parquet, le gouvernement conserve encore une majorité de travail. Une majorité simple vous laisse conduire la voiture ; une supermajorité de 60 sièges vous laisse réécrire le code de la route.`,super_close:`En diluant stratégiquement les électeurs urbains dans les circonscriptions environnantes urbaines-rurales (le schéma d'« hybridation urbaine » identifié dans la voie 2), la proposition minoritaire conçoit exactement le pare-feu structurel nécessaire pour sécuriser ces 60 sièges. Le constat structurel de la voie 2 et le constat statistique de la voie 1 convergent sur la même proposition, la même direction et les mêmes communautés.`,sub4_h:`Confirmation par le test de procédure ciblée`,sub4_p:`Pour s'assurer que ce n'est pas un caprice de la préférence connue de la simulation neutre pour la compacité, l'audit a exécuté une procédure ciblée de gravissement de colline (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et coll. 2022 — cités et décrits dans le rapport technique</a>) dans les deux directions : maximiser les sièges UCP et maximiser les sièges NDP. Même nombre d'étapes (40 000) dans chaque direction, mêmes contraintes statutaires, même géométrie provinciale.`,t4_col_a:`Procédure`,t4_col_b:`Valeur la plus extrême atteinte`,t4_col_c:`Ce que cela nous dit`,t4_r1_a:`MCMC neutre, maximum produit`,t4_r1_b:`sous 51,7 % de sièges UCP @ 50/50`,t4_r1_c:`Le plafond naturel sous un tracé neutre`,t4_r2_a:`MCMC neutre, minimum produit`,t4_r2_b:`~39 % de sièges UCP @ 50/50`,t4_r2_c:`Le plancher naturel sous un tracé neutre`,t4_r3_a:`Gravissement de colline ciblé, maximisation UCP`,t4_r3_b:`<strong>52,9 %</strong>`,t4_r3_c:`Ce qu'une procédure visant délibérément l'avantage UCP peut atteindre`,t4_r4_a:`Gravissement de colline ciblé, maximisation NDP`,t4_r4_b:`<strong>37,9 %</strong>`,t4_r4_c:`Ce qu'une procédure visant délibérément l'avantage NDP peut atteindre (sous le plancher neutre)`,sub4_close:`Le 51,7 % de la carte minoritaire est plus près du plafond ciblé UCP (52,9 %) que de la médiane neutre (44,8 %). Le 46,1 % de la carte majoritaire est à la médiane neutre. La carte adoptée en 2019 et la majoritaire de 2026 tombent toutes deux confortablement dans ce que la procédure neutre produit régulièrement — parts de vote différentes, même zone de résultats sans particularité. La majoritaire prolonge la pratique albertaine de 2019 sur l'axe de l'équité partisane de la même manière qu'elle prolonge la pratique 2019 sur l'ancrage municipal (80,0 % contre 75,2 % en 2019). Deux cartes tracées selon les mêmes règles albertaines, par les mêmes cinq commissaires, dans la même pièce : l'une aboutit là où les procédures neutres aboutissent régulièrement, l'autre aboutit là où il faut spécifiquement viser pour aboutir.`,sub4_quote:`<em>Voilà</em> la forme du constat, et c'est aussi le cadrage qu'un tribunal appliquerait réellement.`,sub5_h:`Écarter les explications alternatives`,sub5_p:`Devant une valeur aberrante statistique de cette ampleur, un audit rigoureux doit écarter les explications innocentes avant d'attribuer ces motifs à une conception délibérée. Les données structurelles (voie 2) démontent systématiquement les défenses alternatives habituelles :`,defense1:`<strong>La défense de la « géographie politique naturelle » :</strong> <em>(« Les électeurs urbains sont naturellement entassés ; la carte ne fait que refléter la géographie de l'Alberta. »)</em> Les 1 010 000 simulations tiennent déjà compte de la géographie naturelle de l'Alberta. La simulation prouve que : si la géographie donne au UCP un avantage de référence en efficacité, celui-ci plafonne naturellement autour du 83<sup>e</sup> au 90<sup>e</sup> centile. La carte minoritaire se situe au 99,99<sup>e</sup> centile — une valeur aberrante extrême <em>même comparée à la référence naturellement biaisée de l'Alberta</em>.`,defense2:`<strong>La défense des « communautés d'intérêts » :</strong> <em>(« Les formes étranges ont été tracées pour garder ensemble des communautés précises. »)</em> Si vous essayez de garder des communautés ensemble, vous suivez les limites municipales. La carte majoritaire a suivi les limites municipales existantes 80 % du temps. La carte minoritaire les a suivies 72 % du temps — toutes deux dans la norme canadienne de 70 à 85 %. Ce que la carte minoritaire fait, en revanche, c'est de diviser activement la ville unifiée d'Airdrie en quatre morceaux distincts, et de placer trois de ses décisions de limites précisément dans les zones urbaines-rurales que le président de la commission a signalées comme géométriquement anormales — des choix non explicables par la logique des communautés d'intérêts.`,defense3:`<strong>La défense de l'« égalité de population » :</strong> <em>(« Ils ont dû tracer des limites bizarres pour s'assurer que chaque circonscription ait exactement la même population. »)</em> La carte minoritaire est en fait beaucoup <em>pire</em> sur l'égalité de population. Son écart absolu moyen (MAD) de population était de 4 707 — 48 % plus large que les 3 180 de la carte majoritaire — la plaçant au 99<sup>e</sup> centile de l'ensemble canonique (seulement 1 carte neutre sur 100 produit un étalement pire). Elle a sacrifié l'égalité de population pour atteindre sa forme.`,defense4:`<strong>La défense de l'« incompétence ou la malchance » :</strong> <em>(« Ils ont simplement tracé une carte bâclée et ont eu de la malchance avec les chiffres. »)</em> Atteindre exactement 60 sièges pour une supermajorité tout en divisant Airdrie en quatre morceaux et en plaçant trois limites précisément dans les zones que le président de la commission lui-même a signalées comme anormales exige une précision chirurgicale. La probabilité conjointe de tracer accidentellement une carte qui atteigne la queue statistique extrême sur quatre mesures partisanes indépendantes simultanément est d'environ <strong>1 sur 15 millions</strong> (p&nbsp;=&nbsp;6,87×10<sup>−8</sup>). On ne tombe pas par maladresse dans le 99,99<sup>e</sup> centile.`,sub5_close:`Ce que les données montrent, c'est que la proposition minoritaire a aggravé à la fois la parité de population et la cohérence communautaire par rapport à ce que les mêmes cinq commissaires ont produit simultanément sous des règles statutaires identiques. L'audit ne détermine pas ce que les commissaires minoritaires entendaient — la géométrie des limites ne peut révéler l'intention — mais l'écart structurel par rapport à l'ensemble neutre et à la production de la proposition majoritaire subsiste indépendamment de l'intention.`,sub6_h:`Note sur la validation croisée R`,sub6_p1:`Une version antérieure de cet audit (utilisant des fichiers de formes approximés plutôt qu'officiels) a effectué une validation croisée de l'ensemble Python ReCom contre l'échantillonneur de Monte-Carlo séquentiel du package R <code>redist</code>. La vérification croisée a produit des résultats instables : sur trois exécutions avec la même graine nominale, la fraction de plans atteignant l'ancienne valeur minoritaire (48,3 % sur la géométrie approximée) était de 5,6 %, puis 28 %, puis 58 % — une défaillance de convergence de l'échantillonneur, pas une découverte. Le compte rendu complet se trouve à <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`Avec les fichiers de formes officiels d'Elections Alberta, le <code>seats@50/50</code> de la carte minoritaire monte à 51,7 % — une valeur que moins de 100 plans sur 1 010 000 plans neutres atteignent. La question de la validation croisée R devient théorique : zéro plan de l'un ou l'autre échantillonneur n'atteint la valeur canonique à des tailles d'échantillon comparables.`,sub6_asymm:`<strong>L'asymétrie autour de 50/50 est plus révélatrice que l'inversion elle-même.</strong> Un balayage de précision de la courbe sièges-votes à une résolution de 0,01 point de pourcentage révèle que la carte minoritaire maintient le UCP au-dessus ou au seuil de majorité législative de 45 sièges jusqu'à une part de vote provinciale UCP d'environ <strong>49,7 %</strong>. C'est techniquement une inversion vote-sièges — le UCP formerait le gouvernement avec la carte minoritaire tout en perdant le vote populaire par 0,3 point de pourcentage — mais 0,3 point est bien dans le bruit ordinaire des sondages, alors en soi ce n'est pas un constat dramatique. Ce qui <em>est</em> dramatique, c'est le contraste : avec la carte <strong>majoritaire</strong>, le UCP devrait <em>remporter</em> le vote populaire par environ 4 points de pourcentage pour atteindre le même seuil de 45 sièges. Les deux cartes font face à la même géographie albertaine et aux mêmes règles statutaires ; l'écart entre elles — 0,3 pp contre +4 pp — est une différence structurelle, pas du bruit.`,sub6_close:`C'est le constat de biais structurel que l'audit tient avec confiance. Il est uniquement géométrique ; il ne dépend d'aucun résultat électoral ; il ne bouge pas quand les sondages bougent.`,sub6_caveat:`<strong>Une réserve que l'audit prend au sérieux.</strong> Un électorat réel n'est pas un 50/50 uniforme. Les électeurs peuvent submerger le penchant structurel de n'importe quelle carte avec assez d'oscillation — un électorat particulièrement contrarié ou inspiré fera basculer le résultat peu importe comment les limites sont tracées. Le test à 50/50 isole <em>la contribution de la carte au résultat</em>, pas le résultat lui-même. Ce qu'il montre, c'est ce que fait la carte lorsque l'électorat ne décide pas à sa place.`,sub7_h:`Le bilan`,sub7_p1:`Le constat central de l'audit est géométrique. <strong>La voie 2 — le tableau de bord d'irrégularité structurelle — est le fondement ; la voie 1 est la preuve que la géométrie fait un travail partisan.</strong>`,sub7_p2:`Le graphique ci-dessous place les deux voies sur une seule image. L'axe horizontal est la voie 1 (l'écart d'efficacité de l'équité partisane, où plus à droite signifie plus favorable au UCP) ; l'axe vertical est la voie 2 (le nombre de tests d'équité structurelle que la proposition échoue, sur cinq, où plus haut signifie plus de problèmes structurels).`,stakes_fig_alt:`Diagramme de dispersion avec l'écart d'efficacité sur l'axe horizontal et le nombre de tests structurels échoués sur l'axe vertical. La carte adoptée en 2019 et la carte majoritaire 2026 se regroupent dans le coin sécuritaire en bas à gauche. La carte minoritaire 2026 apparaît dans la région des valeurs aberrantes en haut à droite.`,stakes_fig_caption:`Les deux façons de mesurer les deux propositions de la commission, tracées ensemble. De gauche à droite : à quel point la proposition paraît biaisée sur le chiffre d'équité partisane — plus c'est à droite, plus cela favorise le UCP. De bas en haut : combien des cinq tests d'équité structurelle la proposition échoue — plus c'est haut, plus c'est mauvais. La carte adoptée en 2019 se trouve dans le coin sécuritaire : basse sur les deux. La proposition majoritaire 2026 reste plate à zéro problème structurel et à un biais partisan quasi nul (+0,1 %). La proposition minoritaire 2026 est une valeur aberrante structurelle sur chaque test qui distingue les deux cartes (4 sur 5 ; le cinquième, l'ancrage, est neutre pour les deux) ; son écart d'efficacité (+4,0 %) se situe juste sous la ligne de seuil albertaine.`,stakes_table_intro:`Les mêmes constats sous forme de résumé simple, en commençant par le constat structurel parce que la preuve validée par croisement l'appuie le plus fortement :`,t5_col_b:`Voie 2 : Structure (géométrie seulement, pas de votes)`,t5_col_c:`Voie 1 : Chiffres (dépendant des votes)`,t5_r1_a:`<strong>Majoritaire 2026</strong>`,t5_r1_b:`nette — ne franchit <em>aucun</em> seuil structurel`,t5_r1_c:`dans la plage normale sur chaque mesure (<code>seats@50/50</code> 46,1 % — p83 ; écart d'efficacité +0,04 %)`,t5_r2_a:`<strong>Minoritaire 2026</strong>`,t5_r2_b:`<strong>franchit 4 sur 5 seuils structurels</strong> par une large marge (ancrage neutre — les deux cartes dans la norme canadienne)`,t5_r2_c:`valeur aberrante statistique sur les quatre mesures d'équité partisane simultanément — <code>seats@50/50</code> 51,7 % (p99,99, moins de 100 sur 1 010 000 l'atteignent) ; écart d'efficacité +3,96 % (p94,4) ; les quatre pré-enregistrées ; Fisher combiné p&nbsp;=&nbsp;6,87×10<sup>−8</sup>`,details2_summary:`Pourquoi la voie 2 porte le dossier — détail technique`,details2_p:`L'audit a pré-enregistré cinq tests d'irrégularité structurelle le 24 avril 2026 avant que les résultats finaux de simulation ne soient compilés. L'ancrage est neutre pour les deux cartes ; sur les quatre tests restants, la minoritaire les franchit tous et la majoritaire n'en franchit aucun. Ces mesures sont géométriques — elles ne dépendent d'aucun échantillonneur statistique ni d'aucune attribution de votes. La voie 1 (les chiffres d'équité partisane) corrobore fortement la voie 2 avec les fichiers de formes officiels canoniques : la minoritaire est une valeur aberrante statistique sur les quatre mesures pré-enregistrées simultanément, avec une probabilité conjointe sous l'hypothèse nulle neutre de p&nbsp;=&nbsp;6,87×10<sup>−8</sup> (test de Fisher combiné pré-enregistré — une méthode qui combine quatre résultats de test indépendants en une seule probabilité en multipliant leurs probabilités de queue individuelles ; le chiffre combiné est bien plus petit que celui de n'importe quel test individuel parce que les quatre pointent dans la même direction ; OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>). La question de savoir si la géométrie inhabituelle de la voie 2 est le <em>mécanisme</em> précis derrière les chiffres de la voie 1 a été testée et la réponse est non — voir <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>. Le test d'attribution de la zone de bascule montre que les choix de limites contestés sont biaisés partisanement, mais la question testée était de savoir si les formes des limites elles-mêmes — le corridor en lasso, l'extension de parc — sont la cause directe de l'oscillation de sièges ; elles ne le sont pas. L'effet sur les sièges vient de la façon dont les réattributions de zones de vote redessinées font basculer l'efficacité du vote d'une circonscription à l'autre, et non des formes en soi. Les deux voies signalent la carte minoritaire ; elles y parviennent par des instruments indépendants. La voie 2 est le constat central. La voie 1 corrobore sans porter.`},impact:{heading:`5 : Effets sur la représentation`,lanes_label:`VOIE 1 ET VOIE 2`,lanes_body:`<strong>La voie 1 (chiffres)</strong> utilise les résultats électoraux pour tester si la carte convertit équitablement les votes en sièges — elle demande comment la carte se comporte à travers différentes répartitions de votes. <strong>La voie 2 (structure)</strong> examine uniquement les lignes tracées — divisions de villes, étalement de population, formes des limites — sans aucune donnée électorale. Chaque voie est indépendante : une carte peut échouer à l'une tout en réussissant l'autre. La proposition minoritaire échoue aux deux ; la majoritaire réussit aux deux.`,intro:`La voie 1 dépend des résultats électoraux selon lesquels vous notez les cartes. La voie 2, non. La preuve structurelle est dans les cartes elles-mêmes — lignes tracées, villes divisées, là où les limites suivent ou non des lignes administratives qui existent pour d'autres raisons. Sur ces tests, les deux cartes ne sont pas proches.`,fig_alt:`Diagramme à barres comparant cinq tests d'équité structurelle côte à côte. Les barres de la carte majoritaire sont à zéro ou bien à l'intérieur des plages sécuritaires. Les barres de la carte minoritaire franchissent le seuil sur quatre des cinq tests par une large marge ; le cinquième (l'ancrage) est neutre pour les deux cartes.`,fig_caption:`Les cinq tests d'équité structurelle, côte à côte. Les barres turquoise représentent la carte majoritaire ; les barres violettes la carte minoritaire. La ligne pointillée dans chaque ligne marque le seuil d'échec. Les barres minoritaires franchissent le seuil sur quatre des cinq tests par une large marge ; le cinquième (l'ancrage) est neutre pour les deux cartes. Les barres majoritaires restent plates à zéro ou bien à l'intérieur de la plage sécuritaire.`,table_intro:`Les mêmes cinq tests sous forme tabulaire, avec le seuil de chaque test indiqué à côté du résultat. La ligne du bas est le <em>résumé</em> de l'audit — le nombre de tests que chaque carte échoue parmi les cinq.`,table_col_test:`Test`,table_col_majority:`Carte majoritaire`,table_col_minority:`Carte minoritaire`,table_col_direction:`Direction / Bénéficiaire`,table_r1_a:`La frontière suit les lignes municipales existantes (norme canadienne de 70 à 85 %)`,table_r1_b:`80 % — dans la norme`,table_r1_c:`72 % — dans la norme`,table_r1_d:`S.O. — les deux dans la norme canadienne`,table_r2_a:`Étalement de la population (plus serré est mieux)`,table_r2_b:`3 180`,table_r2_c:`4 707 — 48 % plus large`,table_r2_d:`Structurel (réduit l'égalité du vote)`,table_r3_a:`Excédent de population du NO de Calgary au-dessus de la moyenne`,table_r3_b:`2,8 %`,table_r3_c:`11,5 %`,table_r3_d:`<strong>UCP</strong> (Entasse les votes NDP urbains)`,table_r4_a:`Limites signalées par le président de la commission`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`S.O.`,table_r5_a:`Division d'Airdrie (minimum contraint : 2)`,table_r5_b:`2 morceaux`,table_r5_c:`4 morceaux`,table_r5_d:`<strong>UCP</strong> (Fractionne le pouvoir urbain / suburbain)`,table_r6_a:`<strong>Résumé pré-enregistré</strong> (&ge; 4 sur 5 = valeur aberrante)`,table_r6_b:`<strong>0 sur 5 déclenchés</strong>`,table_r6_c:`<strong>4 sur 5 déclenchés</strong> (test d'ancrage neutre — les deux cartes dans la norme canadienne ; les 4 tests restants tous déclenchés)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`Un constat distinct, appliqué seulement à la minoritaire : <strong>cinq des six rationnels publiés par les commissaires minoritaires échouent à la vérification indépendante</strong>. Le test ne porte que sur la minoritaire parce que la majoritaire n'a pas publié de liste de rationnels pour redessins contestés — l'audit ne peut l'appliquer symétriquement, et il est rapporté ici comme un signal unique plutôt que comme des lignes supplémentaires dans le décompte d'irrégularités structurelles. (Un septième redessin que l'audit avait antérieurement listé reposait en fait sur une affirmation de limite fédérale introuvable dans le rapport minoritaire ; il a été retiré plutôt que laissé comme allégation faible.)`,chair_appendix_p:`L'audit a aussi testé l'affirmation distincte et globale du président, dans l'annexe C, selon laquelle les sept configurations hybrides contestées de la minoritaire n'avaient <strong>aucun appui public</strong> dans les 1 140+ soumissions du public. Une recherche par mots-clés à travers l'archive complète des soumissions (94 % analysées par machine, 6 % uniquement en image et exclues ; méthodologie et preuves par configuration à <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) a retourné une image plus nuancée que l'affirmation globale du président ou son rejet global : le président avait raison sur trois des sept (la division d'Airdrie en quatre, l'hybride Calgary–Nolan-Hill–Cochrane, et l'alternative minoritaire de St. Albert manquent toutes d'appui documenté), tort sur trois des sept (Rocky Mountain House–Banff Park a suscité une proposition explicite et détaillée d'au moins une soumission de la région Clearwater et plusieurs autres soumissions alignées ; Olds–Three-Hills–Didsbury a été appuyée par écrit par des résidents de Beiseker ; Chestermere a suscité plusieurs soumissions opposées à une fusion avec Calgary qui s'alignent matériellement avec l'intention de la minoritaire), et partiellement tort sur une (les hybrides de Red Deer ont suscité une proposition d'hybride péri-Red-Deer de la part d'un conseiller en exercice de Red Deer, avec un alignement directionnel mais non exact en configuration). Le balayage « aucun appui public » de l'annexe C du président est donc démontré comme trop large — trois sur sept sont démontrablement faux — mais il n'est pas inventé de toutes pièces, puisque trois sur sept tiennent bel et bien. <strong>Ce constat va contre le président, pas contre la minoritaire.</strong>`,summary_p:`<strong>Sur la voie 2, la majoritaire ne franchit aucun seuil structurel. La minoritaire les franchit tous par une large marge.</strong>`},cpd:{heading:`4 : Fractionner, entasser et drainer`,vocab_label:`Trois manœuvres, un seul scénario`,vocab_packing:`<strong>L'entassement</strong> signifie tasser les électeurs d'un parti dans des circonscriptions que ce parti remporte par raz-de-marée — chaque bulletin entassé compte toujours, mais il ne contribue à rien au-delà de la victoire. De grandes victoires lopsides. Des votes gaspillés.`,vocab_cracking:`<strong>Le fractionnement</strong> signifie diviser une communauté entre plusieurs circonscriptions de sorte qu'elle n'en remporte aucune carrément. Une ville assez forte pour porter deux sièges est découpée en quatre, chacune attachée à une région rurale différente. Votes dilués. Aucun siège pour personne.`,vocab_draining:`<strong>Le drainage</strong> est le compagnon spatial : des circonscriptions entassées et fractionnées sont placées les unes à côté des autres de sorte que les partisans surconcentrés d'un côté « drainent » le pouvoir de vote des circonscriptions contestées à proximité. Le schéma d'adjacence amplifie les deux effets — l'entassement et le fractionnement se renforcent mutuellement à travers les lignes de circonscription.`,vocab_disclaimer:`Les trois peuvent se produire sans intention partisane explicite. Ce que l'audit mesure, c'est si le schéma — et son ampleur statistique — est compatible avec ce que produit un processus neutre de tracé de carte. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Méthodologie complète au §5 du rapport technique.</a>`,fig_alt:`Carte montrant la division d'Airdrie en quatre circonscriptions distinctes selon la carte minoritaire`,fig_caption:`La division d'Airdrie en quatre circonscriptions distinctes selon la carte minoritaire, diluant son pouvoir de vote urbain.`,intro:`Les cinq commissaires ont travaillé à partir des mêmes règles statutaires, de la même géographie provinciale, de la même archive de 1 140 soumissions publiques et des mêmes données démographiques. Leurs deux ébauches concurrentes s'accordent sur la majeure partie de l'Alberta. Là où les ébauches divergent, elles divergent sur des choix que quelqu'un dans la pièce devait faire. Trois de ces choix méritent d'être vus comme des choix, et non comme des chiffres.`,airdrie_p:`<strong>Elle divise la Ville d'Airdrie en quatre morceaux.</strong> La loi plafonne chaque division électorale à un et quart fois la moyenne provinciale, de sorte qu'Airdrie a besoin d'au moins deux divisions. La carte majoritaire lui en donne deux. La minoritaire lui en donne quatre — au nord vers Calgary-Nolan Hill-Cochrane, à l'est vers Airdrie East, à l'ouest vers Calgary-Foothills-Airdrie West, et au centre-sud vers Calgary-Airdrie — chacune agrafée à une circonscription rurale ou en bordure de Calgary différente. Une résidente d'Airdrie qui a une question pour son MLA doit savoir dans quel quart de la ville elle vit avant de pouvoir appeler le bon bureau. Ses voisins à deux rues de là lui donneront trois réponses différentes. Le comité de parents à l'école de son enfant ne peut pas envoyer une seule délégation à un seul MLA sur une question de financement scolaire ; ils doivent coordonner quatre délégations à quatre bureaux, chaque MLA principalement responsable d'une circonscription rurale ou suburbaine différente. L'association de hockey mineur, la banque alimentaire, la Chambre de commerce — chaque organisation qui opère à l'échelle de la ville opère maintenant à travers quatre circonscriptions provinciales.`,airdrie_callout_label:`POURQUOI AIRDRIE COMPTE`,airdrie_callout_p1:`Airdrie est la plus grande ville albertaine sans son propre MLA. Avec 85 805 habitants (recensement municipal de 2024), elle est plus grande que Red Deer ; elle a un conseil, une facture fiscale, une commission scolaire — chaque système civique la traite comme une unité.`,airdrie_callout_p2:`La diviser entre quatre divisions provinciales — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Calgary-Nolan Hill-Cochrane et Airdrie East — chacune principalement identifiée à une juridiction environnante différente, retire Airdrie de la carte politique au niveau de gouvernement qui la trace. La ville compte 85 805 résidents et zéro siège à l'assemblée législative où une majorité d'électeurs y vit.`,airdrie_callout_p3:`Une division en quatre est invisible à chaque test d'équité partisane sauf celui qui demande : un électeur peut-il trouver son MLA ?`,airdrie_callout_summary:`Les deux cartes sont légales. La division en quatre est un choix.`,airdrie_btn:`Afficher les circonscriptions signalées sur la carte`,anchoring_p:`<strong>Là où elle s'écarte des lignes municipales, elle s'en écarte à des endroits stratégiquement importants.</strong> Quand les cartes électorales suivent le bord d'une ville ou d'un village, les électeurs reconnaissent où commence et finit leur division — la ligne de taxe foncière, la ligne de commission scolaire, la ligne de quartier d'élection locale et la ligne d'élection provinciale coïncident toutes. Statistique Canada publie ces limites gratuitement. Sur les fichiers officiels d'Elections Alberta, les deux cartes suivent les lignes municipales à des taux globaux comparables : la majoritaire à 80 %, la minoritaire à 72 %, toutes deux dans la norme canadienne de 70 à 85 % (Québec : 78 %, Ontario : 82 %, C.-B. : 71 % ; commissions de comparaison documentées dans la monographie). (L'analyse provisoire initiale de l'audit montrait l'ancrage minoritaire à seulement 15 % ; le chiffre n'a pas survécu au recalcul sur les fichiers officiels — voir la note de correction ci-dessous.) L'observation frappante n'est pas le taux global mais où sont concentrés les écarts de la minoritaire : les trois limites que le président de la commission a lui-même signalées comme anormales — l'extension de Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">voir ↗</button> dans des terres inhabitées de parc national, le corridor en lasso Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">voir ↗</button>, et le prolongement Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">voir ↗</button> — sont chacune des écarts par rapport à la géographie civique préexistante dans les zones urbaines-rurales exactes où l'appariement d'électeurs urbains et ruraux affecte le plus directement quel parti remporte le siège.`,anchoring_followup:`Les commissaires minoritaires ont donné des raisons pour chacune des trois limites signalées. Pour Rocky Mountain House–Banff Park, ils ont invoqué la taille géographique, le corridor de la route 22 et la proximité des réserves des Premières Nations à Rocky Mountain House ; le président de la commission a qualifié l'extension dans des terres de parc national inhabitées d'« effort de mauvaise foi » pour satisfaire au critère de superficie, et la formule apparaît dans le rapport final officiel de la commission. Pour Nolan Hill–Cochrane, ils ont invoqué les liens partagés de transport et d'emploi entre le nord-ouest de Calgary et Cochrane ; les données de Statistique Canada sur les déplacements domicile-travail montrent que seulement 35,8 % des travailleurs de Cochrane se rendent à Calgary, la plupart travaillant à Cochrane même. Pour le prolongement Olds–North Airdrie, ils ont invoqué la continuité du corridor de la route 2 ; l'audit a trouvé que l'extension précise vers Airdrie échoue sur le critère de population. La vérification indépendante a trouvé que cinq des six sous-rationnels publiés par la minoritaire échouent ou ne tiennent que partiellement face aux données primaires.`,packing_p:`<strong>Une zone de Calgary est découpée pour concentrer les électeurs NDP dans des divisions plus grandes que la moyenne.</strong> Dans le quadrant nord-ouest de Calgary <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">voir ↗</button>, les divisions de la carte minoritaire ont en moyenne 11,5 % au-dessus de la population provinciale — contre 2,8 % pour la majoritaire. La même zone géographique, tracée par la même commission sous les mêmes contraintes, produit des circonscriptions un quart plus grandes sur une carte que sur l'autre. Cela correspond à la signature structurelle de l'<em>entassement</em> : concentrer les électeurs d'un parti dans moins de circonscriptions, plus grandes, de sorte que chaque bulletin pèse moins. L'entassement et le <em>fractionnement</em> (répartir mince les électeurs d'un parti dans des circonscriptions qu'ils perdent de peu) sont les deux manœuvres classiques du découpage partisan ; les deux réduisent le nombre de sièges d'un parti sous sa part de vote.`,chair_p:`Le président de la commission — nommé en vertu de la même Loi, travaillant à partir des mêmes soumissions — a signalé trois limites sur la carte minoritaire comme géographiquement anormales : l'extension de Rocky Mountain House–Banff Park dans des terres inhabitées de parc national ; le corridor en forme de lasso Calgary-Nolan Hill–Cochrane ; le prolongement Olds–Three Hills–Didsbury vers le nord d'Airdrie. La majoritaire a reçu zéro signalement du même président. (La critique publiée du président couvre sept configurations de limites au total — quatre signalements géométriques dans le rapport principal et trois à l'annexe C. Cet audit a confirmé de manière indépendante la géométrie anormale pour trois des quatre signalements géométriques ; le quatrième, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">voir ↗</button>, n'a pas atteint le seuil de confirmation de l'audit.)`},litmus:{heading:`3 : Le test décisif de 1 010 000 cartes`,fig_alt:`Histogramme montrant la distribution des écarts d'efficacité sur 250 000 cartes neutres de l'Alberta. La plupart des cartes se regroupent près de zéro. La carte de la commission minoritaire (ligne violette) se situe au 94<sup>e</sup> centile (+3,96 %), dans la queue droite ombrée. La carte majoritaire (ligne turquoise) se situe à +0,04 %, bien dans la plage normale.`,fig_caption:`Distribution des <button class="vocab-term" data-def="une mesure de la disproportion avec laquelle les votes sont convertis en sièges — les valeurs positives favorisent le UCP, les valeurs négatives favorisent le NDP" aria-expanded="false">écarts d'efficacité</button> à travers 250 000 cartes neutres de l'Alberta tracées à partir de la même géographie. La plupart des cartes neutres se regroupent près de zéro ; la queue droite ombrée marque les 10 % supérieurs. Les +3,96 % de la proposition minoritaire se situent au 94<sup>e</sup> <button class="vocab-term" data-def="le pourcentage de cartes ayant obtenu un score inférieur — p94 signifie que 94 sur 100 cartes neutres étaient moins partisanes que celle-ci" aria-expanded="false">centile</button> — une région que moins de 6 cartes neutres sur 100 atteignent. Les +0,04 % de la proposition majoritaire sont indissociables de ce qu'un processus neutre produit habituellement.`,table_intro:`Le tableau compare les deux cartes. Les cinq premières lignes n'utilisent aucun résultat électoral — ce sont des propriétés des lignes elles-mêmes. Les deux dernières dépendent de la façon dont les votes ont été attribués à chaque circonscription.`,table_col_measured:`Ce qui a été mesuré`,table_col_majority:`Carte majoritaire`,table_col_minority:`Carte minoritaire`,table_col_direction:`Direction / Bénéficiaire`,table_r1_a:`Étalement de la population entre circonscriptions (plus serré est mieux)`,table_r1_b:`3 180`,table_r1_c:`4 707 — 48 % plus large`,table_r1_d:`Structurel (réduit l'égalité du vote)`,table_r2_a:`Excédent de population du NO de Calgary au-dessus de la moyenne`,table_r2_b:`2,8 %`,table_r2_c:`11,5 %`,table_r2_d:`<strong>UCP</strong> (Entasse les votes NDP urbains)`,table_r3_a:`Division d'Airdrie`,table_r3_b:`2 divisions`,table_r3_c:`4 divisions`,table_r3_d:`<strong>UCP</strong> (Fractionne le pouvoir urbain / suburbain)`,table_r4_a:`Frontières qui suivent les lignes municipales existantes`,table_r4_b:`80 % — dans la norme`,table_r4_c:`72 % — dans la norme`,table_r4_d:`S.O. — les deux dans la norme canadienne (70 à 85 %)`,table_r5_a:`Limites signalées par le président de la commission`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`S.O.`,table_r6_a:`Sièges à 50/50 (centile dans la simulation de 1 010 000 cartes)`,table_r6_b:`46,1 % — p83 (plage normale)`,table_r6_c:`51,7 % — p99,99 (moins de 100 sur 1 010 000 l'atteignent)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Écart d'efficacité (centile dans la simulation de 1 010 000 cartes)`,table_r7_b:`+0,04 % — p15,5 (plage normale)`,table_r7_c:`+3,96 % — p94,4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Schéma d'entassement-fractionnement de voisinage`,table_r8_b:`6 signaux de chaîne couplée`,table_r8_c:`2 (RÉUSSITE pré-enregistrée)`,table_r8_d:`Neutre — la minoritaire atteint l'effet partisan par hybridation, pas par drainage d'adjacence (§5.3.5)`,vocab_label:`VOCABULAIRE`,vocab_eg:`<strong>Écart d'efficacité.</strong> Un chiffre unique qui mesure de manière disproportionnée comment les votes d'un parti sont traduits en sièges. Les chiffres positifs favorisent le UCP ; les négatifs favorisent le NDP. L'audit utilise environ 5 % comme ligne de valeur aberrante de l'Alberta — la valeur dépassée par seulement 5 % des 1 010 000 simulations neutres spécifiques à l'Alberta. Ce seuil n'est pas emprunté à la littérature américaine ou générale ; un seuil calibré pour une autre juridiction serait erroné parce que la géographie naturelle de l'Alberta produit une plage neutre différente.`,vocab_mm:`<strong>Différence moyenne-médiane.</strong> L'écart entre la part de vote médiane d'un parti dans les circonscriptions et sa part de vote moyenne dans les circonscriptions. Quand un parti remporte beaucoup de courses serrées, la médiane se situe au-dessus de la moyenne — ces votes sont distribués efficacement. Quand un parti remporte beaucoup de courses avec de grandes marges, la moyenne se situe au-dessus de la médiane — les votes sont gaspillés. Un grand écart moyenne-médiane dans une direction signale une inefficacité structurelle dans la façon dont les votes d'un camp sont étalés entre les circonscriptions.`,vocab_percentile:`<strong>Classement par centile.</strong> Dans cet audit, un « centile » est un rang dans les 1 010 000 cartes neutres simulées. « p94 » signifie que 94 % des cartes neutres obtiennent un score inférieur — la vraie carte est plus extrême que 94 % des tirages neutres. « p99,99 » signifie que moins de 1 carte neutre sur 10 000 atteint ce niveau.`,vocab_anchoring:`<strong>Ancrage.</strong> La fraction d'une frontière électorale qui repose sur une ligne administrative préexistante — une limite de ville, une limite de commission scolaire, une ligne de recensement de Statistique Canada.`,closing_p1:`Les lignes du bas dépendent des résultats électoraux. Le test <em>seats@50/50</em> maintient l'électorat à la parité parfaite (le UCP et le NDP remportent chacun exactement la moitié des votes à l'échelle provinciale) et demande combien de sièges la carte attribue au UCP. Une carte neutre de l'Alberta produit une médiane autour de 44,8 % de sièges UCP. La géographie de l'Alberta — électeurs NDP concentrés dans les noyaux urbains, électeurs UCP étalés à travers les circonscriptions rurales — donne au NDP un léger avantage d'efficacité en neutralité. La carte majoritaire à 46,1 % se situe au 83<sup>e</sup> centile de la simulation de 1 010 000 cartes, bien dans la plage normale. La carte minoritaire à 51,7 % se situe au 99,99<sup>e</sup> centile : moins de 100 sur 1 010 000 tirages neutres atteignent cette valeur. Le chiffre d'<em>écart d'efficacité</em> mesure la disproportion avec laquelle les votes de chaque parti se traduisent en sièges. Sur les fichiers officiels d'Elections Alberta, l'écart d'efficacité de la minoritaire est de +3,96 %, la plaçant au 94,4<sup>e</sup> centile — juste sous la ligne des valeurs aberrantes à 95<sup>e</sup> centile de l'audit. Les questions d'ouverture en haut de cette page en déballent les conséquences.`,closing_p2:`La dernière ligne est l'endroit où la carte minoritaire a moins de signaux de chaîne couplée que la majoritaire sur le test de drainage de voisinage : 2 contre 6 pour la majoritaire (et 5 pour la carte 2019 adoptée). L'audit a pré-enregistré ce test avant la mesure, et le décompte inférieur de la minoritaire est une véritable RÉUSSITE pré-enregistrée — la minoritaire ne montre pas le schéma classique d'adjacence entassement-drainage. C'est le seul test où la minoritaire surpasse numériquement la majoritaire. Le §5.3.5 du rapport académique explique pourquoi : la minoritaire atteint son effet partisan par hybridation (division de villes qui internalise l'entassement et le fractionnement à l'intérieur de circonscriptions individuelles), ce qui est invisible à un test de chaîne d'adjacence qui ne mesure que la façon dont les circonscriptions entassées se regroupent près des circonscriptions fractionnées.`},commission_split:{heading:`2 : Comment la commission s'est divisée`,intro:`La Commission de délimitation des circonscriptions électorales de l'Alberta a terminé ses travaux le 23 mars 2026 et n'a pas pu s'entendre. Trois commissaires ont produit une carte ; les deux autres en ont produit une différente. Le président de la commission, le juge Dallas K. Miller, et deux commissaires nommés par l'opposition ont rédigé le rapport majoritaire ; deux commissaires nommés par le gouvernement — le D<sup>r</sup> Julian Martin et John D. Evans — ont rédigé le rapport minoritaire. La division portait sur la manière de tracer les limites dans les communautés urbaines-rurales à croissance rapide. La majorité a donné à Airdrie deux circonscriptions ; la minorité, quatre. La majorité a tracé les divisions du nord-ouest de Calgary près de la moyenne provinciale ; la minorité les a tracées à 11,5 % au-dessus. Les deux cartes suivent la même loi. Les deux sont légales en vertu de la <em>Electoral Boundaries Commission Act</em>. Le désaccord portait sur les configurations géographiques précises qui servaient le mieux les communautés tracées. Le parti au pouvoir en Alberta est le United Conservative Party (UCP) ; son principal opposant est le New Democratic Party (NDP). Des partis plus petits — l'Alberta Party, le Parti libéral de l'Alberta et d'autres — disputent aussi des sièges, mais leur part de vote provincial combinée a été assez faible aux dernières élections pour ne pas affecter matériellement les calculs d'équité partisane de l'audit, qui sont ancrés dans la division UCP–NDP de 2023. Cet audit a mesuré les deux cartes avec les mêmes méthodes, appliquées de façon identique. Trois constats ressortent.`,finding1:`<strong>Les deux cartes diffèrent sur six choses qu'on peut mesurer sans regarder aucun résultat électoral :</strong> à quel point les gens sont étalés également entre les circonscriptions, si les électeurs sont concentrés, à quel point les villes sont mal découpées, si les frontières suivent les limites de la ville, la forme des circonscriptions et combien de limites le président de la commission, le juge Miller lui-même, a signalées comme anormales par écrit (§5.8.2 du rapport majoritaire et annexe C). La carte minoritaire diffère de la majoritaire sur chacun de ces points.`,finding2:`<strong>Chaque différence mesurée va dans la même direction.</strong> Partout où les deux cartes divergent — nord-ouest de Calgary, Airdrie, zones urbaines à limites de ville claires — la carte minoritaire trace des limites qui étalent plus mince les votes NDP et permettent aux votes UCP de compter plus efficacement. Les communautés les plus remodelées par la carte minoritaire sont les mêmes communautés où le NDP est le plus fort. L'audit ne peut pas déterminer l'intention. Il peut mesurer l'effet.`,finding3:`<strong>Le processus qui promeut maintenant la carte minoritaire n'a aucun précédent au Canada.</strong> Aucune autre province ne permet à un cabinet de confier le redécoupage à un comité que son propre parti contrôle en cours de cycle de redécoupage. La plupart des provinces exigent que l'assemblée législative débatte d'abord de la carte des commissaires, ou donnent à la carte de la commission un effet automatique sauf annulation. L'Alberta ne fait ni l'un ni l'autre. Le 16 avril, le gouvernement a écarté les deux cartes de la commission et a confié le travail à un comité de MLA dont la majorité des membres viennent du United Conservative Party (UCP) au pouvoir ; la composition et le mandat complets du comité sont détaillés au §7. La <em>Electoral Boundaries Commission Act</em> de l'Alberta exige que l'assemblée législative adopte une loi distincte (Electoral Districts Act) pour donner effet juridique à un rapport de commission — le rapport de commission lui-même ne change rien. La plupart des autres provinces rendent le rapport d'une commission juridiquement effectif sauf si l'assemblée législative l'annule activement ; le défaut de l'Alberta l'inverse, ce qui signifie que le parti au pouvoir contrôle si une carte de commission devient un jour loi. La justification déclarée du gouvernement était de mettre en œuvre la recommandation 5 du président de la commission, le juge Miller. Mais Miller avait rédigé la recommandation spécifiquement pour dissuader l'assemblée d'accepter la carte minoritaire, et ses collègues majoritaires ne l'ont pas appuyée. La recommandation 5 était aussi géographiquement précise : un siège rural supplémentaire au sud d'Edmonton, et un dans le comté de Clearwater et l'ouest du comté de Mountain View — loin tous deux des communautés urbaines-rurales à croissance rapide de Calgary et d'Edmonton où la commission s'est en fait divisée. Ce n'était pas une invitation à redessiner ces limites contestées. Le gouvernement a adopté le nombre de sièges tout en confiant à un comité qu'il contrôle l'autorité sur les lignes mêmes sur lesquelles la commission n'était pas d'accord.`,closing:`<strong>Le processus est son propre constat, distinct des cartes.</strong>`},november:{heading:`7 : Le comité Lunty`,context_label:`CONTEXTE`,context_body:` — Cette section décrit le processus qui a remplacé la commission et le cadre juridique qui s'y applique. Elle ne fait pas partie des constats statistiques. Les constats se trouvent aux §3 à §6 ci-dessus.`,intro:`Aucune carte de commission n'est en vigueur. Le 16 avril 2026, l'assemblée législative a adopté la Motion 19, écartant les deux cartes et confiant le redécoupage à un comité spécial restreint de cinq MLA — trois UCP, deux NDP — présidé par Brandon Lunty (UCP, Leduc-Beaumont). Le comité lui-même ne trace pas la carte. Il supervise un Comité consultatif indépendant distinct, constitué en vertu de la Motion gouvernementale 37 (adoptée le 21 avril 2026), chargé de produire une proposition de limites à 91 sièges. La Motion 37 prévoyait cinq membres pour le comité — un juge en exercice ou à la retraite comme président, deux membres nommés par le Premier ministre et deux par le chef de l'opposition — mais la juge en chef par intérim de l'Alberta a refusé de nommer un juge à la présidence, et le comité opère maintenant avec les quatre personnes nommées que le comité a confirmées : l'hon. Monte Solberg et Darwin Durnie (nominations du Premier ministre) et le D<sup>r</sup> Gerard Kennedy et Brent Robinson (nominations de l'opposition). Le comité doit livrer son rapport à l'assemblée législative d'ici le 2 novembre 2026. Contrairement à la commission originale, ni le comité ni le panel ne sont tenus de tenir des audiences publiques ; le panel s'appuie sur les soumissions que la commission originale a recueillies. Quand la carte du comité sera publiée, cet audit appliquera la même méthodologie pour l'évaluer.`,h_anomalous:`Pourquoi le comité est anormal`,anomalous_p1:`La pratique canadienne de redécoupage s'est, depuis les années 1960, fixée sur un seul modèle : une commission indépendante, isolée de la direction du gouvernement, produit des recommandations de limites ; l'assemblée peut en débattre mais ne peut pas facilement les annuler sans un vote législatif formel. Le processus statutaire de l'Alberta en vertu de l'<em>Electoral Boundaries Commission Act</em> suit ce modèle — mais avec une différence structurelle par rapport à la plupart des provinces : le rapport de la commission de l'Alberta n'a aucun effet juridique automatique. En vertu de la Loi, une loi distincte (Electoral Districts Act) doit être adoptée par l'assemblée pour donner force de loi à toute carte de commission. Cela signifie que le gouvernement du jour contrôle non seulement si la carte de la commission est débattue, mais si elle devient un jour loi. D'autres juridictions canadiennes prennent le défaut inverse : les recommandations de la commission prennent effet sauf si l'assemblée vote affirmativement pour les annuler.`,anomalous_p2:`Ce que le gouvernement a fait en avril 2026 n'a aucun précédent enregistré dans le redécoupage post-Confédération : il a permis qu'un processus de commission terminé et publié — rapports majoritaire et minoritaire déposés — soit conclu, puis a confié la tâche de redécoupage à un comité de cinq MLA dont la majorité (trois sur cinq) est détenue par le parti au pouvoir, sans soumettre l'un ou l'autre rapport de commission à un vote. Le comité Lunty n'est pas une commission. Il n'a aucune indépendance statutaire par rapport à la direction législative du gouvernement. Sa majorité UCP de trois membres reflète le contrôle du gouvernement sur l'assemblée. Aucune autre province canadienne n'a transféré l'autorité de redécoupage, en cours de cycle, à un comité législatif contrôlé par le gouvernement après qu'une commission indépendante a terminé son travail.`,h_framework:`Le cadre constitutionnel`,framework_p1:`L'article 3 de la <em>Charte des droits et libertés</em> — « Tout citoyen canadien a le droit de vote et est éligible aux élections législatives fédérales ou provinciales » — a été interprété par la Cour suprême du Canada comme garantissant non seulement l'acte de voter mais la <em>représentation effective</em>. L'autorité de référence est <em>Renvoi : Circonscriptions électorales provinciales (Sask.)</em> [1991] 2 RCS 158, dans lequel la juge McLachlin (telle qu'elle était alors) a écrit pour la majorité que l'objet de l'article 3 « n'est pas l'égalité du pouvoir de vote en soi, mais le droit à une représentation effective ». La parité de population est la considération principale ; des écarts sont permis lorsqu'ils sont justifiés par la communauté d'intérêts, la géographie, l'histoire ou les objectifs de représentation des minorités.`,framework_p2:`Le cadre du Renvoi de la Saskatchewan n'interdit pas catégoriquement les considérations partisanes dans le redécoupage. Ce qu'il établit, c'est que les cartes de limites doivent, dans l'ensemble, fournir une représentation effective aux électeurs — et que l'altération systématique de la capacité d'un groupe identifiable à élire une représentation proportionnelle est le motif que les contestations fondées sur l'article 3 visent. Les constats statistiques et structurels de l'audit — la position de la carte minoritaire au 99,99<sup>e</sup> centile de 1 010 000 tirages neutres, son franchissement de quatre des cinq seuils structurels (le cinquième, l'ancrage, est neutre pour les deux cartes), les communautés concernées identifiées — sont le dossier de preuves qu'un demandeur en vertu de l'article 3 aurait besoin d'assembler. Du côté de la communauté d'intérêts de ce dossier, la décision de la Cour fédérale dans <em>Raîche c. Canada</em> (2004 CF 679) est l'autorité canadienne de référence : le tribunal y a exigé que la Commission fédérale de délimitation des circonscriptions électorales reconsidère des limites qui avaient ignoré la communauté d'intérêts acadienne au Nouveau-Brunswick. Les mesures d'ancrage municipal de l'audit et ses constats communautaires précis — Airdrie divisée en quatre circonscriptions, les anomalies urbaines-rurales signalées par le président dans le nord-ouest de Calgary — sont le même type de preuve que la Cour fédérale a traité comme juridiquement recevable. Savoir si ce dossier atteint le seuil constitutionnel est une question juridique que cet audit ne tranche pas ; l'audit rapporte la mesure.`,framework_p3:`La légalité du comité comme processus est une question distincte. L'<em>Electoral Boundaries Commission Act</em> de l'Alberta n'interdit pas expressément à l'assemblée législative de constituer un organe parallèle de redécoupage, parce que la Loi prévoit que l'assemblée adoptera les limites finales par législation ordinaire de toute façon. Savoir si le processus du comité, s'il produit une carte au profil structurel et statistique de la proposition minoritaire, pourrait survivre à une contestation fondée sur l'article 3 de la Charte dépend de savoir si la représentation effective est atteignable sous les limites résultantes — le même critère qui s'appliquerait à toute carte produite par une commission.`,h_quebec:`Le contraste québécois`,quebec_p1:`Le Québec offre la comparaison la plus pertinente pour la situation de l'Alberta. La Commission de la représentation électorale (CRE) du Québec est un organe permanent et indépendant des limites électorales, et non une commission ad hoc constituée par cycle de redécoupage. La CRE opère en continu et ne peut être dissoute ou contournée par une action du cabinet. En vertu de la <em>Loi électorale</em> du Québec, l'Assemblée nationale doit adopter les recommandations de la CRE sauf vote pour s'en écarter — et les écarts exigent une majorité des deux tiers de tous les membres de l'Assemblée, pas une simple majorité législative. L'effet pratique est qu'un parti au pouvoir ne peut pas, agissant seul avec sa propre majorité, substituer sa carte préférée à celle de la commission. Un accord interpartis est constitutionnellement requis pour annuler le jugement de l'organe indépendant.`,quebec_p2:`Le modèle québécois a émergé en partie de leçons sur ce qui arrive quand le redécoupage n'est pas isolé du contrôle partisan. Le contraste avec le processus actuel de l'Alberta — où un comité contrôlé par la majorité a remplacé le travail de la commission avant que l'assemblée n'ait voté sur l'un ou l'autre rapport de commission — illustre la différence structurelle entre les systèmes de redécoupage qui présument une pression partisane et conçoivent contre elle, et les systèmes où cette pression a un chemin plus clair vers le résultat.`,closing:`L'audit appliquera les mêmes tests à la carte du comité Lunty quand elle sera publiée. Les observations constitutionnelles et comparatives ci-dessus sont contextuelles ; la méthodologie ne change pas.`},references:{heading:`10 : Références et méthodologie`,heading_aria:`Lien vers les références`,intro:`La méthodologie sous-jacente s'appuie sur la science politique, les statistiques et la littérature juridique établies. Les citations complètes suivent le style de l'American Political Science Association (APSA) ; les affaires judiciaires suivent la convention juridique canadienne. La liste complète des références figure dans le <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">rapport technique</a>. Les principales sources sont listées ici.`,h_academic:`Littérature universitaire`,h_cases:`Affaires judiciaires`,h_statutes:`Lois`},resources:{heading:`11 : Annexe technique`,heading_aria:`Lien vers la technique`,tag_plain:`Langage clair`,plain_label:`Rapport public complet`,plain_desc:`Format long, avec cartes, pour le grand public`,tag_summary:`Résumé`,summary_label:`Résumé des constats`,summary_desc:`Aperçu en langage clair, explique chaque concept à partir de zéro`,tag_academic:`Académique`,academic_label:`Rapport technique`,academic_desc:`Méthodes complètes et citations pour les chercheurs`,tag_notebook:`Carnet`,notebook_label:`Carnet interactif`,notebook_desc:`Exécutez vous-même les graphiques dans votre navigateur, sans installation`,tag_code:`Code`},about_me:{heading:`À propos de moi`,p1:`Je suis étudiant à l'Université Mount Royal. J'ai fait cette recherche par moi-même — elle n'a pas été assignée comme travail de cours et l'université ne l'a pas commandée. Mes opinions sont les miennes et ne représentent pas l'université. Je n'ai aucun lien avec Elections Alberta, la commission ou un quelconque parti politique.`,p2:`J'ai voté pour différents partis à différentes élections, à travers l'éventail politique. Je vous le dis parce que mon historique politique pourrait affecter la façon dont je regarde cette question. La principale protection contre cela, c'est la méthode : j'ai testé les deux cartes de la même manière, j'ai écrit mes prédictions avant de regarder les résultats et j'ai tout mis en ligne pour que quiconque puisse vérifier mon travail. J'ai payé cette recherche moi-même. Si vous trouvez quelque chose que j'ai mal compris, je veux vraiment le savoir.`,p3:`Dossiers de pré-enregistrement (rédigés avant l'examen des résultats) : <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451.`,p4:`Questions ou corrections : <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9 : Rétractations et corrections`,heading_aria:`Lien vers les rétractations`,conditions_label:`CONDITIONS DE RÉTRACTATION`,conditions_intro:`Chaque constat est pré-engagé à une condition de falsification précise. Si l'une des conditions ci-dessous se matérialise, le constat qu'elle nomme est rétracté publiquement dans les 30 jours. La conclusion directionnelle globale — que la carte minoritaire se situe en dehors de la plage neutre sur plusieurs tests indépendants — n'est rétractée que si au moins trois des cinq tests échouent.`,c1_title:`Condition 1 — Une contre-carte existe`,c1_what:`<em>Ce qui est rétracté :</em> le constat structurel selon lequel la division d'Airdrie en quatre et les trois limites signalées par le président ne peuvent être expliquées par le rationnel de communauté d'intérêts déclaré par la minorité.`,c1_cond:`Condition : quelqu'un produit une carte légale de l'Alberta satisfaisant aux propres raisons déclarées de la minorité — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — et s'ancre sur les lignes municipales à des taux comparables à la majoritaire. Défi ouvert à <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">l'Issue #14</a>.`,c2_title:`Condition 2 — La RÉUSSITE pré-enregistrée du Neighbour-Drain est inversée`,c2_what:`<em>Ce qui est rétracté :</em> l'entrée du tableau de la section 3 enregistrant la carte minoritaire comme une RÉUSSITE pré-enregistrée au test d'adjacence de drainage de voisinage.`,c2_cond:`Condition : le score continu de drainage v2 tombe dans la queue supérieure extrême (p &lt; 0,05) des permutations aléatoires à travers le graphe de contiguïté fixe, ce qui signifie que la réussite était un artéfact de mesure de la méthode de notation binaire v1 plutôt qu'un véritable résultat nul.`,c3_title:`Condition 3 — Un document de commission antérieur à 2026 fait surface`,c3_what:`<em>Ce qui est rétracté :</em> l'inférence selon laquelle les choix de limites de la minorité étaient des décisions de rédaction plutôt que des réponses à des soumissions communautaires documentées.`,c3_cond:`Condition : un document interne de la commission daté avant les choix de limites finaux de la minorité montre que ces choix étaient explicitement motivés par des soumissions communautaires que l'audit n'a pas vues — et non par les six sous-rationnels publiés que l'audit a testés.`,c4_title:`Condition 4 — Le résultat de l'élection de 2027 contredit la simulation`,c4_what:`<em>Ce qui est rétracté :</em> le constat de la voie 1 — selon lequel le score seats@50/50 de la carte minoritaire se situe au 99,99<sup>e</sup> centile de 1 010 000 tirages neutres.`,c4_cond:`Condition : si l'élection provinciale de 2027 se déroule sur l'une ou l'autre carte de commission et que la division partisane réelle des sièges contredit la projection directionnelle des votes de 2023, les constats de centile de la voie 1 sont réexaminés par rapport aux résultats réels.`,c5_title:`Condition 5 — Un tribunal albertain distingue l'arrêt québécois de la CSC`,c5_what:`<em>Ce qui est rétracté :</em> l'argument procédural de la section 7 selon lequel la motion du 16 avril visant à remplacer la commission par le comité Lunty se situe dans la même classe constitutionnelle que le gel de redécoupage du Québec en 2024.`,c5_cond:`Contexte : le 22 avril 2026 — six jours après la motion albertaine du 16 avril — la Cour suprême du Canada a confirmé, 7 contre 2 et séance tenante, un arrêt de la Cour d'appel du Québec selon lequel le gel législatif imposé par le gouvernement Legault à sa commission de redécoupage violait la garantie de représentation démocratique de l'article 3 de la Charte. Condition : un tribunal qui examine la motion albertaine la trouve constitutionnellement distincte — par exemple, parce que la réattribution du travail à un comité de MLA diffère structurellement d'un gel législatif, ou parce que l'analyse de représentation effective de l'Alberta en vertu de l'article 3 aboutit à un résultat différent de celui du Québec.`,corr_label:`CORRECTIONS DOCUMENTÉES (recalcul canonique, 2026-05-11)`,corr_intro:`Le constat préliminaire suivant n'a pas survécu à la réanalyse contre les fichiers de formes officiels d'Elections Alberta (reçus le 6 mai 2026). Il est conservé ici conformément à la politique de pré-engagement de l'audit de ne jamais supprimer les constats échoués.`,corr_municipal:`<strong>Ancrage municipal (rétracté).</strong> L'analyse précoce utilisant les limites de carte provisoires montrait que la carte minoritaire s'ancrait aux lignes municipales seulement 15 % du temps — 4,9&times; sous la norme canadienne de 70 à 85 %. Ce chiffre était un artéfact des reconstructions de limites provisoires (de l'ère DPG). Sur les fichiers de formes canoniques officiels d'Elections Alberta, les deux cartes s'ancrent dans la norme canadienne : majoritaire 80 %, minoritaire 72 %. La <em>divergence</em> d'ancrage municipal entre les deux cartes n'est pas un signal qui survit au recalcul canonique. Les trois anomalies de limites signalées par le président de la commission (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie) demeurent et ne sont pas touchées par cette correction.`},suggestions:{heading:`8 : Suggestions`,heading_aria:`Lien vers la section 8`,intro:`Cet audit s'est heurté à deux problèmes de données qui n'ont rien à voir avec le travail de la commission et tout à voir avec la façon dont le système électoral de l'Alberta est conçu. Les deux sont corrigeables.`,advance_p1:`<strong>Environ la moitié de tous les votes albertains arrivent maintenant avant le jour du scrutin</strong> — bureaux de vote par anticipation, bureaux mobiles, bulletins spéciaux. Elections Alberta rapporte ces résultats comme des totaux pour chaque division électorale, pas par zone de vote précise. Cela signifie qu'environ 395 000 votes NDP et UCP exprimés en 2023 ne peuvent être épinglés à aucun quartier sur une carte. Ils sont comptés ; ils ne peuvent simplement pas être localisés. Chaque électeur par anticipation est vérifié contre une liste électorale avant de recevoir son bulletin, et la liste relie chaque électeur à sa zone de vote précise. Publier les totaux du vote par anticipation au niveau de la VA n'exigerait aucun changement au processus de vote — seulement à ce qu'EA rapporte.`,advance_p2:`Cela affecte aussi les commissaires, pas seulement les analystes externes. Quand une commission décide de garder Airdrie d'un seul tenant ou de la diviser, qu'un corridor entre deux communautés a du sens, qu'une limite proposée divise une circonscription naturelle — ce sont des jugements qui dépendent de savoir où vivent les électeurs. Les commissaires travaillent à partir du même ensemble de données publiées que tout le monde. La moitié du signal géographique sur les communautés dont elles tracent les limites leur manque aussi.`,lesser_slave_p1:`Il y a au moins une communauté dans le nord de l'Alberta où cette lacune est totale. Dans la partie nord de la division de Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">voir ↗</button>, il y a une zone de vote couvrant 4 832 km&#178; — plus grande que l'Île-du-Prince-Édouard — où chaque vote unique en 2023 a été exprimé par l'équipe de scrutin mobile d'Elections Alberta. Les choix de ces 844 résidents sont comptés dans le total divisionnaire mais ne peuvent être épinglés à aucun emplacement sur une carte. La communauté est entièrement invisible dans les résultats électoraux publiés.`,lesser_slave_p2:`Quand la commission a initialement envisagé d'éliminer la division de Lesser Slave Lake et de la fusionner avec une plus grande circonscription, elle travaillait sans données géographiques de vote de ces communautés. La commission a finalement préservé la division — après plus de 80 soumissions publiques, dont beaucoup provenaient des communautés autochtones du nord de la circonscription — invoquant une loi provinciale qui permet aux circonscriptions avec des communautés des Premières Nations et métisses d'avoir des populations plus petites que la moyenne provinciale. Ils y sont arrivés. Mais les données avec lesquelles ils travaillaient ne leur montraient pas qui votait dans les communautés qu'ils décidaient de protéger.`,ebca_label:`ARTICLE 15(2) EBCA`,ebca_body:`L'article 15(2) de l'<em>Electoral Boundaries Commission Act</em> de l'Alberta est une disposition discrétionnaire qui permet aux commissions de protéger les circonscriptions sous-dimensionnées — celles plus de 25 % sous la moyenne provinciale — quand la circonscription répond à au moins trois des cinq critères précis : (a) superficie géographique dépassant 20 000 km², (b) distance de plus de 150 km de l'édifice de l'Assemblée législative par la voie routière la plus directe, (c) absence de toute ville de plus de 8 000 habitants, (d) présence d'une réserve indienne ou d'un établissement métis, et (e) si la circonscription est limitrophe d'une frontière de la province de l'Alberta. La disposition n'est pas automatique ; la commission doit juger si les critères sont remplis. Lesser Slave Lake remplit indépendamment quatre des cinq.`,rationale_p1:`Le rationnel intérimaire pour l'élimination de la circonscription était la population : avec environ 27 000 résidents, Lesser Slave Lake se situe à environ 45 % sous la moyenne provinciale, approchant le plancher légal. Cela se lit comme une application directe des règles. Ce n'est pas le cas. La loi albertaine accorde aux commissions une discrétion explicite pour protéger les circonscriptions sous-dimensionnées quand au moins trois des cinq critères précis s'appliquent, et Lesser Slave Lake en remplit quatre indépendamment. Sa superficie est de 69 566 km² (critère a, seuil 20 000 km²). Sa frontière la plus proche est à plus de 150 km de l'Assemblée par la route (critère b). Aucune ville de la circonscription n'a une population supérieure à 8 000 (critère c). Et la circonscription contient quatorze réserves indiennes et établissements métis dont les communautés partagent une géographie nordique commune, une dépendance commune au scrutin mobile pour voter du tout, et un intérêt collectif à avoir un représentant principalement responsable du nord de l'Alberta (critère d).`,rationale_p2:`Sous la fusion proposée avec Mackenzie, la voix collective aurait été absorbée définitivement dans une circonscription où l'autre parti l'emporte par plus de deux pour un, non pas parce que ces communautés ont changé mais parce que les lignes autour d'elles ont changé. Chacun de ces quatre critères est un fait objectif sur la géographie de la circonscription, pas un jugement subjectif. Ensemble, ils décrivent une constituante que la disposition a été écrite pour protéger : éloignée, vaste, peu peuplée et contenant des communautés dont l'intérêt de représentation ne peut être lu à partir des chiffres bruts de population. Vous avez besoin de trois pour qualifier ; Lesser Slave Lake en a quatre. Traiter le déficit de population comme s'il imposait l'élimination méprend la loi. Le revirement de la commission était l'application correcte de la loi, et non une concession à la pression politique.`,banff_p:`Voici l'autre côté de l'histoire : pendant que les communautés autochtones de Lesser Slave Lake luttaient pour être comptées, les commissaires dissidents ont proposé de protéger une autre circonscription en traçant sa limite à travers le parc national Banff, où personne ne vit. Le président de la commission lui-même l'a qualifié d'« effort de mauvaise foi » pour invoquer la protection légale. La formule est dans le rapport final officiel de la commission. La protection conçue pour les communautés éloignées avec des populations autochtones a été utilisée, dans la carte minoritaire, pour défendre une limite à travers une nature sauvage inhabitée. Les communautés qu'elle était conçue à aider ont dû se battre pour cela par des soumissions publiques. Le comité Lunty fera face à la même décision §&#x2009;15(2) en novembre — sans exigence statutaire de tenir des audiences publiques, et sans garantie que les 80 soumissions qui ont renversé la position intérimaire de la commission auront le même poids une seconde fois.`,census_p1:`<strong>L'Alberta devrait attendre le recensement de 2026 avant de tracer la prochaine carte.</strong> Le Canada compte sa population tous les dix ans. Le dénombrement du recensement de 2026 a lieu au printemps 2026 ; Statistique Canada publie des données infraprovinciales utilisables environ deux ans plus tard, en 2027 ou 2028. La commission qui a tracé les cartes évaluées dans cet audit a dû utiliser le recensement de 2021 — déjà vieux de quatre ans quand les cartes ont été tracées, et potentiellement vieux de quatorze ans au moment où ces limites seront retirées. Les villes à croissance rapide comme Airdrie et Chestermere changeront de 40 % ou plus pendant cette fenêtre. Les communautés rurales rétréciront. La carte sera erronée dès le jour de son utilisation. Une modification simple à l'<em>Electoral Boundaries Commission Act</em> pourrait exiger que toute nouvelle commission soit nommée seulement après que Statistique Canada publie les données les plus à jour des aires de diffusion du recensement précédent. Le résultat : des cartes qui reflètent où vivent réellement les Albertains, et non où ils vivaient il y a une décennie.`,census_p2:`Le comité Lunty opère sous la loi statutaire existante, qui ne fixe aucune exigence de calendrier de recensement, et ne peut unilatéralement retarder au-delà de son échéance de novembre 2026. Cette recommandation s'applique à une future modification de l'<em>Electoral Boundaries Commission Act</em>, pas au processus actuel. La tension est réelle : un comité tenu de livrer une carte d'ici novembre travaille à partir de données déjà vieilles de cinq ans à ce moment-là — nommer la contrainte est plus utile que de prétendre qu'elle n'existe pas.`,closing:`Ni l'un ni l'autre n'est un constat sur les cartes de la commission actuelle. Ce sont des observations sur un système qui rend l'analyse électorale précise plus difficile qu'elle ne devrait l'être. Elles sont offertes ici comme suggestions pratiques, non comme conclusions. Les deux sont véritablement corrigeables, et les corriger ferait que chaque future commission — et chaque futur audit — travaille à partir de meilleures bases.`}},editorial_canada:{heading:`Contexte : le Canada est différent — et semblable`,p1:`Le Canada appartient à la même famille que les États-Unis, le Royaume-Uni et l'Australie. Nous élisons des membres uniques à partir de circonscriptions géographiques selon le scrutin majoritaire uninominal. Nous retraçons les limites périodiquement — au fédéral après chaque recensement décennal, dans les provinces selon des calendriers échelonnés. Nous avons hérité de la machinerie de base des mêmes racines de Westminster. Jusqu'ici, aucune surprise.`,p2:`Ce qui distingue le Canada, c'est le critère que les limites doivent satisfaire.`,p3:`Dans le droit constitutionnel américain, la règle contraignante est <em>une personne, un vote</em> — les circonscriptions doivent avoir des populations aussi égales que possible, et les écarts importants exigent une justification stricte. Dans le droit constitutionnel canadien, la règle contraignante est différente. L'article 3 de la <em>Charte canadienne des droits et libertés</em> garantit à chaque citoyen le droit de vote. Dans le <em>Renvoi : Circonscriptions électorales provinciales (Sask.)</em> — le Renvoi de la Saskatchewan de 1991, l'arrêt de référence — la Cour suprême du Canada a interprété ce droit comme un droit à une <em>représentation effective</em>, et non comme un droit à l'égalité mathématique des populations de circonscriptions.`,p4:`Cette distinction compte. La représentation effective permet aux populations des circonscriptions de varier, parfois substantiellement, lorsqu'il y a de bonnes raisons : de vastes géographies rurales qu'un MLA ne peut raisonnablement desservir à une densité de population standard, des communautés d'intérêts qui doivent rester groupées, une représentation des minorités que l'égalité mathématique diluerait. Le Renvoi de la Saskatchewan a rendu cette flexibilité constitutionnelle. La variance de population de 25 % de l'EBCA — la règle qui protège les sièges ruraux de l'Alberta — en découle directement.`,p5:`Le hic, c'est que la flexibilité fonctionne dans les deux sens. Si une commission peut légitimement s'écarter de l'égalité de population pour les bonnes raisons, elle peut aussi s'en écarter pour les mauvaises. Le droit canadien n'a pas de plancher mathématique à l'américaine sur lequel se rabattre. Il a le critère de représentation effective, appliqué par les juges, après coup, en cas de litige. La plupart des juridictions se prémunissent contre les mauvaises raisons avec des protections structurelles : les commissions fédérales de redécoupage sont isolées par la loi et leurs recommandations entrent en vigueur automatiquement si le Parlement n'agit pas dans un délai imparti. Le Québec utilise une commission permanente indépendante dont l'Assemblée nationale ne peut renverser le travail qu'à une majorité des deux tiers. La Colombie-Britannique fonctionne selon une règle d'adoption par défaut similaire.`,p6:`L'Alberta est l'exception. En vertu de la <em>Electoral Boundaries Commission Act</em>, le rapport de la commission n'est qu'une recommandation — l'assemblée législative doit voter pour l'adopter. C'est normalement une formalité. Dans le cycle 2026, la commission s'est divisée 3 contre 2 et a produit deux propositions concurrentes ; l'assemblée a créé un comité distinct de MLA, présidé par un MLA nommé par le Premier ministre, pour choisir entre elles. Rien dans le droit constitutionnel canadien n'exigeait que ce comité existe. Rien n'exige que son choix suive le processus de la commission. C'est la lacune structurelle que cet audit examine.`,p7:`Donc, quand les tribunaux canadiens disent que « gerrymander » n'est pas leur vocabulaire juridique, ils ne disent pas que le concept sous-jacent ne s'applique pas ici. Ils disent que le critère est différent — représentation effective, et non égalité mathématique. Savoir si la proposition minoritaire répond à ce critère est exactement la question contre laquelle cet audit a mesuré la géométrie, et exactement la question à laquelle seul un juge peut répondre de façon définitive. Le raisonnement complet du <em>Renvoi de la Saskatchewan</em>, le contraste avec d'autres provinces, la question de la qualité pour agir et les voies de réforme disponibles sont traités dans <a href="#references">la section des références ci-dessous</a>.`},chrome:{back_to_top:`Retour en haut`,license_title:`Creative Commons Attribution-PasUtilisationCommerciale-PartageDansLesMêmesConditions 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Retour aux enjeux`,lightbox:{fig_aria:`Vue agrandie de la figure`,fig_close_aria:`Fermer la figure agrandie (Esc)`,map_aria:`Visualiseur de zoom de la carte`,map_close_aria:`Fermer le visualiseur de carte`,close_title:`Fermer (Esc)`},participation:{heading:`Aidez-nous à améliorer MapExplorer`,body:`Pendant que vous explorez, nous suivons quelles cartes et circonscriptions vous visitez et envoyons périodiquement les données à notre base de recherche. Le partage d'une vue enregistre aussi l'endroit où vous avez abouti. L'objectif : comprendre ce qui est utile et améliorer l'outil.`,no_collect:`Nous ne recueillons jamais votre nom, votre adresse IP ni votre emplacement précis. Tout est anonymisé dans votre navigateur avant de partir. Nous ne pourrions pas vous identifier à partir des données même si on nous l'ordonnait.`,dnt:`Votre navigateur a Do Not Track activé. Non est présélectionné en votre nom. Vous pouvez toujours choisir Oui.`,no_thanks:`Non merci`,yes_help:`Oui, je veux aider`,privacy_policy:`Politique de confidentialité`},share:{button:`Partager`,button_title:`Partager ou charger une configuration de carte`,dialog_aria:`Partager la configuration de carte`,close_aria:`Fermer le panneau de partage`,share_label:`Partager cette configuration`,share_hint:`Tapez ce code dans n'importe quel navigateur exécutant l'audit pour charger cette configuration. Le code n'est jamais placé dans une URL.`,load_label:`Charger une configuration`,load_btn:`Charger`,load_placeholder:`alpine-eagle-banff`,copy:`Copier`,copied:`Copié !`,copy_failed:`Échec`,unrecognised:`Code non reconnu — vérifiez l'orthographe.`},map:{minority:`Minoritaire`,majority:`Majoritaire`,current:`Actuelle`,wasted:`Gaspillés`,wasted_title:`Contribution à l'écart d'efficacité par circonscription`,partisan:`Partisan`,partisan_title:`Colorer chaque circonscription selon le résultat partisan (UCP bleu / NDP orange)`,borders:`Frontières`,flagged:`Signalées`,flagged_title:`Les 7 configurations signalées par le président de la commission, le juge Miller — bascule automatiquement sur la carte minoritaire`,help_aria:`Aide pour la carte`,help_title:`Comment utiliser la carte`,pin_aria:`Épingler la carte`,pin_title:`Épingler la carte — empêche le défilement automatique au clic d'une circonscription`,search_placeholder:`Trouver une circonscription…`,zoom_aria:`Zoom de la carte`,clear_aria:`Effacer la sélection de circonscription`,clear_title:`Effacer la sélection`,va_hint:`Cliquez dans cette circonscription pour voir les résultats des bureaux de scrutin`,va_close_aria:`Fermer le détail du bureau de scrutin`,va_close_title:`Fermer`,object_title:`Carte des circonscriptions électorales de l'Alberta — pleine résolution`,ea_credit:`Données cartographiques :`,cc_title:`Contenu textuel : CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`},map_intro:{heading:`Comment utiliser la carte`,click_district:`Cliquez sur une circonscription`,click_district_desc:`voir les résultats électoraux 2023 et y accrocher`,click_within:`Cliquez dans une circonscription sélectionnée`,click_within_desc:`voir les résultats individuels des bureaux de scrutin (couleur = répartition du vote)`,dblclick:`Double-cliquez sur une circonscription`,dblclick_desc:`zoomer pour remplir l'écran ; double-cliquez sur un espace vide pour dézoomer`,layers_primary:`Minoritaire / Majoritaire / Actuelle`,layers_primary_desc:`basculer la carte des limites active`,layers_data:`Partisan / Gaspillés / Frontières`,layers_data_desc:`activer les couches de données`,search:`Trouver une circonscription`,search_desc:`sauter par nom ; flèches pour déplacer, + / − pour zoomer`,escape:`Échap`,escape_desc:`fermer ce visualiseur`,s4_tip:`Au §4, cliquez sur <em>Afficher les circonscriptions signalées sur la carte</em> pour mettre en surbrillance la division d'Airdrie et la zone du NO de Calgary.`,got_it:`Compris`},footer:{title:`Audit des limites électorales de l'Alberta — mai 2026`,copyright:`© Will Conner 2026 —`,text_label:`Texte :`,code_label:`Code :`}}},de:{selector:{label:`Sprache wählen`},disclaimer:{text:`Diese Website wurde von einer KI übersetzt. Einige Inhalte können noch auf Englisch erscheinen, während die Übersetzungen laufen. Wenn Sie Fehler bemerken oder bei der Übersetzung dieses Projekts helfen möchten, %s.`,link_label:`kontaktieren Sie uns bitte`},opener:{heading:`Für wen ist das gedacht?`,body:`Für uns. Für uns alle. Ob ländlich, städtisch, neugierig, politikbegeistert, Journalistin, Anwalt, Wissenschaftlerin, Politiker — für uns alle. Weil es uns alle betrifft. Ob Ihnen die Regierungspartei nun gefällt oder nicht, was die gespaltene Kommission hervorgebracht hat, gab es so noch nie. Und damit haben wir die Gelegenheit, der Maschinerie auf eine Weise hinter die Kulissen zu schauen, wie es uns zuvor nie möglich war. Jetzt können wir einen Bezugspunkt schaffen — eine Reihe von Tests, und alles, was danach kommt, lässt sich daran messen. Lassen Sie mich Ihnen zeigen, was ich gefunden habe.`},stakes:{q1:{heading:`Ist die vorgeschlagene Karte ein Gerrymander?`,body:`„Gerrymander" ist kein Begriff, den kanadische Gerichte verwenden. Aber wäre er es — im alltäglichen Sinn, den die meisten Menschen damit meinen — würden die Belege dieses Audits es vernünftigerweise rechtfertigen, den <em>Minderheitenvorschlag</em>, sollte er erlassen werden, als stark zu Parteivorteilen verzerrte Karte zu bezeichnen. Vier der fünf strukturellen Tests dieses Audits schlagen beim <em>Minderheitenvorschlag</em> Alarm, und keiner schlägt bei der Alternative (dem <em>Mehrheitsvorschlag</em>) Alarm; der fünfte Test ist für beide neutral.`,footnote:`Die Bezeichnungen „Mehrheit" und „Minderheit" gehen auf eine 3-zu-2-Spaltung innerhalb der Wahlbezirkskommission (Electoral Boundaries Commission, Vorsitz: Richter Miller) zurück, die zwei konkurrierende Vorschläge statt einer einzigen Empfehlung hervorbrachte. Die Legislativversammlung hat beide seitdem zurückgestellt und das Redistricting an ein fünfköpfiges MLA-Komitee verwiesen, das von Brandon Lunty (einem vom Premierminister ernannten MLA) geleitet wird; das Komitee beaufsichtigt ein separates vierköpfiges Unabhängiges Beratungsgremium (Independent Advisory Panel) — zwei Mitglieder vom Premierminister nominiert (Hon. Monte Solberg und Darwin Durnie), zwei vom Oppositionsführer (Dr. Gerard Kennedy und Brent Robinson) — mit dem Auftrag, vor der Frist im November 2026 einen neuen Grenzziehungsvorschlag mit 91 Sitzen vorzulegen.`},q2:{heading:`Was bedeutet „Gerrymander" im kanadischen Recht?`,body:`Nichts. Der kanadische Maßstab ist ein anderer: Ob die Grenzen den Wählerinnen und Wählern eine <em>wirksame Vertretung</em> (effective representation) nach Abschnitt 3 der Charter gewährleisten. Der Minderheitenvorschlag wirft im Hinblick auf den Standard der wirksamen Vertretung ernsthafte Fragen auf; nur ein Gericht kann sie endgültig beantworten, und niemand hat ein Gericht bislang darum ersucht.`},q3:{heading:`Was steht für Albertanerinnen und Albertaner auf dem Spiel?`,body:`Bei einem provinzweiten 50/50-Vote platzieren die Messungen des Audits den Minderheitenvorschlag in einem strukturellen Extrem: Weniger als 100 der 1,01 Millionen neutralen Vergleichskarten erzeugen die gleiche Art von Sitzungleichgewicht. Dieses Ungleichgewicht ist deshalb von Bedeutung, weil die Regierungspartei bei 58 von 87 Sitzen (eine Zweidrittel-Supermajorität) außerordentliche Verfahrensbefugnisse erlangt. Sie kann übliche Ankündigungsfristen umgehen und öffentliche Gesetzesvorlagen an einem einzigen Tag durch mehrere Lesungen treiben, wodurch die Beratungskontrollen, auf die sich die Legislative normalerweise stützt, ausgehebelt werden. Ob die Neigung des Minderheitenvorschlags groß genug ist, um eine Partei bei <em>anderen</em> Stimmverhältnissen als 50/50 über die 58-Sitz-Schwelle zu heben, ist eine Frage, die dieses Audit noch nicht geprüft hat. Ob dieses Ungleichgewicht akzeptabel ist, ist eine Frage für die Albertaner, nicht für dieses Audit.`},cta_law:`Den rechtlichen Kontext lesen →`,cta_methods:`Sehen, wie wir getestet haben →`,scorecard_h:`Das Bewertungsblatt`,scorecard_fig_alt:`Streudiagramm: Effizienzlücke auf der horizontalen Achse, Anzahl der nicht bestandenen strukturellen Tests auf der vertikalen Achse. Die 2019 erlassene Karte und die Mehrheitskarte 2026 gruppieren sich in der sicheren unteren linken Ecke. Die Minderheitenkarte 2026 erscheint alleine im Ausreißerbereich oben rechts.`,scorecard_fig_caption:`Beide Spuren in einem Bild. Horizontal: wie stark die Zahl zur Parteifairness verzerrt ist (rechts = stärker UCP-begünstigt). Vertikal: wie viele von fünf strukturellen Fairnesstests die Karte nicht besteht. Unten links ist die sichere Ecke, in der neutrale Verfahren routinemäßig landen; oben rechts ist der Ausreißerbereich. Die 2019 erlassene Karte und die Mehrheitskarte 2026 sitzen in der sicheren Ecke. Die Minderheitenkarte 2026 sitzt allein im Ausreißerbereich.`,scorecard_intro:`Zwei unabhängige Messungen, angewandt auf beide Karten unter denselben vorab registrierten Schwellenwerten. „Struktur" verwendet nur die Form der Linien — keine Wahlergebnisse. „Zahlen" prüft, wie die Linien Stimmen in Sitze umwandeln. Beide Spuren kommen zu demselben Schluss.`,scorecard_close:`Zwei unabhängige Messungen, eine Antwort. Diese Konvergenz ist das stärkste Einzelsignal des Audits.`},head:{title:`Audit der Wahlbezirksgrenzen Albertas`,meta_description:`Statistisches Audit der Wahlbezirkskommission Albertas 2026 — 1.010.000 neutrale Karten, offizielle Shapefiles von Elections Alberta, vorab registrierte Tests.`},nav:{skip_to_content:`Zum Inhalt springen`,home_aria:`Zurück nach oben`,theme_aria:`Dunkel-/Hellmodus umschalten`,theme_title:`Dunkelmodus umschalten`,nav_aria:`Inhaltsverzeichnis öffnen`,drawer_top:`↑ Anfang`,stakes:`Einsatz`,findings:`Ergebnisse`,history:`Geschichte`,reform:`Reform`,notes:`Notizen`,group_overview:`Überblick`,group_audit:`Das Audit`,group_context:`Kontext`,group_forward:`Ausblick`,group_apparatus:`Apparat`,why:`Warum ist das wichtig?`,map:`Die Karte auf einen Blick`,split:`Wie die Kommission zerbrach`,litmus:`1.010.000-Karten-Lackmustest`,crack_pack:`Cracking, Packing, Draining`,for_you:`Was das für Sie bedeutet`,impact:`Auswirkungen vor Ort`,gerrymanders:`Saubere Gerrymander`,history_full:`Eine Geschichte des Gerrymanderings`,canada:`Kanada ist anders`,november:`November`,lunty:`Lunty`,invisible:`Unsichtbar`,suggestions:`Reformvorschläge`,retractions:`Widerrufe`,references:`Quellen`,resources:`Ressourcen`,technical:`Technische Ressourcen`},hero:{h1:`Audit der Wahlbezirksgrenzen Albertas`,subtitle:`Albertas Kommission hat 2026 zwei Wahlbezirkskarten vorgelegt. Dieses Audit hat sie verglichen — mit denselben Tests, gleichermaßen auf beide angewandt — um zu fragen, ob sie die Wählerinnen und Wähler gleich behandeln.`,badge:`Offizielle Karten von Elections Alberta — veröffentlicht im Mai 2026`,cover_note:`Klicken Sie, um hineinzuzoomen und alle drei Grenzvorschläge gleichzeitig zu erkunden. Fixieren Sie den Ausschnitt und wechseln Sie zwischen den Karten — die Grenzen verschieben sich, die Wählerinnen und Wähler bleiben am selben Ort. Scrollen Sie nach unten zur Analyse.`,cover_note_1:`Diese Karte ist der beste Einstieg. Klicken Sie zum Hineinzoomen und Erkunden. Mit den Schaltflächen oben wechseln Sie zwischen der Minderheitenkarte, der Mehrheitskarte und den 2019 erlassenen Grenzen — oder überlagern Sie alle drei, um genau zu sehen, wo sie auseinandergehen. <strong>Detail</strong> färbt jeden Wahlbezirk danach, wie die Menschen 2023 gewählt haben; <strong>Trend</strong> ergänzt parteiliche Schattierung pro Bezirk (blau UCP, orange NDP); <strong>Lines</strong> blendet Grenzen ein und aus. <strong>Find</strong> springt zu jedem Bezirk per Name.`,cover_note_2:`Versuchen Sie, den Ausschnitt zu fixieren und zwischen den Karten umzuschalten — beobachten Sie, wie sich eine Grenze verschiebt, während die Wählerinnen und Wähler darunter still bleiben. Die ganze Frage in einer einzigen Geste.`,cover_note_3:`Wenn Sie mit dem Erkunden fertig sind, scrollen Sie nach unten zur Zusammenfassung. Die vollständige technische Analyse finden Sie im Abschnitt „Ressourcen". Alle Daten sind offizielle Shapefiles von Elections Alberta sowie weitere öffentliche und Open-Source-Quellen.`,image_alt:`Wahlbezirkskarten Albertas — Minderheitenvorschlag der Kommission, gefärbt nach den Stimmen von 2023`,map_hint:`Klicken Sie, um interaktiv zu erkunden`,btn_title:`Klicken, um die interaktive Karte zu öffnen`,btn_aria:`Klicken, um interaktiv zu erkunden`},boundary:{heading:`Was dieses Audit Ihnen sagen kann und was nicht`,can_1:`Die Geometrie der Minderheitenkarte überschreitet 4 von 5 vorab registrierten strukturellen Schwellen <em>ganz ohne den Einsatz von Wahldaten</em>. Der fünfte Test (Anchoring) ist neutral. Die Mehrheitskarte überschreitet 0 der 4 ausgelösten Schwellen. Diese Tests messen Eigenschaften der Grenzlinien selbst — Bezirksform, kommunale Verankerung, Bevölkerungsstreuung — und kommen zu ihrem Schluss, bevor eine einzige Stimme gezählt ist.`,can_2:`Getrennt davon liegt die Minderheitenkarte, sobald Wahldaten hinzugezogen werden, im 99,99. Perzentil von 1,01 Millionen algorithmisch gezeichneten Vergleichskarten, die denselben gesetzlichen Regeln unterliegen. Weniger als 100 dieser 1,01 Millionen neutralen Karten erreichen das gleiche Sitzungleichgewicht. Das kombinierte statistische Signal entspricht ungefähr 1 zu 14,5 Millionen unter einem neutralen Zeichenprozess. Zwei unabhängige Instrumente — ein geometrisches und ein statistisches — kommen zum selben Ergebnis.`,can_3:`Drei der Konfigurationen, die der Minderheitenvorschlag enthält, wurden vom Kommissionsvorsitzenden Richter Miller in §5.8.2 des Mehrheitsberichts und in Anhang C schriftlich beanstandet. Die Tests des Audits wurden ohne Kenntnis seiner Markierungen durchgeführt und identifizieren dieselben Regionen. Ein drittes unabhängiges Instrument — ein richterliches — konvergiert auf dieselben Grenzen.`,cant_1:`Das Audit weist <strong>nicht</strong> nach, dass irgendein Kommissionsmitglied die parteilichen Wirkungen, die es misst, beabsichtigt hätte. Grenzgeometrie kann keine Absicht offenbaren.`,cant_2:`Das Audit sagt <strong>nicht</strong> voraus, was das Lunty-Komitee wählen wird, wie der Urnengang im November 2026 ausgeht oder wie die Albertaner darauf reagieren werden.`,cant_3:`Das Audit sagt <strong>nicht</strong> voraus, wie ein Gericht entscheiden würde, falls gegen einen der beiden Vorschläge eine Charter-Klage erhoben würde.`,cant_4:`Das Audit behauptet <strong>nicht</strong>, die Zahl 1-zu-14,5-Millionen sei die Wahrscheinlichkeit, dass ein Gerrymander stattgefunden hat. Diese Zahl ist die Schwanzwahrscheinlichkeit der Minderheitengeometrie unter einer neutralen algorithmischen Nullhypothese. Sie ist ein Beleg dafür, dass die neutrale Nullhypothese unplausibel ist. Sie ist keine Posterior-Wahrscheinlichkeit für parteiliche Absicht — diese Frage erfordert Belege, die die Geometrie nicht liefern kann.`,cant_5:`Das Audit sagt <strong>keinem</strong> einzelnen Wähler, welche Position er einnehmen oder was er mit diesen Informationen tun soll. Die Wahl liegt bei Ihnen.`},editorial_intro:{heading:`Was ist Redistricting, und warum es wichtig ist`,p1:`Jeder Wähler in Alberta lebt in einem <em>Wahlbezirk</em> (electoral district) — einem Ausschnitt der Provinz, der eine Person in die Legislativversammlung wählt. Es gibt 87 Wahlbezirke. Jeder Wahlbezirk wählt einen MLA. Wenn Sie bei einer Provinzwahl Ihre Stimme abgeben, wählen Sie den MLA des Bezirks, in dem Sie wohnen. Für die meisten Albertaner ist das die gesamte Verbindung zur Legislative: ein MLA, ein Bezirk, eine Stimme.`,p2:`Diese Bezirksgrenzen sind nicht für die Ewigkeit gemacht. Menschen ziehen um, Stadtviertel wachsen, ländliche Gegenden dünnen aus, Städte breiten sich aus. Alle acht bis zehn Jahre soll Alberta die Linien neu ziehen, damit jeder Bezirk in etwa die richtige Größe hat und widerspiegelt, wie die Albertaner heute tatsächlich leben. Das Gremium, das neu zeichnet, ist die <em>Wahlbezirkskommission</em> (Electoral Boundaries Commission) — eine unabhängige Kommission aus Richtern, Anwälten und öffentlichen Mitgliedern, nicht aus Politikern.`,p3:`Das ist das Standardverfahren. Diesmal hat das Standardverfahren etwas Ungewöhnliches hervorgebracht. Die fünf Mitglieder der Kommission haben sich 3 zu 2 darüber gespalten, wie die Karte aussehen soll, und statt sich auf eine Empfehlung zu einigen, haben sie zwei vorgelegt: einen <em>Mehrheitsvorschlag</em> (von drei Kommissaren getragen) und einen <em>Minderheitenvorschlag</em> (von zwei). Beide liegen auf dem Tisch — und die Legislative hat beide zurückgestellt. Ein gesondertes Komitee aus MLAs unter Vorsitz von Brandon Lunty — vom Premierminister für genau diese Entscheidung ernannt — beaufsichtigt nun ein vierköpfiges Unabhängiges Beratungsgremium, das unter Regierungsantrag 37 (verabschiedet am 21. April 2026) eingesetzt wurde und den Auftrag hat, eine neue Karte mit 91 Sitzen zu erstellen. Die Legislative muss alles, was das Komitee liefert, vor November 2026 beschließen.`,p4:`Warum es für Sie wichtig ist: Die Linien entscheiden, wer Ihr MLA ist. Sie entscheiden, welche Stadtviertel, Orte und Anliegen gemeinsam vertreten werden. Wenn Ihre Stadt auf vier MLAs verteilt ist statt auf einen, ist kein einzelner Abgeordneter für die Stadt als Ganzes verantwortlich. Wenn Ihre Interessengemeinschaft — eine Kleinstadt, eine ländliche Region, eine Innenstadt — auf mehrere Bezirke verteilt ist, wird Ihre Stimme bei provinziellen Entscheidungen verwässert. Die Karte prägt außerdem, welche Partei eine Regierung bilden kann und mit welcher Mehrheit. Der spezifische Befund des Audits (dass der Minderheitenvorschlag in einem strukturellen Extrem liegt) ist der Grund, warum Sie diese Seite lesen, aber die übergeordnete Frage ist älter und gilt für jeden Redistricting-Zyklus: Spiegeln die Linien wider, wie die Albertaner leben, oder formen sie die Politik dabei?`,p5:`Der Rest dieser Seite zeigt, was die beiden vorgeschlagenen Karten tatsächlich machen.`,key_terms_lead:`Schlüsselbegriffe in diesem Abschnitt — klicken Sie zum Lesen:`},editorial_reflect:{heading:`Zwischenbetrachtung: Was das für Sie und Ihre Gemeinschaft bedeutet`,intro_p1:`Lassen Sie einen Moment lang die Frage beiseite, welche Partei Sitze gewinnt oder verliert. Politiker und Parteien neigen dazu, das Ganze als Kampf um die Machtkonzentration in der Legislative zu rahmen, und auf legislativer Ebene ist es das auch. Aber die Machtkonzentration in der Legislative ist nicht der Ort, an dem Sie diese Karten erleben. Sie erleben sie über drei konkrete Fragen zu Ihrem eigenen Bezirk:`,intro_q1:`Wo wohnt Ihr MLA?`,intro_q2:`Engagiert er oder sie sich für Ihre Gemeinschaft?`,intro_q3:`Werden die Forderungen des Zentrums die Forderungen der Ränder dominieren?`,intro_p2:`Jede andere Rahmung — parteilicher Vorteil, Supermajoritätsschwelle, statistisches Extrem — verweist letztlich auf diese drei zurück. Die fünf Sprossen weiter unten zeigen, wie jede vorgeschlagene Karte sie auf fünf Maßstäben beantwortet.`,you_h:`Sie.`,you_p:`Ihr Wahlbezirk entscheidet darüber, wer Sie in der Legislative vertritt. Derzeit leben Sie in einem von 87 Bezirken. Unter beiden vorgeschlagenen Karten leben Sie möglicherweise in einem anderen — möglicherweise mit einem anderen MLA, möglicherweise verankert an anderen Nachbargemeinden. Wenn Sie nicht wissen, in welchem Bezirk Sie gerade sind oder wer Ihr MLA ist, sind Sie nicht allein: Die meisten Albertaner könnten ihren MLA nicht benennen. Aber die Grenzlinien sind nicht abstrakt. Sie entscheiden, wessen Telefonnummer an der Bürowand Ihres örtlichen Vertreters hängt, wessen Nachbarschaftspetition Ihren Namen trägt, wessen Anliegen Ihr MLA zuerst hört. Die Postleitzahlsuche auf dieser Seite zeigt Ihnen, in welchem Bezirk Sie unter jedem Vorschlag liegen. Wenn sich Ihr Bezirk ändert, ändert sich Ihr Vertreter — und die Beziehung Ihres Vertreters zu Ihrer Gemeinschaft ändert sich damit.`,community_h:`Ihre Gemeinschaft.`,community_p:`Auch Gemeinschaften sind nicht abstrakt. Der Einzugsbereich einer Highschool, eine Handelskammer, eine Glaubensgemeinschaft, eine Nachbarschaftsvereinigung — das sind reale Gruppierungen von Menschen mit gemeinsamen lokalen Anliegen. Wenn eine Grenzlinie quer durch sie verläuft, ist kein einzelner MLA für das Ganze zuständig. Nehmen Sie Airdrie unter dem Minderheitenvorschlag: eine Stadt mit rund 85.800 Einwohnerinnen und Einwohnern, in vier Wahlbezirke zerschnitten, jeder an ein anderes ländliches Hinterland angedockt. Kein einzelner Vertreter ist für Airdrie als Stadt verantwortlich. Die gleiche Dynamik zeigt sich überall dort, wo ein Ort, ein Viertel oder eine anerkannte Interessengemeinschaft geteilt wird — je größer die Teilung, desto schwächer die Vertretung. Das Audit misst die <em>kommunale Verankerung</em> (welcher Anteil des Umfangs jedes Bezirks bestehenden Gemeindegrenzen folgt), und der Minderheitenvorschlag schneidet beim Anchoring-Test deutlich schlechter ab als der Mehrheitsvorschlag.`,municipality_h:`Ihre Gemeinde.`,municipality_p:`Wenn eine Stadt auf viele Vertreter zersplittert wird, schwächt das ihre Verhandlungsmacht bei provinziellen Entscheidungen. Ein Stadtrat, der um Nahverkehrsmittel bittet, eine Schulbehörde, die eine neue Schule aushandelt, ein Bürgermeister, der sich für Autobahnausbauten einsetzt — all das gelingt besser, wenn die Stadt auf wenige MLAs verweisen kann, die der Stadt als Ganzes Rechenschaft schulden. Der Minderheitenvorschlag spaltet den Nordwesten Calgarys auf mehrere Bezirke auf, deren Stimmverteilungsmuster auf <em>Packing</em> (die Konzentration der Wählerschaft einer Partei in wenige Sitze mit hohem Vorsprung) zusätzlich zum <em>Cracking</em> (die Aufteilung der Wählerschaft der anderen Partei auf viele knappe Sitze) hindeuten. Ob das Muster beabsichtigt ist, ist eine Frage, die das Audit nicht beantworten kann — Grenzgeometrie zeigt keine Absicht. Sagen lässt sich aber, dass die vier statistischen Maße dieselben Bezirke markieren wie die strukturellen Tests, und dass der Alternativvorschlag nicht denselben Fingerabdruck erzeugt.`,region_h:`Ihre Region.`,region_p1:`Wenn Sie außerhalb der Städte Albertas leben, haben Sie wahrscheinlich bemerkt, dass politische Gespräche über Grenzen immer die Städte in den Mittelpunkt rücken. Das ist ein berechtigter Einwand, also seien wir konkret darüber, was dieses Audit über das ländliche Alberta sagt und was nicht.`,region_p2:`Was es <strong>nicht</strong> sagt: Das ländliche Alberta habe zu viele Sitze. Der EBCA erlaubt, dass die Bezirksbevölkerungen um bis zu 25 % schwanken, damit ein ländlicher MLA nicht ein Gebiet von der Größe Süddeutschlands oder Frankreichs vertreten muss. Kanadische Gerichte halten diese Abweichung für legitim. Beide vorgeschlagenen Karten behalten sie bei. Nichts in diesem Audit ändert daran etwas.`,region_p3:`Was es <strong>sehr wohl</strong> sagt: An mehreren Stellen des Minderheitenvorschlags werden ländliche Gemeinden als <em>Anhängsel</em> eines Bezirks angefügt, dessen Bevölkerungszentrum in einer Stadt liegt. Schauen Sie sich an, wie der Minderheitenvorschlag mit Airdrie umgeht — eine Stadt von rund 85.800 Einwohnern, zerteilt in vier Bezirke, jeder davon in einen anderen Streifen ländlicher Umgebung verlängert. Das Bevölkerungszentrum jedes neuen Bezirks ist der städtische Anteil, nicht der ländliche Anhang. Ein aus solch einem Bezirk gewählter MLA wird höchstwahrscheinlich dort wohnen, Wahlkampf führen und Prioritäten setzen, wo die Stimmen sind — was bedeutet, dass ländliche Gemeinden, die zuvor von einem eigens für das Land zuständigen MLA vertreten wurden, zur Rückseite eines stadtgeführten Sitzes werden. Dieses Muster wiederholt sich beim Minderheitenvorschlag in einer Weise, wie es beim Mehrheitsvorschlag nicht der Fall ist.`,region_p4:`Das Audit schlägt nicht vor, dem ländlichen Alberta Sitze wegzunehmen. Es fragt, ob die Linien die ländlichen Gemeinden respektieren, die diese Sitze vertreten sollen, oder ob ländliche Geographie als Ballast benutzt wird, um städtische Stimmen in Bezirke aufzunehmen, deren Schwerpunkt anderswo liegt. Wenn Sie in einem dieser ländlichen Anhängsel leben, entscheidet die Frage, welche Karte erlassen wird, darüber, ob Ihr MLA die ländliche Gemeinschaft vertritt, in der Sie tatsächlich leben, oder einen städtischen Bezirk, dessen Grenzen Ihr Land zufällig einschließen.`,province_h:`Ihre Provinz.`,province_p:`Die Legislative ist das, was Sie erhalten, wenn Sie die Antworten jedes Bezirks auf die drei obigen Fragen zusammenzählen. Wenn die meisten Bezirke an Gemeinden verankert sind, deren MLAs auch dort leben, vertritt die Legislative diese Gemeinden. Wenn die meisten Bezirke ländliche Anhängsel an städtischen Köpfen haben, vertritt die Legislative die Köpfe — und die Anhängsel erhalten, was an Aufmerksamkeit übrig bleibt. Die parteipolitische Frage — welche Partei eine Mehrheit gewinnt — ist diesem nachgelagert. Die Supermajoritäts-Frage — ob eine Partei 58 von 87 Sitzen überschreitet und Verfahrensabkürzungen wie das Aussetzen von Ankündigungsfristen oder das Beschleunigen von Gesetzen über mehrere Lesungen an einem einzigen Tag freischaltet — ist <em>dem</em> nachgelagert. Bei einer hypothetischen 50/50-Provinzaufteilung platzieren die Messungen des Audits den Minderheitenvorschlag in einem strukturellen Extrem: Weniger als 100 der 1,01 Millionen neutralen Vergleichskarten erzeugen die gleiche Art von Sitzungleichgewicht. Ob dieses Ungleichgewicht eine Partei bei den Stimmenanteilen, die die Albertaner tatsächlich liefern, über 58 Sitze hinaustreibt, ist eine Frage, die dieses Audit noch nicht direkt geprüft hat; die Eröffnungsfragen am Anfang dieser Seite stehen ehrlich zu dieser Lücke. Ob die Antwort auf irgendeine dieser Fragen wichtig genug ist, um darauf zu handeln, ist wiederum eine Frage für Sie.`},editorial_history:{heading:`Kontext: Eine kurze Geschichte des Gerrymanderings`,p1:`Das Wort stammt aus dem Jahr 1812. Der Gouverneur von Massachusetts, Elbridge Gerry, billigte eine Karte für den Staatssenat, deren Bezirke zugunsten seiner Partei so verzerrt waren, dass ein Karikaturist aus Boston einen davon als Salamander zeichnete — mit Flügeln, Klauen und gespaltener Zunge. Das Wortspiel des Karikaturisten, <em>Gerry-mander</em>, blieb hängen. Die Form blieb es auch: Zwei Jahrhunderte später bedeutet das Wort immer noch, Wahlkreisgrenzen so zu ziehen, dass ein parteiliches Ergebnis herauskommt.`,p2:`Der Begriff hält sich, weil das Problem sich hält. Überall dort, wo Wählerinnen und Wähler ihre Vertreter aus geographischen Bezirken wählen, muss jemand die Linien ziehen, und die Linien lassen sich auf viele Weisen ziehen. Verschiedene Länder sind zu unterschiedlichen Antworten auf die Frage gekommen, wer die Linien ziehen soll und was sie binden soll.`,p3:`<strong>Die Vereinigten Staaten</strong> behandeln parteiliches Gerrymandering als ein Problem, das die Bundesgerichte größtenteils nicht beheben können. In <em>Rucho v. Common Cause</em> (2019) entschied der U.S. Supreme Court, dass parteiliche Gerrymander „politische Fragen" außerhalb seiner Zuständigkeit seien. Einige Bundesstaaten (Kalifornien, Michigan) haben darauf reagiert, indem sie unabhängige Bürgerkommissionen geschaffen haben, die ihre eigenen Linien zeichnen; andere (Texas, North Carolina) haben weiterhin offen parteiliche Karten gezeichnet und sie damit verteidigt, dass <em>Rucho</em> dies erlaube.`,p4:`<strong>Das Vereinigte Königreich</strong> verwendet vier ständige Boundary Commissions — je eine für England, Schottland, Wales und Nordirland — die mit Richtern und hohen Beamten besetzt sind. Sie zeichnen die Linien etwa alle acht Jahre nach festen Regeln neu (Bevölkerungsgleichheit, geographische Kohärenz, Beachtung kommunaler Grenzen). Das Parlament kann die Empfehlungen der Kommissionen theoretisch ablehnen, tut es in der Praxis jedoch praktisch nie; konventionell hat das Urteil der Kommissionen Bestand.`,p5:`<strong>Australien</strong> überträgt die Arbeit der Australian Electoral Commission, einer unabhängigen Bundesbehörde mit voller Befugnis sowohl für die Wahlverwaltung als auch für die Grenzen. Neuverteilungen erfolgen automatisch, wenn sich die Sitzzahl eines Bundesstaates ändert oder seit der letzten sieben Jahre vergangen sind. Die Entscheidungen der Kommissare sind aus verfahrensrechtlichen, nicht aber aus parteilichen Gründen überprüfbar. Wie im Vereinigten Königreich ist Gerrymandering, wie es die Amerikaner kennen, praktisch unbekannt.`,p6:`Diese drei Fälle umrahmen das Spektrum: Gerichte halten sich heraus (USA), unabhängige Kommissionen mit starker parlamentarischer Zurückhaltung (UK), und eine ständige unabhängige Behörde mit voller Befugnis (Australien). Kanada steht wieder an einer anderen Stelle — was der nächste Abschnitt aufgreift.`},glossary:{more_link:`Mehr erfahren →`,"electoral-district":{term:`Wahlbezirk (electoral district, ED)`,definition:`Das geographische Gebiet, das ein Mitglied in die Provinz-Legislative wählt. Nach erster Erwähnung oft als „ED" abgekürzt. Jeder ED hat einen MLA. (Das Wort „riding" bezieht sich gewöhnlich auf Bundeswahlbezirke; im Provinzkontext ist „electoral district" der korrekte Begriff.)`},riding:{term:`Riding`,definition:`Im kanadischen Sprachgebrauch bezeichnet das meist einen Bundeswahlbezirk. Das provinzielle Äquivalent in Alberta heißt „electoral district" (ED). Das Audit verwendet durchgehend den Provinzbegriff.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly — die aus einem Wahlbezirk gewählte Person, die diesen in der Legislativversammlung Albertas vertritt.`},ucp:{term:`UCP`,definition:`United Conservative Party („Vereinigte Konservative Partei") — Albertas derzeitige Provinzregierungspartei. 2017 aus der Fusion der Progressive Conservatives und der Wildrose Party hervorgegangen; regiert seit 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party („Neue Demokratische Partei", Alberta NDP) — Albertas derzeitige offizielle Opposition. Die Alberta NDP regierte von 2015 bis 2019.`},gerrymander:{term:`Gerrymander`,definition:`Eine Karte, die so gezeichnet ist, dass eine politische Partei mehr Sitze gewinnt, als ihr Stimmenanteil nahelegen würde. Das Wort stammt von einem 1812 in Massachusetts gezeichneten Bezirk in Salamanderform. Im kanadischen Recht ist es kein Rechtsbegriff, aber das Konzept ist breit erforscht.`},cracking:{term:`Cracking`,definition:`Eine Gerrymandering-Technik, die einen Wählerblock auf viele Bezirke verteilt, sodass er in keinem einzigen eine Mehrheit erreicht. Zum Beispiel die Aufteilung einer Stadt auf vier Ridings, sodass ihre Wählerinnen und Wähler in jedem überstimmt werden.`},packing:{term:`Packing`,definition:`Eine Gerrymandering-Technik, die die Wählerinnen und Wähler einer Partei in einer kleinen Zahl von Bezirken zusammenballt. Die Partei gewinnt diese Bezirke überwältigend, „verschwendet" aber viele Stimmen — und hat weniger Wähler übrig, um in anderen Bezirken anzutreten.`},draining:{term:`Draining`,definition:`Ein Begriff, den dieses Audit für einen Folgeeffekt von Cracking und Packing verwendet: Die durch diese Techniken verschwendeten Stimmen werden in strategisch gewählte Orte verschoben und verändern den politischen Charakter benachbarter Wahlbezirke. Dies ist die Einordnung des Audits selbst, kein etabliertes Konzept in der Redistricting-Literatur — das Audit prüft den Effekt und findet damit konsistente Ergebnisse, behandelt das Konzept aber als explorativ statt als gesicherte Methodik.`},anchoring:{term:`Anchoring (Verankerung)`,definition:`Wie konsequent die vorgeschlagenen Grenzen bestehenden kommunalen Linien folgen (Stadtgrenzen, Ortsgrenzen). Eine stark verankerte Karte respektiert diese Linien weitgehend; eine lose verankerte Karte weicht oft von ihnen ab — besonders an politisch bedeutsamen Stellen, was ein strukturelles Warnsignal ist.`},"charter-s3":{term:`Abschnitt 3 der Charter`,definition:`Der Abschnitt der Canadian Charter of Rights and Freedoms („Kanadische Charta der Rechte und Freiheiten"), der den Bürgerinnen und Bürgern das Wahlrecht garantiert. Kanadische Gerichte haben ihn nicht als strikte Regel „eine Person, eine Stimme" ausgelegt, sondern als Recht auf „wirksame Vertretung" (effective representation).`},"effective-representation":{term:`Wirksame Vertretung (effective representation)`,definition:`Der Maßstab, den kanadische Gerichte bei der Beurteilung von Wahlbezirksgrenzen anlegen. Er bedeutet, dass Wählerinnen und Wähler eine sinnvolle Stimme haben sollen — nicht nur numerische Gleichheit der Bezirksbevölkerungen, sondern auch die Berücksichtigung von Gemeinschaftsbindungen, Geographie und Minderheitenvertretung. Die maßgebliche Formulierung stammt aus dem Saskatchewan Reference des Supreme Court of Canada von 1991.`},ebc:{term:`Wahlbezirkskommission (Electoral Boundaries Commission, EBC)`,definition:`Das Gremium, das nach dem EBCA Albertas provinzielle Wahlbezirksgrenzen zeichnet. Die Kommission von 2026 wurde von Richter Miller geleitet und spaltete sich 3 zu 2 unter ihren Mitgliedern, sodass zwei konkurrierende Vorschläge entstanden (der Mehrheits- und der Minderheitenvorschlag) statt einer einzigen Empfehlung.`},"lunty-committee":{term:`Lunty-Komitee`,definition:`Ein fünfköpfiges MLA-Sonderausschuss zu den Wahlbezirken (Select Special Committee on Electoral Boundaries) unter Vorsitz von Brandon Lunty — einem vom Premierminister ernannten MLA — eingesetzt durch Antrag 19 der Legislativversammlung (16. April 2026), der beide Kommissionsberichte beiseitelegte. Das Komitee beaufsichtigt ein separates vierköpfiges Unabhängiges Beratungsgremium, das unter Regierungsantrag 37 (verabschiedet am 21. April 2026) eingesetzt wurde und die eigentliche Karte zeichnet; das Komitee berichtet anschließend der Legislative vor der Frist im November 2026. Beide Gremien sind getrennt vom EBC und nicht Teil des Standard-EBCA-Verfahrens.`},"advisory-panel":{term:`Unabhängiges Beratungsgremium (Independent Advisory Panel)`,definition:`Das vom Lunty-Komitee unter Klausel C(d)(ii) des Regierungsantrags 37 ernannte vierköpfige Gremium zur Erarbeitung einer Grenzempfehlung mit 91 Sitzen. Der Premierminister nominierte Hon. Monte Solberg und Darwin Durnie; der Oppositionsführer nominierte Dr. Gerard Kennedy und Brent Robinson. Ein fünfter Sitz — ein amtierender oder pensionierter Richter als Vorsitz — blieb unbesetzt, nachdem Albertas amtierender Chief Justice eine Nominierung ablehnte.`},ebca:{term:`EBCA`,definition:`Der Alberta Electoral Boundaries Commission Act (Gesetz über die Wahlbezirkskommission Albertas) — das Gesetz, das regelt, wie die Wahlbezirksgrenzen in der Provinz gezogen werden. Es schafft die Kommission, das öffentliche Anhörungsverfahren und die Regeln dafür, wann eine neue Karte in Kraft tritt.`},fsa:{term:`Forward Sortation Area (FSA)`,definition:`Die ersten drei Zeichen einer kanadischen Postleitzahl (der Buchstabe-Ziffer-Buchstabe-Teil). Etwa 270 FSAs decken Alberta ab. Die meisten liegen vollständig innerhalb eines einzelnen Wahlbezirks.`}},body:{section_link_aria:`Link zum Abschnitt`,the_map:{heading:`1: Die Karte`,p1:`Die Titelkarte ist das beste Einzelbild in diesem Audit. So lesen Sie sie.`,p2:`Alberta ist in 4.765 Voting Areas eingeteilt — kleine geographische Zonen, die Elections Alberta zur Auszählung der Wahllokal-Stimmzettel verwendet. Jede einzelne ist nach dem tatsächlichen Wahlverhalten der Menschen 2023 eingefärbt: orange dort, wo NDP-Stimmen konzentriert sind, blau dort, wo UCP-Stimmen konzentriert sind. Aber die Farbe wird nur dort dunkel und gesättigt, wo viele Menschen wohnen. Eine Voting Area, die Hunderte von Quadratkilometern Parkland oder Ackerland abdeckt, bleibt blass — nahezu unsichtbar. Die Karte leuchtet dort auf, wo Menschen sind, und verblasst dort, wo sie es nicht sind.`,p3:`Das unterscheidet sich stark von dem Alberta, das Sie am Wahlabend sehen. Die meisten Wahlkarten färben ganze Ridings nach Wahlsieg solid blau oder orange. Ländliche Ridings sind geographisch groß, und die UCP gewinnt die meisten von ihnen, sodass das Wahlabend-Alberta wie eine Wand aus Blau mit kleinen orangen Inseln in Edmonton und Calgary aussieht. Die Titelkarte verwendet dieselben Stimmen und dieselbe Geographie — zeigt sie aber gewichtet danach, wo Menschen tatsächlich leben. Was erscheint, ist eine Provinz, in der der Großteil der Bevölkerung in einem dichten Bogen aus Städten konzentriert ist, und diese Städte wählen ganz anders als die ländliche Karte, die sie normalerweise abbildet.`,p4:`Die Grenzlinien, die über die Farbe gelegt sind, sind die 89 vorgeschlagenen Wahlbezirke der Minderheitenkommission — die Karte, die dieses Audit am Ende kritisiert. Die Aufgabe des Audits besteht darin zu fragen, was diese Linien mit den Menschen darunter machen.`,p5:`Dieses Bild macht die Tragweite deutlich. Eine Provinz, die auf einer Standardkarte aussieht, als wähle sie auf eine bestimmte Weise, ist tatsächlich eine Provinz, in der die meisten Menschen in Gebieten leben, die anders wählen. Sobald die Bevölkerung unter den Grenzentscheidungen sichtbar wird, sehen diese Entscheidungen nicht mehr zufällig aus.`},structural_results:{heading:`Ergebnisse des strukturellen Audits — vor jeder Statistik:`,body:`Die Mehrheitskarte überschreitet <strong>null von fünf</strong> vorab registrierten strukturellen Schwellen. Die Minderheitenkarte überschreitet <strong>vier von fünf</strong>; der fünfte Test (Anchoring) ist neutral — beide Karten liegen innerhalb der kanadischen Norm von 70–85 %. Das sind geometrische Messungen — Bevölkerungsstreuung, <button class="vocab-term" data-def="wie eng die Bezirksgrenzen den bereits bestehenden Stadt- und Gemeindegrenzen folgen, anstatt sie zu durchschneiden" aria-expanded="false">kommunale Verankerung</button>, Anzahl der Airdrie-Aufteilungen, Bevölkerungsüberhang im Nordwesten Calgarys und die sieben Grenzkonfigurationen, die Kommissionsvorsitzender Richter Miller selbst schriftlich beanstandet hat (§5.8.2 des Mehrheitsberichts und Anhang C) —, die keinerlei Wahldaten und keinen statistischen Sampler erfordern. Der nächste Abschnitt testet beide Karten gegen 1.010.000 computergenerierte neutrale Karten und kommt durch ein völlig anderes Instrument zum selben Ergebnis. Drei unabhängige Instrumente — geometrisch, richterlich und statistisch — konvergieren.`},clean:{heading:`6: Wenn eine fair aussehende Karte es nicht ist`,legal_label:`EIN HINWEIS ZUR JURISTISCHEN TERMINOLOGIE`,legal_body:`„Gerrymandering" hat im kanadischen Recht keine rechtliche Definition. Das Wort wird in diesem Bericht durchgehend im alltäglichen politischen Sinn verwendet — Manipulation von Wahlbezirksgrenzen zugunsten einer Partei. Die in Kanada tatsächlich anwendbaren rechtlichen Prüfungen sind andere: ob die Grenzen eine „wirksame Vertretung" nach Abschnitt 3 der <em>Charter of Rights and Freedoms</em> („Kanadische Charta der Rechte und Freiheiten") gewährleisten — der verfassungsrechtliche Standard, den der Supreme Court of Canada im Saskatchewan Reference 1991 festgelegt hat — und ob die Kommission die Regeln des Albertas <em>Electoral Boundaries Commission Act</em> („Gesetz über die Wahlbezirkskommission") befolgt hat. Die Befunde des Audits sind Beweismaterial mit Bezug zu diesen Rechtsfragen. Sie sind kein Beweis für ein rechtlich definiertes Unrecht, und dieser Bericht beschreibt sie nicht in solchen Begriffen.`,intro_p1:`Die sauberste Einzelfrage, die man jeder Wahlkarte stellen kann, lautet: Wenn die Stimmenaufteilung der Provinz sich exakt gleichmäßig zwischen den beiden Hauptparteien aufteilte, welche Sitzzahl würde die Karte hervorbringen? Das hält die Wählerschaft konstant und fragt allein die Karte, was sie bewirkt.`,intro_p2:`Um diese Frage zu beantworten, hat das Audit 1.010.000 computersimulierte, mathematisch neutrale Alberta-Karten erzeugt. Die Simulation verwendete die offiziellen Shapefiles von Elections Alberta und hielt sich an genau dieselben gesetzlichen Regeln und geographischen Grenzen, die die Kommission verwendete. Die beiden Karten der Kommission von 2026 wurden dann in diese Verteilung gestellt, um zu sehen, wie normal sie sind. Die Simulation lief in vier unabhängigen Ketten von je 252.500 Schritten, wobei der Basis-Seed aus dem Cloudflare-drand-Zufallszahlenbeacon gezogen und vor der Ausführung auf OSF vorab registriert wurde.`,howmcmc_label:`WIE DIE SIMULATION FUNKTIONIERT`,howmcmc_mcmc:`<strong>MCMC (Markov Chain Monte Carlo)</strong> ist eine Methode, einen großen Raum zu erkunden — hier den Raum aller legalen Alberta-Karten —, indem sie von einem Startpunkt aus zufällige Schritte macht. Jeder Schritt schlägt einen kleinen Tausch zwischen benachbarten Bezirken vor; bleibt das Ergebnis innerhalb der gesetzlichen Regeln, wird es zum neuen Startpunkt. Nach genügend Schritten bilden die besuchten Karten eine repräsentative Stichprobe legaler Pläne. Die Simulation ist mit dem öffentlichen Zufalls-Beacon Cloudflare-drand initialisiert, um jegliches Rosinenpicken bei den Startbedingungen zu verhindern.`,howmcmc_recom:`<strong>ReCom (Redistricting Compiler)</strong> ist der hier verwendete spezifische Algorithmus. Jeder Schritt verschmilzt zwei benachbarte Bezirke zu einer Region und teilt sie zufällig erneut in zwei neue gültige Bezirke auf, wobei Zusammenhang und Bevölkerungsbalance per Konstruktion erhalten bleiben — sodass der Algorithmus nie einen ungültigen Vorschlag ablehnen muss.`,prereg_label:`VORAB-REGISTRIERUNG`,prereg_body:`Vorab-Registrierung bedeutet, die genauen Tests, Schwellen und vorhergesagten Richtungen aufzuschreiben, bevor irgendwelche Daten betrachtet werden, und diese Festlegungen in einem öffentlichen, mit Zeitstempel versehenen Verzeichnis zu sperren. Das Open Science Framework (OSF) ist das öffentliche Repository, in dem die Festlegungen dieses Audits hinterlegt sind. Es verhindert nachträgliche Anpassungen: Wenn ein Ergebnis nicht sauber erscheint, kann die Schwelle nicht im Nachhinein verändert und dann als ursprünglicher Test präsentiert werden. Alle fünf strukturellen Tests und vier Parteifairness-Metriken in diesem Audit wurden auf OSF registriert, bevor irgendeine Simulation lief.`,neutral_p:`In Alberta ist die neutrale Antwort nicht 50/50. <em>Über 1.010.000 computersimulierte legale Alberta-Karten hinweg gibt die Median-Karte der UCP bei 50/50-Stimmen nur 44,8 % der Sitze</em> — eine typische Alberta-Karte unter neutralen Stimmen verschafft der NDP eine knappe Sitzmehrheit. Das ist kontraintuitiv, aber mechanisch erklärbar: Ländliche UCP-Wählerinnen und -Wähler gewinnen ihre Ridings mit 60-zu-40-Marge (und verschwenden so viele „zusätzliche" UCP-Stimmen), während städtische NDP-Wählerinnen und -Wähler ihre Ridings mit knapperen 51-zu-49-Margen gewinnen (und so weniger NDP-Stimmen pro Sieg verschwenden). Bei Neutralität liegt die NDP bei der Sitz-Effizienz vorne.`,full_dist:`Die vollständige Verteilung aus der kanonischen 1.010.000-Karten-Simulation:`,t1_col_a:`Wo die Karte liegt`,t1_col_b:`UCP-Sitze bei 50/50-Stimmen`,t1_r1_a:`Median-Alberta-Karte`,t1_r1_b:`44,8 % — leichte NDP-Sitzmehrheit`,t1_r2_a:`Karte am 95. Perzentil`,t1_r2_b:`47,1 %`,t1_r3_a:`Karte am 99. Perzentil`,t1_r3_b:`48,4 %`,t1_r4_a:`<strong>Maximum über 1.010.000 Karten</strong>`,t1_r4_b:`<strong>unter 51,7 % (weniger als 100 Pläne erreichen diesen Wert)</strong>`,seat_count_note:`Eine Anmerkung zu den Sitzzahlen. Die beiden Kommissionskarten von 2026 haben jeweils <strong>89</strong> Bezirke; die Computersimulation des Audits läuft auf der <strong>87</strong>-Bezirks-Karte von 2019 (ihrem Startsubstrat); das Lunty-Komitee im November wird <strong>91</strong> hervorbringen. Alle Prozentsätze sind Sitz<em>anteile</em>, vergleichbar über diese Nenner hinweg. Die Simulation verwendet die Karte von 2019 als Startpunkt, weil der ReCom-Algorithmus eine gesetzlich erlassene Karte braucht, von der aus er Tausche vorschlagen kann — die Karte von 2019 ist die zuletzt erlassene Wahlkarte Albertas. Einen der beiden Kommissionsvorschläge als Substrat zu verwenden, wäre zirkulär: Wir würden messen, ob eine Karte im Vergleich zu Karten, die von ihr selbst abgeleitet sind, extrem ist.`,pattern_intro:`Die Ergebnisse — die Platzierung der drei realen Karten in dieser Verteilung — weisen auf ein spezifisches, chirurgisches Muster der Grenzziehung hin.`,sub1_h:`Alle vier statistischen Maße schlagen gleichzeitig an`,sub1_p:`Wenn die offiziellen Shapefiles von Elections Alberta verwendet werden, ist die Minderheitenkarte bei jeder einzelnen Parteifairness-Metrik ein statistischer Ausreißer — nicht nur bei der Tipping-Point-Metrik.`,t2_col_a:`Karte`,t2_col_b:`Effizienzlücke`,t2_col_c:`Mittel-Median`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Die Declination misst die Winkeldifferenz zwischen den Sitz-Stimmen-Kurven der Parteien. Negative Werte begünstigen die UCP; positive begünstigen die NDP.">Declination</a>`,t2_col_e:`Sitze bei 50/50`,t2_r1_a:`Mehrheit 2026`,t2_r1_b:`+0,04 % (p15.5)`,t2_r1_c:`−3,6 % (p2)`,t2_r1_d:`+0,027 (p81)`,t2_r1_e:`46,1 % (p83)`,t2_r2_a:`Minderheit 2026`,t2_r2_b:`<strong>+3,96 % (p94.4)</strong>`,t2_r2_c:`<strong>+1,0 % (p99.98)</strong>`,t2_r2_d:`<strong>−0,077 (p1.2)</strong>`,t2_r2_e:`<strong>51,7 % (p99.99)</strong>`,sub1_close:`Die Mehrheitskarte sitzt bei drei von vier Metriken bequem innerhalb des normalen Bereichs. Ihr Mittel-Median-Wert liegt bei p2 in NDP-begünstigender Richtung — ein ungewöhnliches Ergebnis, das aber in die falsche Richtung weist, um der UCP zu helfen. Die enge Anlehnung der Mehrheitskarte an kommunale Grenzen platziert NDP-starke städtische Kerne in eigene, kompakte Bezirke, in denen NDP-Stimmen mit effizienten Margen gewinnen, während ländliche UCP-Siege tendenziell mit größeren Margen erfolgen; dieser milde strukturelle NDP-Effizienzvorteil ist es, der sich im Mittel-Median-Wert zeigt. Die Minderheitenkarte liegt bei allen vier Maßen im Verteilungsschwanz, jeder in dieselbe parteiliche Richtung weisend.`,sub2_h:`Der 50/50-Tipping-Point: Weniger als 100 von 1.010.000 neutralen Karten erreichen ihn`,sub2_p:`Die oben eingeführte Tipping-Point-Metrik — UCP-Sitze bei einer provinzweiten 50/50-Abstimmung — ist die intuitivste Möglichkeit, die drei Karten zu vergleichen.`,t3_col_a:`Karte`,t3_col_b:`UCP-Sitze bei 50/50-Stimmen`,t3_col_c:`Wo sie sitzt`,t3_r1_a:`2019 erlassen`,t3_r1_b:`46,0 %`,t3_r1_c:`83. Perzentil — innerhalb des normalen Bereichs`,t3_r2_a:`<strong>Mehrheit 2026</strong>`,t3_r2_b:`<strong>46,1 %</strong>`,t3_r2_c:`<strong>83. Perzentil — deutlich im Rahmen</strong>`,t3_r3_a:`<strong>Minderheit 2026</strong>`,t3_r3_b:`<strong>51,7 % (46 Sitze)</strong>`,t3_r3_c:`<strong>99,99. Perzentil — weniger als 100 von 1.010.000 neutralen Ziehungen erreichen dies</strong>`,sub2_close:`Weniger als 100 von 1.010.000 computersimulierten neutralen Alberta-Karten erzeugten einen <code>seats@50/50</code>-Wert so hoch wie den des Minderheitenvorschlags. Auf Basis aktueller tatsächlicher Wahlmuster würde er der UCP 60 Sitze einbringen (im Vergleich zu 55 beim Mehrheitsvorschlag). Der Mehrheitsvorschlag ist die Art Karte, die ein neutrales Verfahren routinemäßig erzeugt. Der Minderheitenvorschlag ist die Art Karte, die man gezielt zeichnen muss.`,sub3_h:`Was das im Klartext bedeutet`,sub3_p:`Die offiziellen Shapefiles offenbaren eine Karte, die in derselben parteilichen Richtung bei allen vier Maßen gleichzeitig statistisch extrem ist. Die gemeinsame Wahrscheinlichkeit, dass ein neutraler Zeichenprozess eine über alle vier Maße gleichzeitig so extreme Karte hervorbringt, liegt bei etwa eins zu 15 Millionen (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>, <a href="https://osf.io/6pt83" rel="noopener">vorab registrierter Fisher-Kombinationstest</a>). Das ist kein Rundungsfehler und kein Messartefakt — es ist dieselbe Antwort von vier unabhängigen statistischen Instrumenten, abgelesen im selben Raum.`,details_summary:`Was dieser p-Wert bedeutet — und was nicht`,details_p1:`Ein p-Wert beantwortet eine Frage: Wenn die Karte von einem neutralen Prozess gezeichnet würde, wie oft würden wir ein so extremes oder noch extremeres Ergebnis sehen? Bei p&nbsp;=&nbsp;6.87×10<sup>−8</sup> ist die Antwort etwa einmal in 14,5 Millionen Versuchen.`,details_p2:`Das ist ein frequentistischer Hypothesentest, keine Messung von Absicht. Er sagt nicht, dass die Kommission gerrymandern wollte, und er quantifiziert nicht, wie unfair die Karte in praktischer Hinsicht ist. Er sagt: Das Grenzmuster ist statistisch unvereinbar mit einem neutralen Zeichenprozess — dieselbe Schlussfolgerung, zu der ein randomisiertes Audit gelangen würde, unabhängig davon, wer die Karte gezeichnet hat oder warum.`,details_p3:`Der Test wurde vor der Analyse der Daten vorab registriert (<a href="https://osf.io/w2s8k" rel="noopener">OSF-Registrierung w2s8k</a>). Die Vorab-Registrierung legt die Nullhypothese, die Metriken und die Ablehnungsschwelle im Voraus fest, sodass das Ergebnis nicht darauf zurückgeführt werden kann, dass nach dem Einsehen der Zahlen ein günstiger Rahmen gewählt wurde.`,szat_label:`SWING-ZONE-ZUWEISUNGSTEST (SZAT)`,szat_body:`SZAT ist der zweite unabhängige Test des Audits und stellt eine andere Frage als die Simulation: nicht „ist diese Karte insgesamt extrem?", sondern „sind die spezifischen Linienentscheidungen parteilich-neutral?" Er funktioniert, indem er nur die Voting Areas isoliert, in denen sich die Karte der Minderheit von der der Mehrheit unterscheidet — die strittigen Neuziehungen — und prüft, ob diese bestimmten Entscheidungen, zusammen genommen, die Stimmeneffizienz in Richtung einer Partei verschieben. Da er nur die Abweichungspunkte vergleicht, kontrolliert er automatisch für alles, was die beiden Karten teilen: dieselbe Geographie, Bevölkerungsziele und gesetzliche Regeln. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Technische Details und Bootstrap-Ergebnisse →</a>`,two_q:`<strong>Zwei Fragen, eine Antwort.</strong> Die 1.010.000-Karten-Simulation fragt: <em>Ist diese Karte extrem im Vergleich zu neutralen Karten, die auf derselben Alberta-Geographie gezeichnet wurden?</em> Ein zweiter, separater Test — der <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Swing-Zone-Zuweisungstest</a> — stellt eine andere Frage: <em>Sind die spezifischen Linien auf der Karte parteilich-neutral?</em> Er funktioniert, indem er nur die Voting Areas betrachtet, in denen die Minderheit anders gezeichnet hat als die Mehrheit, und fragt, ob diese bestimmten Entscheidungen, zusammen genommen, die Stimmeneffizienz in Richtung einer Partei verschoben haben. Da er nur die Stellen vergleicht, an denen sich die beiden Karten unterscheiden, kontrolliert er automatisch für alles, was sie teilen — dieselbe provinzielle Geographie, dieselben Bevölkerungsziele, dieselben gesetzlichen Regeln. Beide Fragen liefern dieselbe Antwort. Deshalb ist die Eins-zu-15-Millionen-Zahl ein kombiniertes Ergebnis und kein Einzeltest: Sie ist die Konvergenz zweier unabhängiger Beweislinien.`,super_lead:`Das erklärt, warum der Minderheitenvorschlag ein derart extremer statistischer Ausreißer sein musste (p99.99) gegen 1.010.000 neutrale Simulationen. In einer 89-Sitze-Legislative erfordert eine Zweidrittel-Supermajorität exakt 60 Sitze. Neutrale Verfahren erzeugen auf Albertas Geographie bei neutralen Stimmen keine 60-Sitze-Ergebnisse; das Erreichen der Schwelle erfordert bewusste Grenzentscheidungen, die vom neutralen Bezugswert abweichen.`,super_label:`WARUM EINE SUPERMAJORITÄT WICHTIG IST`,super_body:`Unter Kanadas Westminster-Parlamentssystem reicht eine einfache Mehrheit (45 Sitze) aus, um Routinegesetze und Haushalte zu verabschieden. Eine Zweidrittel-Supermajorität (60 Sitze) leistet mehr. Sie erlaubt der Regierungspartei, „Closure" zu beantragen, um die Debatte zu beenden, Verfahrensregeln ohne Zustimmung der Opposition neu zu schreiben und die Zusammensetzung jedes Legislativausschusses zu kontrollieren. Sie schirmt die Regierung auch gegen internen Widerspruch ab: Selbst wenn ein halbes Dutzend Hinterbänkler die Seiten wechseln würde, hielte die Regierung immer noch eine Arbeitsmehrheit. Eine einfache Mehrheit erlaubt Ihnen, das Auto zu fahren; eine 60-Sitze-Supermajorität erlaubt Ihnen, die Verkehrsregeln neu zu schreiben.`,super_close:`Indem der Minderheitenvorschlag städtische Wählerschaft strategisch in umliegende Stadtrand-Bezirke verdünnt (das in Spur 2 identifizierte Muster der „urbanen Hybridisierung"), konstruiert er genau die strukturelle Brandmauer, die nötig ist, um diese 60 Sitze zu sichern. Der strukturelle Befund aus Spur 2 und der statistische Befund aus Spur 1 konvergieren auf demselben Vorschlag, in derselben Richtung und in denselben Gemeinden.`,sub4_h:`Bestätigung durch den Test mit gezieltem Verfahren`,sub4_p:`Um sicherzugehen, dass dies kein Artefakt der bekannten Kompaktheitspräferenz der neutralen Simulation ist, hat das Audit ein gezieltes Hill-Climbing-Verfahren (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon u. a. 2022 — im technischen Bericht zitiert und beschrieben</a>) in beide Richtungen laufen lassen: maximale UCP-Sitze und maximale NDP-Sitze. Gleiche Schrittzahl (40.000) in beide Richtungen, gleiche gesetzliche Einschränkungen, gleiche provinzielle Geometrie.`,t4_col_a:`Verfahren`,t4_col_b:`Erreichter Extremwert`,t4_col_c:`Was es uns sagt`,t4_r1_a:`Neutrales MCMC, max. erzeugt`,t4_r1_b:`unter 51,7 % UCP-Sitze @ 50/50`,t4_r1_c:`Die natürliche Obergrenze unter neutraler Zeichnung`,t4_r2_a:`Neutrales MCMC, min. erzeugt`,t4_r2_b:`~39 % UCP-Sitze @ 50/50`,t4_r2_c:`Die natürliche Untergrenze unter neutraler Zeichnung`,t4_r3_a:`Gezieltes Hill-Climb, UCP-maximierend`,t4_r3_b:`<strong>52,9 %</strong>`,t4_r3_c:`Was ein Verfahren, das bewusst auf UCP-Vorteil zielt, erreichen kann`,t4_r4_a:`Gezieltes Hill-Climb, NDP-maximierend`,t4_r4_b:`<strong>37,9 %</strong>`,t4_r4_c:`Was ein Verfahren, das bewusst auf NDP-Vorteil zielt, erreichen kann (unter der neutralen Untergrenze)`,sub4_close:`Die 51,7 % der Minderheitenkarte liegen näher an der UCP-Zielobergrenze (52,9 %) als am neutralen Median (44,8 %). Die 46,1 % der Mehrheitskarte liegen am neutralen Median. Sowohl die 2019 erlassene Karte als auch die Mehrheit 2026 fallen bequem in den Bereich, den ein neutrales Verfahren routinemäßig erzeugt — unterschiedliche Stimmanteile, dieselbe Zone unauffälliger Ergebnisse. Die Mehrheit setzt die Alberta-Praxis von 2019 auf der Achse der Parteifairness genauso fort wie die Praxis von 2019 bei der kommunalen Verankerung (80,0 % gegenüber 75,2 % im Jahr 2019). Zwei Karten, gezeichnet unter denselben Alberta-Regeln, von denselben fünf Kommissaren, im selben Raum: Die eine landet dort, wo neutrale Verfahren routinemäßig hinkommen, die andere landet dort, wo man gezielt landen muss.`,sub4_quote:`<em>So</em> sieht der Befund aus, und so wäre auch der Rahmen, den ein Gericht tatsächlich anwenden würde.`,sub5_h:`Alternative Erklärungen ausschließen`,sub5_p:`Angesichts eines statistischen Ausreißers dieser Größenordnung muss ein gründliches Audit harmlose Erklärungen ausschließen, bevor es diese Muster bewusster Gestaltung zuschreibt. Die strukturellen Daten (Spur 2) entkräften die üblichen alternativen Verteidigungen systematisch:`,defense1:`<strong>Die Verteidigung mit „natürlicher politischer Geographie":</strong> <em>(„Die städtischen Wählerinnen und Wähler sind natürlicherweise konzentriert; die Karte spiegelt einfach Albertas Geographie wider.")</em> Die 1.010.000 Simulationen berücksichtigen Albertas natürliche Geographie bereits. Die Simulation zeigt: Während die Geographie der UCP einen Grundlinien-Effizienzvorteil verschafft, deckelt sich dieser natürlich um das 83. bis 90. Perzentil. Die Minderheitenkarte sitzt beim 99,99. Perzentil — ein extremer Ausreißer <em>selbst im Vergleich zu Albertas natürlich verzerrter Grundlinie</em>.`,defense2:`<strong>Die Verteidigung mit „Interessengemeinschaften":</strong> <em>(„Die seltsamen Formen wurden gezeichnet, um bestimmte Gemeinschaften zusammenzuhalten.")</em> Wenn Sie versuchen, Gemeinschaften zusammenzuhalten, folgen Sie kommunalen Grenzen. Die Mehrheitskarte folgte bestehenden Stadtgrenzen zu 80 %. Die Minderheitenkarte folgte ihnen zu 72 % — beide innerhalb der kanadischen Norm von 70–85 %. Was die Minderheitenkarte allerdings tut: Sie spaltet die einheitliche Stadt Airdrie aktiv in vier separate Stücke und platziert drei ihrer Grenzentscheidungen genau in den Stadtrand-Zonen, die der Kommissionsvorsitzende als geometrisch anormal beanstandet hat — Entscheidungen, die sich mit der Logik der Interessengemeinschaft nicht erklären lassen.`,defense3:`<strong>Die Verteidigung mit „Bevölkerungsgleichheit":</strong> <em>(„Sie mussten seltsame Grenzen ziehen, um sicherzustellen, dass jeder Bezirk genau dieselbe Bevölkerung hat.")</em> Die Minderheitenkarte ist bei der Bevölkerungsgleichheit tatsächlich deutlich <em>schlechter</em>. Ihre Population Mean Absolute Deviation (MAD) lag bei 4.707 — 48 % größer als die 3.180 der Mehrheitskarte —, was sie auf das 99. Perzentil des kanonischen Ensembles platziert (nur 1 von 100 neutralen Karten erzeugt eine schlechtere Streuung). Sie opferte Bevölkerungsgleichheit, um ihre Form zu erreichen.`,defense4:`<strong>Die Verteidigung mit „Inkompetenz oder Pech":</strong> <em>(„Sie haben einfach eine schlampige Karte gezeichnet und hatten Pech mit den Zahlen.")</em> Genau 60 Sitze für eine Supermajorität zu treffen, gleichzeitig Airdrie in vier Stücke zu spalten und drei Grenzen exakt in die Zonen zu legen, die der Kommissionsvorsitzende selbst als anormal beanstandet hat, erfordert chirurgische Präzision. Die gemeinsame Wahrscheinlichkeit, versehentlich eine Karte zu zeichnen, die bei vier unabhängigen parteilichen Metriken gleichzeitig im extremen statistischen Schwanz landet, liegt bei rund <strong>1 zu 15 Millionen</strong> (p&nbsp;=&nbsp;6.87×10<sup>−8</sup>). Man stolpert nicht ins 99,99. Perzentil.`,sub5_close:`Was die Daten zeigen, ist, dass der Minderheitenvorschlag sowohl die Bevölkerungsparität als auch die Gemeindekohäsion gegenüber dem verschlechterte, was dieselben fünf Kommissare gleichzeitig unter identischen gesetzlichen Regeln hervorbrachten. Das Audit stellt nicht fest, was die Minderheitskommissare beabsichtigten — Grenzgeometrie kann keine Absicht offenbaren —, aber die strukturelle Abweichung sowohl vom neutralen Ensemble als auch vom Ergebnis des Mehrheitsvorschlags steht unabhängig von der Absicht fest.`,sub6_h:`Eine Anmerkung zur R-Kreuzvalidierung`,sub6_p1:`Eine frühere Version dieses Audits (das angenäherte statt offizielle Shapefiles verwendete) hat das Python-ReCom-Ensemble gegen den Sequential-Monte-Carlo-Sampler des R-Pakets <code>redist</code> kreuzvalidiert. Die Gegenprüfung lieferte instabile Ergebnisse: Über drei Läufe mit demselben nominalen Seed lag der Anteil der Pläne, die den alten Minderheitenwert (48,3 % auf der angenäherten Geometrie) erreichten, bei 5,6 %, dann 28 %, dann 58 % — ein Sampler-Konvergenzversagen, kein Befund. Die vollständige Aufarbeitung findet sich unter <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`Mit offiziellen Shapefiles von Elections Alberta steigt der <code>seats@50/50</code>-Wert der Minderheitenkarte auf 51,7 % — einen Wert, den weniger als 100 von 1.010.000 neutralen Plänen erreichen. Die Frage der R-Kreuzvalidierung wird damit gegenstandslos: null Pläne aus beiden Samplern erreichen den kanonischen Wert bei vergleichbaren Stichprobengrößen.`,sub6_asymm:`<strong>Die Asymmetrie um 50/50 ist aufschlussreicher als die Inversion selbst.</strong> Ein Präzisionsscan der Sitz-Stimmen-Kurve mit einer Auflösung von 0,01 Prozentpunkten findet, dass die Minderheitenkarte die UCP bis zu einem provinziellen UCP-Stimmenanteil von etwa <strong>49,7 %</strong> auf oder über der gesetzlichen Mehrheitsschwelle von 45 Sitzen hält. Das ist technisch gesehen eine Stimm-Sitz-Inversion — die UCP würde mit der Minderheitenkarte die Regierung bilden, während sie die Volksstimme um 0,3 Prozentpunkte verlöre —, aber 0,3 Punkte liegen gut im üblichen Umfrage-Rauschen, sodass dies für sich genommen kein dramatischer Befund ist. Was <em>dramatisch</em> ist, ist der Kontrast: Auf der <strong>Mehrheitskarte</strong> müsste die UCP die Volksstimme mit etwa 4 Prozentpunkten <em>gewinnen</em>, um dieselbe 45-Sitze-Schwelle zu erreichen. Beide Karten stehen vor derselben Alberta-Geographie und denselben gesetzlichen Regeln; der Abstand zwischen ihnen — 0,3 Punkte vs. +4 Punkte — ist struktureller Unterschied, nicht Rauschen.`,sub6_close:`Dies ist der strukturelle Verzerrungsbefund, den das Audit mit Zuversicht vertritt. Er ist rein geometrisch; er hängt von keinem Wahlergebnis ab; er bewegt sich nicht, wenn sich Umfragen bewegen.`,sub6_caveat:`<strong>Einen Vorbehalt nimmt das Audit ernst.</strong> Eine reale Wählerschaft ist nicht gleichmäßig 50/50. Wählerinnen und Wähler können die strukturelle Neigung jeder Karte mit ausreichender Schwankung übertrumpfen — eine besonders verärgerte oder inspirierte Wählerschaft wird das Ergebnis unabhängig vom Verlauf der Grenzen kippen. Der 50/50-Test isoliert <em>den Beitrag der Karte zum Ergebnis</em>, nicht das Ergebnis selbst. Er zeigt, was die Karte tut, wenn die Wählerschaft nicht für sie entscheidet.`,sub7_h:`Die Quintessenz`,sub7_p1:`Der zentrale Befund des Audits ist geometrisch. <strong>Spur 2 — das Bewertungsblatt zur strukturellen Unregelmäßigkeit — ist das Fundament; Spur 1 ist der Nachweis, dass die Geometrie parteiliche Arbeit leistet.</strong>`,sub7_p2:`Das nachfolgende Diagramm bringt beide Spuren in ein einziges Bild. Die horizontale Achse ist Spur 1 (die Parteifairness-Effizienzlücke, wobei weiter rechts stärker UCP-begünstigt bedeutet); die vertikale Achse ist Spur 2 (die Anzahl der nicht bestandenen strukturellen Fairness-Tests des Vorschlags, von fünf, wobei höher mehr strukturelle Probleme bedeutet).`,stakes_fig_alt:`Streudiagramm mit Effizienzlücke auf der horizontalen Achse und Anzahl der nicht bestandenen strukturellen Tests auf der vertikalen Achse. Die 2019 erlassene Karte und die Mehrheitskarte 2026 gruppieren sich in der sicheren unteren linken Ecke. Die Minderheitenkarte 2026 erscheint im Ausreißerbereich oben rechts.`,stakes_fig_caption:`Die beiden Methoden zur Messung der beiden Kommissionsvorschläge, gemeinsam aufgetragen. Links nach rechts: Wie stark der Vorschlag bei der Parteifairness-Zahl verzerrt aussieht — je weiter rechts, desto stärker begünstigt er die UCP. Unten nach oben: Wie viele von fünf strukturellen Fairness-Tests der Vorschlag nicht besteht — je höher, desto schlechter. Die 2019 erlassene Karte sitzt in der sicheren Ecke: bei beiden niedrig. Der Mehrheitsvorschlag 2026 bleibt flach bei null strukturellen Problemen und nahezu null parteilicher Verzerrung (+0,1 %). Der Minderheitenvorschlag 2026 ist bei jedem Test, der die beiden Karten unterscheidet, ein struktureller Ausreißer (4 von 5; der fünfte, Anchoring, ist für beide neutral); seine Effizienzlücke (+4,0 %) sitzt knapp unter der Alberta-Schwellenlinie.`,stakes_table_intro:`Dieselben Befunde in klarer Übersichtsform, mit dem strukturellen Befund vorangestellt, weil die kreuzvalidierte Evidenz ihn am stärksten stützt:`,t5_col_b:`Spur 2: Struktur (nur Geometrie, keine Stimmen)`,t5_col_c:`Spur 1: Zahlen (stimmenabhängig)`,t5_r1_a:`<strong>Mehrheit 2026</strong>`,t5_r1_b:`sauber — überschreitet <em>keine</em> strukturelle Schwelle`,t5_r1_c:`innerhalb des normalen Bereichs bei jeder Metrik (<code>seats@50/50</code> 46,1 % — p83; Effizienzlücke +0,04 %)`,t5_r2_a:`<strong>Minderheit 2026</strong>`,t5_r2_b:`<strong>überschreitet 4 von 5 strukturellen Schwellen</strong> mit großem Abstand (Anchoring neutral — beide Karten innerhalb der kanadischen Norm)`,t5_r2_c:`statistischer Ausreißer bei allen vier Parteifairness-Maßen gleichzeitig — <code>seats@50/50</code> 51,7 % (p99.99, weniger als 100 von 1.010.000 erreichen das); Effizienzlücke +3,96 % (p94.4); alle vier vorab registriert; Fisher kombiniert p&nbsp;=&nbsp;6.87×10<sup>−8</sup>`,details2_summary:`Warum Spur 2 den Fall trägt — technische Details`,details2_p:`Das Audit hat am 24. April 2026, vor der Zusammenstellung der finalen Simulationsergebnisse, fünf Tests zur strukturellen Unregelmäßigkeit vorab registriert. Anchoring ist für beide Karten neutral; bei den verbleibenden vier Tests überschreitet die Minderheit jeden einzelnen und die Mehrheit keinen. Diese Messungen sind geometrisch — sie hängen von keinem statistischen Sampler und keiner Stimmzuordnung ab. Spur 1 (die Parteifairness-Zahlen) bestätigt Spur 2 unter den kanonischen offiziellen Shapefiles stark: Die Minderheit ist bei allen vier vorab registrierten Metriken gleichzeitig ein statistischer Ausreißer, mit einer gemeinsamen Wahrscheinlichkeit unter der neutralen Nullhypothese von p&nbsp;=&nbsp;6.87×10<sup>−8</sup> (vorab registrierter Fisher-Kombinationstest — eine Methode, die vier unabhängige Testergebnisse zu einer einzigen Wahrscheinlichkeit verbindet, indem sie ihre individuellen Schwanzwahrscheinlichkeiten multipliziert; die kombinierte Zahl ist viel kleiner als die jedes einzelnen Tests, weil alle vier in dieselbe Richtung weisen; OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>). Die Frage, ob die ungewöhnliche Geometrie aus Spur 2 der spezifische <em>Mechanismus</em> hinter den Zahlen aus Spur 1 ist, wurde getestet, und die Antwort lautet nein — siehe <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>. Der Swing-Zone-Zuweisungstest zeigt, dass die strittigen Grenzentscheidungen parteilich verzerrt sind, aber die getestete Frage war, ob die Grenzformen selbst — der Lasso-Korridor, die Park-Verlängerung — die direkte Ursache des Sitzwechsels sind; das sind sie nicht. Der Sitzeffekt rührt daher, wie umgezeichnete Voting-Area-Zuordnungen die Stimmeneffizienz über die Bezirke hinweg verschieben, nicht aus den Formen an sich. Beide Spuren markieren die Minderheitenkarte; sie kommen über unabhängige Instrumente dorthin. Spur 2 ist der zentrale Befund. Spur 1 bestätigt, ohne zu tragen.`},impact:{heading:`5: Auswirkungen auf die Repräsentation`,lanes_label:`SPUR 1 UND SPUR 2`,lanes_body:`<strong>Spur 1 (Zahlen)</strong> verwendet Wahlergebnisse, um zu prüfen, ob die Karte Stimmen fair in Sitze umwandelt — sie fragt, wie die Karte sich über unterschiedliche Stimmverteilungen verhält. <strong>Spur 2 (Struktur)</strong> untersucht nur die gezogenen Linien — Stadtteilungen, Bevölkerungsstreuung, Grenzformen — ohne jegliche Wahldaten. Jede Spur ist unabhängig: Eine Karte kann eine nicht bestehen und die andere bestehen. Der Minderheitenvorschlag besteht beide nicht; der Mehrheitsvorschlag besteht beide.`,intro:`Spur 1 hängt davon ab, welche Wahlergebnisse Sie zur Bewertung der Karten heranziehen. Spur 2 nicht. Die strukturelle Evidenz liegt in den Karten selbst — gezogene Linien, geteilte Städte, wo die Grenzen Verwaltungslinien folgen und wo nicht, die aus anderen Gründen existieren. Bei diesen Tests liegen die beiden Karten nicht nah beieinander.`,fig_alt:`Balkendiagramm, das fünf strukturelle Fairness-Tests nebeneinander vergleicht. Die Balken der Mehrheitskarte liegen bei null oder gut innerhalb sicherer Bereiche. Die Balken der Minderheitenkarte überschreiten die Schwelle bei vier der fünf Tests mit großem Abstand; der fünfte (Anchoring) ist für beide Karten neutral.`,fig_caption:`Die fünf strukturellen Fairness-Tests im Seitenvergleich. Türkisfarbene Balken sind die Mehrheitskarte; lila Balken sind die Minderheitenkarte. Die gestrichelte Linie in jeder Zeile markiert die Versagensschwelle. Die Minderheitenbalken überschreiten die Schwelle bei vier der fünf Tests mit großem Abstand; der fünfte (Anchoring) ist für beide Karten neutral. Die Mehrheitsbalken liegen flach bei null oder gut innerhalb des sicheren Bereichs.`,table_intro:`Dieselben fünf Tests in Tabellenform, jeweils mit der Schwelle des Tests neben dem Ergebnis. Die unterste Zeile ist die <em>Zusammenfassung</em> des Audits — die Anzahl der nicht bestandenen Tests jeder Karte von den fünf.`,table_col_test:`Test`,table_col_majority:`Mehrheitskarte`,table_col_minority:`Minderheitenkarte`,table_col_direction:`Richtung / Begünstigter`,table_r1_a:`Grenze folgt bestehenden kommunalen Linien (kanadische Norm 70–85 %)`,table_r1_b:`80 % — im Rahmen der Norm`,table_r1_c:`72 % — im Rahmen der Norm`,table_r1_d:`N/Z — beide innerhalb der kanadischen Norm`,table_r2_a:`Bevölkerungsstreuung (enger ist besser)`,table_r2_b:`3.180`,table_r2_c:`4.707 — 48 % weiter`,table_r2_d:`Strukturell (Reduziert Wahlgleichheit)`,table_r3_a:`Bevölkerungsüberhang NW Calgary über dem Durchschnitt`,table_r3_b:`2,8 %`,table_r3_c:`11,5 %`,table_r3_d:`<strong>UCP</strong> (Packt städtische NDP-Stimmen)`,table_r4_a:`Vom Kommissionsvorsitzenden selbst beanstandete Grenzen`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`N/Z`,table_r5_a:`Airdrie-Aufteilung (gesetzliches Minimum: 2)`,table_r5_b:`2 Stücke`,table_r5_c:`4 Stücke`,table_r5_d:`<strong>UCP</strong> (Cracking der städtischen/vorstädtischen Macht)`,table_r6_a:`<strong>Vorab registrierte Zusammenfassung</strong> (&ge; 4 von 5 = Ausreißer)`,table_r6_b:`<strong>0 von 5 ausgelöst</strong>`,table_r6_c:`<strong>4 von 5 ausgelöst</strong> (Anchoring-Test neutral — beide Karten innerhalb der kanadischen Norm; übrige 4 Tests alle ausgelöst)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`Ein gesonderter Befund, nur auf die Minderheit angewandt: <strong>fünf von sechs der von den Minderheitskommissaren veröffentlichten Begründungen halten einer unabhängigen Prüfung nicht stand</strong>. Der Test läuft nur gegen die Minderheit, weil die Mehrheit keine Liste umstrittener Neuziehungs-Begründungen veröffentlichte — das Audit kann ihn nicht symmetrisch anwenden, und er wird hier als einzelne Markierung berichtet, nicht als zusätzliche Zeilen in der Zählung struktureller Unregelmäßigkeiten. (Eine siebte Neuziehung, die das Audit zuvor aufgeführt hatte, beruhte auf einer Bundesgrenzen-Behauptung, die im Minderheitenbericht nicht nachverfolgbar war; sie wurde entfernt statt als schwache Behauptung stehen gelassen.)`,chair_appendix_p:`Das Audit hat auch die gesonderte, pauschale Behauptung des Vorsitzenden in Anhang C geprüft, dass die sieben strittigen Hybridkonfigurationen der Minderheit in den über 1.140 öffentlichen Eingaben <strong>keinerlei öffentliche Unterstützung</strong> hätten. Eine Stichwortsuche über das gesamte Eingaben-Archiv (94 % maschinell verarbeitet, 6 % nur als Bild und daher ausgeschlossen; Methodik und konfigurationsspezifische Belege unter <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) ergab ein nuancierteres Bild als die pauschale Behauptung des Vorsitzenden oder deren pauschale Ablehnung: Der Vorsitzende lag in drei von sieben Fällen richtig (die Vierfach-Aufteilung Airdrie, die Hybrid-Konfiguration Calgary–Nolan-Hill–Cochrane und die Minderheitenalternative St. Albert haben keine dokumentierte Unterstützung), in drei von sieben Fällen falsch (Rocky Mountain House–Banff Park erhielt einen expliziten, detaillierten Vorschlag aus mindestens einer Eingabe aus der Clearwater-Region sowie mehreren ähnlichen; Olds–Three-Hills–Didsbury wurde von Einwohnern Beisekers schriftlich unterstützt; Chestermere erhielt mehrere Eingaben gegen eine Fusion mit Calgary, die inhaltlich mit der Absicht der Minderheit übereinstimmen), und teilweise falsch in einem Fall (Red-Deer-Hybride erhielten von einem amtierenden Stadtrat in Red Deer einen Hybridvorschlag in der Umgebung von Red Deer mit richtungsweisender, aber nicht konfigurationsgenauer Übereinstimmung). Die pauschale „keine öffentliche Unterstützung"-Aussage in Anhang C des Vorsitzenden ist daher nachweislich überdehnt — drei von sieben sind nachweislich falsch —, aber sie ist nicht aus dem Nichts erfunden, da drei von sieben standhalten. <strong>Dieser Befund spricht gegen den Vorsitzenden, nicht gegen die Minderheit.</strong>`,summary_p:`<strong>In Spur 2 überschreitet die Mehrheit null strukturelle Schwellen. Die Minderheit überschreitet jede einzelne mit großem Abstand.</strong>`},cpd:{heading:`4: Cracking, Packing und Draining`,vocab_label:`Drei Züge, ein Spielbuch`,vocab_packing:`<strong>Packing</strong> bedeutet, die Wählerinnen und Wähler einer Partei in Bezirke zu pferchen, die die Partei mit Erdrutschmehrheit gewinnt — jeder gepackte Stimmzettel zählt zwar weiterhin, trägt aber nichts über den Sieg hinaus bei. Große, einseitige Siege. Verschwendete Stimmen.`,vocab_cracking:`<strong>Cracking</strong> bedeutet, eine Gemeinschaft auf mehrere Bezirke zu zersplittern, sodass sie keinen einzigen direkt gewinnt. Eine Stadt, die zwei Sitze tragen könnte, wird in vier zerschnitten, jeder an ein anderes ländliches Gebiet gekoppelt. Verdünnte Stimmen. Kein Sitz für niemanden.`,vocab_draining:`<strong>Draining</strong> ist der räumliche Begleiter: Gepackte und gecrackte Bezirke werden nebeneinander platziert, sodass überkonzentrierte Anhängerinnen und Anhänger der einen Seite Wahlmacht von den umliegenden umkämpften Bezirken „abziehen". Das Nachbarschaftsmuster verstärkt beide Effekte — Packing und Cracking verstärken sich gegenseitig über Bezirksgrenzen hinweg.`,vocab_disclaimer:`Alle drei können ohne ausdrückliche parteiliche Absicht auftreten. Was das Audit misst, ist, ob das Muster — und sein statistisches Ausmaß — mit dem übereinstimmt, was ein neutraler Kartenziehungsprozess hervorbringt. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Vollständige Methodik in §5 des technischen Berichts.</a>`,fig_alt:`Karte, die die Aufteilung Airdries in vier separate Bezirke unter der Minderheitenkarte zeigt`,fig_caption:`Die Aufteilung Airdries in vier separate Bezirke unter der Minderheitenkarte, die ihre städtische Wahlmacht verdünnt.`,intro:`Die fünf Kommissare arbeiteten mit denselben gesetzlichen Regeln, derselben provinziellen Geographie, demselben Archiv von 1.140 öffentlichen Eingaben und denselben demografischen Daten. Ihre zwei konkurrierenden Entwürfe stimmen in den meisten Teilen Albertas überein. Wo die Entwürfe auseinandergehen, gehen sie an Entscheidungen auseinander, die jemand im Raum treffen musste. Drei dieser Entscheidungen lohnt es sich, als Entscheidungen zu sehen, nicht als Zahlen.`,airdrie_p:`<strong>Es teilt die Stadt Airdrie in vier Stücke.</strong> Das Gesetz deckelt jeden Wahlbezirk auf eineinviertelmal den provinziellen Durchschnitt, sodass Airdrie mindestens zwei Bezirke braucht. Die Mehrheitskarte gibt ihr zwei. Die Minderheit gibt ihr vier — nach Norden zu Calgary-Nolan Hill-Cochrane, nach Osten zu Airdrie East, nach Westen zu Calgary-Foothills-Airdrie West und im Süden/Zentrum zu Calgary-Airdrie — jeder einzelne an einen anderen ländlichen oder Calgary-nahen Bezirk angeklammert. Eine Einwohnerin Airdries mit einer Frage an ihren MLA muss wissen, in welchem Viertel der Stadt sie wohnt, bevor sie das richtige Büro anrufen kann. Ihre Nachbarn zwei Blocks weiter werden ihr drei verschiedene Antworten geben. Die Eltern-Lehrer-Vereinigung an der Schule ihres Kindes kann nicht eine einzige Delegation zu einem MLA zu einer Frage der Schulfinanzierung schicken; sie muss vier Delegationen in vier Büros koordinieren, wobei jeder MLA in erster Linie einer anderen ländlichen oder vorstädtischen Wählerschaft verpflichtet ist. Der Eishockey-Nachwuchsverband, die Tafel, die Handelskammer — jede stadtweit operierende Organisation operiert nun über vier provinzielle Ridings hinweg.`,airdrie_callout_label:`WARUM AIRDRIE WICHTIG IST`,airdrie_callout_p1:`Airdrie ist die größte Alberta-Stadt ohne eigenen MLA. Mit 85.805 Einwohnerinnen und Einwohnern (Gemeindezählung 2024) ist sie größer als Red Deer; sie hat einen Stadtrat, eine Steuerrechnung, ein Schulbezirk — jedes Verwaltungssystem behandelt sie als Einheit.`,airdrie_callout_p2:`Sie auf vier Provinzbezirke aufzuteilen — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Calgary-Nolan Hill-Cochrane und Airdrie East —, jeder primär mit einer anderen umliegenden Gerichtsbarkeit identifiziert, entfernt Airdrie auf der Regierungsebene, die sie zeichnet, aus der politischen Karte. Die Stadt hat 85.805 Einwohnerinnen und Einwohner und null Sitze in der Legislative, in der die Mehrheit der Wählerinnen und Wähler den Ort ihr Zuhause nennen.`,airdrie_callout_p3:`Eine Vierer-Aufteilung ist für jeden Parteifairness-Test unsichtbar — außer für den, der fragt: Kann eine Wählerin ihren MLA finden?`,airdrie_callout_summary:`Beide Karten sind legal. Die Vierer-Aufteilung ist eine Wahl.`,airdrie_btn:`Beanstandete Bezirke auf der Karte zeigen`,anchoring_p:`<strong>Wo sie von kommunalen Linien abweicht, weicht sie an strategisch wichtigen Stellen ab.</strong> Wenn Wahlkarten dem Rand einer Stadt oder eines Orts folgen, erkennen Wählerinnen und Wähler, wo ihr Bezirk beginnt und endet — die Grundsteuerlinie, die Schulbezirkslinie, die Kommunalwahl-Bezirkslinie und die Provinzwahllinie fallen alle zusammen. Statistics Canada veröffentlicht diese Grenzen kostenlos. Auf den offiziellen Shapefiles von Elections Alberta folgen beide Karten kommunalen Linien zu vergleichbaren Gesamtraten: die Mehrheit zu 80 %, die Minderheit zu 72 %, beide innerhalb der kanadischen Norm von 70–85 % (Quebec: 78 %, Ontario: 82 %, BC: 71 %; Vergleichskommissionen in der Monographie dokumentiert). (Die anfängliche, vorläufige Analyse des Audits zeigte die Minderheits-Verankerung nur bei 15 %; diese Zahl überstand die Neuberechnung auf den offiziellen Shapefiles nicht — siehe Korrekturhinweis unten.) Die bemerkenswerte Beobachtung ist nicht die Gesamtrate, sondern wo die Abweichungen der Minderheit konzentriert sind: Die drei Grenzen, die der Kommissionsvorsitzende selbst als anormal beanstandet hat — Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">zeigen ↗</button>s Verlängerung in unbewohntes Nationalparkland, der Lasso-Korridor Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">zeigen ↗</button> und die Olds–Nord-Airdrie-Erweiterung <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">zeigen ↗</button> — sind allesamt Abweichungen von bestehender ziviler Geographie genau in den Stadtrandzonen, in denen die Paarung städtischer und ländlicher Wählerinnen und Wähler am unmittelbarsten beeinflusst, welche Partei den Sitz gewinnt.`,anchoring_followup:`Die Minderheitskommissare gaben für jede der drei beanstandeten Grenzen Gründe an. Für Rocky Mountain House–Banff Park nannten sie die geographische Größe, den Highway-22-Korridor und die Nähe von First-Nations-Reservaten zu Rocky Mountain House; der Kommissionsvorsitzende nannte die Verlängerung in unbewohntes Nationalparkland „einen Versuch in bösem Glauben", das Flächenkriterium zu erfüllen, und die Formulierung erscheint im offiziellen Abschlussbericht der Kommission. Für Nolan Hill–Cochrane verwiesen sie auf gemeinsame Verkehrs- und Beschäftigungsverbindungen zwischen Nordwest-Calgary und Cochrane; Daten von Statistics Canada zum Pendelverhalten zeigen, dass nur 35,8 % der Arbeitenden in Cochrane überhaupt nach Calgary fahren, und die meisten arbeiten innerhalb Cochranes selbst. Für die Olds–Nord-Airdrie-Erweiterung verwiesen sie auf die Kontinuität des Highway-2-Korridors; das Audit fand, dass die spezifische Airdrie-Erweiterung aus Bevölkerungsgründen scheitert. Eine unabhängige Prüfung ergab, dass fünf der sechs veröffentlichten Unterbegründungen der Minderheit gegen Primärdaten ganz oder teilweise versagen.`,packing_p:`<strong>Ein Gebiet Calgarys wird zerschnitten, um NDP-Wählerinnen und -Wähler in überdurchschnittlich große Bezirke zu konzentrieren.</strong> Im nordwestlichen Quadranten Calgarys <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">zeigen ↗</button> liegen die Bezirke der Minderheitenkarte im Durchschnitt 11,5 % über der provinzweiten Bevölkerung — gegenüber 2,8 % bei der Mehrheit. Dieselbe geographische Zone, gezeichnet von derselben Kommission unter denselben Bedingungen, erzeugt Bezirke, die auf einer Karte ein Viertel größer sind als auf der anderen. Das passt zur strukturellen Signatur von <em>Packing</em>: die Wählerinnen und Wähler einer Partei in weniger, größere Bezirke zu konzentrieren, sodass jeder ihrer Stimmzettel weniger wiegt. Packing und <em>Cracking</em> (Aufteilung der Wählerinnen und Wähler einer Partei dünn über Bezirke, in denen sie knapp verlieren) sind die zwei klassischen Gerrymandering-Züge; beide verringern die Sitzzahl einer Partei unter ihren Stimmenanteil.`,chair_p:`Der Kommissionsvorsitzende — unter demselben Gesetz ernannt, auf Grundlage derselben Eingaben arbeitend — beanstandete drei Grenzen auf der Minderheitenkarte als geographisch anormal: die Verlängerung von Rocky Mountain House–Banff Park in unbewohntes Nationalparkland; den lassoförmigen Korridor Calgary-Nolan Hill–Cochrane; die Olds–Three Hills–Didsbury-Erweiterung in den Norden Airdries. Die Mehrheit erhielt vom selben Vorsitzenden null solche Beanstandungen. (Die veröffentlichte Kritik des Vorsitzenden umfasst insgesamt sieben Grenzkonfigurationen — vier geometrische Beanstandungen im Hauptbericht und drei in Anhang C. Das Audit hat anormale Geometrie für drei der vier geometrischen Beanstandungen unabhängig bestätigt; die vierte, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">zeigen ↗</button>, erfüllte die Bestätigungsschwelle des Audits nicht.)`},litmus:{heading:`3: Der 1.010.000-Karten-Lackmustest`,fig_alt:`Histogramm, das die Verteilung der Effizienzlücken über 250.000 neutrale Alberta-Karten zeigt. Die meisten Karten gruppieren sich nahe null. Die Karte der Minderheitenkommission (lila Linie) sitzt am 94. Perzentil (+3,96 %), im schattierten rechten Schwanz. Die Mehrheitskarte (türkise Linie) sitzt bei +0,04 %, gut innerhalb des normalen Bereichs.`,fig_caption:`Verteilung der <button class="vocab-term" data-def="ein Maß dafür, wie einseitig Stimmen in Sitze umgewandelt werden — positive Werte begünstigen die UCP, negative Werte die NDP" aria-expanded="false">Effizienzlücken</button> über 250.000 neutrale Alberta-Karten, die aus derselben Geographie gezeichnet wurden. Die meisten neutralen Karten gruppieren sich nahe null; der schattierte rechte Schwanz markiert die oberen 10 %. Die +3,96 % des Minderheitenvorschlags sitzen am 94. <button class="vocab-term" data-def="der Prozentsatz der Karten, die niedriger abgeschnitten haben — p94 bedeutet 94 von 100 neutralen Karten waren weniger parteilich als diese" aria-expanded="false">Perzentil</button> — einem Bereich, den weniger als 6 von 100 neutralen Karten je erreichen. Die +0,04 % des Mehrheitsvorschlags sind nicht zu unterscheiden von dem, was ein neutraler Prozess typischerweise hervorbringt.`,table_intro:`Die Tabelle vergleicht die beiden Karten. Die ersten fünf Zeilen verwenden keine Wahlergebnisse — sie sind Eigenschaften der Linien selbst. Die letzten beiden hängen davon ab, wie Stimmen den jeweiligen Bezirken zugeordnet wurden.`,table_col_measured:`Was gemessen wurde`,table_col_majority:`Mehrheitskarte`,table_col_minority:`Minderheitenkarte`,table_col_direction:`Richtung / Begünstigter`,table_r1_a:`Bevölkerungsstreuung über Bezirke (enger ist besser)`,table_r1_b:`3.180`,table_r1_c:`4.707 — 48 % weiter`,table_r1_d:`Strukturell (Reduziert Wahlgleichheit)`,table_r2_a:`Bevölkerungsüberhang NW Calgary über dem Durchschnitt`,table_r2_b:`2,8 %`,table_r2_c:`11,5 %`,table_r2_d:`<strong>UCP</strong> (Packt städtische NDP-Stimmen)`,table_r3_a:`Airdrie-Aufteilung`,table_r3_b:`2 Bezirke`,table_r3_c:`4 Bezirke`,table_r3_d:`<strong>UCP</strong> (Cracking der städtischen/vorstädtischen Macht)`,table_r4_a:`Grenzen, die bestehenden kommunalen Linien folgen`,table_r4_b:`80 % — im Rahmen der Norm`,table_r4_c:`72 % — im Rahmen der Norm`,table_r4_d:`N/Z — beide innerhalb der kanadischen Norm (70–85 %)`,table_r5_a:`Vom Kommissionsvorsitzenden beanstandete Grenzen`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`N/Z`,table_r6_a:`Sitze bei 50/50-Stimmen (Perzentil in der 1.010.000-Karten-Simulation)`,table_r6_b:`46,1 % — p83 (normaler Bereich)`,table_r6_c:`51,7 % — p99.99 (weniger als 100 von 1.010.000 erreichen das)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Effizienzlücke (Perzentil in der 1.010.000-Karten-Simulation)`,table_r7_b:`+0,04 % — p15.5 (normaler Bereich)`,table_r7_c:`+3,96 % — p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Packing-Cracking-Nachbarschaftsmuster`,table_r8_b:`6 gekoppelte Kettensignale`,table_r8_c:`2 (vorab registrierter BESTEHT)`,table_r8_d:`Neutral — Minderheit erreicht parteiliche Wirkung durch Hybridisierung, nicht durch Nachbarschafts-Drain (§5.3.5)`,vocab_label:`GLOSSAR`,vocab_eg:`<strong>Effizienzlücke (Efficiency Gap).</strong> Eine einzelne Zahl, die misst, wie einseitig die Stimmen einer Partei in Sitze übersetzt werden. Positive Zahlen begünstigen die UCP; negative die NDP. Das Audit verwendet ~5 % als Albertas Ausreißerlinie — den Wert, den nur 5 % der 1.010.000 neutralen Alberta-spezifischen Simulationen übersteigen. Diese Schwelle ist nicht aus US- oder allgemeiner Literatur entlehnt; eine auf eine andere Gerichtsbarkeit kalibrierte Schwelle wäre falsch, weil Albertas natürliche Geographie einen anderen neutralen Bereich erzeugt.`,vocab_mm:`<strong>Mittel-Median-Differenz.</strong> Die Lücke zwischen dem Median-Stimmanteil einer Partei in den Bezirken und ihrem Mittel-Stimmanteil in den Bezirken. Wenn eine Partei viele knappe Rennen gewinnt, sitzt der Median über dem Mittel — diese Stimmen sind effizient verteilt. Wenn eine Partei viele Rennen mit großen Margen gewinnt, sitzt das Mittel über dem Median — Stimmen werden verschwendet. Eine große Mittel-Median-Lücke in eine Richtung kennzeichnet strukturelle Ineffizienz darin, wie die Stimmen der einen Seite über die Bezirke verteilt sind.`,vocab_percentile:`<strong>Perzentilrang.</strong> In diesem Audit ist ein „Perzentil" ein Rang innerhalb der 1.010.000 neutralen simulierten Karten. „p94" bedeutet, 94 % der neutralen Karten schneiden niedriger ab — die reale Karte ist extremer als 94 % der neutralen Ziehungen. „p99.99" bedeutet, dass weniger als 1 von 10.000 neutralen Karten den Wert erreicht.`,vocab_anchoring:`<strong>Anchoring (Verankerung).</strong> Der Anteil einer Wahlgrenze, der auf einer bereits bestehenden Verwaltungslinie liegt — einer Stadtgrenze, einer Schulbezirksgrenze, einer Statistics-Canada-Zensuslinie.`,closing_p1:`Die unteren Zeilen hängen von Wahlergebnissen ab. Der Test <em>seats@50/50</em> hält die Wählerschaft auf perfekter Parität (UCP und NDP gewinnen jeweils genau die Hälfte der Stimmen provinzweit) und fragt, wie viele Sitze die Karte der UCP zuteilt. Eine neutrale Alberta-Karte erzeugt einen Median von etwa 44,8 % UCP-Sitzen. Albertas Geographie — NDP-Wählerinnen und -Wähler konzentriert in städtischen Kernen, UCP-Wählerinnen und -Wähler verteilt über ländliche Ridings — verschafft der NDP bei Neutralität einen kleinen Effizienzvorteil. Die Mehrheitskarte sitzt bei 46,1 % am 83. Perzentil der 1.010.000-Karten-Simulation, gut innerhalb des normalen Bereichs. Die Minderheitenkarte sitzt bei 51,7 % am 99,99. Perzentil: Weniger als 100 von 1.010.000 neutralen Ziehungen erreichen diesen Wert. Die <em>Effizienzlücke</em> misst, wie einseitig die Stimmen jeder Partei in Sitze übersetzt werden. Auf den offiziellen Shapefiles von Elections Alberta beträgt die Effizienzlücke der Minderheit +3,96 %, was sie am 94,4. Perzentil platziert — knapp unter der 95.-Perzentil-Ausreißerlinie des Audits. Die Eröffnungsfragen am Anfang dieser Seite legen die Konsequenzen offen.`,closing_p2:`In der letzten Zeile schneidet die Minderheitenkarte beim Nachbarschafts-Drain-Test mit weniger gekoppelten Kettensignalen ab als die Mehrheit: 2 gegen die 6 der Mehrheit (und die 5 der 2019 erlassenen Karte). Das Audit hat diesen Test vor der Messung vorab registriert, und die niedrigere Zahl der Minderheit ist ein echtes vorab registriertes BESTEHEN — die Minderheit zeigt nicht das klassische Pack-und-Drain-Nachbarschaftsmuster. Es ist der einzige Test, in dem die Minderheit die Mehrheit numerisch übertrifft. §5.3.5 des akademischen Berichts erklärt warum: Die Minderheit erreicht ihre parteiliche Wirkung durch Hybridisierung (Stadtteilung, die Packing und Cracking innerhalb einzelner EDs internalisiert), was für einen Nachbarschaftsketten-Test unsichtbar ist, der nur misst, wie sich gepackte Bezirke neben gecrackten gruppieren.`},commission_split:{heading:`2: Wie die Kommission sich spaltete`,intro:`Albertas Wahlbezirkskommission beendete ihre Arbeit am 23. März 2026 und konnte sich nicht einigen. Drei Kommissare brachten eine Karte hervor; die anderen zwei eine andere. Der Kommissionsvorsitzende Richter Dallas K. Miller und zwei von der Opposition nominierte Kommissare schrieben den Mehrheitsbericht; zwei von der Regierung nominierte Kommissare — Dr. Julian Martin und John D. Evans — schrieben den Minderheitenbericht. Die Spaltung konzentrierte sich darauf, wie Grenzen in schnell wachsenden Stadtrandgemeinden zu ziehen seien. Die Mehrheit gab Airdrie zwei Bezirke; die Minderheit vier. Die Mehrheit zeichnete die Bezirke im Nordwesten Calgarys nahe am provinziellen Durchschnitt; die Minderheit zeichnete sie 11,5 % darüber. Beide Karten folgen demselben Gesetz. Beide sind nach dem <em>Electoral Boundaries Commission Act</em> („Gesetz über die Wahlbezirkskommission") rechtmäßig. Die Meinungsverschiedenheit drehte sich darum, welche spezifischen geographischen Konfigurationen den zu zeichnenden Gemeinden am besten dienten. Albertas Regierungspartei ist die United Conservative Party (UCP); ihre Hauptopposition ist die New Democratic Party (NDP). Kleinere Parteien — die Alberta Party, die Liberal Party of Alberta und andere — kandidieren ebenfalls für Sitze, aber ihr kombinierter provinzieller Stimmenanteil war in den jüngsten Wahlen niedrig genug, dass er die Parteifairness-Berechnungen des Audits, die auf der UCP–NDP-Aufteilung von 2023 beruhen, nicht wesentlich beeinflusst. Dieses Audit hat beide Karten mit denselben Methoden gemessen, identisch angewandt. Drei Befunde stechen heraus.`,finding1:`<strong>Die beiden Karten unterscheiden sich bei sechs Dingen, die man ohne Blick auf Wahlergebnisse messen kann:</strong> wie gleichmäßig die Bevölkerung über die Bezirke verteilt ist, ob die Wählerinnen und Wähler konzentriert sind, wie schlimm Städte zerschnitten werden, ob die Grenzen Stadtgrenzen folgen, der Form der Bezirke und wie viele Grenzen der Kommissionsvorsitzende Richter Miller selbst schriftlich als anormal beanstandet hat (§5.8.2 des Mehrheitsberichts und Anhang C). Die Minderheitenkarte unterscheidet sich von der Mehrheit in jedem einzelnen dieser Punkte.`,finding2:`<strong>Jeder gemessene Unterschied bewegt sich in dieselbe Richtung.</strong> Überall, wo die beiden Karten auseinandergehen — Nordwest-Calgary, Airdrie, städtische Gebiete mit klaren Stadtgrenzen —, zieht die Minderheitenkarte Grenzen, die NDP-Stimmen dünner streuen und UCP-Stimmen effizienter zählen lassen. Die Gemeinden, die durch die Minderheitenkarte am stärksten umgestaltet werden, sind dieselben Gemeinden, in denen die NDP am stärksten ist. Das Audit kann keine Absicht feststellen. Es kann Wirkung messen.`,finding3:`<strong>Das Verfahren, das nun die Minderheitenkarte fördert, hat in Kanada kein Vorbild.</strong> Keine andere Provinz erlaubt es einem Kabinett, das Redistricting mitten in einem Redistribution-Zyklus an ein Komitee zu übergeben, das die eigene Partei kontrolliert. Die meisten Provinzen verlangen entweder, dass die Legislative zuerst über die Karte der Kommissare debattiert, oder verleihen der Karte der Kommission automatische Geltung, sofern sie nicht aufgehoben wird. Alberta tut weder das eine noch das andere. Am 16. April hat die Regierung beide Kommissionskarten beiseitegelegt und die Arbeit einem MLA-Komitee zugewiesen, dessen Mehrheit der Mitglieder aus der regierenden United Conservative Party (UCP) stammt; die vollständige Zusammensetzung und der Auftrag des Komitees werden in §7 detailliert dargelegt. Albertas <em>Electoral Boundaries Commission Act</em> verlangt, dass die Legislative ein separates Electoral Districts Act verabschiedet, um einem Kommissionsbericht Rechtskraft zu verleihen — der Kommissionsbericht selbst ändert nichts. Die meisten anderen Provinzen machen den Bericht einer Kommission rechtswirksam, sofern die Legislative ihn nicht aktiv aufhebt; Albertas Standardregel ist umgekehrt, was bedeutet, dass die Regierungspartei kontrolliert, ob eine Kommissionskarte je Gesetz wird. Die erklärte Begründung der Regierung war die Umsetzung der Empfehlung 5 des Kommissionsvorsitzenden Richter Miller. Aber Miller hatte die Empfehlung gerade deshalb geschrieben, um die Legislative davon abzuhalten, die Minderheitenkarte zu akzeptieren, und seine Mehrheitskollegen haben sie nicht befürwortet. Empfehlung 5 war außerdem geographisch spezifisch: ein zusätzlicher ländlicher Sitz südlich von Edmonton und einer in Clearwater County und im westlichen Mountain View County — beide weit entfernt von den schnell wachsenden Stadtrandgemeinden Calgarys und Edmontons, an denen sich die Kommission tatsächlich gespalten hat. Es war keine Einladung, diese strittigen Grenzen neu zu gestalten. Die Regierung hat die Sitzzahl übernommen und gleichzeitig einem von ihr kontrollierten Komitee Autorität über genau die Linien gegeben, über die die Kommission sich uneinig war.`,closing:`<strong>Das Verfahren ist ein eigener Befund, getrennt von den Karten.</strong>`},november:{heading:`7: Das Lunty-Komitee`,context_label:`KONTEXT`,context_body:` — Dieser Abschnitt beschreibt das Verfahren, das die Kommission ersetzt hat, und den dafür geltenden rechtlichen Rahmen. Er ist nicht Teil der statistischen Befunde. Die Befunde finden sich in §3–§6 oben.`,intro:`Keine der Kommissionskarten ist in Kraft. Am 16. April 2026 verabschiedete die Legislativversammlung Antrag 19, der beide beiseitelegte und das Redistricting an einen Sonderausschuss aus fünf MLAs verwies — drei UCP, zwei NDP —, der von Brandon Lunty (UCP, Leduc-Beaumont) geleitet wird. Das Komitee selbst zeichnet nicht die Karte. Es beaufsichtigt ein separates Unabhängiges Beratungsgremium, das unter Regierungsantrag 37 (verabschiedet am 21. April 2026) eingesetzt wurde und mit der Erstellung eines Grenzvorschlags mit 91 Sitzen beauftragt ist. Antrag 37 sah fünf Gremiumsmitglieder vor — einen amtierenden oder pensionierten Richter als Vorsitz, zwei vom Premierminister nominierte Mitglieder und zwei vom Oppositionsführer —, aber Albertas amtierender Chief Justice lehnte es ab, einen Richter zum Vorsitz zu nominieren, und das Gremium arbeitet jetzt mit den vier vom Komitee bestätigten Ernannten: Hon. Monte Solberg und Darwin Durnie (Nominierte des Premierministers) sowie Dr. Gerard Kennedy und Brent Robinson (Nominierte der Opposition). Das Komitee muss seinen Bericht der Legislative bis zum 2. November 2026 vorlegen. Anders als die ursprüngliche Kommission ist weder das Komitee noch das Gremium zur Abhaltung öffentlicher Anhörungen verpflichtet; das Gremium stützt sich auf Eingaben, die die ursprüngliche Kommission gesammelt hat. Wenn die Karte des Komitees veröffentlicht wird, wird dieses Audit dieselbe Methodik anwenden, um sie zu bewerten.`,h_anomalous:`Warum das Komitee anomal ist`,anomalous_p1:`Die kanadische Redistricting-Praxis hat sich seit den 1960er Jahren auf ein einziges Modell verfestigt: Eine unabhängige Kommission, von Regierungsweisungen abgeschirmt, erstellt Grenzempfehlungen; die Legislative kann sie debattieren, aber nicht ohne förmlichen Gesetzgebungsbeschluss leicht aufheben. Albertas gesetzliches Verfahren nach dem <em>Electoral Boundaries Commission Act</em> folgt dieser Vorlage — aber mit einem strukturellen Unterschied zu den meisten Provinzen: Albertas Kommissionsbericht hat keine automatische rechtliche Wirkung. Nach dem Gesetz muss die Legislative ein separates Electoral Districts Act verabschieden, um einer Kommissionskarte Rechtskraft zu verleihen. Das bedeutet, dass die jeweilige Regierung nicht nur kontrolliert, ob die Kommissionskarte debattiert wird, sondern auch, ob sie überhaupt je Gesetz wird. Andere kanadische Jurisdiktionen haben die umgekehrte Standardregel: Die Empfehlungen der Kommission treten in Kraft, sofern die Legislative sie nicht durch aktiven Beschluss aufhebt.`,anomalous_p2:`Was die Regierung im April 2026 getan hat, hat in der Nach-Konföderations-Redistricting-Geschichte keinen dokumentierten Präzedenzfall: Sie hat ein abgeschlossenes, veröffentlichtes Kommissionsverfahren — Mehrheits- und Minderheitsbericht eingereicht — zu Ende kommen lassen und dann die Redistricting-Aufgabe an ein fünfköpfiges MLA-Komitee verwiesen, dessen Mehrheit (drei von fünf) bei der regierenden Partei liegt, ohne einen der Kommissionsberichte zur Abstimmung zu bringen. Das Lunty-Komitee ist keine Kommission. Es hat keine gesetzliche Unabhängigkeit von den Anweisungen der Regierungsfraktion. Seine Drei-Mitglieder-UCP-Mehrheit spiegelt die Kontrolle der Regierung über die Legislative wider. Keine andere kanadische Provinz hat die Redistricting-Befugnis mitten im Zyklus an ein von der Regierung kontrolliertes Legislativkomitee übertragen, nachdem eine unabhängige Kommission ihre Arbeit beendet hatte.`,h_framework:`Der verfassungsrechtliche Rahmen`,framework_p1:`Abschnitt 3 der <em>Charter of Rights and Freedoms</em> („Kanadische Charta der Rechte und Freiheiten") — „Jeder Bürger Kanadas hat das Recht, bei einer Wahl der Mitglieder des House of Commons oder einer Legislativversammlung zu wählen" — ist vom Supreme Court of Canada so ausgelegt worden, dass er nicht bloß den Akt der Stimmabgabe garantiert, sondern <em>wirksame Vertretung</em>. Die maßgebliche Autorität ist <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, in der McLachlin J. (wie sie damals hieß) für die Mehrheit schrieb, der Zweck von s.3 „sei nicht die Gleichheit der Stimmkraft an sich, sondern das Recht auf wirksame Vertretung". Die Bevölkerungsparität ist die primäre Erwägung; Abweichungen sind zulässig, wenn sie durch Interessengemeinschaft, Geographie, Geschichte oder Minderheitenrepräsentation gerechtfertigt sind.`,framework_p2:`Der Saskatchewan-Rahmen verbietet parteiliche Erwägungen im Redistricting nicht kategorisch. Er stellt vielmehr fest, dass Grenzkarten insgesamt eine wirksame Vertretung der Wählerinnen und Wähler gewähren müssen — und dass die systematische Beeinträchtigung der Fähigkeit einer identifizierbaren Gruppe, eine angemessene Vertretung zu wählen, das Muster ist, auf das s.3-Klagen abzielen. Die statistischen und strukturellen Befunde des Audits — die Position der Minderheitenkarte am 99,99. Perzentil von 1.010.000 neutralen Ziehungen, ihre Überschreitung von vier der fünf strukturellen Schwellen (der fünfte, Anchoring, ist für beide Karten neutral), die identifizierten betroffenen Gemeinden — sind das Beweismaterial, das eine s.3-Klägerin zusammenstellen müsste. Auf der Seite der Interessengemeinschaft dieses Beweismaterials ist die Entscheidung des Federal Court in <em>Raîche v. Canada</em> (2004 FC 679) die maßgebliche kanadische Autorität: Das Gericht verpflichtete dort die föderale Electoral Boundaries Commission, Grenzen erneut zu überprüfen, die die akadische Interessengemeinschaft in New Brunswick ignoriert hatten. Die Messungen der kommunalen Verankerung des Audits und seine spezifischen Gemeindebefunde — Airdrie in vier Bezirke aufgeteilt, die vom Vorsitzenden beanstandeten Stadtrand-Anomalien im Nordwesten Calgarys — sind dieselbe Art von Beweismaterial, die der Federal Court als rechtlich anerkennbar behandelt hat. Ob dieses Material die verfassungsrechtliche Schwelle erreicht, ist eine Rechtsfrage, die dieses Audit nicht entscheidet; das Audit berichtet die Messung.`,framework_p3:`Die Rechtmäßigkeit des Komitees als Verfahren ist eine separate Frage. Albertas <em>Electoral Boundaries Commission Act</em> verbietet der Legislative nicht ausdrücklich, ein paralleles Redistricting-Gremium einzusetzen, weil das Gesetz ohnehin vorsieht, dass die Legislative die endgültigen Grenzen durch ordentliche Gesetzgebung erlässt. Ob das Komiteeverfahren, falls es eine Karte mit dem strukturellen und statistischen Profil des Minderheitenvorschlags hervorbringt, eine s.3-Charter-Klage überstehen könnte, hängt davon ab, ob unter den resultierenden Grenzen eine wirksame Vertretung erreichbar ist — derselbe Maßstab, der auf jede von einer Kommission erzeugte Karte angewandt würde.`,h_quebec:`Der Quebec-Kontrast`,quebec_p1:`Quebec bietet den für Albertas Situation relevantesten Vergleich. Quebecs Commission de la représentation électorale (CRE) ist ein permanentes, unabhängiges Wahlbezirksgremium, keine Ad-hoc-Kommission, die pro Redistribution-Zyklus eingesetzt wird. Die CRE arbeitet kontinuierlich und kann durch Kabinettsbeschluss weder aufgelöst noch umgangen werden. Nach Quebecs <em>Loi électorale</em> muss die Nationalversammlung die Empfehlungen der CRE annehmen, sofern sie nicht für eine Abweichung stimmt — und Abweichungen erfordern eine Zweidrittelmehrheit aller Mitglieder der Versammlung, nicht eine knappe Legislativmehrheit. Die praktische Wirkung ist, dass eine Regierungspartei nicht allein mit eigener Mehrheit ihre bevorzugte Karte an die Stelle der Kommissionskarte setzen kann. Eine parteiübergreifende Einigung ist verfassungsrechtlich erforderlich, um das Urteil des unabhängigen Gremiums aufzuheben.`,quebec_p2:`Quebecs Modell ist teilweise aus Lehren darüber entstanden, was geschieht, wenn Redistricting nicht von parteilicher Kontrolle abgeschirmt ist. Der Kontrast zu Albertas aktuellem Verfahren — bei dem ein mehrheitlich kontrolliertes Komitee die Arbeit der Kommission ersetzt hat, bevor die Legislative über einen der Kommissionsberichte abgestimmt hat — illustriert den strukturellen Unterschied zwischen Redistricting-Systemen, die parteilichen Druck voraussetzen und sich dagegen wappnen, und Systemen, in denen dieser Druck einen klareren Weg zum Ergebnis hat.`,closing:`Das Audit wird dieselben Tests auf die Karte des Lunty-Komitees anwenden, wenn sie veröffentlicht wird. Die verfassungsrechtlichen und vergleichenden Beobachtungen oben sind kontextuell; die Methodik ändert sich nicht.`},references:{heading:`10: Quellen und Methodik`,heading_aria:`Link zu Quellen`,intro:`Die zugrundeliegende Methodik stützt sich auf etablierte politikwissenschaftliche, statistische und rechtswissenschaftliche Literatur. Vollständige Zitate folgen dem Stil der American Political Science Association (APSA); Gerichtsentscheidungen folgen kanadischer Rechtskonvention. Die vollständige Literaturliste erscheint im <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">technischen Bericht</a>. Wichtige Quellen sind hier aufgeführt.`,h_academic:`Wissenschaftliche Literatur`,h_cases:`Gerichtsentscheidungen`,h_statutes:`Gesetze`},resources:{heading:`11: Technischer Anhang`,heading_aria:`Link zur technischen Sektion`,tag_plain:`Allgemeinverständlich`,plain_label:`Vollständiger öffentlicher Bericht`,plain_desc:`Langform mit Karten, für ein allgemeines Publikum`,tag_summary:`Zusammenfassung`,summary_label:`Zusammenfassung der Befunde`,summary_desc:`Allgemeinverständliche Übersicht, erklärt jedes Konzept von Grund auf`,tag_academic:`Akademisch`,academic_label:`Technischer Bericht`,academic_desc:`Vollständige Methoden und Zitate für Forschende`,tag_notebook:`Notebook`,notebook_label:`Interaktives Notebook`,notebook_desc:`Erstellen Sie die Grafiken selbst im Browser, keine Installation nötig`,tag_code:`Code`},about_me:{heading:`Über mich`,p1:`Ich bin Student an der Mount Royal University. Ich habe diese Forschung auf eigene Initiative betrieben — sie war nicht als Kursarbeit zugewiesen, und die Universität hat sie nicht in Auftrag gegeben. Meine Ansichten sind meine eigenen und repräsentieren nicht die Universität. Ich habe keine Verbindung zu Elections Alberta, der Kommission oder irgendeiner politischen Partei.`,p2:`Ich habe bei verschiedenen Wahlen für verschiedene Parteien quer durch das politische Spektrum gestimmt. Ich erzähle Ihnen das, weil meine politische Vergangenheit beeinflussen könnte, wie ich dieses Thema betrachte. Der wichtigste Schutz dagegen ist die Methode: Ich habe beide Karten auf dieselbe Weise getestet, meine Vorhersagen niedergeschrieben, bevor ich die Ergebnisse einsah, und alles online gestellt, damit jeder meine Arbeit prüfen kann. Ich habe diese Forschung selbst bezahlt. Wenn Sie etwas finden, das ich falsch dargestellt habe, möchte ich es wirklich wissen.`,p3:`Vorab-Registrierungsunterlagen (vor Einsicht der Ergebnisse verfasst): <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451.`,p4:`Fragen oder Korrekturen: <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9: Widerrufe und Korrekturen`,heading_aria:`Link zu Widerrufen`,conditions_label:`WIDERRUFSBEDINGUNGEN`,conditions_intro:`Jeder Befund ist im Voraus an eine bestimmte Falsifizierungsbedingung gebunden. Falls eine der unten genannten Bedingungen eintritt, wird der benannte Befund innerhalb von 30 Tagen öffentlich widerrufen. Die übergeordnete Richtungsschlussfolgerung — dass die Minderheitenkarte bei mehreren unabhängigen Tests außerhalb des neutralen Bereichs liegt — wird nur dann widerrufen, wenn mindestens drei der fünf Tests scheitern.`,c1_title:`Bedingung 1 — Eine Gegenkarte existiert`,c1_what:`<em>Was widerrufen wird:</em> Der strukturelle Befund, dass die Vierfach-Aufteilung Airdries und die drei vom Vorsitzenden beanstandeten Grenzen nicht durch die von der Minderheit selbst angegebene Begründung der Interessengemeinschaft erklärt werden können.`,c1_cond:`Bedingung: jemand erstellt eine legale Alberta-Karte, die die von der Minderheit selbst genannten Gründe erfüllt — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — und verankert sich an kommunalen Linien zu mit der Mehrheit vergleichbaren Raten. Offene Herausforderung unter <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,c2_title:`Bedingung 2 — Das vorab registrierte BESTEHEN des Nachbar-Drain wird umgekehrt`,c2_what:`<em>Was widerrufen wird:</em> Der Tabelleneintrag in Abschnitt 3, der die Minderheitenkarte als vorab registriertes BESTEHEN beim Nachbar-Drain-Adjazenztest aufführt.`,c2_cond:`Bedingung: Der kontinuierliche v2-Drain-Score fällt in den extremen oberen Schwanz (p &lt; 0,05) zufälliger Permutationen über den festen Kontiguitätsgraphen, was bedeutet, dass das BESTEHEN ein Messartefakt der binären v1-Bewertungsmethode war und kein echtes Nullresultat.`,c3_title:`Bedingung 3 — Ein Kommissionsdokument von vor 2026 taucht auf`,c3_what:`<em>Was widerrufen wird:</em> Die Schlussfolgerung, dass die Grenzentscheidungen der Minderheit Entwurfsentscheidungen waren und keine Reaktionen auf dokumentierte Eingaben aus den Gemeinden.`,c3_cond:`Bedingung: Ein internes Kommissionsdokument vor den endgültigen Grenzentscheidungen der Minderheit zeigt, dass diese Entscheidungen ausdrücklich von Gemeindeeingaben angetrieben waren, die das Audit nicht gesehen hat — und nicht von den sechs veröffentlichten Unterbegründungen, die das Audit geprüft hat.`,c4_title:`Bedingung 4 — Das Wahlergebnis von 2027 widerspricht der Simulation`,c4_what:`<em>Was widerrufen wird:</em> Der Befund aus Spur 1 — dass der seats@50/50-Wert der Minderheitenkarte am 99,99. Perzentil von 1.010.000 neutralen Ziehungen liegt.`,c4_cond:`Bedingung: Wird die Provinzwahl 2027 auf einer der beiden Kommissionskarten ausgetragen und widerspricht die tatsächliche parteiliche Sitzaufteilung der Richtungsprojektion aus den Stimmen von 2023, werden die Perzentilbefunde aus Spur 1 gegen tatsächliche Ergebnisse erneut geprüft.`,c5_title:`Bedingung 5 — Ein Alberta-Gericht unterscheidet sich vom SCC-Urteil zu Quebec`,c5_what:`<em>Was widerrufen wird:</em> Das Verfahrensargument in Abschnitt 7, dass der Antrag vom 16. April, die Kommission durch das Lunty-Komitee zu ersetzen, in dieselbe verfassungsrechtliche Klasse fällt wie Quebecs Redistricting-Aufschub 2024.`,c5_cond:`Hintergrund: Am 22. April 2026 — sechs Tage nach Albertas Antrag vom 16. April — bestätigte der Supreme Court of Canada 7-zu-2 und aus dem Stand ein Urteil des Quebec Court of Appeal, dass die Legislativ-Aussetzung der Redistricting-Kommission durch die Regierung Legault die in s.3 der Charter garantierte demokratische Repräsentation verletzt. Bedingung: Ein Gericht, das den Alberta-Antrag überprüft, befindet ihn verfassungsrechtlich für unterscheidbar — zum Beispiel, weil die Übertragung der Arbeit an ein MLA-Komitee sich strukturell von einer Legislativ-Aussetzung unterscheidet, oder weil Albertas Analyse der wirksamen Vertretung unter s.3 anders ausgeht als die Quebecs.`,corr_label:`DOKUMENTIERTE KORREKTUREN (kanonische Neuberechnung, 11.05.2026)`,corr_intro:`Der folgende frühe Befund hielt der erneuten Analyse gegen die offiziellen Shapefiles von Elections Alberta (erhalten am 06.05.2026) nicht stand. Er wird hier gemäß der vorab festgelegten Audit-Politik, gescheiterte Befunde nie zu löschen, beibehalten.`,corr_municipal:`<strong>Kommunale Verankerung (widerrufen).</strong> Eine frühe Analyse mit vorläufigen Kartengrenzen zeigte, dass die Minderheitenkarte nur zu 15 % an kommunalen Linien verankert war — 4,9&times; unter der kanadischen Norm von 70–85 %. Diese Zahl war ein Artefakt der vorläufigen (DPG-Ära) Grenzrekonstruktionen. Auf den offiziellen kanonischen Shapefiles von Elections Alberta verankern sich beide Karten innerhalb der kanadischen Norm: Mehrheit 80 %, Minderheit 72 %. Die kommunale Verankerungs-<em>Divergenz</em> zwischen den beiden Karten ist kein Signal, das die kanonische Neuberechnung übersteht. Die drei vom Kommissionsvorsitzenden beanstandeten Grenzanomalien (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–Nord-Airdrie) bleiben bestehen und sind von dieser Korrektur nicht betroffen.`},suggestions:{heading:`8: Vorschläge`,heading_aria:`Link zu Abschnitt 8`,intro:`Dieses Audit ist auf zwei Datenprobleme gestoßen, die nichts mit der Arbeit der Kommission zu tun haben, sondern alles damit, wie Albertas Wahlsystem aufgebaut ist. Beide sind behebbar.`,advance_p1:`<strong>Ungefähr die Hälfte aller Stimmen in Alberta kommt mittlerweile vor dem Wahltag an</strong> — Vorabwahllokale, mobile Wahllokale, Sonderstimmzettel. Elections Alberta meldet diese Ergebnisse als Summen pro Wahlbezirk, nicht pro spezifischer Voting Area. Das bedeutet, dass etwa 395.000 NDP- und UCP-Stimmen, die 2023 abgegeben wurden, keinem Stadtviertel auf einer Karte zugeordnet werden können. Sie werden gezählt; sie können nur nicht verortet werden. Jede Vorabwählerin wird vor Ausgabe ihres Stimmzettels gegen ein Wählerverzeichnis geprüft, und das Verzeichnis verknüpft jede Wählerin mit ihrer spezifischen Voting Area. Die Veröffentlichung von VA-Ebene-Summen für die Vorabstimmen würde keinerlei Änderung am Wahlverfahren erfordern — nur an dem, was EA berichtet.`,advance_p2:`Das betrifft auch die Kommissionsmitglieder, nicht nur externe Analysten. Wenn eine Kommission entscheidet, ob Airdrie ganz bleibt oder aufgeteilt wird, ob ein Korridor zwischen zwei Gemeinden Sinn ergibt, ob eine vorgeschlagene Grenze eine natürliche Wählerschaft trennt — das sind Urteile, die davon abhängen zu wissen, wo Wählerinnen und Wähler leben. Die Kommissare arbeiten mit demselben veröffentlichten Datensatz wie alle anderen. Die Hälfte des geographischen Signals über die Gemeinden, um die sie Grenzen ziehen, fehlt auch ihnen.`,lesser_slave_p1:`Es gibt mindestens eine Gemeinde im Norden Albertas, wo diese Lücke total ist. Im nördlichen Teil des Wahlbezirks Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">zeigen ↗</button> gibt es eine Voting Area mit 4.832 km&#178; — größer als Prince Edward Island —, in der jede einzelne Stimme 2023 über das mobile Wahllokal-Team von Elections Alberta abgegeben wurde. Die Wahlentscheidungen dieser 844 Einwohnerinnen und Einwohner werden in der Bezirkssumme gezählt, aber sie können keinem Ort auf einer Karte zugeordnet werden. Die Gemeinde ist in den veröffentlichten Wahlergebnissen vollständig unsichtbar.`,lesser_slave_p2:`Als die Kommission zunächst erwog, den Bezirk Lesser Slave Lake aufzulösen und in einen größeren Riding einzugliedern, arbeitete sie ohne geographische Stimmdaten aus diesen Gemeinden. Die Kommission hat den Bezirk schließlich erhalten — nach über 80 öffentlichen Eingaben, viele davon aus den indigenen Gemeinden im Norden des Bezirks — und sich auf ein Provinzgesetz berufen, das es Ridings mit First-Nations- und M&#233;tis-Gemeinden erlaubt, geringere Bevölkerungen als der Provinzdurchschnitt zu haben. Sie haben es geschafft. Aber die Daten, mit denen sie arbeiteten, zeigten ihnen nicht, wer in den Gemeinden wählte, die sie zu schützen beschlossen.`,ebca_label:`ABSCHNITT 15(2) EBCA`,ebca_body:`Abschnitt 15(2) von Albertas <em>Electoral Boundaries Commission Act</em> ist eine Ermessensvorschrift, die es Kommissionen erlaubt, unterdurchschnittlich große Ridings zu schützen — solche, die mehr als 25 % unter dem provinziellen Bevölkerungsdurchschnitt liegen —, wenn das Riding mindestens drei von fünf bestimmten Kriterien erfüllt: (a) eine geographische Fläche von mehr als 20.000 km², (b) eine Entfernung von mehr als 150 km vom Legislative Building auf der direktesten Highway-Route, (c) das Fehlen einer Stadt mit mehr als 8.000 Einwohnern, (d) das Vorhandensein eines Indian Reserve oder einer Métis-Siedlung, und (e) ob das Riding mit einer Grenze der Provinz Alberta deckungsgleich ist. Die Vorschrift gilt nicht automatisch; die Kommission muss beurteilen, ob die Kriterien erfüllt sind. Lesser Slave Lake erfüllt unabhängig vier der fünf.`,rationale_p1:`Die vorläufige Begründung für die Auflösung des Ridings war die Bevölkerung: Mit rund 27.000 Einwohnerinnen und Einwohnern liegt Lesser Slave Lake etwa 45 % unter dem Provinzdurchschnitt und nähert sich der gesetzlichen Untergrenze. Das liest sich wie eine einfache Anwendung der Regeln. Ist es aber nicht. Albertas Recht gibt Kommissionen ein ausdrückliches Ermessen, unterdurchschnittlich große Ridings zu schützen, wenn mindestens drei von fünf bestimmten Kriterien zutreffen, und Lesser Slave Lake erfüllt vier davon unabhängig. Seine Fläche beträgt 69.566 km² (Kriterium a, Schwelle 20.000 km²). Seine nächstgelegene Grenze ist über 150 km vom Legislative Building per Highway entfernt (Kriterium b). Keine Stadt im Riding hat eine Bevölkerung über 8.000 (Kriterium c). Und das Riding enthält vierzehn Indian Reserves und M&#233;tis-Siedlungen, deren Gemeinden eine gemeinsame nördliche Geographie, eine gemeinsame Abhängigkeit von mobiler Wahllokal-Logistik zum Wählen überhaupt und ein kollektives Interesse an einer Vertretung teilen, die primär dem nördlichen Alberta gegenüber rechenschaftspflichtig ist (Kriterium d).`,rationale_p2:`Unter der vorgeschlagenen Mackenzie-Fusion wäre die kollektive Stimme dauerhaft in ein Riding aufgesogen worden, in dem die andere Partei mit über zwei zu eins gewinnt — nicht, weil sich diese Gemeinden geändert hätten, sondern weil sich die Linien um sie herum geändert hätten. Jedes dieser vier Kriterien ist eine objektive Tatsache über die Geographie des Ridings, keine Ermessensentscheidung. Zusammen beschreiben sie eine Wählerschaft, die die Vorschrift schützen sollte: abgelegen, groß, dünn besiedelt und mit Gemeinden, deren Repräsentationsinteresse sich nicht aus reinen Bevölkerungszahlen ablesen lässt. Sie brauchen drei, um sich zu qualifizieren; Lesser Slave Lake hat vier. Den Bevölkerungsmangel so zu behandeln, als zwinge er zur Auflösung, missdeutet das Gesetz. Die Umkehr der Kommission war die korrekte Anwendung des Rechts, kein Zugeständnis an politischen Druck.`,banff_p:`Hier ist die andere Seite der Geschichte: Während die indigenen Gemeinden im Lesser Slave Lake kämpften, gezählt zu werden, schlugen die abweichenden Kommissare vor, ein anderes Riding zu schützen, indem sie seine Grenze durch den Banff National Park zogen, wo niemand lebt. Der Kommissionsvorsitzende selbst nannte es „einen Versuch in bösem Glauben", den gesetzlichen Schutz zu beanspruchen. Die Formulierung steht im offiziellen Abschlussbericht der Kommission. Der Schutz, der für abgelegene Gemeinden mit indigener Bevölkerung gedacht war, wurde in der Karte der Minderheit verwendet, um eine Grenze durch unbewohnte Wildnis zu verteidigen. Die Gemeinden, denen er helfen sollte, mussten ihn sich durch öffentliche Eingaben erkämpfen. Das Lunty-Komitee wird im November vor derselben §&#x2009;15(2)-Entscheidung stehen — ohne gesetzliche Pflicht, öffentliche Anhörungen abzuhalten, und ohne Garantie, dass die 80 Eingaben, die die vorläufige Position der Kommission umgekehrt haben, ein zweites Mal dasselbe Gewicht haben.`,census_p1:`<strong>Alberta sollte mit dem Zeichnen der nächsten Karte auf den Zensus 2026 warten.</strong> Kanada zählt seine Bevölkerung alle zehn Jahre. Die Erhebung des Zensus 2026 findet im Frühjahr 2026 statt; Statistics Canada veröffentlicht brauchbare subprovinzielle Daten etwa zwei Jahre später, 2027 oder 2028. Die Kommission, die die in diesem Audit bewerteten Karten gezeichnet hat, musste den Zensus von 2021 verwenden — bereits vier Jahre alt, als die Karten gezeichnet wurden, und möglicherweise vierzehn Jahre alt, wenn diese Grenzen außer Kraft treten. Schnell wachsende Städte wie Airdrie und Chestermere werden sich in diesem Zeitraum um 40 % oder mehr verändern. Ländliche Gemeinden werden schrumpfen. Die Karte wird vom Tag ihres Inkrafttretens an falsch sein. Eine einfache Änderung des <em>Electoral Boundaries Commission Act</em> könnte vorschreiben, dass eine neue Kommission erst eingesetzt wird, nachdem Statistics Canada die aktuellsten Dissemination-Area-Daten aus dem vorhergehenden Zensus veröffentlicht hat. Das Ergebnis: Karten, die widerspiegeln, wo Albertaner tatsächlich leben, nicht wo sie vor einem Jahrzehnt lebten.`,census_p2:`Das Lunty-Komitee arbeitet unter dem bestehenden Gesetz, das keine Anforderung zur Zensus-Zeitplanung enthält, und kann seine Frist im November 2026 nicht einseitig hinausschieben. Diese Empfehlung gilt für eine zukünftige Änderung des <em>Electoral Boundaries Commission Act</em>, nicht für das aktuelle Verfahren. Die Spannung ist real: Ein Komitee, das eine Karte bis November liefern muss, arbeitet mit Daten, die bis dahin bereits fünf Jahre alt sind — die Einschränkung zu benennen ist nützlicher, als so zu tun, als gäbe es sie nicht.`,closing:`Keines davon ist ein Befund über die aktuellen Karten der Kommission. Es sind Beobachtungen zu einem System, das genaue Wahlanalysen schwerer macht, als sie sein müssten. Sie werden hier als praktische Vorschläge angeboten, nicht als Schlussfolgerungen. Beide sind tatsächlich behebbar, und sie zu beheben würde jede zukünftige Kommission — und jedes zukünftige Audit — von besserem Boden aus arbeiten lassen.`}},editorial_canada:{heading:`Kontext: Kanada ist anders — und ähnlich`,p1:`Kanada gehört zur selben Familie wie die USA, das Vereinigte Königreich und Australien. Wir wählen einzelne Vertreter aus geographischen Bezirken nach dem Mehrheitswahlrecht (first-past-the-post). Wir ziehen die Linien regelmäßig neu — auf Bundesebene nach jeder zehnjährigen Volkszählung, auf Provinzebene nach gestaffelten Zeitplänen. Wir haben die grundlegende Mechanik aus denselben Westminster-Wurzeln geerbt. So weit, so wenig überraschend.`,p2:`Was Kanada unterscheidet, ist der Maßstab, dem die Linien standhalten müssen.`,p3:`Im amerikanischen Verfassungsrecht lautet die bindende Regel <em>eine Person, eine Stimme</em> — die Bezirke müssen so gleiche Bevölkerungen haben, wie praktikabel, und große Abweichungen erfordern eine strenge Rechtfertigung. Im kanadischen Verfassungsrecht lautet die bindende Regel anders. Abschnitt 3 der <em>Canadian Charter of Rights and Freedoms</em> („Kanadische Charta der Rechte und Freiheiten") garantiert jedem Bürger das Wahlrecht. In <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — dem Saskatchewan Reference von 1991, dem Leitfall — hat der Supreme Court of Canada das Recht als Recht auf <em>wirksame Vertretung</em> ausgelegt, nicht als Recht auf mathematische Gleichheit der Bezirksbevölkerungen.`,p4:`Diese Unterscheidung ist wichtig. Wirksame Vertretung erlaubt, dass Bezirksbevölkerungen variieren — manchmal erheblich —, wenn es gute Gründe dafür gibt: ausgedehnte ländliche Gegenden, die ein MLA bei standardmäßiger Bevölkerungsdichte nicht angemessen versorgen kann, Interessengemeinschaften, die zusammengehalten werden sollen, Minderheitenvertretung, die mathematische Gleichheit verwässern würde. Das Saskatchewan Reference machte diese Flexibilität verfassungsrechtlich. Die 25-Prozent-Bevölkerungsabweichung des EBCA — die Regel, die die Sitze des ländlichen Alberta schützt — fließt direkt daraus.`,p5:`Der Haken ist, dass Flexibilität in beide Richtungen schneidet. Wenn eine Kommission aus den richtigen Gründen rechtmäßig von der Bevölkerungsgleichheit abweichen kann, kann sie auch aus den falschen Gründen abweichen. Das kanadische Recht hat keine mathematische Untergrenze im US-Stil, auf die es zurückgreifen kann. Es hat den Test der wirksamen Vertretung, von Richtern angewandt, nachträglich, im Streitverfahren. Die meisten Gerichtsbarkeiten wappnen sich gegen die falschen Gründe mit strukturellen Schutzmaßnahmen: Bundesredistricting-Kommissionen sind gesetzlich abgeschirmt, und ihre Empfehlungen treten automatisch in Kraft, wenn das Parlament nicht innerhalb einer Frist tätig wird. Quebec verwendet eine ständige unabhängige Kommission, deren Arbeit die Nationalversammlung nur mit einer Zweidrittel-Supermehrheit aufheben kann. British Columbia arbeitet unter einer ähnlichen Standardannahme.`,p6:`Alberta ist die Ausnahme. Nach dem <em>Electoral Boundaries Commission Act</em> ist der Kommissionsbericht nur eine Empfehlung — die Legislative muss abstimmen, um ihn zu erlassen. Die Zustimmung ist normalerweise eine Formalität. Im Zyklus 2026 spaltete sich die Kommission 3 zu 2 und brachte zwei konkurrierende Vorschläge hervor; die Legislative hat ein separates MLA-Komitee, vorgesessen von einem vom Premierminister ernannten MLA, geschaffen, um zwischen ihnen zu wählen. Nichts im kanadischen Verfassungsrecht verlangte die Existenz dieses Komitees. Nichts verlangt, dass seine Wahl dem Verfahren der Kommission folgt. Das ist die strukturelle Lücke, die dieses Audit untersucht.`,p7:`Wenn also kanadische Gerichte sagen, „Gerrymander" gehöre nicht zu ihrem juristischen Vokabular, sagen sie nicht, dass das zugrundeliegende Konzept hier nicht zutrifft. Sie sagen, dass der Maßstab ein anderer ist — wirksame Vertretung, nicht mathematische Gleichheit. Ob der Minderheitenvorschlag diesen Maßstab erfüllt, ist genau die Frage, gegen die dieses Audit die Geometrie gemessen hat, und genau die Frage, die nur ein Richter endgültig beantworten kann. Die vollständige Begründung des <em>Saskatchewan Reference</em>, der Kontrast zu anderen Provinzen, die Frage der Klagebefugnis und die verfügbaren Reformwege werden in <a href="#references">dem Quellenabschnitt unten</a> behandelt.`},chrome:{back_to_top:`Zurück nach oben`,license_title:`Creative Commons Attribution-NonCommercial-ShareAlike 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Zurück zum Einsatz`,lightbox:{fig_aria:`Vergrößerte Ansicht der Abbildung`,fig_close_aria:`Vergrößerte Abbildung schließen (Esc)`,map_aria:`Kartenzoom-Anzeige`,map_close_aria:`Kartenanzeige schließen`,close_title:`Schließen (Esc)`},participation:{heading:`Helfen Sie uns, MapExplorer zu verbessern`,body:`Während Sie erkunden, erfassen wir, welche Karten und Bezirke Sie besuchen, und senden die Daten gelegentlich an unsere Forschungsdatenbank. Beim Teilen einer Ansicht wird ebenfalls gespeichert, wo Sie gelandet sind. Ziel: zu verstehen, was nützlich ist, und das Werkzeug zu verbessern.`,no_collect:`Wir erfassen niemals Ihren Namen, Ihre IP-Adresse oder Ihren genauen Standort. Alles wird in Ihrem Browser anonymisiert, bevor es ihn verlässt. Wir könnten Sie selbst auf gerichtliche Anordnung hin aus den Daten nicht identifizieren.`,dnt:`Ihr Browser hat Do Not Track aktiviert. „Nein" ist für Sie voreingestellt. Sie können trotzdem „Ja" wählen.`,no_thanks:`Nein danke`,yes_help:`Ja, ich helfe`,privacy_policy:`Datenschutzerklärung`},share:{button:`Teilen`,button_title:`Eine Kartenkonfiguration teilen oder laden`,dialog_aria:`Kartenkonfiguration teilen`,close_aria:`Teilen-Bereich schließen`,share_label:`Diese Konfiguration teilen`,share_hint:`Geben Sie diesen Code in einem beliebigen Browser ein, der das Audit ausführt, um diese Konfiguration zu laden. Der Code wird nie in eine URL geschrieben.`,load_label:`Eine Konfiguration laden`,load_btn:`Laden`,load_placeholder:`alpine-eagle-banff`,copy:`Kopieren`,copied:`Kopiert!`,copy_failed:`Fehlgeschlagen`,unrecognised:`Code nicht erkannt — bitte die Schreibweise prüfen.`},map:{minority:`Minderheit`,majority:`Mehrheit`,current:`Aktuell`,wasted:`Verschwendet`,wasted_title:`Beitrag zur Effizienzlücke pro Bezirk`,partisan:`Parteilich`,partisan_title:`Jeden Bezirk nach parteilichem Ergebnis einfärben (UCP blau / NDP orange)`,borders:`Grenzen`,flagged:`Beanstandet`,flagged_title:`Alle 7 Konfigurationen, die vom Kommissionsvorsitzenden Richter Miller beanstandet wurden — wechselt automatisch zur Minderheitenkarte`,help_aria:`Kartenhilfe`,help_title:`So benutzen Sie die Karte`,pin_aria:`Karte fixieren`,pin_title:`Karte fixieren — kein automatisches Schwenken beim Klick auf einen Bezirk`,search_placeholder:`Bezirk finden…`,zoom_aria:`Kartenzoom`,clear_aria:`Bezirksauswahl aufheben`,clear_title:`Auswahl aufheben`,va_hint:`Klicken Sie innerhalb dieses Bezirks, um Wahllokal-Ergebnisse zu sehen`,va_close_aria:`Wahllokal-Detail schließen`,va_close_title:`Schließen`,object_title:`Wahlbezirkskarte Albertas — volle Auflösung`,ea_credit:`Kartendaten:`,cc_title:`Textinhalt: CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`},map_intro:{heading:`So benutzen Sie die Karte`,click_district:`Auf einen Bezirk klicken`,click_district_desc:`Wahlergebnisse 2023 anzeigen und einrasten`,click_within:`Innerhalb eines ausgewählten Bezirks klicken`,click_within_desc:`einzelne Wahllokal-Ergebnisse anzeigen (Farbe = Stimmenaufteilung)`,dblclick:`Doppelklick auf einen Bezirk`,dblclick_desc:`auf Bildschirmgröße zoomen; Doppelklick auf leere Fläche zoomt heraus`,layers_primary:`Minderheit / Mehrheit / Aktuell`,layers_primary_desc:`aktive Grenzkarte wechseln`,layers_data:`Parteilich / Verschwendet / Grenzen`,layers_data_desc:`Datenebenen umschalten`,search:`Bezirk finden`,search_desc:`per Namen springen; Pfeiltasten schwenken, + / − zoomen`,escape:`Escape`,escape_desc:`diesen Viewer schließen`,s4_tip:`In §4 auf <em>Beanstandete Bezirke auf der Karte zeigen</em> klicken, um die Airdrie-Aufteilung und die NW-Calgary-Zone hervorzuheben.`,got_it:`Verstanden`},footer:{title:`Audit der Wahlbezirksgrenzen Albertas — Mai 2026`,copyright:`© Will Conner 2026 —`,text_label:`Text:`,code_label:`Code:`}}},es:{},ar:{},uk:{selector:{label:`Виберіть мову`},disclaimer:{text:`Цей сайт перекладено за допомогою ШІ. Деякий вміст може все ще відображатися англійською, поки переклади тривають. Якщо Ви помітили помилки або хочете допомогти з перекладом цього проєкту, будь ласка, %s.`,link_label:`зв'яжіться з нами`},opener:{heading:`Для кого це?`,body:`Для нас. Для всіх нас. Для сільських мешканців, міських, цікавих, фахівців, журналістів, юристів, науковців, політиків — для всіх нас. Бо це впливає на всіх нас. Незалежно від того, подобається Вам партія при владі чи ні, того, що створила розділена комісія, ніколи раніше не було. І це дало нам можливість зазирнути всередину машини так, як ми ніколи не могли раніше. Тепер ми можемо встановити базову лінію — серію тестів, і все, що буде далі, можна буде за нею оцінювати. Дозвольте показати Вам, що я знайшов.`},stakes:{q1:{heading:`Чи є запропонована карта джеррімендером?`,body:`«Джеррімендер» — це не термін, яким користуються канадські суди. Але якби це було так — у повсякденному сенсі, який більшість людей у нього вкладають — докази цього аудиту обґрунтовано підтримали б кваліфікацію <em>пропозиції меншості</em>, якщо її ухвалити, як карти, серйозно переробленої на партійну користь. Чотири з п'яти структурних тестів цього аудиту сигналізують про <em>пропозицію меншості</em>, і жоден не сигналізує про альтернативу (<em>пропозицію більшості</em>); п'ятий тест є нейтральним для обох.`,footnote:`Назви «більшість» і «меншість» походять від розколу 3–2 у Комісії з виборчих меж (під головуванням судді Міллера), яка створила дві конкуруючі пропозиції замість єдиної рекомендації. Законодавчі збори згодом відклали обидві й передали перерозподіл комітету з п'яти MLA під головуванням Брендона Ланті (Brandon Lunty) (MLA, призначеного прем'єр-міністром); комітет наглядає за окремою чотиричленною Незалежною дорадчою панеллю — двох членів номінує прем'єр-міністр (достопочесний Монте Солберг (Monte Solberg) і Дарвін Дурні (Darwin Durnie)), двох — лідер опозиції (д-р Джерард Кеннеді (Gerard Kennedy) і Брент Робінсон (Brent Robinson)) — якій доручено створити нову пропозицію меж на 91 округ до граничного терміну у листопаді 2026 року.`},q2:{heading:`Що означає «джеррімендер» у канадському праві?`,body:`Нічого. Канадський критерій інший: чи забезпечують межі виборцям <em>дієве представництво</em> згідно зі статтею 3 Хартії. Пропозиція меншості викликає серйозні питання за стандартом дієвого представництва; лише суддя може дати на них остаточну відповідь, а ніхто ще не звертався до суду.`},q3:{heading:`Що поставлено на карту для альбертанців?`,body:`При провінційному голосуванні 50/50 виміри аудиту розміщують пропозицію меншості у структурній крайності: менш ніж 100 із 1,01 мільйона нейтральних карт-порівнянь дають такий самий дисбаланс місць. Цей дисбаланс важливий тому, що при 58 із 87 місць (надбільшість у дві третини) правляча партія розблоковує надзвичайні процедурні повноваження. Вона може скасовувати стандартні терміни повідомлення й проштовхувати публічні законопроєкти через декілька законодавчих етапів за один день, обходячи дорадчі запобіжники, на які зазвичай покладаються законодавчі збори. Чи достатньо сильний нахил пропозиції меншості, щоб підняти одну партію через цей поріг у 58 місць при частках голосів, <em>відмінних</em> від 50/50 — питання, яке цей аудит ще не перевірив. Чи прийнятний такий дисбаланс — питання для альбертанців, а не для цього аудиту.`},cta_law:`Прочитати правовий контекст →`,cta_methods:`Дивитися, як ми тестували →`,scorecard_h:`Зведена таблиця`,scorecard_fig_alt:`Діаграма розсіювання: розрив ефективності на горизонтальній осі, кількість провалених структурних тестів на вертикальній. Карта 2019 року й карта більшості 2026 року групуються у безпечному нижньому лівому куті. Карта меншості 2026 року з'являється сама у верхній правій зоні виняткових значень.`,scorecard_fig_caption:`Обидві смуги на одному зображенні. Горизонталь: наскільки скошене число партійної справедливості (праворуч = більше на користь UCP). Вертикаль: скільки з п'яти тестів структурної справедливості провалила карта. Нижній лівий — це безпечний кут, де нейтральні процедури зазвичай опиняються; верхній правий — це зона виняткових значень. Карта 2019 року й більшість 2026 року сидять у безпечному куті. Меншість 2026 року сидить сама у зоні виняткових значень.`,scorecard_intro:`Два незалежні виміри, застосовані до обох карт за тими самими попередньо зареєстрованими порогами. Структура використовує лише форму ліній — жодних результатів виборів. Числа перевіряють, як лінії перетворюють голоси на місця. Обидві смуги доходять до того самого висновку.`,scorecard_close:`Два незалежні виміри, одна відповідь. Збіг — найсильніший окремий сигнал аудиту.`},head:{title:`Аудит виборчих меж Альберти`,meta_description:`Статистичний аудит комісії з виборчих меж Альберти 2026 року — 1 010 000 нейтральних карт, офіційні шейпфайли Elections Alberta, попередньо зареєстровані тести.`},nav:{skip_to_content:`Перейти до вмісту`,home_aria:`Повернутися нагору`,theme_aria:`Перемкнути темний / світлий режим`,theme_title:`Перемкнути темний режим`,nav_aria:`Відкрити зміст`,drawer_top:`↑ Нагору`,stakes:`Ставки`,findings:`Висновки`,history:`Історія`,reform:`Реформа`,notes:`Примітки`,group_overview:`Огляд`,group_audit:`Аудит`,group_context:`Контекст`,group_forward:`Що далі`,group_apparatus:`Апарат`,why:`Чому це важливо?`,map:`Карта з першого погляду`,split:`Як розкололася комісія`,litmus:`Лакмусовий тест 1 010 000 карт`,crack_pack:`Розщеплення, пакування, виснаження`,for_you:`Що це означає для Вас`,impact:`Вплив на місцях`,gerrymanders:`Чисті джеррімендери`,history_full:`Історія джеррімендерингу`,canada:`Канада — інакше`,november:`Листопад`,lunty:`Ланті`,invisible:`Невидиме`,suggestions:`Пропозиції реформи`,retractions:`Спростування`,references:`Посилання`,resources:`Ресурси`,technical:`Технічні ресурси`},hero:{h1:`Аудит виборчих меж Альберти`,subtitle:`Комісія Альберти у 2026 році створила дві карти округів. Цей аудит порівняв їх — застосовуючи однакові тести однаково до обох — щоб запитати, чи однаково вони ставляться до виборців.`,badge:`Офіційні карти Elections Alberta — опубліковано у травні 2026 року`,cover_note:`Натисніть, щоб збільшити й одночасно дослідити всі три пропозиції меж. Закріпіть область перегляду й перемикайтесь між картами — межі зміщуються, виборці залишаються на місці. Прокрутіть вниз для аналізу.`,cover_note_1:`Ця карта — найкращий вхід. Натисніть її, щоб збільшити й дослідити. Кнопки вгорі перемикають між картою меншості, картою більшості й межами, ухваленими у 2019 році — або накладіть усі три, щоб побачити, де саме вони розходяться. <strong>Detail</strong> розфарбовує кожну виборчу зону за тим, як люди голосували у 2023 році; <strong>Trend</strong> додає партійне затемнення за округом (синє UCP, помаранчеве NDP); <strong>Lines</strong> вмикає й вимикає межі. <strong>Find</strong> переходить до будь-якого округу за назвою.`,cover_note_2:`Спробуйте заблокувати область перегляду й перемикатися між картами — спостерігайте, як межа зміщується, тоді як виборці під нею залишаються нерухомими. Усе питання — в одному жесті.`,cover_note_3:`Коли закінчите досліджувати, прокрутіть вниз до підсумку. Для повного технічного аналізу див. розділ Ресурси. Усі дані — офіційні шейпфайли Elections Alberta та інші державні й відкриті записи.`,image_alt:`Карти виборчих округів Альберти — пропозиція комісії меншості, розфарбована за голосуванням 2023 року`,map_hint:`Натисніть, щоб дослідити інтерактивно`,btn_title:`Натисніть, щоб відкрити інтерактивну карту`,btn_aria:`Натисніть, щоб дослідити інтерактивно`},boundary:{heading:`Що цей аудит може й не може Вам сказати`,can_1:`Геометрія карти меншості перетинає 4 з 5 попередньо зареєстрованих структурних порогів <em>без використання будь-яких виборчих даних узагалі</em>. П'ятий (прив'язка) є нейтральним. Більшість перетинає 0 з 4 спрацьованих. Ці тести вимірюють властивості самих меж — форму округу, муніципальну прив'язку, розкид населення — і доходять висновку до того, як підрахують хоч один голос.`,can_2:`Окремо, коли долучаються виборчі дані, карта меншості сидить на 99,99-му процентилі 1,01 мільйона алгоритмічно намальованих карт-порівнянь, дотриманих тих самих статутних правил. Менш ніж 100 із цих 1,01 мільйона нейтральних карт досягають такого самого дисбалансу місць. Об'єднаний статистичний сигнал становить приблизно 1 на 14,5 мільйона за нейтрального процесу малювання. Два незалежні інструменти — геометричний і статистичний — доходять того самого висновку.`,can_3:`Три з конфігурацій, які містить пропозиція меншості, голова комісії суддя Міллер позначив письмово в §5.8.2 звіту більшості та Додатку C. Тести аудиту виконано без знання його позначок і виявляють ті самі регіони. Третій незалежний інструмент — судовий — сходиться на тих самих межах.`,cant_1:`Аудит <strong>не</strong> встановлює, що будь-який комісар мав намір виробити партійні ефекти, які він вимірює. Геометрія меж не може розкрити намір.`,cant_2:`Аудит <strong>не</strong> передбачає, що обере комітет Ланті, яким буде голосування у листопаді 2026 року, або як зреагують альбертанці.`,cant_3:`Аудит <strong>не</strong> передбачає, як суд би вирішив справу, якби проти будь-якої з пропозицій було подано позов на основі Хартії.`,cant_4:`Аудит <strong>не</strong> стверджує, що цифра 1 на 14,5 мільйона — це ймовірність того, що джеррімендер стався. Це число — ймовірність хвоста для геометрії меншості за нейтральної алгоритмічної нульової гіпотези. Це доказ того, що нейтральна нульова гіпотеза неправдоподібна. Це не апостеріорна ймовірність партійного наміру — для цього питання потрібні докази, які геометрія не може надати.`,cant_5:`Аудит <strong>не</strong> вказує жодному окремому виборцю, яку позицію займати чи що робити з цією інформацією. Вибір — за Вами.`},editorial_intro:{heading:`Що таке перерозподіл меж і чому це важливо`,p1:`Кожен виборець в Альберті живе у <em>виборчому окрузі</em> — ділянці провінції, що обирає одну особу до законодавчих зборів. Округів — 87. Кожен округ обирає одного MLA. Коли Ви голосуєте на провінційних виборах, Ви обираєте MLA для округу, де живете. Для більшості альбертанців це і є весь зв'язок із законодавчими зборами: один MLA, один округ, один голос.`,p2:`Ці лінії округів не є постійними. Люди переїжджають, мікрорайони ростуть, сільські райони рідшають, міста розповзаються. Кожні вісім-десять років Альберта має перемалювати лінії, щоб кожен округ був приблизно правильного розміру й відображав те, як альбертанці насправді живуть зараз. Орган, що проводить перемалювання, — це <em>Комісія з виборчих меж</em> — незалежна комісія з суддів, юристів і громадських членів, а не політиків.`,p3:`Це стандартний процес. Цього разу стандартний процес дав щось незвичайне. П'ять членів комісії розкололися 3–2 щодо того, якою має бути карта, і замість того, щоб погодитися на одну рекомендацію, вони створили дві: <em>пропозицію більшості</em> (підтриману трьома комісарами) і <em>пропозицію меншості</em> (підтриману двома). Обидві лежать на столі — і законодавчі збори відклали обидві. Окремий комітет MLA під головуванням Брендона Ланті — призначеного прем'єр-міністром для цього конкретного рішення — тепер наглядає за чотиричленною Незалежною дорадчою панеллю, створеною за урядовою постановою 37 (ухваленою 21 квітня 2026 року), якій доручено створити нову карту на 91 місце. Законодавчі збори мають затвердити те, що подасть комітет, до листопада 2026 року.`,p4:`Чому це важливо для Вас: лінії вирішують, хто Ваш MLA. Вони вирішують, які мікрорайони, міста й інтереси представлятимуться разом. Якщо Ваше місто розділене між чотирма MLA замість одного, жоден окремий представник не несе відповідальності за місто в цілому. Якщо Вашу спільноту інтересів — мале місто, сільський регіон, центр міста — розділено між округами, Ваш голос у провінційних рішеннях розбавляється. Карта також формує, яка партія може сформувати уряд і з якою перевагою. Конкретний висновок аудиту (пропозиція меншості перебуває у структурній крайності) — це причина, з якої Ви читаєте цей сайт, але ширше питання старіше й стосується кожного циклу перерозподілу: чи відображають лінії те, як живуть альбертанці, чи вони формують політику, яка з цього випливає?`,p5:`Решта цієї сторінки крок за кроком показує, що насправді роблять дві запропоновані карти.`,key_terms_lead:`Ключові терміни в цьому розділі — натисніть, щоб прочитати:`},editorial_reflect:{heading:`Інтерлюдія: що це означає для Вас і Вашої громади`,intro_p1:`Відкладіть на мить питання про те, яка партія здобуває чи втрачає місця. Політики й партії схильні подавати це як боротьбу за концентрацію влади в законодавчих зборах, і на законодавчому рівні так воно і є. Але концентрацію влади в законодавчих зборах Ви не відчуваєте. Ви відчуваєте ці карти через три конкретні питання про Ваш власний округ:`,intro_q1:`Де живе Ваш MLA?`,intro_q2:`Чи вкладаються вони у Вашу громаду?`,intro_q3:`Чи будуть вимоги «голови» домінувати над вимогами «хвостів»?`,intro_p2:`Будь-яке інше формулювання — партійна перевага, поріг надбільшості, статистична крайність — зрештою вказує на ці три. П'ять сходинок нижче показують, як кожна запропонована карта відповідає на них на п'яти масштабах.`,you_h:`Ви.`,you_p:`Ваш виборчий округ вирішує, хто представляє Вас у законодавчих зборах. Зараз Ви живете в одному з 87 округів. За обох запропонованих карт Ви можете опинитися в іншому — можливо, з іншим MLA, можливо, прив'язаним до інших сусідніх громад. Якщо Ви не знаєте, у якому окрузі зараз знаходитесь, або хто Ваш MLA, Ви не самотні: більшість альбертанців не змогли б назвати свого MLA. Але лінії меж не абстрактні. Вони вирішують, чий номер телефону на стіні офісу Вашого місцевого представника, чия районна петиція отримує Ваше ім'я, чиї занепокоєння Ваш MLA почує першими. Пошук за поштовим індексом на цьому сайті показує, у якому окрузі Ви опиняєтеся за кожною пропозицією. Якщо Ваш округ змінюється, Ваш представник змінюється — а разом із ним змінюється і стосунки Вашого представника з Вашою громадою.`,community_h:`Ваша громада.`,community_p:`Громади також не абстрактні. Зона охоплення середньої школи, торгова палата, релігійна громада, асоціація мікрорайону — це реальні групи людей зі спільними місцевими інтересами. Коли лінія межі проходить через них, жоден окремий MLA не відповідає за ціле. Візьміть Airdrie за пропозицією меншості: місто приблизно з 85 800 людьми, розрізане на чотири виборчі округи, кожен прив'язаний до іншого сільського околу. Жоден окремий представник не несе відповідальності за Airdrie як місто. Та сама динаміка діє там, де розділяється місто, мікрорайон чи визнана громада інтересів — чим більший розкол, тим слабше представництво. Аудит вимірює <em>муніципальну прив'язку</em> (яка частка периметра кожного округу проходить уздовж наявних муніципальних ліній), і пропозиція меншості отримує помітно нижчий бал за прив'язкою, ніж більшість.`,municipality_h:`Ваш муніципалітет.`,municipality_p:`Коли місто роздроблено між багатьма представниками, його здатність торгуватися щодо провінційних рішень слабшає. Рада, що просить фінансування транспорту, шкільна рада, що домовляється про нову школу, мер, що лобіює продовження автомагістралей — кожне з цього йде краще, коли місто може вказати на кількох MLA, що несуть відповідальність перед містом у цілому. Пропозиція меншості розколює північно-західний квадрант Калгарі на кілька округів, моделі часток голосів яких свідчать про <em>пакування</em> (концентрацію виборців однієї партії у кількох місцях з великим відривом) поверх <em>розщеплення</em> (розпорошення виборців іншої партії між багатьма місцями з малим відривом). Чи є цей шаблон навмисним — питання, на яке аудит не може відповісти: геометрія меж не розкриває наміру. Що він може сказати — це що чотири статистичні міри сигналізують про ті самі округи, що й структурні тести, і що альтернативна пропозиція не дає такого самого «відбитка пальця».`,region_h:`Ваш регіон.`,region_p1:`Якщо Ви живете поза містами Альберти, Ви, ймовірно, помітили, що політичні розмови про межі завжди ніби зосереджуються на містах. Це справедлива скарга, тож скажімо прямо, що цей аудит говорить, а що ні про сільську Альберту.`,region_p2:`Що він <strong>не</strong> говорить: у сільської Альберти забагато місць. EBCA дозволяє населенню округів варіюватися до 25%, щоб один сільський MLA не представляв територію розміром з південну Францію. Канадські суди розглядають це відхилення як легітимне. Обидві запропоновані карти його зберігають. Ніщо в цьому аудиті цього не змінює.`,region_p3:`Що він <strong>говорить</strong>: у кількох місцях на пропозиції меншості сільські громади приєднуються як <em>хвіст</em> округу, центр населення якого розташований у місті. Подивіться, як пропозиція меншості поводиться з Airdrie — містом приблизно з 85 800 людьми, розрізаним на чотири округи, кожен з яких простягається в інший шмат сільської місцевості. Центр населення кожного нового округу — це міська частка, а не сільський хвіст. MLA, обраний з округу такого типу, найімовірніше живе, проводить кампанію й розставляє пріоритети там, де голоси — а це означає, що сільські громади, які раніше представлялися спеціальним сільським MLA, стають задньою половиною округу під керівництвом міста. Цей шаблон повторюється на пропозиції меншості так, як він не повторюється на пропозиції більшості.`,region_p4:`Аудит не пропонує відбирати місця у сільської Альберти. Він запитує, чи поважають лінії сільські громади, які ці місця мають представляти, чи сільська географія використовується як баласт, щоб поглинати міські голоси в округи, центр яких знаходиться десь в іншому місці. Якщо Ви живете в одному з цих сільських «хвостів», питання, яку карту буде ухвалено, вирішує, чи представляє Ваш MLA сільську громаду, в якій Ви насправді живете, чи міський округ, лінії якого випадково охоплюють Вашу землю.`,province_h:`Ваша провінція.`,province_p:`Законодавчі збори — це те, що Ви отримуєте, коли підсумовуєте відповіді кожного округу на три попередні питання. Якщо більшість округів прив'язані до громад, у яких насправді живуть їхні MLA, законодавчі збори представляють ці громади. Якщо у більшості округів сільські хвости приєднані до міських голів, законодавчі збори представляють голови — а хвости отримують будь-яку увагу, що залишилася. Партійне питання — яка партія здобуде більшість — є наслідком цього. Питання надбільшості — чи перетне одна партія 58 із 87 місць і розблокує процедурні скорочення на кшталт скасування періодів повідомлення або прискорення проходження законопроєктів через кілька етапів за один день — є наслідком <em>цього</em>. При гіпотетичному провінційному поділі 50/50 виміри аудиту розміщують пропозицію меншості у структурній крайності: менш ніж 100 із 1,01 мільйона нейтральних карт-порівнянь дають такий самий дисбаланс місць. Чи виштовхує цей дисбаланс партію за 58 місць при тих частках голосів, які альбертанці насправді віддають — питання, яке цей аудит ще не перевіряв напряму; початкові питання у верхній частині сторінки чесно говорять про цю прогалину. Чи відповідь на якесь із цих питань має достатньо ваги, щоб діяти — це, знову ж таки, питання для Вас.`},editorial_history:{heading:`Контекст: коротка історія джеррімендерингу`,p1:`Слово походить з 1812 року. Губернатор Массачусетсу Елбрідж Геррі підписав карту сенату штату, округи якої були настільки скривлені на користь його партії, що один бостонський карикатурист намалював один із них як саламандру — крила, кігті, роздвоєний язик. Каламбур карикатуриста <em>Gerry-mander</em> закріпився. Форма теж закріпилася: через два століття слово досі означає малювання виборчих ліній для конструювання партійного результату.`,p2:`Термін зберігається, бо проблема зберігається. Усюди, де виборці обирають представників з географічних округів, хтось має малювати лінії, а лінії можна намалювати багатьма способами. Різні країни прийшли до різних відповідей про те, хто має малювати й що має їх обмежувати.`,p3:`<strong>Сполучені Штати</strong> ставляться до партійного джеррімендерингу як до проблеми, яку федеральні суди здебільшого не можуть розв'язати. У справі <em>Rucho v. Common Cause</em> (2019) Верховний суд США постановив, що партійні джеррімендери — це «політичні питання» поза його юрисдикцією. Деякі штати (Каліфорнія, Мічиган) відреагували створенням незалежних громадських комісій, що малюють свої лінії; інші (Техас, Північна Кароліна) продовжують малювати відкрито партійні карти й захищають їх на основі того, що <em>Rucho</em> це дозволяє.`,p4:`<strong>Сполучене Королівство</strong> використовує чотири постійні Комісії з меж — по одній для Англії, Шотландії, Уельсу й Північної Ірландії — укомплектовані суддями й вищими держслужбовцями. Вони перемальовують лінії приблизно кожні вісім років за фіксованими правилами (рівність населення, географічна цілісність, повага до меж місцевого самоврядування). Парламент теоретично може відхилити рекомендації комісій, але на практиці майже ніколи цього не робить; за конвенцією, рішення комісій залишається в силі.`,p5:`<strong>Австралія</strong> делегує роботу Австралійській виборчій комісії, федеральному незалежному агентству з повною владою як над адмініструванням виборів, так і над межами. Перерозподіл відбувається автоматично, коли змінюється кількість місць штату або минає сім років з моменту останнього. Рішення комісарів можуть переглядатися з процедурних підстав, але не з партійних. Як і в Сполученому Королівстві, джеррімендеринг у тому розумінні, в якому його знають американці, практично невідомий.`,p6:`Ці три випадки окреслюють спектр: суди тримаються осторонь (США), незалежні комісії з сильною парламентською повагою (Сполучене Королівство), й постійне незалежне агентство з повною владою (Австралія). Канада знаходиться десь в іншому місці — і саме це бере наступний розділ.`},glossary:{more_link:`Дізнатися більше →`,"electoral-district":{term:`Виборчий округ (ED)`,definition:`Географічна територія, яка обирає одного члена до провінційних законодавчих зборів. Часто скорочується як «ED» після першого вживання. Кожен ED має одного MLA. (Слово «riding» зазвичай стосується федеральних округів; у провінційному контексті правильний термін — виборчий округ.)`},riding:{term:`Riding`,definition:`У канадському вжитку це найчастіше стосується федерального виборчого округу. Альбертанський провінційний еквівалент називається «виборчим округом» (ED). Аудит послідовно вживає провінційний термін.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly (член законодавчих зборів) — особа, обрана від одного виборчого округу для представництва його в законодавчих зборах Альберти.`},ucp:{term:`UCP`,definition:`United Conservative Party (Об'єднана консервативна партія) — нинішня правляча провінційна партія Альберти. Утворена у 2017 році зі злиття Прогресивних консерваторів і партії Wildrose; перебуває при владі з 2019 року.`},ndp:{term:`NDP`,definition:`New Democratic Party (Нова демократична партія Альберти) — нинішня офіційна опозиція Альберти. Альбертанські NDP перебували при владі з 2015 по 2019 рік.`},gerrymander:{term:`Джеррімендер`,definition:`Карта, намальована так, щоб одна політична партія здобула більше місць, ніж вказувала б її частка голосів. Слово походить з округу в Массачусетсі 1812 року, формою схожого на саламандру. У Канаді це не правовий термін, але концепція широко вивчається.`},cracking:{term:`Розщеплення (cracking)`,definition:`Техніка джеррімендерингу, що розділяє виборчий блок між багатьма округами так, що він ніколи не досягає більшості в жодному окремому. Наприклад, поділ міста між чотирма округами так, щоб його виборці програвали чисельністю в кожному.`},packing:{term:`Пакування (packing)`,definition:`Техніка джеррімендерингу, що концентрує виборців однієї партії у невеликій кількості округів. Партія виграє ці округи з великим відривом, але «марнує» багато голосів — залишаючи менше своїх виборців доступними для боротьби в інших округах.`},draining:{term:`Виснаження (draining)`,definition:`Термін, який цей аудит використовує для побічного ефекту розщеплення й пакування: змарновані голоси, що їх продукують ці техніки, проштовхуються у стратегічно обрані місця, змінюючи політичний характер сусідніх виборчих округів. Це власне формулювання аудиту, а не усталене поняття у літературі про перерозподіл — аудит тестує цей ефект і знаходить результати, узгоджені з ним, але розглядає його як дослідницький, а не як усталену методологію.`},anchoring:{term:`Прив'язка (anchoring)`,definition:`Наскільки чітко запропоновані межі йдуть уздовж наявних муніципальних ліній (міські межі, межі містечок). Сильно прив'язана карта здебільшого поважає ці лінії; слабо прив'язана карта часто від них відходить — особливо у політично значущих місцях, що є структурним попереджувальним знаком.`},"charter-s3":{term:`Стаття 3 Хартії`,definition:`Стаття Канадської хартії прав і свобод, що гарантує громадянам право голосу. Канадські суди тлумачать її не як суворе правило «одна особа, один голос», а як право на «дієве представництво».`},"effective-representation":{term:`Дієве представництво`,definition:`Стандарт, який застосовують канадські суди, оцінюючи виборчі межі. Він означає, що виборці повинні мати значущий голос — не лише чисельну рівність населення округів, але й визнання громадських зв'язків, географії та представництва меншин. Провідне формулювання — у саскачеванському посиланні Верховного суду Канади 1991 року.`},ebc:{term:`Комісія з виборчих меж (EBC)`,definition:`Орган, що малює провінційні виборчі межі Альберти за EBCA. Комісію 2026 року очолював суддя Міллер, і її члени розкололися 3–2, створивши дві конкуруючі пропозиції (пропозиції більшості й меншості) замість єдиної рекомендації.`},"lunty-committee":{term:`Комітет Ланті`,definition:`Спеціальний відбірковий комітет з виборчих меж з п'яти MLA під головуванням Брендона Ланті — призначеного прем'єр-міністром MLA — створений Постановою 19 законодавчих зборів (16 квітня 2026 року), яка відклала обидва звіти комісії. Комітет наглядає за окремою чотиричленною Незалежною дорадчою панеллю, створеною за урядовою Постановою 37 (ухваленою 21 квітня 2026 року), яка малює фактичну карту; потім комітет звітує перед законодавчими зборами до граничного терміну листопада 2026 року. Обидва органи окремі від EBC і не є частиною стандартного процесу EBCA.`},"advisory-panel":{term:`Незалежна дорадча панель`,definition:`Чотиричленна панель, призначена комітетом Ланті згідно з пунктом C(d)(ii) урядової Постанови 37 для розробки рекомендації меж на 91 місце. Прем'єр-міністр номінував достопочесного Монте Солберга й Дарвіна Дурні; лідер опозиції номінував д-ра Джерарда Кеннеді й Брента Робінсона. П'яте місце — діючий або відставний суддя на посаду голови — залишилося незаповненим після того, як виконуючий обов'язки голови суду Альберти відмовився когось номінувати.`},ebca:{term:`EBCA`,definition:`Alberta Electoral Boundaries Commission Act (Закон Альберти про Комісію виборчих меж) — закон, що регулює, як малюються виборчі межі у провінції. Він установлює комісію, процес публічних слухань і правила того, коли нова карта набирає чинності.`},fsa:{term:`Forward sortation area (FSA)`,definition:`Перші три символи канадського поштового індексу (частина «літера-цифра-літера»). Альберту охоплюють близько 270 FSA. Більшість повністю розташовані в межах одного виборчого округу.`}},body:{section_link_aria:`Посилання на розділ`,the_map:{heading:`1: Карта`,p1:`Обкладинкова карта — найкраще окреме зображення цього аудиту. Ось як її читати.`,p2:`Альберту поділено на 4765 виборчих зон — невеликих географічних ділянок, які Elections Alberta використовує для підрахунку бюлетенів виборчих дільниць. Кожна розфарбована за тим, як люди в ній насправді голосували у 2023 році: помаранчевий там, де сконцентровані голоси NDP, синій там, де сконцентровані голоси UCP. Але колір стає темним і насиченим лише там, де живе багато людей. Виборча зона, що охоплює сотні квадратних кілометрів паркової зони або сільгоспугідь, залишається блідою — майже невидимою. Карта освітлюється там, де є люди, і блякне там, де їх немає.`,p3:`Це дуже відрізняється від Альберти, яку Ви бачите у виборчий вечір. Більшість виборчих карт розфарбовують цілі округи суцільним синім або помаранчевим залежно від того, хто переміг. Сільські округи географічно великі, і UCP виграє більшість із них, тож Альберта виборчого вечора виглядає як стіна синього з невеликими помаранчевими острівцями в Едмонтоні й Калгарі. Обкладинкова карта використовує ті самі голоси й ту саму географію — але показує їх зваженими за тим, де насправді живуть люди. Виявляється провінція, де більшість населення зосереджена в густій дузі міст, і ці міста голосують дуже інакше, ніж сільська карта, яка їх зазвичай представляє.`,p4:`Лінії меж, намальовані поверх кольору, — це 89 запропонованих виборчих округів комісії меншості — карта, яку цей аудит зрештою критикує. Робота аудиту полягає в тому, щоб запитати, що ці лінії роблять із людьми під ними.`,p5:`Це зображення робить ставки зрозумілими. Провінція, яка на стандартній карті виглядає так, ніби голосує одним способом, насправді є провінцією, де більшість людей живе в районах, що голосують інакше. Щойно населення стає видимим під вибором меж, ці вибори перестають виглядати випадковими.`},structural_results:{heading:`Результати структурного аудиту — до будь-якої статистики:`,body:`Карта більшості перетинає <strong>нуль із п'яти</strong> попередньо зареєстрованих структурних порогів. Карта меншості перетинає <strong>чотири з п'яти</strong>; п'ятий (прив'язка) є нейтральним — обидві карти потрапляють у канадську норму 70–85%. Це геометричні виміри — розкид населення, <button class="vocab-term" data-def="наскільки тісно межі округу йдуть уздовж наявних міських і муніципальних меж, а не перетинають їх" aria-expanded="false">муніципальна прив'язка</button>, кількість поділів Airdrie, надлишок населення у NW Калгарі та сім конфігурацій меж, які голова комісії суддя Міллер сам позначив письмово (§5.8.2 звіту більшості й Додаток C) — не потребуючи жодних виборчих даних і жодного статистичного семплера. Наступний розділ тестує обидві карти проти 1 010 000 згенерованих комп'ютером нейтральних карт і доходить того самого висновку через зовсім інший інструмент. Три незалежні інструменти — геометричний, судовий і статистичний — сходяться.`},clean:{heading:`6: Коли справедлива на вигляд карта такою не є`,legal_label:`ПРИМІТКА ПРО ПРАВОВУ ТЕРМІНОЛОГІЮ`,legal_body:`«Джеррімендеринг» не має правового визначення в канадському праві. Це слово вживається у цьому звіті у його повсякденному політичному сенсі — маніпулювання виборчими межами заради партійної переваги. Правові тести, які насправді застосовуються в Канаді, інші: чи забезпечують межі «дієве представництво» згідно зі статтею 3 <em>Хартії прав і свобод</em> (конституційний стандарт, який Верховний суд Канади встановив у саскачеванському посиланні 1991 року <em>Saskatchewan Reference</em>), і чи дотрималася комісія правил Альбертанського <em>Electoral Boundaries Commission Act</em>. Висновки аудиту — це докази, що стосуються цих правових питань. Вони не є доказом правопорушення, визначеного законом, і цей звіт не описує їх такими словами.`,intro_p1:`Найчистіше окреме питання, яке можна поставити до будь-якої виборчої карти, таке: якби голоси провінції розділилися точно порівну між двома основними партіями, яку кількість місць дала б карта? Це утримує електорат постійним і запитує саму карту, що вона робить.`,intro_p2:`Щоб відповісти на це, аудит згенерував 1 010 000 комп'ютерно змодельованих, математично нейтральних карт Альберти. Симуляція використовувала офіційні шейпфайли Elections Alberta й трималася точно тих самих статутних правил і географічних меж, які використовувала комісія. Дві карти комісії 2026 року потім помістили в цей розподіл, щоб побачити, наскільки вони нормальні. Симуляція провела чотири незалежні ланцюги по 252 500 кроків кожен, з базовим зерном, узятим з маяка випадковості Cloudflare drand і попередньо зареєстрованим на OSF до виконання.`,howmcmc_label:`ЯК ПРАЦЮЄ СИМУЛЯЦІЯ`,howmcmc_mcmc:`<strong>MCMC (Markov Chain Monte Carlo)</strong> — це метод дослідження великого простору — тут, простору всіх легальних карт Альберти — шляхом випадкових кроків від початкової точки. Кожен крок пропонує невелику перестановку між сусідніми округами; якщо результат залишається в межах статутних правил, він стає новою початковою точкою. Після достатньої кількості кроків відвідані карти утворюють репрезентативну вибірку легальних планів. Симуляція засіяна з маяка публічної випадковості Cloudflare drand для запобігання будь-якому вибірковому підбору початкових умов.`,howmcmc_recom:`<strong>ReCom (Redistricting Compiler)</strong> — це конкретний алгоритм, що тут використовується. Кожен крок об'єднує два сусідні округи в один регіон і знову випадково розщеплює його на два нові дійсні округи, за побудовою зберігаючи зв'язність і баланс населення — тож алгоритм ніколи не повинен відхиляти недійсну пропозицію.`,prereg_label:`ПОПЕРЕДНЯ РЕЄСТРАЦІЯ`,prereg_body:`Попередня реєстрація означає записування точних тестів, порогів і передбачених напрямків до перегляду будь-яких даних і фіксацію цих зобов'язань у публічному записі з міткою часу. Open Science Framework (OSF) — це публічний репозиторій, де реєструються зобов'язання цього аудиту. Це запобігає підгонці заднім числом: якщо результат не вийшов чисто, поріг не можна змінити постфактум і потім подати так, ніби він завжди був тестом. Усі п'ять структурних тестів і чотири метрики партійної справедливості в цьому аудиті були зареєстровані на OSF до того, як було проведено будь-яку симуляцію.`,neutral_p:`В Альберті нейтральна відповідь — це не 50/50. <em>Серед 1 010 000 комп'ютерно змодельованих легальних карт Альберти медіанна карта дає UCP лише 44,8% місць при голосуванні 50/50</em> — типова карта Альберти за нейтральних голосів передає NDP невелику більшість місць. Це контрінтуїтивно, але механічно: сільські виборці UCP виграють свої округи з відривом 60–40 (марнуючи багато «зайвих» голосів UCP), тоді як міські виборці NDP виграють свої округи з тіснішим відривом 51–49 (марнуючи менше голосів NDP на перемогу). За нейтральності NDP виходить уперед за ефективністю місць.`,full_dist:`Повний розподіл з канонічної симуляції 1 010 000 карт:`,t1_col_a:`Де сидить карта`,t1_col_b:`Місця UCP при голосуванні 50/50`,t1_r1_a:`Медіанна карта Альберти`,t1_r1_b:`44,8% — невелика більшість місць NDP`,t1_r2_a:`Карта 95-го процентиля`,t1_r2_b:`47,1%`,t1_r3_a:`Карта 99-го процентиля`,t1_r3_b:`48,4%`,t1_r4_a:`<strong>Максимум серед 1 010 000 карт</strong>`,t1_r4_b:`<strong>нижче 51,7% (менш ніж 100 планів досягають цього значення)</strong>`,seat_count_note:`Примітка про кількість місць. Карти комісії 2026 року мають по <strong>89</strong> округів; комп'ютерна симуляція аудиту виконується на карті 2019 року з <strong>87</strong> округами (її початковому субстраті); листопадовий комітет Ланті створить <strong>91</strong>. Усі відсотки — це <em>частки</em> місць, порівнянні між цими знаменниками. Симуляція використовує карту 2019 року як початкову точку, бо алгоритму ReCom потрібна юридично ухвалена карта для пропозиції обмінів — карта 2019 року є останньою ухваленою виборчою картою Альберти. Використання будь-якої з пропозицій комісії як субстрату було б замкнутим колом: ми б вимірювали, чи екстремальна карта порівняно з картами, похідними від неї самої.`,pattern_intro:`Результати — розміщення трьох реальних карт у цьому розподілі — вказують на конкретний хірургічний шаблон малювання меж.`,sub1_h:`Усі чотири статистичні міри спрацьовують одночасно`,sub1_p:`Коли використовуються офіційні шейпфайли Elections Alberta, карта меншості є статистичним виключенням за кожною метрикою партійної справедливості — не лише за критичною точкою.`,t2_col_a:`Карта`,t2_col_b:`Розрив ефективності`,t2_col_c:`Середнє-медіана`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Деклінація вимірює кутову різницю між кривою місця-голоси для кожної партії. Від'ємні значення на користь UCP; додатні на користь NDP.">Деклінація</a>`,t2_col_e:`Місця при 50/50`,t2_r1_a:`Більшість 2026`,t2_r1_b:`+0,04% (p15.5)`,t2_r1_c:`−3,6% (p2)`,t2_r1_d:`+0,027 (p81)`,t2_r1_e:`46,1% (p83)`,t2_r2_a:`Меншість 2026`,t2_r2_b:`<strong>+3,96% (p94.4)</strong>`,t2_r2_c:`<strong>+1,0% (p99.98)</strong>`,t2_r2_d:`<strong>−0,077 (p1.2)</strong>`,t2_r2_e:`<strong>51,7% (p99.99)</strong>`,sub1_close:`Карта більшості зручно сидить усередині нормального діапазону за трьома з чотирьох метрик. Її середнє-медіана сидить на p2 у напрямку, сприятливому для NDP — незвичайний результат, але вказує не в той бік, щоб допомогти UCP. Тісне дотримання картою більшості муніципальних меж розміщує переважно NDP міські ядра у власні компактні округи, де голоси NDP виграють з ефективним відривом, тоді як сільські перемоги UCP схильні до більших відривів; ця м'яка структурна перевага NDP за ефективністю — це те, що з'являється у мірі середнє-медіана. Карта меншості — у хвості за всіма чотирма, кожен з яких вказує в один і той самий партійний напрямок.`,sub2_h:`Точка перелому 50/50: менш ніж 100 із 1 010 000 нейтральних карт її досягають`,sub2_p:`Метрика точки перелому, представлена вище — місця UCP при провінційному голосуванні 50/50 — є найінтуїтивнішим способом порівняти три карти.`,t3_col_a:`Карта`,t3_col_b:`Місця UCP при голосуванні 50/50`,t3_col_c:`Де вона сидить`,t3_r1_a:`2019, ухвалена`,t3_r1_b:`46,0%`,t3_r1_c:`83-й процентиль — усередині нормального діапазону`,t3_r2_a:`<strong>Більшість 2026</strong>`,t3_r2_b:`<strong>46,1%</strong>`,t3_r2_c:`<strong>83-й процентиль — добре в межах</strong>`,t3_r3_a:`<strong>Меншість 2026</strong>`,t3_r3_b:`<strong>51,7% (46 місць)</strong>`,t3_r3_c:`<strong>99,99-й процентиль — менш ніж 100 із 1 010 000 нейтральних жеребкувань досягають цього</strong>`,sub2_close:`Менш ніж 100 із 1 010 000 комп'ютерно змодельованих нейтральних карт Альберти дали значення <code>seats@50/50</code> таке ж високе, як у пропозиції меншості. На основі фактичних останніх моделей голосування воно передало б UCP 60 місць (порівняно з 55 у пропозиції більшості). Пропозиція більшості — це той тип карти, який нейтральна процедура зазвичай генерує. Пропозиція меншості — це той тип карти, який потрібно цілеспрямовано прицілитися намалювати.`,sub3_h:`Що це означає простою мовою`,sub3_p:`Офіційні шейпфайли виявляють карту, статистично екстремальну в одному й тому самому партійному напрямку за всіма чотирма мірами одночасно. Спільна ймовірність того, що нейтральний процес малювання дасть карту, настільки екстремальну за всіма чотирма мірами одночасно, становить приблизно один на 15 мільйонів (p&nbsp;=&nbsp;6,87×10<sup>−8</sup>, <a href="https://osf.io/6pt83" rel="noopener">попередньо зареєстрований об'єднаний тест Фішера</a>). Це не похибка округлення й не вимірювальний артефакт — це та сама відповідь від чотирьох незалежних статистичних інструментів, зчитаних в одній кімнаті.`,details_summary:`Що означає це p-значення — і чого воно не означає`,details_p1:`P-значення відповідає на одне питання: якби карту намалював нейтральний процес, як часто ми бачили б настільки екстремальний результат або більш екстремальний? При p&nbsp;=&nbsp;6,87×10<sup>−8</sup> відповідь — приблизно один раз на 14,5 мільйона спроб.`,details_p2:`Це частотний тест гіпотез, а не вимір наміру. Він не каже, що комісія мала намір зробити джеррімендеринг, і не кількісно оцінює, наскільки карта несправедлива на практиці. Він каже, що шаблон меж статистично несумісний з нейтральним процесом малювання — той самий висновок, до якого дійшов би рандомізований аудит незалежно від того, хто й чому намалював карту.`,details_p3:`Тест був попередньо зареєстрований до аналізу даних (<a href="https://osf.io/w2s8k" rel="noopener">реєстрація OSF w2s8k</a>). Попередня реєстрація заздалегідь визначає нульову гіпотезу, метрики й поріг відхилення, тож результат не можна приписати вибору сприятливого формулювання після перегляду чисел.`,szat_label:`ТЕСТ РОЗПОДІЛУ ЗОНИ КОЛИВАНЬ (SZAT)`,szat_body:`SZAT — другий незалежний тест аудиту, і він ставить інше питання, ніж симуляція: не «чи екстремальна ця карта загалом?», а «чи є конкретні рішення щодо ліній партійно-нейтральними?». Він працює, ізолюючи лише ті виборчі зони, де карта меншості відрізняється від карти більшості — спірні переробки — і перевіряючи, чи зміщують ці конкретні рішення, взяті разом, ефективність голосування на користь однієї партії. Оскільки він порівнює лише точки розходження, він автоматично контролює все, що дві карти поділяють: ту саму географію, цілі населення й статутні правила. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Технічні деталі та результати бутстрапу →</a>`,two_q:`<strong>Два питання, одна відповідь.</strong> Симуляція 1 010 000 карт запитує: <em>чи екстремальна ця карта порівняно з нейтральними картами, намальованими на тій самій географії Альберти?</em> Другий, окремий тест — <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Тест розподілу зони коливань</a> — запитує інше: <em>чи є конкретні лінії на карті партійно-нейтральними?</em> Він працює, дивлячись лише на виборчі зони, де меншість намалювала інакше, ніж більшість, і запитуючи, чи зміщують ці конкретні рішення, взяті разом, ефективність голосування на користь однієї партії. Оскільки він порівнює лише місця, де дві карти відрізняються, він автоматично контролює все, що вони поділяють — ту саму провінційну географію, ті самі цілі населення, ті самі статутні правила. Обидва питання дають ту саму відповідь. Ось чому показник один на 15 мільйонів — це об'єднаний результат, а не один тест: це два незалежні рядки доказів, які сходяться.`,super_lead:`Це пояснює, чому пропозиція меншості мала бути таким екстремальним статистичним виключенням (p99.99) проти 1 010 000 нейтральних симуляцій. У 89-місному законодавчому органі надбільшість у дві третини вимагає рівно 60 місць. Нейтральні процедури не дають результатів у 60 місць на географії Альберти при нейтральних голосах; досягнення цього порогу вимагає навмисних рішень щодо меж, що відходять від нейтральної базової лінії.`,super_label:`ЧОМУ НАДБІЛЬШІСТЬ МАЄ ЗНАЧЕННЯ`,super_body:`У межах Вестмінстерської парламентської системи Канади простої більшості (45 місць) достатньо для ухвалення повсякденних законів і бюджетів. Надбільшість у дві третини (60 місць) робить більше. Вона дозволяє правлячій партії застосувати «закриття дебатів», щоб зупинити обговорення, переписати процедурні правила без згоди опозиції й контролювати склад кожного законодавчого комітету. Вона також ізолює уряд від внутрішніх розбіжностей: навіть якщо півдесятка задньолавочників перейдуть на інший бік, уряд усе ще тримає робочу більшість. Проста більшість дозволяє керувати машиною; надбільшість у 60 місць дозволяє переписати правила дорожнього руху.`,super_close:`Стратегічно розбавляючи міських виборців у сусідні округи з сільським краєм («шаблон міської гібридизації», виявлений у Смузі 2), пропозиція меншості конструює саме той структурний брандмауер, потрібний для забезпечення цих 60 місць. Структурний висновок Смуги 2 і статистичний висновок Смуги 1 сходяться на тій самій пропозиції, тому самому напрямку й тих самих громадах.`,sub4_h:`Підтвердження від тесту цільової процедури`,sub4_p:`Щоб бути впевненим, що це не примха відомої переваги компактності нейтральної симуляції, аудит провів цільову процедуру сходження на пагорб (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et al. 2022 — цитовано й описано в технічному звіті</a>) в обох напрямках: максимізуючи місця UCP і максимізуючи місця NDP. Та сама кількість кроків (40 000) у кожному напрямку, ті самі статутні обмеження, та сама провінційна геометрія.`,t4_col_a:`Процедура`,t4_col_b:`Найекстремальніше досягнуте значення`,t4_col_c:`Що це нам говорить`,t4_r1_a:`Нейтральна MCMC, виданий максимум`,t4_r1_b:`нижче 51,7% місць UCP @ 50/50`,t4_r1_c:`Природна стеля за нейтрального малювання`,t4_r2_a:`Нейтральна MCMC, виданий мінімум`,t4_r2_b:`~39% місць UCP @ 50/50`,t4_r2_c:`Природна підлога за нейтрального малювання`,t4_r3_a:`Цільове сходження, максимізація UCP`,t4_r3_b:`<strong>52,9%</strong>`,t4_r3_c:`Чого може досягти процедура, що навмисно прагне переваги UCP`,t4_r4_a:`Цільове сходження, максимізація NDP`,t4_r4_b:`<strong>37,9%</strong>`,t4_r4_c:`Чого може досягти процедура, що навмисно прагне переваги NDP (нижче нейтральної підлоги)`,sub4_close:`51,7% карти меншості сидять ближче до цільової стелі UCP (52,9%), ніж до нейтральної медіани (44,8%). 46,1% карти більшості сидять на нейтральній медіані. І карта 2019 року, ухвалена, і більшість 2026 року зручно потрапляють у те, що нейтральна процедура зазвичай продукує — різні частки голосів, та сама зона нічим не примітних результатів. Більшість продовжує практику Альберти 2019 року на осі партійної справедливості так само, як вона продовжує практику 2019 року щодо муніципальної прив'язки (80,0% проти 75,2% у 2019 році). Дві карти, намальовані за тими самими правилами Альберти, тими самими п'ятьма комісарами, в тій самій кімнаті: одна приземляється там, де нейтральні процедури зазвичай продукують, інша приземляється там, де треба спеціально прицілитися, щоб приземлитися.`,sub4_quote:`<em>Це</em> — форма висновку, і це також формулювання, яке суд би справді застосував.`,sub5_h:`Виключення альтернативних пояснень`,sub5_p:`При статистичному виключенні такої величини суворий аудит повинен виключити невинні пояснення, перш ніж приписувати ці шаблони навмисному задуму. Структурні дані (Смуга 2) системно демонтують стандартні альтернативні захисти:`,defense1:`<strong>Захист «природної політичної географії»:</strong> <em>(«Міські виборці природно запаковані; карта просто відображає географію Альберти.»)</em> 1 010 000 симуляцій вже враховують природну географію Альберти. Симуляція доводить: хоча географія дає UCP базову перевагу за ефективністю, вона природно обмежується приблизно на 83–90-му процентилі. Карта меншості сидить на 99,99-му процентилі — екстремальне виключення <em>навіть у порівнянні з природно скошеною базовою лінією Альберти</em>.`,defense2:`<strong>Захист «громад інтересів»:</strong> <em>(«Дивні форми були намальовані, щоб тримати конкретні громади разом.»)</em> Якщо Ви намагаєтесь тримати громади разом, Ви слідуєте муніципальним межам. Карта більшості слідувала наявним міським межам 80% часу. Карта меншості слідувала їм 72% часу — обидві в межах канадської норми 70–85%. Що карта меншості справді робить — активно розколює об'єднане місто Airdrie на чотири окремі частини й розміщує три зі своїх рішень щодо меж саме у зонах міського краю, які голова комісії позначив як геометрично аномальні — вибір, не пояснюваний логікою громад інтересів.`,defense3:`<strong>Захист «рівності населення»:</strong> <em>(«Їм довелося малювати дивні межі, щоб кожен округ мав точно однакову кількість населення.»)</em> Карта меншості насправді набагато <em>гірша</em> щодо рівності населення. Її середнє абсолютне відхилення (MAD) становило 4707 — на 48% ширше, ніж 3180 у карти більшості — розміщуючи її на 99-му процентилі канонічного ансамблю (лише 1 із 100 нейтральних карт продукує гірший розкид). Вона пожертвувала рівністю населення, щоб досягти своєї форми.`,defense4:`<strong>Захист «некомпетентності або поганої удачі»:</strong> <em>(«Вони просто намалювали неохайну карту й їм не пощастило з числами.»)</em> Потрапляння рівно у 60 місць для надбільшості, водночас розколюючи Airdrie на чотири частини й розміщуючи три межі точно у тих зонах, які власний голова комісії позначив як аномальні, вимагає хірургічної точності. Спільна ймовірність випадково намалювати карту, що потрапляє в екстремальний статистичний хвіст за чотирма незалежними партійними метриками одночасно, становить приблизно <strong>1 на 15 мільйонів</strong> (p&nbsp;=&nbsp;6,87×10<sup>−8</sup>). Не можна випадково спіткнутися на 99,99-й процентиль.`,sub5_close:`Що показують дані — це що пропозиція меншості погіршила і паритет населення, і когерентність громад порівняно з тим, що ті самі п'ять комісарів продукували одночасно за ідентичних статутних правил. Аудит не визначає, що мали на меті комісари меншості — геометрія меж не може розкрити намір — але структурне відхилення і від нейтрального ансамблю, і від результату пропозиції більшості зберігається незалежно від наміру.`,sub6_h:`Примітка про R-крос-валідацію`,sub6_p1:`Більш рання версія цього аудиту (з використанням наближених, а не офіційних шейпфайлів) крос-валідувала ансамбль Python ReCom проти семплера послідовного Монте-Карло пакета R <code>redist</code>. Перехресна перевірка дала нестабільні результати: за три запуски з тим самим номінальним зерном частка планів, які досягали старого значення меншості (48,3% на наближеній геометрії), становила 5,6%, потім 28%, потім 58% — невдача збіжності семплера, а не відкриття. Повне описання — на <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`З офіційними шейпфайлами Elections Alberta <code>seats@50/50</code> карти меншості зростає до 51,7% — значення, якого досягають менш ніж 100 із 1 010 000 нейтральних планів. Питання R-крос-валідації стає неактуальним: жоден план з жодного семплера не досягає канонічного значення при порівнянних розмірах вибірки.`,sub6_asymm:`<strong>Асиметрія навколо 50/50 промовистіша за саму інверсію.</strong> Прецизійне сканування кривої місця-голоси з роздільністю 0,01 процентного пункту показує, що карта меншості тримає UCP на рівні або вище порогу законодавчої більшості у 45 місць аж до провінційної частки голосів UCP приблизно <strong>49,7%</strong>. Це технічно інверсія голосів-місць — UCP сформувало б уряд за картою меншості, програючи популярне голосування на 0,3 процентного пункту — але 0,3 пункту цілком у межах звичайного шуму опитувань, тож саме собою це не драматичний висновок. Що <em>є</em> драматичним — це контраст: за картою <strong>більшості</strong> UCP мала б <em>виграти</em> популярне голосування приблизно на 4 процентних пункти, щоб досягти того самого порогу у 45 місць. Обидві карти стикаються з тією самою географією Альберти й тими самими статутними правилами; розрив між ними — 0,3 пп проти +4 пп — є структурною різницею, а не шумом.`,sub6_close:`Це висновок про структурне зміщення, який аудит тримає з упевненістю. Він лише про геометрію; він не залежить від жодного результату виборів; він не зміщується, коли зміщуються опитування.`,sub6_caveat:`<strong>Одне застереження, до якого аудит ставиться серйозно.</strong> Реальний електорат не є рівномірно 50/50. Виборці можуть переважити структурний нахил будь-якої карти достатнім коливанням — особливо обурений або натхненний електорат перекине результат незалежно від того, як намальовані межі. Тест 50/50 ізолює <em>внесок карти в результат</em>, а не сам результат. Він показує, що робить карта, коли електорат не вирішує за неї.`,sub7_h:`Підсумок`,sub7_p1:`Центральний висновок аудиту геометричний. <strong>Смуга 2 — структурна шкала нерегулярностей — є фундаментом; Смуга 1 — доказ того, що геометрія виконує партійну роботу.</strong>`,sub7_p2:`Графік нижче розміщує обидві смуги на одному зображенні. Горизонтальна вісь — Смуга 1 (розрив ефективності партійної справедливості, де далі вправо означає більше на користь UCP); вертикальна вісь — Смуга 2 (кількість тестів структурної справедливості, які пропозиція провалює, з п'яти, де вище означає більше структурних проблем).`,stakes_fig_alt:`Діаграма розсіювання з розривом ефективності на горизонтальній осі й кількістю провалених структурних тестів на вертикальній. Ухвалена карта 2019 року й карта більшості 2026 року групуються в безпечному нижньому лівому куті. Карта меншості 2026 року з'являється у верхній правій зоні виключень.`,stakes_fig_caption:`Два способи виміру двох пропозицій комісії, нанесені разом. Зліва направо: наскільки скошено виглядає пропозиція за числом партійної справедливості — чим далі вправо, тим більше вона на користь UCP. Знизу догори: скільки з п'яти тестів структурної справедливості провалює пропозиція — чим вище, тим гірше. Ухвалена карта 2019 року сидить у безпечному куті: низько за обома. Пропозиція більшості 2026 року тримається на нулі структурних проблем і майже на нулі партійного скосу (+0,1%). Пропозиція меншості 2026 року — структурне виключення на кожному тесті, що розрізняє дві карти (4 з 5; п'ятий, прив'язка, нейтральний для обох); її розрив ефективності (+4,0%) сидить трохи нижче порогової лінії Альберти.`,stakes_table_intro:`Ті самі висновки у вигляді простого підсумку, починаючи зі структурного висновку, бо перехресно валідовані докази підтримують його найсильніше:`,t5_col_b:`Смуга 2: Структура (лише геометрія, без голосів)`,t5_col_c:`Смуга 1: Числа (залежать від голосів)`,t5_r1_a:`<strong>Більшість 2026</strong>`,t5_r1_b:`чиста — перетинає <em>жоден</em> структурний поріг`,t5_r1_c:`усередині нормального діапазону за кожною метрикою (<code>seats@50/50</code> 46,1% — p83; розрив ефективності +0,04%)`,t5_r2_a:`<strong>Меншість 2026</strong>`,t5_r2_b:`<strong>перетинає 4 з 5 структурних порогів</strong> з великим відривом (прив'язка нейтральна — обидві карти в межах канадської норми)`,t5_r2_c:`статистичне виключення за всіма чотирма мірами партійної справедливості одночасно — <code>seats@50/50</code> 51,7% (p99.99, менш ніж 100 із 1 010 000 досягають цього); розрив ефективності +3,96% (p94.4); усі чотири попередньо зареєстровані; об'єднаний тест Фішера p&nbsp;=&nbsp;6,87×10<sup>−8</sup>`,details2_summary:`Чому Смуга 2 несе аргументацію — технічна деталь`,details2_p:`Аудит попередньо зареєстрував п'ять тестів структурної нерегулярності 24 квітня 2026 року до того, як було скомпільовано остаточні результати симуляції. Прив'язка нейтральна для обох карт; за рештою чотирьох тестів меншість перетинає кожен, а більшість не перетинає жоден. Ці виміри геометричні — вони не залежать від жодного статистичного семплера або жодної атрибуції голосів. Смуга 1 (числа партійної справедливості) сильно підтверджує Смугу 2 за канонічними офіційними шейпфайлами: меншість є статистичним виключенням за всіма чотирма попередньо зареєстрованими метриками одночасно, зі спільною нейтрально-нульовою ймовірністю p&nbsp;=&nbsp;6,87×10<sup>−8</sup> (попередньо зареєстрований об'єднаний тест Фішера — метод, що поєднує чотири результати незалежних тестів в одну ймовірність шляхом множення їхніх індивідуальних хвостових ймовірностей; об'єднана цифра значно менша за будь-яку окрему, бо всі чотири вказують в одному напрямку; OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>). Питання, чи є незвичайна геометрія Смуги 2 конкретним <em>механізмом</em>, що стоїть за числами Смуги 1, було перевірено, і відповідь — ні — див. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>. Тест розподілу зони коливань показує, що спірні рішення щодо меж партійно скошені, але перевіряне питання полягало в тому, чи є самі форми меж — коридор-ласо, продовження парку — прямою причиною зміщення місць; вони не є. Ефект на місця походить від того, як перерозподілені призначення виборчих зон зміщують ефективність голосування між округами, а не від форм самих по собі. Обидві смуги сигналізують про карту меншості; вони доходять до неї через незалежні інструменти. Смуга 2 — це центральний висновок. Смуга 1 підтверджує, не несучи.`},impact:{heading:`5: Вплив на представництво`,lanes_label:`СМУГА 1 І СМУГА 2`,lanes_body:`<strong>Смуга 1 (числа)</strong> використовує результати виборів, щоб перевірити, чи карта справедливо перетворює голоси на місця — вона запитує, як працює карта за різних розподілів голосів. <strong>Смуга 2 (структура)</strong> досліджує лише намальовані лінії — поділи міст, розкид населення, форми меж — без жодних виборчих даних. Кожна смуга незалежна: карта може провалити одну, пройшовши іншу. Пропозиція меншості провалює обидві; пропозиція більшості проходить обидві.`,intro:`Смуга 1 залежить від того, проти яких результатів виборів Ви оцінюєте карти. Смуга 2 не залежить. Структурні докази знаходяться в самих картах — намальовані лінії, розколоті міста, де межі слідують і не слідують адміністративним лініям, що існують з інших причин. За цими тестами дві карти не близькі.`,fig_alt:`Стовпчикова діаграма, що порівнює п'ять тестів структурної справедливості пліч-о-пліч. Стовпчики карти більшості сидять на нулі або глибоко в безпечних діапазонах. Стовпчики карти меншості перетинають поріг за чотирма з п'яти тестів з великим відривом; п'ятий (прив'язка) є нейтральним для обох карт.`,fig_caption:`П'ять тестів структурної справедливості, пліч-о-пліч. Бірюзові стовпчики — карта більшості; фіолетові стовпчики — карта меншості. Пунктирна лінія в кожному рядку позначає поріг провалу. Стовпчики меншості перетинають поріг за чотирма з п'яти тестів з великим відривом; п'ятий (прив'язка) є нейтральним для обох карт. Стовпчики більшості сидять рівно на нулі або глибоко в безпечному діапазоні.`,table_intro:`Ті самі п'ять тестів у табличній формі, з порогом кожного тесту, вказаним поруч із результатом. Нижній рядок — це <em>підсумок</em> аудиту — кількість тестів, які провалює кожна карта, з п'яти.`,table_col_test:`Тест`,table_col_majority:`Карта більшості`,table_col_minority:`Карта меншості`,table_col_direction:`Напрямок / Бенефіціар`,table_r1_a:`Межа слідує наявним муніципальним лініям (канадська норма 70–85%)`,table_r1_b:`80% — у межах норми`,table_r1_c:`72% — у межах норми`,table_r1_d:`Н/Д — обидві в межах канадської норми`,table_r2_a:`Розкид населення (тісніше — краще)`,table_r2_b:`3180`,table_r2_c:`4707 — на 48% ширше`,table_r2_d:`Структурний (Зменшує рівність голосів)`,table_r3_a:`Надлишок населення в NW Калгарі над середнім`,table_r3_b:`2,8%`,table_r3_c:`11,5%`,table_r3_d:`<strong>UCP</strong> (Пакує міські голоси NDP)`,table_r4_a:`Межі, позначені власним головою комісії`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`Н/Д`,table_r5_a:`Поділ Airdrie (мінімум за обмеженням: 2)`,table_r5_b:`2 частини`,table_r5_c:`4 частини`,table_r5_d:`<strong>UCP</strong> (Розщеплює міську/приміську силу)`,table_r6_a:`<strong>Попередньо зареєстрований підсумок</strong> (&ge; 4 з 5 = виключення)`,table_r6_b:`<strong>спрацювало 0 з 5</strong>`,table_r6_c:`<strong>спрацювало 4 з 5</strong> (тест прив'язки нейтральний — обидві карти в межах канадської норми; решта 4 тести всі спрацьовують)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`Окремий висновок, застосований лише до меншості: <strong>п'ять із шести опублікованих обґрунтувань комісарів меншості не витримують незалежної перевірки</strong>. Тест запускається лише проти меншості, бо більшість не опублікувала перелік обґрунтувань спірних переробок — аудит не може застосувати його симетрично, і він тут поданий як один прапорець, а не як додаткові рядки у підрахунку структурних нерегулярностей. (Сьому переробку, яку аудит раніше перелічував, виявилося, спиралася на твердження про федеральну межу, яке не вдалося відстежити у звіті меншості; її видалено, а не залишено як слабке твердження.)`,chair_appendix_p:`Аудит також перевірив окреме, загальне твердження голови у Додатку C, що сім спірних гібридних конфігурацій меншості мали <strong>нульову громадську підтримку</strong> у понад 1140 публічних заявах. Пошук за ключовими словами по всьому архіву заяв (94% машинно опрацьовано, 6% лише зображення й виключено; методологія й докази по конфігураціях на <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) повернув більш нюансовану картину, ніж загальне твердження голови чи його загальне відкидання: голова мав рацію щодо трьох із семи (поділ Airdrie на 4 частини, гібрид Calgary–Nolan-Hill–Cochrane й альтернатива меншості Сент-Альберта — кожен бракує задокументованої підтримки), помилявся щодо трьох із семи (Rocky Mountain House–Banff Park привернув явну, детальну пропозицію принаймні від однієї заяви з району Clearwater плюс кількох суміжних; Olds–Three-Hills–Didsbury був підтриманий мешканцями Beiseker письмово; Chestermere привернув кілька заяв проти злиття з Калгарі, які матеріально відповідають намірам меншості), і частково помилявся щодо одного (гібриди Red Deer привернули гібридну пропозицію навколо Red Deer від чинного радника Red Deer, з напрямним, але не точним за конфігурацією узгодженням). Таким чином, загальне твердження голови у Додатку C про «відсутність громадської підтримки» демонстративно надмірне — три з семи демонстративно хибні — але воно не вигадане з нічого, бо три з семи витримують. <strong>Цей висновок працює проти голови, а не проти меншості.</strong>`,summary_p:`<strong>За Смугою 2 більшість перетинає нуль структурних порогів. Меншість перетинає кожен із них з великим відривом.</strong>`},cpd:{heading:`4: Розщеплення, пакування та виснаження`,vocab_label:`Три рухи, один сценарій`,vocab_packing:`<strong>Пакування</strong> означає набивання виборців однієї партії у округи, які партія виграє з оглушливою перевагою — кожен запакований бюлетень досі рахується, але він нічого не дає поза перемогою. Великі односторонні перемоги. Змарновані голоси.`,vocab_cracking:`<strong>Розщеплення</strong> означає поділ громади між кількома округами так, щоб вона не вигравала жоден з них прямо. Місто, достатньо сильне, щоб взяти два місця, розрізають на чотири, кожне прив'язане до іншого сільського району. Розбавлені голоси. Жодного місця для нікого.`,vocab_draining:`<strong>Виснаження</strong> — просторовий компаньйон: запаковані й розщеплені округи розміщені поруч так, що надмірно сконцентровані прихильники з одного боку «виснажують» виборчу силу від спірних округів поруч. Шаблон сусідства підсилює обидва ефекти — пакування й розщеплення взаємно підкріплюють один одного через лінії округу.`,vocab_disclaimer:`Усі три можуть відбуватися без будь-якого явного партійного наміру. Що аудит вимірює — це чи відповідає шаблон — і його статистична величина — тому, що продукує нейтральний процес малювання карти. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Повна методологія в §5 технічного звіту.</a>`,fig_alt:`Карта, що показує поділ Airdrie на чотири окремі округи за картою меншості`,fig_caption:`Поділ Airdrie на чотири окремі округи за картою меншості, розбавляючи його міську виборчу силу.`,intro:`П'ятеро комісарів працювали за тими самими статутними правилами, тією самою провінційною географією, тим самим архівом з 1140 публічних заяв і тими самими демографічними даними. Їхні дві конкуруючі чернетки погоджуються щодо більшої частини Альберти. Там, де чернетки розходяться, вони розходяться у виборах, які хтось у кімнаті мусив зробити. Три з цих виборів варто бачити як вибори, а не як числа.`,airdrie_p:`<strong>Вона поділяє місто Airdrie на чотири частини.</strong> Закон обмежує кожен виборчий поділ півтора середнього провінційного, тож Airdrie потребує щонайменше двох поділів. Карта більшості дає йому два. Меншість дає чотири — на північ до Calgary-Nolan Hill-Cochrane, на схід до Airdrie East, на захід до Calgary-Foothills-Airdrie West і центральний південь до Calgary-Airdrie — кожен пришпилений до іншого сільського або приміського округу Калгарі. Мешканка Airdrie з питанням до свого MLA мусить знати, у якому кварталі міста вона живе, перш ніж зможе зателефонувати до правильного офісу. Її сусіди за два квартали далі дадуть їй три різні відповіді. PTA школи її дитини не може надіслати єдину делегацію до одного MLA з питання шкільного фінансування; вони мусять координувати чотири делегації до чотирьох офісів, кожен MLA в першу чергу підзвітний іншому сільському або приміському виборчому округу. Асоціація молодшого хокею, продовольчий банк, торгова палата — кожна організація, що працює в межах міста, тепер працює у чотирьох провінційних округах.`,airdrie_callout_label:`ЧОМУ AIRDRIE ВАЖЛИВИЙ`,airdrie_callout_p1:`Airdrie — найбільше місто Альберти без власного MLA. З 85 805 людьми (муніципальний перепис 2024 року) він більший за Red Deer; має одну раду, один податковий рахунок, один шкільний округ — кожна громадянська система ставиться до нього як до одиниці.`,airdrie_callout_p2:`Розкол його між чотирма провінційними поділами — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Calgary-Nolan Hill-Cochrane і Airdrie East — кожен переважно ідентифікований з іншою навколишньою юрисдикцією, видаляє Airdrie з політичної карти на тому рівні влади, який її малює. У місті 85 805 мешканців і нуль місць у законодавчих зборах, де більшість виборців називає це місце домом.`,airdrie_callout_p3:`Поділ на чотири шляхи невидимий для кожного тесту партійної справедливості, окрім того, що запитує: чи може виборець знайти свого MLA?`,airdrie_callout_summary:`Обидві карти легальні. Поділ на чотири шляхи — це вибір.`,airdrie_btn:`Показати позначені округи на карті`,anchoring_p:`<strong>Там, де вона відходить від муніципальних ліній, вона відходить у стратегічно важливих місцях.</strong> Коли виборчі карти слідують краю міста чи містечка, виборці впізнають, де починається й закінчується їхній поділ — лінія податку на нерухомість, лінія шкільного округу, лінія міської виборчої дільниці й лінія провінційних виборів — усі збігаються. Statistics Canada публікує ці межі безкоштовно. На офіційних шейпфайлах Elections Alberta обидві карти слідують муніципальним лініям з порівняними загальними показниками: більшість на 80%, меншість на 72%, обидві в межах канадської норми 70–85% (Квебек: 78%, Онтаріо: 82%, BC: 71%; порівняльні комісії задокументовані в монографії). (Початковий попередній аналіз аудиту показав прив'язку меншості лише на 15%; ця цифра не пережила перерахунок на офіційних шейпфайлах — див. примітку про виправлення нижче.) Вражаюче спостереження — не загальний показник, а те, де сконцентровані відходи меншості: три межі, які власний голова комісії позначив як аномальні — продовження Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">показати ↗</button> в незаселену землю національного парку, корідор-ласо Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">показати ↗</button> й простягання Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">показати ↗</button> — кожна з них є відходом від наявної громадянської географії саме у тих зонах міського краю, де поєднання міських і сільських виборців найбезпосередніше впливає на те, яка партія виграє місце.`,anchoring_followup:`Комісари меншості дали підстави для кожної з трьох позначених меж. Для Rocky Mountain House–Banff Park вони послалися на географічний розмір, коридор шосе 22 й близькість резервацій корінних народів до Rocky Mountain House; голова комісії назвав продовження в незаселену землю національного парку «зусиллям недобросовісним», щоб задовольнити критерій площі, і ця фраза з'являється в офіційному остаточному звіті комісії. Для Nolan Hill–Cochrane вони послалися на спільні транспортні й трудові зв'язки між північно-західним Калгарі й Cochrane; дані Statistics Canada про пересування на роботу показують, що лише 35,8% працівників Cochrane взагалі їздять до Калгарі, причому більшість працюють у самому Cochrane. Для простягання Olds–North Airdrie вони послалися на безперервність коридору шосе 2; аудит виявив, що конкретне продовження Airdrie провалюється на підставі населення. Незалежна перевірка виявила, що п'ять з шести опублікованих субобґрунтувань меншості не витримують або витримують лише частково проти первинних даних.`,packing_p:`<strong>Одну ділянку Калгарі розрізано, щоб зосередити виборців NDP у поділах, більших за середній.</strong> У північно-західному квадранті Калгарі <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">показати ↗</button> поділи карти меншості в середньому на 11,5% перевищують провінційне населення — проти 2,8% на карті більшості. Та сама географічна зона, намальована тією самою комісією за тими самими обмеженнями, дає округи на чверть більші на одній карті, ніж на іншій. Це відповідає структурному підпису <em>пакування</em>: концентрації виборців однієї партії у меншу кількість більших округів так, щоб кожен їхній бюлетень важив менше. Пакування і <em>розщеплення</em> (тонке розпорошення виборців партії між округами, які вони ледь програють) — два класичні рухи джеррімендерингу; обидва зменшують підрахунок місць партії нижче її частки голосів.`,chair_p:`Голова комісії — призначений за тим самим Законом, працюючи за тими самими заявами — позначив три межі на карті меншості як географічно аномальні: продовження Rocky Mountain House–Banff Park у незаселену землю національного парку; корідор лассо-подібний Calgary-Nolan Hill–Cochrane; простягання Olds–Three Hills–Didsbury у північний Airdrie. Більшість отримала нуль таких позначок від того самого голови. (Опублікована критика голови охоплює загалом сім конфігурацій меж — чотири геометричні позначки в основному звіті й три в Додатку C. Цей аудит незалежно підтвердив аномальну геометрію для трьох з чотирьох геометричних позначок; четверта, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">показати ↗</button>, не досягла порогу підтвердження аудиту.)`},litmus:{heading:`3: Лакмусовий тест 1 010 000 карт`,fig_alt:`Гістограма, що показує розподіл розривів ефективності серед 250 000 нейтральних карт Альберти. Більшість карт групуються поблизу нуля. Карта меншості (фіолетова лінія) сидить на 94-му процентилі (+3,96%) у заштрихованому правому хвості. Карта більшості (бірюзова лінія) сидить на +0,04%, цілком у нормальному діапазоні.`,fig_caption:`Розподіл <button class="vocab-term" data-def="міра того, наскільки нерівно голоси перетворюються на місця — додатні значення на користь UCP, від'ємні значення на користь NDP" aria-expanded="false">розривів ефективності</button> серед 250 000 нейтральних карт Альберти, намальованих з тієї самої географії. Більшість нейтральних карт групуються поблизу нуля; заштрихований правий хвіст позначає верхні 10%. +3,96% пропозиції меншості сидить на 94-му <button class="vocab-term" data-def="відсоток карт, що отримали нижчий бал — p94 означає, що 94 з 100 нейтральних карт були менш партійними, ніж ця" aria-expanded="false">процентилі</button> — у регіоні, якого досягає менше 6 зі 100 нейтральних карт. +0,04% пропозиції більшості нерозрізнимий від того, що зазвичай продукує нейтральний процес.`,table_intro:`Таблиця порівнює дві карти. Перші п'ять рядків не використовують жодних результатів виборів — це властивості самих ліній. Останні два залежать від того, як голоси були приписані кожному округу.`,table_col_measured:`Що було виміряно`,table_col_majority:`Карта більшості`,table_col_minority:`Карта меншості`,table_col_direction:`Напрямок / Бенефіціар`,table_r1_a:`Розкид населення між округами (тісніше — краще)`,table_r1_b:`3180`,table_r1_c:`4707 — на 48% ширше`,table_r1_d:`Структурний (Зменшує рівність голосів)`,table_r2_a:`Надлишок населення в NW Калгарі над середнім`,table_r2_b:`2,8%`,table_r2_c:`11,5%`,table_r2_d:`<strong>UCP</strong> (Пакує міські голоси NDP)`,table_r3_a:`Поділ Airdrie`,table_r3_b:`2 поділи`,table_r3_c:`4 поділи`,table_r3_d:`<strong>UCP</strong> (Розщеплює міську/приміську силу)`,table_r4_a:`Межі, що слідують наявним муніципальним лініям`,table_r4_b:`80% — у межах норми`,table_r4_c:`72% — у межах норми`,table_r4_d:`Н/Д — обидві в межах канадської норми (70–85%)`,table_r5_a:`Межі, позначені головою комісії`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`Н/Д`,table_r6_a:`Місця при голосуванні 50/50 (процентиль у симуляції 1 010 000 карт)`,table_r6_b:`46,1% — p83 (нормальний діапазон)`,table_r6_c:`51,7% — p99.99 (менш ніж 100 із 1 010 000 досягають цього)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Розрив ефективності (процентиль у симуляції 1 010 000 карт)`,table_r7_b:`+0,04% — p15.5 (нормальний діапазон)`,table_r7_c:`+3,96% — p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Сусідський шаблон пакування-розщеплення`,table_r8_b:`6 з'єднаних ланцюгових сигналів`,table_r8_c:`2 (попередньо зареєстроване ПРОЙДЕНО)`,table_r8_d:`Нейтрально — меншість досягає партійного ефекту через гібридизацію, а не сусідське виснаження (§5.3.5)`,vocab_label:`СЛОВНИК`,vocab_eg:`<strong>Розрив ефективності.</strong> Єдине число, що вимірює, наскільки нерівно голоси партії перетворюються на місця. Додатні числа на користь UCP; від'ємні на користь NDP. Аудит використовує ~5% як лінію виключення Альберти — значення, що перевищується лише 5% з 1 010 000 нейтральних симуляцій, специфічних для Альберти. Цей поріг не запозичений з літератури США чи загальної; поріг, відкалібрований для іншої юрисдикції, був би неправильним, бо природна географія Альберти продукує інший нейтральний діапазон.`,vocab_mm:`<strong>Різниця середнього-медіани.</strong> Розрив між медіанною часткою голосів партії в окрузі та середньою часткою голосів партії в окрузі. Коли одна партія виграє багато тісних перегонів, медіана сидить вище середнього — ті голоси розподілені ефективно. Коли партія виграє багато перегонів з великим відривом, середнє сидить вище медіани — голоси марнуються. Великий розрив середнього-медіани в одному напрямку сигналізує про структурну неефективність того, як розподілені голоси однієї сторони між округами.`,vocab_percentile:`<strong>Процентильний ранг.</strong> У цьому аудиті «процентиль» — це ранг у межах 1 010 000 нейтральних змодельованих карт. «p94» означає, що 94% нейтральних карт мають нижчий бал — реальна карта екстремальніша за 94% нейтральних жеребкувань. «p99.99» означає, що менш ніж 1 з 10 000 нейтральних карт досягає цього рівня.`,vocab_anchoring:`<strong>Прив'язка.</strong> Частка виборчої межі, що лежить на наявній адміністративній лінії — міській межі, межі шкільного округу, переписній лінії Statistics Canada.`,closing_p1:`Нижні рядки залежать від результатів виборів. Тест <em>seats@50/50</em> утримує електорат у досконалому паритеті (UCP і NDP отримують рівно по половині голосів у провінції) й запитує, скільки місць карта дає UCP. Нейтральна карта Альберти продукує медіану навколо 44,8% місць UCP. Географія Альберти — виборці NDP сконцентровані в міських ядрах, виборці UCP розпорошені по сільських округах — дає NDP невелику перевагу за ефективністю при нейтральності. Карта більшості на 46,1% сидить на 83-му процентилі симуляції 1 010 000 карт, цілком у нормальному діапазоні. Карта меншості на 51,7% сидить на 99,99-му процентилі: менш ніж 100 із 1 010 000 нейтральних жеребкувань досягають цього значення. Число <em>розрив ефективності</em> вимірює, наскільки нерівно голоси кожної партії перетворюються на місця. На офіційних шейпфайлах Elections Alberta розрив ефективності меншості становить +3,96%, розміщуючи її на 94,4-му процентилі — трохи нижче 95-го процентильної лінії виключення аудиту. Початкові питання у верхній частині сторінки розкривають наслідки.`,closing_p2:`Останній рядок — це місце, де у карти меншості менше з'єднаних ланцюгових сигналів, ніж у більшості, за тестом сусідського виснаження: 2 проти 6 у більшості (і 5 у ухваленої карти 2019 року). Аудит попередньо зареєстрував цей тест перед вимірюванням, і нижчий підрахунок меншості — це справжнє попередньо зареєстроване ПРОЙДЕНО — меншість не показує класичного сусідського шаблону пакування-виснаження. Це єдиний тест, де меншість числово переграє більшість. §5.3.5 академічного звіту пояснює чому: меншість досягає свого партійного ефекту через гібридизацію (поділ міст, що інтерналізує пакування й розщеплення в межах окремих ED), що невидимо для тесту сусідського ланцюга, який лише вимірює, як запаковані округи групуються поруч із розщепленими.`},commission_split:{heading:`2: Як розкололася Комісія`,intro:`Комісія з виборчих меж Альберти завершила свою роботу 23 березня 2026 року й не змогла дійти згоди. Троє комісарів створили одну карту; двоє інших створили іншу. Голова комісії суддя Даллас К. Міллер і двоє комісарів, номінованих опозицією, написали звіт більшості; двоє комісарів, номінованих урядом — д-р Джуліан Мартін і Джон Д. Еванс — написали звіт меншості. Розкол зосередився на тому, як малювати межі у швидкозростаючих громадах міського краю. Більшість дала Airdrie два округи; меншість — чотири. Більшість намалювала поділи північно-західного Калгарі близько до провінційного середнього; меншість намалювала їх на 11,5% вище. Обидві карти слідують одному й тому самому статуту. Обидві легальні згідно з <em>Electoral Boundaries Commission Act</em>. Розбіжність була в тому, які конкретні географічні конфігурації найкраще служать громадам, що малюються. Правляча партія Альберти — Об'єднана консервативна партія (UCP); її основна опозиція — Нова демократична партія (NDP). Менші партії — Партія Альберти, Ліберальна партія Альберти та інші — також змагаються за місця, але їхня сукупна провінційна частка голосів була на останніх виборах достатньо низькою, щоб матеріально не впливати на розрахунки партійної справедливості аудиту, які ґрунтуються на розколі UCP–NDP 2023 року. Цей аудит виміряв обидві карти за тими самими методами, застосованими ідентично. Три висновки виділяються.`,finding1:`<strong>Дві карти відрізняються за шістьма речами, які можна виміряти, не дивлячись на жодні результати виборів:</strong> наскільки рівномірно люди розподілені по округах, чи сконцентровані виборці, наскільки погано розрізані міста, чи слідують межі міським лініям, форма округів, і скільки меж голова комісії суддя Міллер сам позначив письмово як аномальні (§5.8.2 звіту більшості й Додаток C). Карта меншості відрізняється від більшості за кожною з них.`,finding2:`<strong>Кожна виміряна різниця рухається в тому самому напрямку.</strong> Усюди, де дві карти розходяться — північно-західне Калгарі, Airdrie, міські райони з чіткими міськими межами — карта меншості малює межі, що розпорошують голоси NDP тонше й дозволяють голосам UCP рахуватися ефективніше. Громади, найбільш переформовані картою меншості, — ті самі громади, де NDP найсильніша. Аудит не може визначити намір. Він може виміряти ефект.`,finding3:`<strong>Процес, що зараз просуває карту меншості, не має прецеденту в Канаді.</strong> Жодна інша провінція не дозволяє кабінету передати перерозподіл комітету, який контролює його власна партія, посеред циклу перерозподілу. Більшість провінцій або вимагає, щоб законодавчі збори спочатку обговорювали карту комісарів, або надає карті комісії автоматичної дії, якщо її не скасують. Альберта не робить ні того, ні іншого. 16 квітня уряд відклав обидві карти комісії й передав роботу комітету MLA, більшість членів якого походять з правлячої Об'єднаної консервативної партії (UCP); повний склад і мандат комітету детально розглянуто в §7. <em>Electoral Boundaries Commission Act</em> Альберти вимагає, щоб законодавчі збори ухвалили окремий Закон про виборчі округи, щоб надати звіту комісії законної сили — сам звіт комісії нічого не змінює. Більшість інших провінцій роблять звіт комісії юридично чинним, якщо законодавчі збори активно не відмінять його; за замовчуванням Альберти все навпаки, що означає, що правляча партія контролює, чи стане якась карта комісії законом. Заявленим виправданням уряду було впровадження Рекомендації 5 голови комісії судді Міллера. Але Міллер написав рекомендацію спеціально, щоб відмовити законодавчі збори приймати карту меншості, і його колеги з більшості її не підтримали. Рекомендація 5 також була географічно конкретною: одне додаткове сільське місце на південь від Едмонтону й одне в окрузі Клірвотер і західному окрузі Маунтін-В'ю — обидва далеко від швидкозростаючих громад міського краю Калгарі й Едмонтону, де комісія насправді розкололася. Це не було запрошенням перепроєктувати ті спірні межі. Уряд прийняв кількість місць, передаючи комітету, який він контролює, владу над саме тими лініями, щодо яких комісія не погоджувалася.`,closing:`<strong>Процес — це власне самостійне відкриття, окреме від карт.</strong>`},november:{heading:`7: Комітет Ланті`,context_label:`КОНТЕКСТ`,context_body:` — Цей розділ описує процес, що замінив комісію, і правову основу, що до нього застосовується. Він не є частиною статистичних висновків. Висновки — у §3–§6 вище.`,intro:`Жодна карта комісії не діє. 16 квітня 2026 року законодавчі збори ухвалили Постанову 19, відклавши обидві й передавши перерозподіл Спеціальному відбірковому комітету з п'яти MLA — три UCP, два NDP — під головуванням Брендона Ланті (UCP, Leduc-Beaumont). Сам комітет не малює карту. Він наглядає за окремою Незалежною дорадчою панеллю, створеною за урядовою Постановою 37 (ухваленою 21 квітня 2026 року), якій доручено створити пропозицію меж на 91 місце. Постанова 37 передбачала п'ять членів панелі — діючий або відставний суддя як голова, два члени, номіновані прем'єр-міністром, і два — лідером опозиції — але виконуючий обов'язки головного судді Альберти відмовився номінувати суддю на посаду голови, і панель тепер працює з чотирма призначенцями, яких підтвердив комітет: достопочесний Монте Солберг і Дарвін Дурні (номінанти прем'єр-міністра) та д-р Джерард Кеннеді й Брент Робінсон (номінанти опозиції). Комітет повинен подати свій звіт законодавчим зборам до 2 листопада 2026 року. На відміну від початкової комісії, ні комітет, ні панель не зобов'язані проводити публічні слухання; панель спирається на заяви, зібрані початковою комісією. Коли карту комітету буде оприлюднено, цей аудит застосує ту саму методологію для її оцінки.`,h_anomalous:`Чому Комітет є аномальним`,anomalous_p1:`Канадська практика перерозподілу з 1960-х років зупинилася на єдиній моделі: незалежна комісія, ізольована від урядового керівництва, продукує рекомендації щодо меж; законодавчі збори можуть їх обговорювати, але не можуть легко відмінити без формального законодавчого голосування. Статутний процес Альберти за <em>Electoral Boundaries Commission Act</em> слідує цьому шаблону — але з однією структурною відмінністю від більшості провінцій: звіт комісії Альберти не має автоматичної юридичної сили. За цим Законом окремий Electoral Districts Act повинен бути ухвалений законодавчими зборами, щоб надати будь-якій карті комісії силу закону. Це означає, що уряд дня контролює не лише те, чи обговорюватиметься карта комісії, а й чи стане вона коли-небудь законом. Інші канадські юрисдикції беруть протилежне за замовчуванням: рекомендації комісії набирають чинності, якщо законодавчі збори не проголосують за їх скасування.`,anomalous_p2:`Те, що уряд зробив у квітні 2026 року, не має зафіксованого прецеденту у пост-Конфедераційному перерозподілі: він дозволив завершеному, опублікованому процесу комісії дійти кінця — обидва звіти більшості й меншості подано — а потім передав завдання перерозподілу п'ятичленному комітету MLA, більшість якого (троє з п'яти) тримає правляча партія, не виносячи жодного зі звітів комісії на голосування. Комітет Ланті — не комісія. Він не має статутної незалежності від законодавчого керівництва уряду. Його трьохчленна більшість UCP віддзеркалює контроль уряду над законодавчими зборами. Жодна інша канадська провінція не передавала повноваження перерозподілу посеред циклу контрольованому урядом законодавчому комітету після того, як незалежна комісія завершила свою роботу.`,h_framework:`Конституційна основа`,framework_p1:`Стаття 3 <em>Хартії прав і свобод</em> — «Кожен громадянин Канади має право голосувати на виборах членів Палати громад або законодавчих зборів» — Верховним судом Канади тлумачиться як гарантія не просто акта подавання бюлетеня, а <em>дієвого представництва</em>. Провідним органом є <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, у якій суддя Маклахлін (тоді як вона була) написала для більшості, що мета статті 3 «це не рівність виборчої сили як такої, а право на дієве представництво». Паритет населення є основним розглядом; відхилення допускаються, коли виправдані громадою інтересів, географією, історією або цілями представництва меншин.`,framework_p2:`Саскачеванська основа не категорично забороняє партійні розгляди в перерозподілі. Що вона встановлює — це що карти меж мають у цілому забезпечувати дієве представництво виборцям — і що системне ослаблення здатності однієї ідентифікованої групи обирати пропорційне представництво — це шаблон, на який спрямовані виклики статті 3. Статистичні й структурні висновки аудиту — положення карти меншості на 99,99-му процентилі 1 010 000 нейтральних жеребкувань, її перетин чотирьох із п'яти структурних порогів (п'ятий, прив'язка, нейтральна для обох карт), визначені постраждалі громади — це доказовий запис, який заявник за статтею 3 мав би зібрати. На стороні громади інтересів цього запису рішення Федерального суду у справі <em>Raîche v. Canada</em> (2004 FC 679) є провідним канадським органом: суд там вимагав від федеральної Комісії з виборчих меж переглянути межі, які ігнорували громаду інтересів акадійців у Нью-Брансвіку. Виміри муніципальної прив'язки аудиту та його конкретні висновки про громади — Airdrie, розрізаний на чотири округи, аномалії міського краю, позначені головою, у північно-західному Калгарі — це той самий тип доказів, які Федеральний суд розглядав як юридично визнані. Чи відповідає цей запис конституційному порогу — правове питання, яке цей аудит не вирішує; аудит звітує про вимір.`,framework_p3:`Законність комітету як процесу — окреме питання. <em>Electoral Boundaries Commission Act</em> Альберти прямо не забороняє законодавчим зборам створювати паралельний орган перерозподілу, бо Закон передбачає, що законодавчі збори в будь-якому випадку ухвалять остаточні межі через звичайне законодавство. Чи зможе процес комітету, якщо він дасть карту зі структурним і статистичним профілем пропозиції меншості, пережити виклик за статтею 3 Хартії, залежить від того, чи досяжне дієве представництво за отриманих меж — той самий тест, що застосовувався б до будь-якої карти, виготовленої комісією.`,h_quebec:`Контраст з Квебеком`,quebec_p1:`Квебек пропонує порівняння, найбільш релевантне до ситуації Альберти. Commission de la représentation électorale Квебеку (CRE) — це постійний, незалежний орган виборчих меж, а не ad hoc комісія, що формується на кожен цикл перерозподілу. CRE працює безперервно й не може бути розпущена або обійдена дією кабінету. Згідно з квебекським <em>Loi électorale</em>, Національні збори мають ухвалити рекомендації CRE, якщо не проголосують за відхилення — а відхилення вимагає більшості у дві третини всіх членів Зборів, не просту законодавчу більшість. Практичний ефект полягає в тому, що правляча партія не може, діючи самостійно своєю власною більшістю, замінити свою улюблену карту на карту комісії. Угода між партіями конституційно потрібна, щоб скасувати рішення незалежного органу.`,quebec_p2:`Модель Квебеку виникла частково з уроків того, що відбувається, коли перерозподіл не ізольований від партійного контролю. Контраст з нинішнім процесом Альберти — де комітет, контрольований більшістю, замінив роботу комісії до того, як законодавчі збори проголосували за будь-який зі звітів комісії — ілюструє структурну різницю між системами перерозподілу, що передбачають партійний тиск і проєктуються проти нього, проти систем, де цей тиск має чіткіший шлях до результату.`,closing:`Аудит застосує ті самі тести до карти комітету Ланті, коли її буде оприлюднено. Конституційні й порівняльні спостереження вище — контекстуальні; методологія не змінюється.`},references:{heading:`10: Посилання й методологія`,heading_aria:`Посилання на джерела`,intro:`Основна методологія спирається на встановлену літературу з політології, статистики й права. Повні цитування слідують стилю Американської асоціації політичних наук (APSA); судові справи — канадській правовій конвенції. Повний список посилань з'являється у <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">технічному звіті</a>. Ключові джерела перелічені тут.`,h_academic:`Академічна література`,h_cases:`Судові справи`,h_statutes:`Закони`},resources:{heading:`11: Технічний додаток`,heading_aria:`Посилання на технічний`,tag_plain:`Простою мовою`,plain_label:`Повний публічний звіт`,plain_desc:`Розгорнута форма, з картами, для широкого читача`,tag_summary:`Підсумок`,summary_label:`Підсумок висновків`,summary_desc:`Огляд простою мовою, пояснює кожне поняття з нуля`,tag_academic:`Академічний`,academic_label:`Технічний звіт`,academic_desc:`Повні методи й цитати для дослідників`,tag_notebook:`Зошит`,notebook_label:`Інтерактивний зошит`,notebook_desc:`Запустіть графіки самі у браузері, без встановлення`,tag_code:`Код`},about_me:{heading:`Про мене`,p1:`Я студент Mount Royal University. Я зробив це дослідження самостійно — воно не було призначено як навчальна робота, і університет його не замовляв. Мої погляди — мої власні й не представляють університет. Я не маю зв'язку з Elections Alberta, комісією або будь-якою політичною партією.`,p2:`Я голосував за різні партії на різних виборах, у всьому політичному спектрі. Я кажу Вам про це, бо моя політична історія могла б вплинути на те, як я дивлюся на це питання. Основний захист від цього — метод: я тестував обидві карти однаково, записав свої передбачення до того, як подивитися на результати, і виклав усе онлайн, щоб будь-хто міг перевірити мою роботу. Я заплатив за це дослідження сам. Якщо Ви знайдете щось, що я зробив неправильно, я щиро хочу про це знати.`,p3:`Записи попередньої реєстрації (написані до того, як було досліджено результати): <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451.`,p4:`Питання чи виправлення: <a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9: Спростування й виправлення`,heading_aria:`Посилання на спростування`,conditions_label:`УМОВИ СПРОСТУВАННЯ`,conditions_intro:`Кожен висновок попередньо прив'язаний до конкретної умови фальсифікації. Якщо будь-яка з нижченаведених умов реалізується, висновок, який вона називає, публічно спростовується протягом 30 днів. Загальний напрямний висновок — що карта меншості сидить поза нейтральним діапазоном на кількох незалежних тестах — спростовується лише якщо принаймні три з п'яти тестів зазнають невдачі.`,c1_title:`Умова 1 — Існує контр-карта`,c1_what:`<em>Що спростовується:</em> Структурний висновок, що поділ Airdrie на чотири шляхи й три позначені головою межі неможливо пояснити заявленим меншістю обґрунтуванням громади інтересів.`,c1_cond:`Умова: хтось продукує легальну карту Альберти, що задовольняє власні заявлені причини меншості — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — і прив'язується до муніципальних ліній зі швидкостями, порівняними з більшістю. Відкритий виклик у <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,c2_title:`Умова 2 — Попередньо зареєстроване проходження сусідського виснаження скасоване`,c2_what:`<em>Що спростовується:</em> Запис у таблиці Розділу 3, що фіксує карту меншості як попередньо зареєстроване ПРОЙДЕНО на тесті сусідського виснаження.`,c2_cond:`Умова: безперервна оцінка виснаження v2 потрапляє в екстремальний верхній хвіст (p &lt; 0,05) випадкових перестановок на фіксованому графі суміжності, що означає, що проходження було вимірювальним артефактом методу бінарного оцінювання v1, а не справжнім нульовим результатом.`,c3_title:`Умова 3 — З'являється документ комісії, датований до 2026`,c3_what:`<em>Що спростовується:</em> Висновок, що рішення меншості щодо меж були чернетковими рішеннями, а не відповідями на задокументовані громадські заяви.`,c3_cond:`Умова: внутрішній документ комісії, датований до остаточних рішень меншості щодо меж, показує, що ці рішення явно керувалися громадськими заявами, які аудит не бачив — а не шістьма опублікованими субобґрунтуваннями, які аудит тестував.`,c4_title:`Умова 4 — Результат виборів 2027 року суперечить симуляції`,c4_what:`<em>Що спростовується:</em> Висновок Смуги 1 — що оцінка seats@50/50 карти меншості сидить на 99,99-му процентилі 1 010 000 нейтральних жеребкувань.`,c4_cond:`Умова: якщо вибори 2027 року в провінції боротимуться за будь-якою з карт комісії й фактичний партійний поділ місць суперечить напрямному прогнозу за голосами 2023 року, висновки процентиля Смуги 1 переглядаються проти фактичних результатів.`,c5_title:`Умова 5 — Альбертанський суд розрізняє постанову SCC щодо Квебеку`,c5_what:`<em>Що спростовується:</em> Процедурний аргумент Розділу 7, що постанова від 16 квітня про заміну комісії комітетом Ланті належить до того самого конституційного класу, що й заморожування перерозподілу в Квебеку 2024 року.`,c5_cond:`Передісторія: 22 квітня 2026 року — через шість днів після постанови Альберти від 16 квітня — Верховний суд Канади підтвердив, 7–2 і з лави, рішення Апеляційного суду Квебеку, що законодавче заморожування урядом Лего своєї комісії з перерозподілу порушило гарантію демократичного представництва за статтею 3 Хартії. Умова: суд, що переглядає постанову Альберти, виявить її конституційно відмінною — наприклад, тому що передавання роботи комітету MLA структурно відрізняється від законодавчого заморожування, або тому, що аналіз дієвого представництва за статтею 3 в Альберті виходить інакшим, ніж у Квебеку.`,corr_label:`ЗАДОКУМЕНТОВАНІ ВИПРАВЛЕННЯ (канонічний перерахунок, 2026-05-11)`,corr_intro:`Наступний ранній висновок не пережив повторного аналізу проти офіційних шейпфайлів Elections Alberta (отриманих 2026-05-06). Він зберігається тут відповідно до попередньо взятої політики аудиту ніколи не видаляти невдалі висновки.`,corr_municipal:`<strong>Муніципальна прив'язка (спростовано).</strong> Ранній аналіз з використанням попередніх меж карти показав, що карта меншості прив'язана до муніципальних ліній лише 15% часу — у 4,9&times; нижче канадської норми 70–85%. Ця цифра була артефактом попередніх (DPG-епохи) реконструкцій меж. На офіційних канонічних шейпфайлах Elections Alberta обидві карти прив'язуються в межах канадської норми: більшість 80%, меншість 72%. <em>Розбіжність</em> муніципальної прив'язки між двома картами — це не сигнал, що переживає канонічний перерахунок. Три аномалії меж, позначені головою комісії (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie) залишаються й не зачеплені цим виправленням.`},suggestions:{heading:`8: Пропозиції`,heading_aria:`Посилання на розділ 8`,intro:`Цей аудит зіткнувся з двома проблемами даних, які не мають жодного стосунку до роботи комісії й цілком стосуються того, як спроєктовано виборчу систему Альберти. Обидві можна виправити.`,advance_p1:`<strong>Приблизно половина всіх голосів Альберти тепер надходить до дня виборів</strong> — попередні дільниці, мобільні дільниці, спеціальні бюлетені. Elections Alberta повідомляє ці результати як підсумки для кожного виборчого поділу, а не за конкретною виборчою зоною. Це означає, що приблизно 395 000 голосів NDP і UCP, поданих у 2023 році, не можна прив'язати до жодного мікрорайону на карті. Вони пораховані; їх просто не можна локалізувати. Кожен попередній виборець перевіряється у списку виборців перед отриманням бюлетеня, і список пов'язує кожного виборця з його конкретною виборчою зоною. Публікація підсумків попереднього голосування на рівні VA не вимагатиме жодної зміни процесу голосування — лише того, про що звітує EA.`,advance_p2:`Це впливає і на самих комісарів, не лише на сторонніх аналітиків. Коли комісія вирішує, чи зберегти Airdrie цілим, чи розколоти, чи має сенс коридор між двома громадами, чи запропонована межа розділяє природний виборчий округ — це судження, що залежать від знання, де живуть виборці. Комісари працюють з того самого опублікованого набору даних, що й усі інші. Половина географічного сигналу про громади, навколо яких вони малюють межі, відсутня і для них.`,lesser_slave_p1:`Є принаймні одна громада на півночі Альберти, де ця прогалина повна. У північній частині поділу Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">показати ↗</button> є виборча зона, що охоплює 4832 км&#178; — більша за Острів Принца Едварда — де кожен голос у 2023 році було подано через команду мобільного голосування Elections Alberta. Вибори тих 844 мешканців пораховані в підсумку поділу, але не можуть бути прив'язані до жодного місця на карті. Громада повністю невидима в опублікованих результатах виборів.`,lesser_slave_p2:`Коли комісія спочатку розглядала ліквідацію поділу Lesser Slave Lake та злиття його в більший округ, вона працювала без географічних даних про голоси з тих громад. Комісія зрештою зберегла поділ — після понад 80 публічних заяв, багатьох з боку Корінних громад у північній частині округу — посилаючись на провінційний закон, що дозволяє округам з громадами Перших Націй і Метіс мати менше населення, ніж провінційне середнє. Вони туди дійшли. Але дані, з якими вони працювали, не показували їм, хто голосував у громадах, які вони вирішували захистити.`,ebca_label:`СТАТТЯ 15(2) EBCA`,ebca_body:`Стаття 15(2) <em>Electoral Boundaries Commission Act</em> Альберти — це дискреційне положення, що дозволяє комісіям захищати недомірні округи — ті, що більш ніж на 25% нижче провінційного середнього населення — коли округ відповідає принаймні трьом із п'яти конкретних критеріїв: (a) географічна площа, що перевищує 20 000 км², (b) відстань понад 150 км від будівлі Законодавчих зборів за найпрямішим шосе, (c) відсутність будь-якого міста з більш ніж 8000 мешканцями, (d) наявність індіанської резервації або поселення Метіс, і (e) чи округ є коcтермінальним з межею провінції Альберта. Положення не автоматичне; комісія повинна судити, чи відповідають критеріям. Lesser Slave Lake незалежно відповідає чотирьом із п'яти.`,rationale_p1:`Проміжне обґрунтування ліквідації округу було через населення: при приблизно 27 000 мешканцях Lesser Slave Lake сидить приблизно на 45% нижче провінційного середнього, наближаючись до правового мінімуму. Це читається як пряме застосування правил. Це не так. Закон Альберти надає комісіям явну дискрецію захищати недомірні округи, коли застосовуються принаймні три з п'яти конкретних критеріїв, і Lesser Slave Lake незалежно відповідає чотирьом з них. Його площа — 69 566 км² (критерій a, поріг 20 000 км²). Найближча його межа — на понад 150 км від Законодавчих зборів за шосе (критерій b). Жодне місто в окрузі не має населення понад 8000 (критерій c). І округ містить чотирнадцять індіанських резервацій і поселень Метіс, чиї громади поділяють спільну північну географію, спільну залежність від мобільного голосування для голосування взагалі та колективний інтерес у тому, щоб мати представника, в першу чергу підзвітного північній Альберті (критерій d).`,rationale_p2:`За запропонованим злиттям з Mackenzie колективний голос був би назавжди поглинутий в окрузі, де інша партія виграє з відривом понад два до одного, не тому що ті громади змінилися, а тому що лінії навколо них змінилися. Кожен із цих чотирьох критеріїв — об'єктивний факт про географію округу, а не оцінне судження. Разом вони описують виборчий округ, для захисту якого й було написане положення: віддалений, великий, рідко заселений і такий, що містить громади, чий інтерес представництва не можна прочитати з сирих чисел населення. Треба три, щоб кваліфікуватися; Lesser Slave Lake має чотири. Розгляд нестачі населення так, ніби він зобов'язував до ліквідації, неправильно тлумачить статут. Розворот комісії був правильним застосуванням закону, а не поступкою політичному тиску.`,banff_p:`Ось інший бік історії: поки Корінні громади в Lesser Slave Lake боролися за те, щоб їх рахували, незгодні комісари запропонували захистити інший округ, провівши його межу через національний парк Banff, де ніхто не живе. Власний голова комісії назвав це «зусиллям недобросовісним», щоб претендувати на правовий захист. Ця фраза є в офіційному остаточному звіті комісії. Захист, призначений для віддалених громад з Корінним населенням, було використано на карті меншості, щоб захистити межу через незаселену пустелю. Громади, яким він був призначений допомогти, мусили за нього боротися через публічні заяви. Комітет Ланті зіткнеться з тим самим рішенням §&#x2009;15(2) у листопаді — без статутної вимоги проводити публічні слухання й без гарантії, що 80 заяв, що скасовують проміжну позицію комісії, нестимуть ту саму вагу вдруге.`,census_p1:`<strong>Альберта повинна почекати на перепис 2026 року перед малюванням наступної карти.</strong> Канада рахує своє населення кожні десять років. Перепис 2026 року відбувається весною 2026 року; Statistics Canada випускає придатні до використання субпровінційні дані приблизно за два роки, у 2027 або 2028 році. Комісія, що малювала карти, оцінені в цьому аудиті, мусила використовувати перепис 2021 року — вже чотирирічної давнини, коли карти малювалися, і потенційно чотирнадцятирічної давнини на час відставки тих меж. Швидкозростаючі міста, як Airdrie і Chestermere, зміняться на 40% або більше за цей період. Сільські громади зменшаться. Карта буде неправильною з дня її використання. Пряма зміна до <em>Electoral Boundaries Commission Act</em> могла б вимагати, щоб будь-яку нову комісію було призначено лише після того, як Statistics Canada випустить найсвіжіші дані областей поширення з попереднього перепису. Результат: карти, що відображають, де насправді живуть альбертанці, а не де вони жили десять років тому.`,census_p2:`Комітет Ланті працює за існуючим статутом, який не встановлює жодної вимоги до часу перепису, і не може односторонньо затягувати поза свій кінцевий термін у листопаді 2026 року. Ця рекомендація стосується майбутньої поправки до <em>Electoral Boundaries Commission Act</em>, а не нинішнього процесу. Напруга реальна: комітет, який повинен подати карту до листопада, працює з даними, що вже на цей час п'ятирічної давнини — назвати обмеження корисніше, ніж робити вигляд, що його не існує.`,closing:`Жодне з цих не є висновком про карти нинішньої комісії. Це спостереження про систему, що робить точний виборчий аналіз важчим, ніж він має бути. Вони пропонуються тут як практичні пропозиції, а не висновки. Обидві справді можна виправити, і їх виправлення зробило б, щоб кожна майбутня комісія — і кожен майбутній аудит — працювали з кращого ґрунту.`}},editorial_canada:{heading:`Контекст: Канада інакша — і подібна`,p1:`Канада належить до тієї самої сім'ї, що й США, Сполучене Королівство й Австралія. Ми обираємо окремих членів з географічних округів за системою першого, що пройшов. Ми періодично перемальовуємо лінії — федерально після кожного десятилітнього перепису, провінційно за поетапним графіком. Ми успадкували основну машинерію з тих самих вестмінстерських коренів. Поки що жодних несподіванок.`,p2:`Що відрізняє Канаду — це тест, який мають пройти лінії.`,p3:`В американському конституційному праві обов'язковим правилом є <em>одна особа, один голос</em> — округи повинні мати населення, наскільки практично можливо рівне, а великі відхилення вимагають суворого обґрунтування. У канадському конституційному праві обов'язкове правило інше. Стаття 3 <em>Канадської хартії прав і свобод</em> гарантує кожному громадянину право голосу. У справі <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — саскачеванському посиланні 1991 року, провідній справі — Верховний суд Канади витлумачив це право як право на <em>дієве представництво</em>, а не право на математичну рівність населення округів.`,p4:`Це розрізнення має значення. Дієве представництво дозволяє населенню округів варіюватися, іноді суттєво, коли є вагомі причини: широкі сільські географії, які один MLA не може розумно обслуговувати при стандартній щільності населення, громади інтересів, які слід тримати разом, представництво меншин, яке математична рівність розбавила б. Саскачеванське посилання зробило цю гнучкість конституційною. Допуск населення в 25% EBCA — правило, що захищає сільські місця Альберти — випливає з нього безпосередньо.`,p5:`Заковика в тому, що гнучкість працює в обидва боки. Якщо комісія може законно відходити від рівності населення з правильних причин, вона також може відходити від рівності населення з неправильних. У канадському праві немає американської математичної підлоги, на яку можна повернутися. У нього є тест дієвого представництва, що його застосовують судді постфактум у судовому процесі. Більшість юрисдикцій захищаються від неправильних причин структурними захистами: федеральні комісії з перерозподілу ізольовані статутом, і їхні рекомендації набирають чинності автоматично, якщо Парламент не діє за ними протягом терміну. Квебек використовує постійну незалежну комісію, роботу якої Національні збори можуть скасувати лише надбільшістю у дві третини. Британська Колумбія працює за подібним правилом за замовчуванням — прийняти.`,p6:`Альберта — виняток. За <em>Electoral Boundaries Commission Act</em> звіт комісії — це лише рекомендація — законодавчі збори мають проголосувати за його ухвалення. Затвердження зазвичай — формальність. У циклі 2026 року комісія розкололася 3–2 і створила дві конкуруючі пропозиції; законодавчі збори створили окремий комітет MLA, очолюваний MLA, призначеним прем'єр-міністром, щоб обрати між ними. Ніщо в канадському конституційному праві не вимагало існування цього комітету. Ніщо не вимагає, щоб його вибір слідував процесу комісії. Це структурна прогалина, яку цей аудит досліджує.`,p7:`Тож коли канадські суди кажуть, що «джеррімендер» — не їхній правовий словник, вони не кажуть, що базова концепція тут не застосовується. Вони кажуть, що тест інший — дієве представництво, а не математична рівність. Чи відповідає пропозиція меншості цьому тесту — саме те питання, проти якого цей аудит виміряв геометрію, і саме те питання, на яке лише суддя може відповісти остаточно. Розгорнуте обґрунтування <em>Saskatchewan Reference</em>, контраст з іншими провінціями, питання процесуальної правоздатності та доступні шляхи реформи розглядаються у <a href="#references">розділі посилань нижче</a>.`},chrome:{back_to_top:`Повернутися нагору`,license_title:`Creative Commons Attribution-NonCommercial-ShareAlike 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Назад до Ставок`,lightbox:{fig_aria:`Збільшений вигляд фігури`,fig_close_aria:`Закрити збільшену фігуру (Esc)`,map_aria:`Переглядач масштабування карти`,map_close_aria:`Закрити переглядач карти`,close_title:`Закрити (Esc)`},participation:{heading:`Допоможіть нам удосконалити MapExplorer`,body:`Поки Ви досліджуєте, ми відстежуємо, які карти й округи Ви відвідуєте, і періодично надсилаємо дані до нашої дослідницької бази. Спільне використання вигляду також зберігає, де Ви опинилися. Мета: зрозуміти, що корисно, і зробити інструмент кращим.`,no_collect:`Ми ніколи не збираємо Ваше ім'я, IP-адресу або точне місцезнаходження. Усе анонімізується у Вашому браузері, перш ніж залишити його. Ми не змогли б ідентифікувати Вас за даними, навіть якби нам так наказали.`,dnt:`У Вашому браузері ввімкнено Do Not Track. «Ні» попередньо вибрано від Вашого імені. Ви все ще можете вибрати «Так».`,no_thanks:`Ні, дякую`,yes_help:`Так, я допоможу`,privacy_policy:`Політика конфіденційності`},share:{button:`Поділитися`,button_title:`Поділитися або завантажити конфігурацію карти`,dialog_aria:`Поділитися конфігурацією карти`,close_aria:`Закрити панель спільного доступу`,share_label:`Поділитися цією конфігурацією`,share_hint:`Введіть цей код у будь-якому браузері, де запущено аудит, щоб завантажити цю конфігурацію. Код ніколи не розміщується в URL.`,load_label:`Завантажити конфігурацію`,load_btn:`Завантажити`,load_placeholder:`alpine-eagle-banff`,copy:`Копіювати`,copied:`Скопійовано!`,copy_failed:`Не вдалося`,unrecognised:`Нерозпізнаний код — перевірте правопис.`},map:{minority:`Меншість`,majority:`Більшість`,current:`Поточна`,wasted:`Змарновані`,wasted_title:`Внесок розриву ефективності на округ`,partisan:`Партійний`,partisan_title:`Розфарбувати кожен округ за партійним результатом (UCP синім / NDP помаранчевим)`,borders:`Межі`,flagged:`Позначені`,flagged_title:`Усі 7 конфігурацій, позначені головою комісії суддею Міллером — автоматично перемикається на карту меншості`,help_aria:`Допомога з картою`,help_title:`Як користуватися картою`,pin_aria:`Закріпити карту`,pin_title:`Закріпити карту — запобігти автоматичному переміщенню при кліку на округ`,search_placeholder:`Знайти округ…`,zoom_aria:`Масштабування карти`,clear_aria:`Очистити вибір округу`,clear_title:`Очистити вибір`,va_hint:`Натисніть у межах цього округу, щоб побачити результати виборчих дільниць`,va_close_aria:`Закрити деталі виборчої дільниці`,va_close_title:`Закрити`,object_title:`Карта виборчих округів Альберти — повна роздільна здатність`,ea_credit:`Дані карти:`,cc_title:`Текстовий вміст: CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`},map_intro:{heading:`Як користуватися картою`,click_district:`Натисніть будь-який округ`,click_district_desc:`побачити результати виборів 2023 року та перейти до нього`,click_within:`Натисніть у межах вибраного округу`,click_within_desc:`побачити результати окремих виборчих дільниць (колір = розподіл голосів)`,dblclick:`Подвійний клік по округу`,dblclick_desc:`збільшити на весь екран; подвійний клік по порожньому місцю — зменшити`,layers_primary:`Меншість / Більшість / Поточна`,layers_primary_desc:`перемкнути активну карту меж`,layers_data:`Партійний / Змарновані / Межі`,layers_data_desc:`перемкнути шари даних`,search:`Знайти округ`,search_desc:`перейти за назвою; клавіші зі стрілками переміщують, + / − масштабують`,escape:`Escape`,escape_desc:`закрити цей переглядач`,s4_tip:`У §4 натисніть <em>Показати позначені округи на карті</em>, щоб виділити поділ Airdrie і зону NW Калгарі.`,got_it:`Зрозуміло`},footer:{title:`Аудит виборчих меж Альберти — травень 2026`,copyright:`© Will Conner 2026 —`,text_label:`Текст:`,code_label:`Код:`}}},tl:{selector:{label:`Pumili ng wika`},disclaimer:{text:`Isinalin ang site na ito sa pamamagitan ng AI. Maaaring may mga nilalamang nasa Ingles pa habang isinasagawa ang pagsasalin. Kung may mga mali o nais ninyong tumulong sa pagsasalin ng proyektong ito, mangyaring %s.`,link_label:`makipag-ugnayan sa amin`},opener:{heading:`Para kanino ito?`,body:`Para sa atin. Para sa ating lahat. Sa mga taga-bukid, sa mga taga-lungsod, sa mga curious, sa mga mahilig sa pulitika, sa mga mamamahayag, sa mga abugado, sa mga akademiko, sa mga pulitiko — para sa ating lahat. Dahil nakakaapekto ito sa ating lahat. Anuman ang iyong palagay sa partidong nasa poder, ang ginawa ng hating komisyon ay hindi pa nangyari noon. At binigyan tayo nito ng pagkakataong masilip ang loob ng makinarya sa paraang hindi pa natin nagawa. Ngayon ay maaari na tayong magtatag ng isang batayan — isang serye ng mga pagsusulit, at lahat ng susunod ay maaaring sukatin batay dito. Hayaan ninyong ipakita ko sa inyo ang aking natuklasan.`},stakes:{q1:{heading:`Ang iminungkahing mapa ba ay isang gerrymander?`,body:`Ang "gerrymander" ay hindi terminong ginagamit ng mga korte sa Canada. Ngunit kung gagamitin ito — sa pang-araw-araw na kahulugang ibinibigay ng karamihan — ang mga ebidensya sa audit na ito ay makatuwirang sumusuporta sa pagtawag sa <em>panukala ng minorya</em>, kung ito ay magiging batas, bilang isang mapa na malalim na gerrymandered. Apat sa limang istrukturang pagsusulit ng audit na ito ang tumutukoy sa <em>panukala ng minorya</em> at wala ni isa ang tumutukoy sa kabilang panukala (ang <em>panukala ng mayorya</em>); ang ikalimang pagsusulit ay neutral para sa parehong mapa.`,footnote:`Ang mga pangalang "mayorya" at "minorya" ay galing sa 3–2 na paghahati sa Electoral Boundaries Commission (pinamumunuan ni Justice Miller), na nagprodyus ng dalawang nagtutunggaling panukala sa halip na isang rekomendasyon. Mula noon ay isinantabi na ng lehislatura ang parehong panukala at inihatid ang muling pagguhit ng mga hangganan sa isang limang-MLA na komite na pinamumunuan ni Brandon Lunty (isang MLA na hinirang ng Premier); ang komite ay nangangasiwa sa isang hiwalay na apat na miyembrong Independent Advisory Panel — dalawang miyembrong hinirang ng Premier (Hon. Monte Solberg at Darwin Durnie), at dalawa ng Pinuno ng Oposisyon (Dr. Gerard Kennedy at Brent Robinson) — na inatasang gumawa ng bagong 91-puwesto na panukalang hangganan bago ang takdang petsa ng Nobyembre 2026.`},q2:{heading:`Ano ang ibig sabihin ng "gerrymander" sa batas ng Canada?`,body:`Wala. Iba ang pagsusuri ng Canada: kung binibigyan ng <em>epektibong representasyon</em> ang mga botante sa ilalim ng seksyon 3 ng Charter. Ang panukala ng minorya ay nagdudulot ng mga seryosong tanong sa ilalim ng pagsusuring iyon; isang hukom lamang ang makakasagot ng tiyak, at walang sinuman pa ang nagtanong sa kanya.`},q3:{heading:`Ano ang ibig sabihin nito para sa mga Albertan?`,body:`Sa isang 50/50 na boto sa probinsya, inilalagay ng mga sukat ng audit ang panukala ng minorya sa isang istrukturang sukdulan — mas mababa sa 100 ng 1.01 milyong neutral na mga mapa ng paghahambing ang nagbibigay ng kaparehong uri ng kawalan ng balanse sa upuan. Mahalaga ang kawalan ng balanseng iyon dahil sa 58 ng 87 upuan — isang dalawang-katlong supermayorya — ang naghaharing partido ay nakakakuha ng pambihirang mga kapangyarihang pamamaraan: maaari nitong tanggalin ang karaniwang mga panahon ng abiso at itulak ang mga panukalang batas sa pamamagitan ng maraming yugto ng pambabatasan sa isang araw lamang, lampas sa mga pagsusuri ng paglalapat na karaniwang nagpipigil sa kanya. Kung ang pagkakahilig ng panukala ng minorya ay sapat na laki upang itulak ang isang partido lampas sa hangganang 58-upuan sa mga sukat ng boto na <em>iba</em> sa 50/50 ay isang tanong na hindi pa sinuri ng audit na ito. Kung katanggap-tanggap ang pagpapalitan mismo ay isang tanong para sa mga Albertan, hindi para sa audit na ito.`},cta_law:`Basahin ang legal na konteksto →`,cta_methods:`Tingnan kung paano namin sinubukan →`},head:{title:`Pag-audit ng Hangganan ng Halalan sa Alberta`,meta_description:`Estadistikong pag-audit ng komisyon ng hangganan ng halalan sa Alberta sa 2026 — 1,010,000 neutral na mga mapa, opisyal na mga shapefile ng Elections Alberta, mga pre-registered na pagsusulit.`},nav:{home_aria:`Bumalik sa itaas`,theme_aria:`Palitan ang madilim / maliwanag na mode`,theme_title:`Palitan ang madilim na mode`,nav_aria:`I-toggle ang nabigasyon`,drawer_top:`↑ Itaas`,stakes:`Hatol`,why:`Bakit?`,map:`Mapa`,split:`Ang Paghahati`,litmus:`Pagsusulit`,crack_pack:`Crack at Pack`,for_you:`Para Sa Iyo`,impact:`Epekto`,history:`Kasaysayan`,canada:`Canada`,gerrymanders:`Mga Gerrymander`,november:`Nobyembre`,lunty:`Lunty`,invisible:`Hindi Nakikita`,suggestions:`Mga Mungkahi`,retractions:`Mga Pagbawi`,references:`Mga Sanggunian`,resources:`Mga Mapagkukunan`,technical:`Teknikal`},hero:{h1:`Pag-audit ng Hangganan ng Halalan sa Alberta`,subtitle:`Ang komisyon ng Alberta ay nagprodyus ng dalawang mapa ng riding sa 2026. Inihambing ng audit na ito ang mga ito — gamit ang parehong mga pagsusulit, na inilapat nang pantay sa pareho — upang itanong kung pareho nilang itinuturing ang mga botante.`,badge:`Mga opisyal na mapa ng Elections Alberta — Inilathala noong Mayo 2026`,cover_note:`I-click upang mag-zoom at galugarin ang lahat ng tatlong panukala ng hangganan nang sabay-sabay. I-pin ang viewport at mag-flip sa pagitan ng mga mapa — gumagalaw ang mga hangganan, nananatili ang mga botante. Mag-scroll pababa para sa pagsusuri.`,cover_note_1:`Ang mapang ito ang pinakamahusay na paraan upang magsimula. I-click ito upang mag-zoom at galugarin. Ang mga pindutan sa itaas ay nagpapalipat sa pagitan ng mapa ng minorya, mapa ng mayorya, at mga hangganan na nasaad noong 2019 — o ilatag ang lahat ng tatlo upang makita kung saan sila eksaktong nag-iiba. Kinukulayan ng <strong>Detail</strong> ang bawat polling area ayon sa paano bumoto ang mga tao noong 2023; nagdadagdag ang <strong>Trend</strong> ng partisan shading bawat distrito (asul UCP, kahel NDP); ginagawang on/off ng <strong>Lines</strong> ang mga hangganan. Ang <strong>Find</strong> ay lumulukso sa anumang riding ayon sa pangalan.`,cover_note_2:`Subukang i-lock ang viewport at mag-flip sa pagitan ng mga mapa — pagmasdan ang isang hangganan na lumilipat habang ang mga botante sa ilalim ay nananatiling tahimik. Iyon ang buong tanong sa isang galaw.`,cover_note_3:`Kapag tapos ka nang mag-explore, mag-scroll pababa para sa buod. Para sa kumpletong teknikal na pagsusuri, tingnan ang seksyon ng Mga Mapagkukunan. Lahat ng data ay mula sa opisyal na shapefile ng Elections Alberta at iba pang gobyerno at open-source na mga rekord.`,image_alt:`Mga mapa ng distritong pang-eleksyon sa Alberta — panukala ng minorya ng komisyon, kinulayan ayon sa boto noong 2023`,map_hint:`I-click upang galugarin nang interactive`,btn_title:`I-click upang buksan ang interactive na mapa`,btn_aria:`Buksan ang interactive na mapa`},editorial_intro:{heading:`Ano ang redistricting at bakit ito ay dapat mahalaga sa iyo?`,p1:`Ang bawat botante sa Alberta ay naninirahan sa isang <em>elektoral na distrito</em> — isang seksyon ng probinsya na pumipili ng isang tao sa lehislatura. May 87 distrito. Ang bawat distrito ay pumipili ng isang MLA. Kapag ikaw ay bumoboto sa isang elektoral na probinsya, pinipili mo ang MLA para sa distrito kung saan ka nakatira. Iyon ang buong koneksyon ng karamihan sa mga Albertan sa lehislatura: isang MLA, isang distrito, isang boto.`,p2:`Ang mga linyang ito ng distrito ay hindi permanente. Lumilipat ang mga tao, lumalago ang mga kapitbahayan, ang mga lugar sa kanayunan ay nagiging manipis, at ang mga lungsod ay lumalawak. Tuwing walo hanggang sampung taon, dapat na muling iguhit ng Alberta ang mga linya upang ang bawat distrito ay nasa tamang sukat at sumasalamin sa kung paano talaga nakatira ang mga Albertan ngayon. Ang katawan na muling gumuhit ay ang <em>Komisyon ng Hangganan ng Halalan</em> — isang independiyenteng komisyon na may mga huwes, abugado, at miyembro ng publiko, hindi mga politiko.`,p3:`Iyon ang karaniwang proseso. Sa pagkakataong ito, ang karaniwang proseso ay nagprodyus ng isang bagay na hindi karaniwan. Ang limang miyembro ng komisyon ay naghati-hati ng 3 sa 2 sa kung anong itsura ng mapa ay dapat, at sa halip na magkasundo sa isang rekomendasyon, sila ay nagprodyus ng dalawa: isang <em>panukala ng mayorya</em> (sinusuportahan ng tatlong komisyonado) at isang <em>panukala ng minorya</em> (sinusuportahan ng dalawa). Ang dalawa ay nakapatong sa mesa — at ang lehislatura ay isinantabi na ang dalawa. Isang hiwalay na komite ng mga MLA na pinamumunuan ni Brandon Lunty — hinirang ng Premier para sa partikular na desisyong ito — ang ngayon ay nangangasiwa sa isang apat na miyembrong Independent Advisory Panel, na binuo sa ilalim ng Government Motion 37 (ipinasa noong Abril 21, 2026), na inatasang gumawa ng bagong 91-puwesto na mapa. Ang lehislatura ay dapat aprubahan kung anuman ang ihatid ng komite bago ang Nobyembre 2026.`,p4:`Kung bakit ito mahalaga sa iyo: ang mga linya ay nagdedesisyon kung sino ang iyong MLA. Sila ang nagdedesisyon kung anong mga kapitbahayan, bayan, at alalahanin ang kinakatawan nang magkasama. Kung ang iyong lungsod ay nahahati sa apat na MLA sa halip na isa, walang iisang kinatawan ang may pananagutan para sa lungsod sa kabuuan. Kung ang iyong komunidad ng interes — isang maliit na bayan, isang rural na rehiyon, isang sentro ng lungsod — ay nahahati sa pagitan ng mga distrito, ang iyong boses sa mga desisyon ng probinsya ay nalalabnaw. Hinuhubog din ng mapa kung anong partido ang maaaring magtatag ng gobyerno, at sa anong margin. Ang partikular na natuklasan ng audit (na ang panukala ng minorya ay nasa isang sukdulan ng istraktura) ay ang dahilan kung bakit binabasa mo ang site na ito, ngunit ang mas malawak na tanong ay mas matanda at naaangkop sa bawat redistricting cycle: ang mga linya ba ay sumasalamin sa kung paano nakatira ang mga Albertan, o hinuhubog ba nila ang pulitika na susunod?`,p5:`Ang natitirang bahagi ng pahinang ito ay tumatakbo sa kung ano talaga ang ginagawa ng dalawang iminungkahing mapa.`,key_terms_lead:`Mga pangunahing termino sa seksyong ito — i-click upang basahin:`},boundary:{heading:`Kung ano ang masasabi at hindi masasabi ng audit na ito`,can_1:`Mas mababa sa 1 sa 14.5 milyong random na nilikhang mga mapa ng paghahambing ang nagprodyus ng mga pattern na kasinghirap ng panukala ng minorya sa lahat ng apat na estadistikong sukat na pinagsama.`,can_2:`Ang panukala ng minorya ay bumagsak sa 4 sa 5 pre-registered na istrukturang pagsusulit; ang ikalima (anchoring) ay neutral — ang parehong mapa ay nasa loob ng pamantayang Canadian. Ang panukala ng mayorya ay bumagsak sa 0 sa 4 na tumama.`,can_3:`Ang mga resultang ito ay tugma sa mga mapa na nagpoprodyus ng malalakas na epektong partisan, at hindi tugma sa kung ano ang prinopodyus ng random na set ng paghahambing.`,cant_1:`Ang audit ay <strong>hindi</strong> nagtatatag na anumang komisyonado ay may intensyon sa mga epektong partisan na sinusukat nito. Hindi maipakikita ng geometriya ng hangganan ang intensyon.`,cant_2:`Ang audit ay <strong>hindi</strong> humuhula kung ano ang pipiliin ng Lunty committee, kung ano ang magiging boto sa Nobyembre 2026, o kung paano magrereaksyon ang mga Albertan.`,cant_3:`Ang audit ay <strong>hindi</strong> humuhula kung paano huhusgahan ng isang korte kung magsasampa ng Charter challenge laban sa alinmang panukala.`,cant_4:`Ang audit ay <strong>hindi</strong> nagsasabi sa anumang indibidwal na botante kung anong posisyon ang dapat kunin o ano ang gagawin sa impormasyong ito. Sa inyo iyon na desisyon.`}},pa:{selector:{label:`ਭਾਸ਼ਾ ਚੁਣੋ`},disclaimer:{text:`ਇਸ ਸਾਈਟ ਦਾ ਅਨੁਵਾਦ AI ਦੁਆਰਾ ਕੀਤਾ ਗਿਆ ਹੈ। ਅਨੁਵਾਦ ਚੱਲ ਰਹੇ ਹੋਣ ਦੌਰਾਨ ਕੁਝ ਸਮੱਗਰੀ ਅਜੇ ਵੀ ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਦਿਖਾਈ ਦੇ ਸਕਦੀ ਹੈ। ਜੇ ਤੁਸੀਂ ਗਲਤੀਆਂ ਦੇਖਦੇ ਹੋ ਜਾਂ ਇਸ ਪ੍ਰੋਜੈਕਟ ਦੇ ਅਨੁਵਾਦ ਵਿੱਚ ਮਦਦ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਕਿਰਪਾ ਕਰਕੇ %s।`,link_label:`ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ`},opener:{heading:`ਇਹ ਕਿਸ ਲਈ ਹੈ?`,body:`ਸਾਡੇ ਲਈ। ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਪੇਂਡੂ, ਸ਼ਹਿਰੀ, ਜਿਗਿਆਸੂ, ਸਿਆਸਤ ਦੇ ਸ਼ੁਕੀਨ, ਪੱਤਰਕਾਰ, ਵਕੀਲ, ਵਿਦਵਾਨ, ਚੁਣੇ ਹੋਏ ਨੁਮਾਇੰਦੇ — ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ। ਕਿਉਂਕਿ ਇਹ ਸਾਨੂੰ ਸਾਰਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ। ਭਾਵੇਂ ਤੁਸੀਂ ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਨੂੰ ਪਸੰਦ ਕਰਦੇ ਹੋ ਜਾਂ ਨਹੀਂ, ਜੋ ਵੰਡੇ ਹੋਏ ਕਮਿਸ਼ਨ ਨੇ ਪੈਦਾ ਕੀਤਾ ਉਹ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਹੋਇਆ। ਅਤੇ ਇਸ ਨੇ ਸਾਨੂੰ ਇਸ ਮਸ਼ੀਨ ਦੇ ਅੰਦਰ ਝਾਤੀ ਮਾਰਨ ਦਾ ਮੌਕਾ ਦਿੱਤਾ ਹੈ ਜਿਸ ਤਰ੍ਹਾਂ ਅਸੀਂ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ ਮਾਰ ਸਕੇ। ਹੁਣ ਅਸੀਂ ਇੱਕ ਆਧਾਰ-ਰੇਖਾ ਸਥਾਪਤ ਕਰ ਸਕਦੇ ਹਾਂ — ਪਰੀਖਣਾਂ ਦੀ ਇੱਕ ਲੜੀ, ਅਤੇ ਜੋ ਕੁਝ ਵੀ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦਾ ਹੈ ਉਸਨੂੰ ਇਸ ਦੇ ਆਧਾਰ ਉੱਤੇ ਪਰਖਿਆ ਜਾ ਸਕਦਾ ਹੈ। ਮੈਨੂੰ ਤੁਹਾਨੂੰ ਦਿਖਾਉਣ ਦਿਓ ਕਿ ਮੈਂ ਕੀ ਲੱਭਿਆ ਹੈ।`},stakes:{q1:{heading:`ਕੀ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ਾ ਇੱਕ ਗੈਰੀਮੈਂਡਰ ਹੈ?`,body:`"ਗੈਰੀਮੈਂਡਰ" ਕੈਨੇਡੀਅਨ ਅਦਾਲਤਾਂ ਦੁਆਰਾ ਵਰਤਿਆ ਜਾਣ ਵਾਲਾ ਸ਼ਬਦ ਨਹੀਂ ਹੈ। ਪਰ ਜੇ ਇਹ ਹੁੰਦਾ — ਜਿਸ ਆਮ ਅਰਥ ਵਿੱਚ ਜ਼ਿਆਦਾਤਰ ਲੋਕ ਇਸਨੂੰ ਸਮਝਦੇ ਹਨ — ਤਾਂ ਇਸ ਆਡਿਟ ਦੇ ਸਬੂਤ ਮੁਨਾਸਬ ਤੌਰ ਤੇ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਨੂੰ, ਜੇ ਲਾਗੂ ਕੀਤਾ ਜਾਵੇ, ਇੱਕ ਡੂੰਘੀ ਗੈਰੀਮੈਂਡਰਡ ਨਕਸ਼ੇ ਵਜੋਂ ਕਹਿਣ ਦੀ ਹਮਾਇਤ ਕਰਨਗੇ। ਇਸ ਆਡਿਟ ਦੇ ਪੰਜ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣਾਂ ਵਿੱਚੋਂ ਚਾਰ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> ਨੂੰ ਚਿੰਨ੍ਹਿਤ ਕਰਦੇ ਹਨ ਅਤੇ ਕੋਈ ਵੀ ਬਦਲ (<em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em>) ਨੂੰ ਚਿੰਨ੍ਹਿਤ ਨਹੀਂ ਕਰਦਾ; ਪੰਜਵਾਂ ਪਰੀਖਣ ਦੋਵਾਂ ਨਕਸ਼ਿਆਂ ਲਈ ਨਿਰਪੱਖ ਹੈ।`,footnote:`"ਬਹੁ-ਗਿਣਤੀ" ਅਤੇ "ਘੱਟ-ਗਿਣਤੀ" ਨਾਂ ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ (ਜਸਟਿਸ ਮਿਲਰ ਦੀ ਪ੍ਰਧਾਨਗੀ ਅਧੀਨ) ਵਿੱਚ 3–2 ਦੀ ਵੰਡ ਤੋਂ ਆਏ ਹਨ, ਜਿਸ ਨੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਦੀ ਬਜਾਏ ਦੋ ਮੁਕਾਬਲੇ ਵਾਲੀਆਂ ਪ੍ਰਸਤਾਵਾਂ ਪੈਦਾ ਕੀਤੀਆਂ। ਵਿਧਾਨ ਸਭਾ ਨੇ ਉਸ ਤੋਂ ਬਾਅਦ ਦੋਵਾਂ ਪ੍ਰਸਤਾਵਾਂ ਨੂੰ ਪਾਸੇ ਰੱਖ ਦਿੱਤਾ ਹੈ ਅਤੇ ਚੋਣ-ਖੇਤਰਾਂ ਦੀ ਮੁੜ-ਵੰਡ ਬ੍ਰੈਂਡਨ ਲੰਟੀ (ਪ੍ਰੀਮੀਅਰ ਦੁਆਰਾ ਨਿਯੁਕਤ ਇੱਕ MLA) ਦੀ ਪ੍ਰਧਾਨਗੀ ਵਾਲੀ ਪੰਜ-MLA ਕਮੇਟੀ ਨੂੰ ਸੌਂਪ ਦਿੱਤੀ ਹੈ; ਇਹ ਕਮੇਟੀ ਚਾਰ ਮੈਂਬਰਾਂ ਦੇ ਇੱਕ ਸੁਤੰਤਰ ਸਲਾਹਕਾਰ ਪੈਨਲ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦੀ ਹੈ — ਦੋ ਨੂੰ ਪ੍ਰੀਮੀਅਰ ਨੇ ਨਾਮਜ਼ਦ ਕੀਤਾ (ਮਾਣਯੋਗ ਮੌਂਟੇ ਸੋਲਬਰਗ ਅਤੇ ਡਾਰਵਿਨ ਡਰਨੀ), ਦੋ ਨੂੰ ਵਿਰੋਧੀ ਧਿਰ ਦੇ ਨੇਤਾ ਨੇ (ਡਾ. ਗੈਰਾਰਡ ਕੈਨੇਡੀ ਅਤੇ ਬ੍ਰੈਂਟ ਰੌਬਿਨਸਨ) — ਜਿਨ੍ਹਾਂ ਨੂੰ ਨਵੰਬਰ 2026 ਦੀ ਆਖਰੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ 91 ਸੀਟਾਂ ਦੀ ਨਵੀਂ ਸਰਹੱਦ ਪ੍ਰਸਤਾਵ ਤਿਆਰ ਕਰਨ ਦਾ ਕੰਮ ਸੌਂਪਿਆ ਗਿਆ ਹੈ।`},q2:{heading:`ਕੈਨੇਡੀਅਨ ਕਾਨੂੰਨ ਵਿੱਚ "ਗੈਰੀਮੈਂਡਰ" ਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`ਕੁਝ ਨਹੀਂ। ਕੈਨੇਡੀਅਨ ਪਰੀਖਣ ਵੱਖਰਾ ਹੈ: ਕੀ ਸਰਹੱਦਾਂ ਚਾਰਟਰ ਦੀ ਧਾਰਾ 3 ਦੇ ਅਧੀਨ ਵੋਟਰਾਂ ਨੂੰ <em>ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਪ੍ਰਤੀਨਿਧਤਾ</em> ਦਿੰਦੀਆਂ ਹਨ। ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇਸ ਪਰੀਖਣ ਅਧੀਨ ਗੰਭੀਰ ਸਵਾਲ ਖੜੇ ਕਰਦੀ ਹੈ; ਸਿਰਫ਼ ਇੱਕ ਜੱਜ ਹੀ ਉਨ੍ਹਾਂ ਦਾ ਨਿਸ਼ਚਿਤ ਜਵਾਬ ਦੇ ਸਕਦਾ ਹੈ, ਅਤੇ ਅਜੇ ਤੱਕ ਕਿਸੇ ਨੇ ਨਹੀਂ ਪੁੱਛਿਆ।`},q3:{heading:`ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਇਸਦਾ ਕੀ ਅਰਥ ਹੈ?`,body:`50/50 ਸੂਬਾਈ ਵੋਟ ਉੱਤੇ, ਆਡਿਟ ਦੇ ਮਾਪ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਨੂੰ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਰੱਖਦੇ ਹਨ — 1.01 ਮਿਲੀਅਨ ਨਿਰਪੱਖ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 100 ਤੋਂ ਘੱਟ ਉਸੇ ਕਿਸਮ ਦਾ ਸੀਟ ਅਸੰਤੁਲਨ ਪੈਦਾ ਕਰਦੇ ਹਨ। ਉਹ ਅਸੰਤੁਲਨ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਕਿਉਂਕਿ 87 ਵਿੱਚੋਂ 58 ਸੀਟਾਂ ਉੱਤੇ — ਦੋ ਤਿਹਾਈ ਸੁਪਰ-ਬਹੁਮਤ — ਸੱਤਾਧਾਰੀ ਪਾਰਟੀ ਅਸਾਧਾਰਨ ਪ੍ਰਕਿਰਿਆਤਮਕ ਸ਼ਕਤੀਆਂ ਖੋਲ੍ਹਦੀ ਹੈ: ਇਹ ਨੋਟਿਸ ਦੀਆਂ ਮਾਨਕ ਮਿਆਦਾਂ ਨੂੰ ਛੱਡ ਸਕਦੀ ਹੈ ਅਤੇ ਜਨਤਕ ਬਿੱਲਾਂ ਨੂੰ ਇੱਕ ਹੀ ਦਿਨ ਵਿੱਚ ਕਈ ਵਿਧਾਨਕ ਪੜਾਵਾਂ ਰਾਹੀਂ ਅੱਗੇ ਧੱਕ ਸਕਦੀ ਹੈ, ਉਨ੍ਹਾਂ ਵਿਚਾਰ-ਵਟਾਂਦਰੇ ਦੀਆਂ ਜਾਂਚਾਂ ਨੂੰ ਟਪਾ ਕੇ ਜੋ ਆਮ ਤੌਰ ਤੇ ਇਸਨੂੰ ਸੀਮਤ ਕਰਦੀਆਂ ਹਨ। ਕੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਦਾ ਝੁਕਾਅ 50/50 ਤੋਂ <em>ਇਲਾਵਾ</em> ਹੋਰ ਵੋਟ ਅਨੁਪਾਤਾਂ ਉੱਤੇ ਇੱਕ ਪਾਰਟੀ ਨੂੰ 58-ਸੀਟਾਂ ਦੀ ਹੱਦ ਤੋਂ ਪਾਰ ਧੱਕਣ ਲਈ ਕਾਫ਼ੀ ਵੱਡਾ ਹੈ, ਇਹ ਇੱਕ ਸਵਾਲ ਹੈ ਜਿਸਨੂੰ ਇਹ ਆਡਿਟ ਅਜੇ ਤੱਕ ਨਹੀਂ ਪਰਖ ਸਕਿਆ। ਕੀ ਇਹ ਅਦਲਾ-ਬਦਲੀ ਆਪਣੇ ਆਪ ਵਿੱਚ ਸਵੀਕਾਰਯੋਗ ਹੈ, ਇਹ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਲਈ ਸਵਾਲ ਹੈ, ਇਸ ਆਡਿਟ ਲਈ ਨਹੀਂ।`},cta_law:`ਕਾਨੂੰਨੀ ਸੰਦਰਭ ਪੜ੍ਹੋ →`,cta_methods:`ਦੇਖੋ ਅਸੀਂ ਕਿਵੇਂ ਪਰਖਿਆ →`},head:{title:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,meta_description:`ਅਲਬਰਟਾ ਦੇ 2026 ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ ਦਾ ਅੰਕੜਾ ਆਡਿਟ — 1,010,000 ਨਿਰਪੱਖ ਨਕਸ਼ੇ, ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ, ਪੂਰਵ-ਰਜਿਸਟਰਡ ਪਰੀਖਣ।`},nav:{home_aria:`ਉੱਪਰ ਵਾਪਸ ਜਾਓ`,theme_aria:`ਡਾਰਕ / ਲਾਈਟ ਮੋਡ ਬਦਲੋ`,theme_title:`ਡਾਰਕ ਮੋਡ ਬਦਲੋ`,nav_aria:`ਨੇਵੀਗੇਸ਼ਨ ਟੌਗਲ ਕਰੋ`,drawer_top:`↑ ਉੱਪਰ`,stakes:`ਫੈਸਲਾ`,why:`ਕਿਉਂ?`,map:`ਨਕਸ਼ਾ`,split:`ਵੰਡ`,litmus:`ਪਰਖ`,crack_pack:`ਫੁੱਟ ਤੇ ਪੈਕ`,for_you:`ਤੁਹਾਡੇ ਲਈ`,impact:`ਅਸਰ`,history:`ਇਤਿਹਾਸ`,canada:`ਕੈਨੇਡਾ`,gerrymanders:`ਗੈਰੀਮੈਂਡਰ`,november:`ਨਵੰਬਰ`,lunty:`ਲੰਟੀ`,invisible:`ਅਦ੍ਰਿਸ਼`,suggestions:`ਸੁਝਾਅ`,retractions:`ਵਾਪਸੀਆਂ`,references:`ਹਵਾਲੇ`,resources:`ਸਰੋਤ`,technical:`ਤਕਨੀਕੀ`},hero:{h1:`ਅਲਬਰਟਾ ਚੋਣ ਸਰਹੱਦ ਆਡਿਟ`,subtitle:`ਅਲਬਰਟਾ ਦੇ ਕਮਿਸ਼ਨ ਨੇ 2026 ਵਿੱਚ ਦੋ ਰਾਈਡਿੰਗ ਨਕਸ਼ੇ ਪੈਦਾ ਕੀਤੇ। ਇਸ ਆਡਿਟ ਨੇ ਉਹਨਾਂ ਦੀ ਤੁਲਨਾ ਕੀਤੀ — ਉਹੀ ਪਰੀਖਣ ਵਰਤਦੇ ਹੋਏ, ਦੋਵਾਂ ਉੱਤੇ ਬਰਾਬਰ ਲਾਗੂ ਕੀਤੇ — ਇਹ ਪੁੱਛਣ ਲਈ ਕਿ ਕੀ ਉਹ ਵੋਟਰਾਂ ਨਾਲ ਇੱਕੋ ਜਿਹਾ ਸਲੂਕ ਕਰਦੇ ਹਨ।`,badge:`ਅਧਿਕਾਰਤ Elections Alberta ਨਕਸ਼ੇ — ਮਈ 2026 ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਿਤ`,cover_note:`ਤਿੰਨੇ ਸਰਹੱਦ ਪ੍ਰਸਤਾਵਾਂ ਨੂੰ ਇੱਕੋ ਸਮੇਂ ਜ਼ੂਮ ਕਰਨ ਅਤੇ ਖੋਜਣ ਲਈ ਕਲਿੱਕ ਕਰੋ। ਵਿਊਪੋਰਟ ਪਿੰਨ ਕਰੋ ਅਤੇ ਨਕਸ਼ਿਆਂ ਵਿਚਕਾਰ ਫਲਿੱਪ ਕਰੋ — ਸਰਹੱਦਾਂ ਖਿਸਕਦੀਆਂ ਹਨ, ਵੋਟਰ ਆਪਣੀ ਥਾਂ ਰਹਿੰਦੇ ਹਨ। ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ।`,cover_note_1:`ਇਹ ਨਕਸ਼ਾ ਅੰਦਰ ਆਉਣ ਦਾ ਸਭ ਤੋਂ ਵਧੀਆ ਰਾਹ ਹੈ। ਜ਼ੂਮ ਕਰਨ ਅਤੇ ਖੋਜਣ ਲਈ ਇਸ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ। ਉੱਪਰਲੇ ਬਟਨ ਘੱਟ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਬਹੁ-ਗਿਣਤੀ ਦੇ ਨਕਸ਼ੇ, ਅਤੇ 2019 ਵਿੱਚ ਲਾਗੂ ਕੀਤੀਆਂ ਸਰਹੱਦਾਂ ਵਿਚਕਾਰ ਬਦਲਦੇ ਹਨ — ਜਾਂ ਤਿੰਨੋਂ ਨੂੰ ਲੇਅਰ ਕਰੋ ਇਹ ਦੇਖਣ ਲਈ ਕਿ ਉਹ ਕਿੱਥੇ ਠੀਕ ਨਾਲ ਵੱਖ ਹੁੰਦੇ ਹਨ। <strong>Detail</strong> ਹਰ ਪੋਲਿੰਗ ਖੇਤਰ ਨੂੰ 2023 ਵਿੱਚ ਲੋਕਾਂ ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗਦਾ ਹੈ; <strong>Trend</strong> ਜ਼ਿਲ੍ਹੇ ਅਨੁਸਾਰ ਪਾਰਟੀ ਛਾਂ ਜੋੜਦਾ ਹੈ (ਨੀਲਾ UCP, ਸੰਤਰੀ NDP); <strong>Lines</strong> ਸਰਹੱਦਾਂ ਨੂੰ ਚਾਲੂ-ਬੰਦ ਕਰਦਾ ਹੈ। <strong>Find</strong> ਨਾਮ ਅਨੁਸਾਰ ਕਿਸੇ ਵੀ ਰਾਈਡਿੰਗ ਉੱਤੇ ਪਹੁੰਚਦਾ ਹੈ।`,cover_note_2:`ਵਿਊਪੋਰਟ ਨੂੰ ਲਾਕ ਕਰਕੇ ਨਕਸ਼ਿਆਂ ਵਿਚਕਾਰ ਬਦਲਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ — ਦੇਖੋ ਕਿਵੇਂ ਸਰਹੱਦ ਖਿਸਕਦੀ ਹੈ ਜਦੋਂ ਕਿ ਹੇਠਾਂ ਦੇ ਵੋਟਰ ਉੱਥੇ ਹੀ ਰਹਿੰਦੇ ਹਨ। ਇਹ ਇੱਕ ਇਸ਼ਾਰੇ ਵਿੱਚ ਸਾਰਾ ਸਵਾਲ ਹੈ।`,cover_note_3:`ਜਦੋਂ ਤੁਹਾਡੀ ਖੋਜ ਮੁਕੰਮਲ ਹੋ ਜਾਵੇ, ਸੰਖੇਪ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ। ਪੂਰੇ ਤਕਨੀਕੀ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਸਰੋਤ ਸੈਕਸ਼ਨ ਦੇਖੋ। ਸਾਰਾ ਡੇਟਾ ਅਧਿਕਾਰਤ Elections Alberta ਸ਼ੇਪਫਾਈਲਾਂ ਅਤੇ ਹੋਰ ਸਰਕਾਰੀ ਅਤੇ ਓਪਨ-ਸੋਰਸ ਰਿਕਾਰਡਾਂ ਤੋਂ ਹੈ।`,image_alt:`ਅਲਬਰਟਾ ਦੇ ਚੋਣ ਜ਼ਿਲ੍ਹਾ ਨਕਸ਼ੇ — ਕਮਿਸ਼ਨ ਦੀ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ, 2023 ਦੇ ਵੋਟਾਂ ਮੁਤਾਬਕ ਰੰਗੀ`,map_hint:`ਇੰਟਰਐਕਟਿਵ ਤੌਰ ਤੇ ਖੋਜਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_title:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹਣ ਲਈ ਕਲਿੱਕ ਕਰੋ`,btn_aria:`ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ਾ ਖੋਲ੍ਹੋ`},editorial_intro:{heading:`ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਕੀ ਹੈ ਅਤੇ ਤੁਹਾਨੂੰ ਇਸ ਦੀ ਪਰਵਾਹ ਕਿਉਂ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ?`,p1:`ਅਲਬਰਟਾ ਦਾ ਹਰ ਵੋਟਰ ਇੱਕ <em>ਚੋਣ ਜ਼ਿਲ੍ਹੇ</em> ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ — ਸੂਬੇ ਦਾ ਇੱਕ ਹਿੱਸਾ ਜੋ ਵਿਧਾਨ ਸਭਾ ਲਈ ਇੱਕ ਵਿਅਕਤੀ ਨੂੰ ਚੁਣਦਾ ਹੈ। 87 ਜ਼ਿਲ੍ਹੇ ਹਨ। ਹਰ ਜ਼ਿਲ੍ਹਾ ਇੱਕ MLA ਚੁਣਦਾ ਹੈ। ਜਦੋਂ ਤੁਸੀਂ ਸੂਬਾਈ ਚੋਣ ਵਿੱਚ ਵੋਟ ਪਾਉਂਦੇ ਹੋ, ਤੁਸੀਂ ਉਸ ਜ਼ਿਲ੍ਹੇ ਲਈ MLA ਚੁਣ ਰਹੇ ਹੋ ਜਿਸ ਵਿੱਚ ਤੁਸੀਂ ਰਹਿੰਦੇ ਹੋ। ਜ਼ਿਆਦਾਤਰ ਅਲਬਰਟਾ ਦੇ ਲੋਕਾਂ ਦਾ ਵਿਧਾਨ ਸਭਾ ਨਾਲ ਪੂਰਾ ਸੰਪਰਕ ਇਹੀ ਹੈ: ਇੱਕ MLA, ਇੱਕ ਜ਼ਿਲ੍ਹਾ, ਇੱਕ ਵੋਟ।`,p2:`ਇਹ ਜ਼ਿਲ੍ਹੇ ਦੀਆਂ ਲਾਈਨਾਂ ਸਥਾਈ ਨਹੀਂ ਹਨ। ਲੋਕ ਚਲੇ ਜਾਂਦੇ ਹਨ, ਮੁਹੱਲੇ ਵੱਡੇ ਹੁੰਦੇ ਹਨ, ਪੇਂਡੂ ਖੇਤਰ ਖਾਲੀ ਹੁੰਦੇ ਹਨ, ਸ਼ਹਿਰ ਫੈਲਦੇ ਹਨ। ਹਰ ਅੱਠ ਤੋਂ ਦਸ ਸਾਲਾਂ ਬਾਅਦ, ਅਲਬਰਟਾ ਨੂੰ ਲਾਈਨਾਂ ਨੂੰ ਮੁੜ ਖਿੱਚਣਾ ਚਾਹੀਦਾ ਹੈ ਤਾਂ ਜੋ ਹਰ ਜ਼ਿਲ੍ਹਾ ਲਗਭਗ ਸਹੀ ਆਕਾਰ ਦਾ ਹੋਵੇ ਅਤੇ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰੇ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਅਸਲ ਵਿੱਚ ਹੁਣ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ। ਮੁੜ-ਖਿੱਚਣ ਵਾਲੀ ਸੰਸਥਾ <em>ਚੋਣ ਸਰਹੱਦ ਕਮਿਸ਼ਨ</em> ਹੈ — ਜੱਜਾਂ, ਵਕੀਲਾਂ, ਅਤੇ ਜਨਤਕ ਮੈਂਬਰਾਂ ਦਾ ਇੱਕ ਸੁਤੰਤਰ ਕਮਿਸ਼ਨ, ਨਾ ਕਿ ਸਿਆਸਤਦਾਨਾਂ ਦਾ।`,p3:`ਇਹੀ ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਹੈ। ਇਸ ਵਾਰ, ਸਟੈਂਡਰਡ ਪ੍ਰਕਿਰਿਆ ਨੇ ਕੁਝ ਅਸਾਧਾਰਨ ਪੈਦਾ ਕੀਤਾ। ਕਮਿਸ਼ਨ ਦੇ ਪੰਜ ਮੈਂਬਰ 3 ਬਨਾਮ 2 ਵਿੱਚ ਵੰਡੇ ਗਏ ਕਿ ਨਕਸ਼ੇ ਨੂੰ ਕਿਹੋ ਜਿਹਾ ਦਿਖਣਾ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਸਿਫ਼ਾਰਸ਼ ਉੱਤੇ ਸਹਿਮਤ ਹੋਣ ਦੀ ਬਜਾਏ ਉਹਨਾਂ ਨੇ ਦੋ ਤਿਆਰ ਕੀਤੀਆਂ: ਇੱਕ <em>ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਤਿੰਨ ਕਮਿਸ਼ਨਰਾਂ ਦੁਆਰਾ ਸਮਰਥਨ) ਅਤੇ ਇੱਕ <em>ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ</em> (ਦੋਆਂ ਦੁਆਰਾ ਸਮਰਥਨ)। ਦੋਵੇਂ ਮੇਜ਼ ਉੱਤੇ ਹਨ — ਅਤੇ ਵਿਧਾਨ ਸਭਾ ਨੇ ਦੋਵਾਂ ਨੂੰ ਪਾਸੇ ਰੱਖ ਦਿੱਤਾ ਹੈ। ਬ੍ਰੈਂਡਨ ਲੰਟੀ ਦੀ ਅਗਵਾਈ ਵਾਲੀ MLA ਦੀ ਇੱਕ ਵੱਖਰੀ ਕਮੇਟੀ — ਜਿਸਨੂੰ ਪ੍ਰੀਮੀਅਰ ਨੇ ਇਸ ਖਾਸ ਫੈਸਲੇ ਲਈ ਨਿਯੁਕਤ ਕੀਤਾ — ਹੁਣ ਸਰਕਾਰੀ ਮਤਾ 37 (21 ਅਪ੍ਰੈਲ 2026 ਨੂੰ ਪਾਸ) ਦੇ ਤਹਿਤ ਗਠਿਤ ਚਾਰ ਮੈਂਬਰਾਂ ਦੇ ਇੱਕ ਸੁਤੰਤਰ ਸਲਾਹਕਾਰ ਪੈਨਲ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦੀ ਹੈ ਜਿਸਨੂੰ 91 ਸੀਟਾਂ ਦਾ ਨਵਾਂ ਨਕਸ਼ਾ ਤਿਆਰ ਕਰਨ ਦਾ ਕੰਮ ਸੌਂਪਿਆ ਗਿਆ ਹੈ। ਨਵੰਬਰ 2026 ਤੋਂ ਪਹਿਲਾਂ ਵਿਧਾਨ ਸਭਾ ਨੂੰ ਉਸ ਨੂੰ ਮਨਜ਼ੂਰੀ ਦੇਣੀ ਚਾਹੀਦੀ ਹੈ ਜੋ ਕਮੇਟੀ ਪੇਸ਼ ਕਰਦੀ ਹੈ।`,p4:`ਇਹ ਤੁਹਾਡੇ ਲਈ ਕਿਉਂ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ: ਲਾਈਨਾਂ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਤੁਹਾਡਾ MLA ਕੌਣ ਹੈ। ਉਹ ਫੈਸਲਾ ਕਰਦੀਆਂ ਹਨ ਕਿ ਕਿਹੜੇ ਮੁਹੱਲੇ, ਕਸਬੇ, ਅਤੇ ਚਿੰਤਾਵਾਂ ਇਕੱਠੇ ਪ੍ਰਤੀਨਿਧਤਾ ਪ੍ਰਾਪਤ ਕਰਦੀਆਂ ਹਨ। ਜੇ ਤੁਹਾਡਾ ਸ਼ਹਿਰ ਇੱਕ ਦੀ ਥਾਂ ਚਾਰ MLAs ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਕੋਈ ਇੱਕ ਨੁਮਾਇੰਦਾ ਪੂਰੇ ਸ਼ਹਿਰ ਲਈ ਜਵਾਬਦੇਹ ਨਹੀਂ ਹੈ। ਜੇ ਤੁਹਾਡਾ ਹਿੱਤ ਸਮੁਦਾਇ — ਇੱਕ ਛੋਟਾ ਕਸਬਾ, ਇੱਕ ਪੇਂਡੂ ਖੇਤਰ, ਇੱਕ ਡਾਊਨਟਾਊਨ ਕੋਰ — ਜ਼ਿਲ੍ਹਿਆਂ ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ, ਸੂਬਾਈ ਫੈਸਲਿਆਂ ਉੱਤੇ ਤੁਹਾਡੀ ਆਵਾਜ਼ ਪਤਲੀ ਹੁੰਦੀ ਹੈ। ਨਕਸ਼ਾ ਇਹ ਵੀ ਆਕਾਰ ਦਿੰਦਾ ਹੈ ਕਿ ਕਿਹੜੀ ਪਾਰਟੀ ਸਰਕਾਰ ਬਣਾ ਸਕਦੀ ਹੈ, ਅਤੇ ਕਿਸ ਮਾਰਜਨ ਨਾਲ। ਆਡਿਟ ਦੀ ਖਾਸ ਖੋਜ (ਕਿ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਇੱਕ ਸੰਰਚਨਾਤਮਕ ਸਿਖਰ ਉੱਤੇ ਬੈਠੀ ਹੈ) ਉਹ ਕਾਰਨ ਹੈ ਜੋ ਤੁਸੀਂ ਇਸ ਸਾਈਟ ਨੂੰ ਪੜ੍ਹ ਰਹੇ ਹੋ, ਪਰ ਵਿਆਪਕ ਸਵਾਲ ਪੁਰਾਣਾ ਹੈ ਅਤੇ ਹਰ ਮੁੜ-ਜ਼ਿਲ੍ਹਾਬੰਦੀ ਚੱਕਰ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ: ਕੀ ਲਾਈਨਾਂ ਇਹ ਪ੍ਰਤੀਬਿੰਬਤ ਕਰਦੀਆਂ ਹਨ ਕਿ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਰਹਿੰਦੇ ਹਨ, ਜਾਂ ਉਹ ਉਸ ਰਾਜਨੀਤੀ ਨੂੰ ਆਕਾਰ ਦਿੰਦੀਆਂ ਹਨ ਜੋ ਬਾਅਦ ਵਿੱਚ ਆਉਂਦੀ ਹੈ?`,p5:`ਇਸ ਪੰਨੇ ਦਾ ਬਾਕੀ ਹਿੱਸਾ ਇਸ ਦੇ ਪਾਰ ਚੱਲਦਾ ਹੈ ਕਿ ਦੋ ਪ੍ਰਸਤਾਵਿਤ ਨਕਸ਼ੇ ਅਸਲ ਵਿੱਚ ਕੀ ਕਰਦੇ ਹਨ।`,key_terms_lead:`ਇਸ ਸੈਕਸ਼ਨ ਦੇ ਮੁੱਖ ਸ਼ਬਦ — ਪੜ੍ਹਨ ਲਈ ਕਲਿੱਕ ਕਰੋ:`},boundary:{heading:`ਇਹ ਆਡਿਟ ਤੁਹਾਨੂੰ ਕੀ ਦੱਸ ਸਕਦਾ ਹੈ ਅਤੇ ਕੀ ਨਹੀਂ`,can_1:`1.45 ਕਰੋੜ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਨਕਸ਼ਿਆਂ ਵਿੱਚੋਂ 1 ਤੋਂ ਘੱਟ ਨੇ ਚਾਰੇ ਅੰਕੜਾ ਮਾਪਾਂ ਨੂੰ ਮਿਲਾ ਕੇ ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਜਿੰਨੇ ਅਤਿਅੰਤ ਨਮੂਨੇ ਪੈਦਾ ਕੀਤੇ।`,can_2:`ਘੱਟ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ 5 ਵਿੱਚੋਂ 4 ਪੂਰਵ-ਰਜਿਸਟਰਡ ਸੰਰਚਨਾਤਮਕ ਪਰੀਖਣਾਂ ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ; ਪੰਜਵਾਂ (ਐਂਕਰਿੰਗ) ਨਿਰਪੱਖ ਹੈ — ਦੋਵੇਂ ਨਕਸ਼ੇ ਕੈਨੇਡੀਅਨ ਮਿਆਰ ਦੇ ਅੰਦਰ ਹਨ। ਬਹੁ-ਗਿਣਤੀ ਦੀ ਪ੍ਰਸਤਾਵ ਚਾਲੂ ਹੋਏ 4 ਵਿੱਚੋਂ 0 ਵਿੱਚ ਅਸਫ਼ਲ ਰਹਿੰਦੀ ਹੈ।`,can_3:`ਇਹ ਨਤੀਜੇ ਉਹਨਾਂ ਨਕਸ਼ਿਆਂ ਨਾਲ ਮੇਲ ਖਾਂਦੇ ਹਨ ਜੋ ਮਜ਼ਬੂਤ ਪਾਰਟੀ ਪ੍ਰਭਾਵ ਪੈਦਾ ਕਰਦੇ ਹਨ, ਅਤੇ ਬੇਤਰਤੀਬੀ ਤੁਲਨਾਤਮਕ ਸੈੱਟ ਦੇ ਉਤਪਾਦਨ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ।`,cant_1:`ਆਡਿਟ ਇਹ ਸਥਾਪਤ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਕਿਸੇ ਕਮਿਸ਼ਨਰ ਨੇ ਉਹਨਾਂ ਪਾਰਟੀ ਪ੍ਰਭਾਵਾਂ ਦੀ ਨੀਅਤ ਰੱਖੀ ਜੋ ਇਹ ਮਾਪਦਾ ਹੈ। ਸਰਹੱਦੀ ਜਿਓਮੈਟਰੀ ਨੀਅਤ ਨੂੰ ਪ੍ਰਗਟ ਨਹੀਂ ਕਰ ਸਕਦੀ।`,cant_2:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਲੰਟੀ ਕਮੇਟੀ ਕੀ ਚੁਣੇਗੀ, ਨਵੰਬਰ 2026 ਦੀ ਵੋਟ ਕੀ ਹੋਵੇਗੀ, ਜਾਂ ਅਲਬਰਟਾ ਦੇ ਲੋਕ ਕਿਵੇਂ ਪ੍ਰਤੀਕਿਰਿਆ ਕਰਨਗੇ।`,cant_3:`ਆਡਿਟ ਇਹ ਭਵਿੱਖਬਾਣੀ <strong>ਨਹੀਂ</strong> ਕਰਦਾ ਕਿ ਜੇ ਕਿਸੇ ਪ੍ਰਸਤਾਵ ਖਿਲਾਫ਼ ਚਾਰਟਰ ਚੁਣੌਤੀ ਦਾਇਰ ਕੀਤੀ ਜਾਂਦੀ ਤਾਂ ਅਦਾਲਤ ਕਿਵੇਂ ਫੈਸਲਾ ਕਰੇਗੀ।`,cant_4:`ਆਡਿਟ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀਗਤ ਵੋਟਰ ਨੂੰ ਇਹ <strong>ਨਹੀਂ</strong> ਦੱਸਦਾ ਕਿ ਕੀ ਪੋਜੀਸ਼ਨ ਲਵੇ ਜਾਂ ਇਸ ਜਾਣਕਾਰੀ ਨਾਲ ਕੀ ਕਰੇ। ਇਹ ਫੈਸਲਾ ਤੁਹਾਡਾ ਹੈ।`}},"zh-Hans":{selector:{label:`选择语言`},disclaimer:{text:`本网站由 AI 翻译。在翻译进行期间,部分内容可能仍以英文显示。如果你发现错误或希望帮助翻译本项目,请%s。`,link_label:`联系我们`},opener:{heading:`这是为谁准备的?`,body:`为我们。为我们所有人。无论你是乡村居民、城市居民、好奇者、政治爱好者、记者、律师、学者还是政治人物——我们所有人。因为这影响着我们所有人。无论你是否喜欢执政党,分裂的委员会所产生的结果都是前所未有的。它给了我们一个前所未有的机会,得以窥视这台机器的内部运作。现在我们可以建立一个基准——一系列测试,之后的一切都可以以此为标准进行评估。让我向你展示我所发现的。`},stakes:{q1:{heading:`所提议的地图是否构成选区不公划分?`,body:`"Gerrymander"(选区不公划分)并非加拿大法院使用的术语。但如果以大多数人理解的日常意义来衡量——本次审计的证据合理地支持将<em>少数派提议</em>(若被采纳)称为一份严重经过党派划分的地图。本次审计运行的五项结构性测试中有四项标记了<em>少数派提议</em>,没有任何一项标记另一份提议(<em>多数派提议</em>);第五项测试对两份地图均为中性。`,footnote:`"多数派"和"少数派"的称谓源自选举边界委员会(由 Miller 法官主持)内部 3 比 2 的分裂——该委员会未能形成单一建议,而是提出了两份相互竞争的提议。立法机构此后已将两份提议均搁置,并将选区重划事宜交予一个由 Brandon Lunty(由省长任命的 MLA)主持的五人 MLA 委员会;该委员会监督一个独立的四人咨询小组——两名由省长提名(Monte Solberg 阁下和 Darwin Durnie),两名由反对党领袖提名(Gerard Kennedy 博士和 Brent Robinson)——负责在 2026 年 11 月截止日期前提出一份全新的 91 席选区方案。`},q2:{heading:`"Gerrymander" 在加拿大法律中是什么意思?`,body:`没有这一术语。加拿大的检验标准不同:即边界是否在《加拿大权利与自由宪章》第 3 条之下给予选民<em>有效代表权</em>。少数派提议在有效代表权这一标准下提出了严重问题;只有法官才能给出确定性的回答,而目前尚无人提起诉讼。`},q3:{heading:`这对阿尔伯塔人意味着什么?`,body:`在 50/50 的省级投票情况下,审计的测量将少数派提议置于结构性极端:在 101 万张中立比较地图中,产生类似议席不平衡的不到 100 张。这种不平衡之所以重要,是因为在 87 席中获得 58 席(三分之二的超级多数),执政党便可解锁非常规的程序权力。它可以免除标准通知期,并在一天内将公共法案推过多个立法阶段,绕过通常约束它的审议性检查。少数派提议的倾斜是否大到足以在<em>非</em> 50/50 的投票比例下将一个政党推过 58 席门槛,这是本次审计尚未测试的问题。这种不平衡是否可接受,这是属于阿尔伯塔人的问题,而非本次审计的问题。`},cta_law:`阅读法律背景 →`,cta_methods:`查看我们如何测试 →`,scorecard_h:`评分卡`,scorecard_fig_alt:`散点图:横轴为效率差,纵轴为未通过的结构性测试数量。2019 年颁布的地图和 2026 年多数派地图集中在左下角的安全区域。2026 年少数派地图单独出现在右上角的离群区域。`,scorecard_fig_caption:`两条评估路径合并到同一张图中。横轴:党派公平性数值的偏斜程度(越靠右,越有利于 UCP)。纵轴:地图未通过的五项结构公平性测试的数量。左下角是中立程序通常会落入的安全区域;右上角是离群区域。2019 年颁布的地图和 2026 年多数派地图位于安全区域。2026 年少数派地图单独位于离群区域。`,scorecard_intro:`两项独立测量,使用相同的预先注册阈值,同时应用于两份地图。结构路径只使用线条的形状——不使用任何选举结果。数字路径检验线条如何将选票转化为议席。两条路径得出相同的结论。`,scorecard_close:`两项独立测量,一个答案。这种汇合是本次审计最强的单一信号。`},head:{title:`阿尔伯塔选举边界审计`,meta_description:`对阿尔伯塔 2026 年选举边界委员会的统计审计——1,010,000 张中立地图、Elections Alberta 官方 shapefile、预先注册的测试。`},nav:{skip_to_content:`跳至正文`,home_aria:`返回顶部`,theme_aria:`切换深色 / 浅色模式`,theme_title:`切换深色模式`,nav_aria:`打开目录`,drawer_top:`↑ 顶部`,stakes:`利害关系`,findings:`发现`,history:`历史`,reform:`改革`,notes:`附注`,group_overview:`总览`,group_audit:`审计`,group_context:`背景`,group_forward:`未来展望`,group_apparatus:`附录`,why:`为什么这件事重要?`,map:`地图概览`,split:`委员会如何分裂`,litmus:`1,010,000 张地图试金石测试`,crack_pack:`分散、集中、排空`,for_you:`这对你意味着什么`,impact:`实地影响`,gerrymanders:`"干净"的选区不公`,history_full:`选区不公划分的历史`,canada:`加拿大的不同之处`,november:`十一月`,lunty:`Lunty`,invisible:`隐形`,suggestions:`改革建议`,retractions:`撤回`,references:`参考资料`,resources:`资源`,technical:`技术资料`},hero:{h1:`阿尔伯塔选举边界审计`,subtitle:`阿尔伯塔的委员会在 2026 年提出了两份选区地图。本次审计对它们进行了比较——使用相同的测试,平等地应用于两者——以询问它们是否以同样的方式对待选民。`,badge:`Elections Alberta 官方地图——2026 年 5 月发布`,cover_note:`点击以缩放并同时探索三份边界提议。固定视口并在地图之间切换——边界移动,选民不变。向下滚动查看分析。`,cover_note_1:`这张地图是最好的入口。点击它即可缩放和探索。顶部按钮可在少数派地图、多数派地图和 2019 年颁布的边界之间切换——或叠加三者以查看它们的分歧之处。<strong>Detail</strong> 根据 2023 年人们的投票情况为每个投票区上色;<strong>Trend</strong> 按选区添加党派色调(蓝色 UCP,橙色 NDP);<strong>Lines</strong> 切换边界的显示与隐藏。<strong>Find</strong> 按名称跳转到任意选区。`,cover_note_2:`试试锁定视图并在地图之间切换——观察一条边界在下方选民保持不动时如何移动。整个问题,用一个动作就能体现。`,cover_note_3:`当你探索完毕后,向下滚动查看摘要。如需完整的技术分析,请参阅"资源"部分。所有数据均来自 Elections Alberta 官方 shapefile 以及其他政府和开源记录。`,image_alt:`阿尔伯塔选区地图——委员会少数派提议,按 2023 年投票上色`,map_hint:`点击进行交互式探索`,btn_title:`点击打开交互式地图`,btn_aria:`点击进行交互式探索`},boundary:{heading:`本次审计能告诉你什么、不能告诉你什么`,can_1:`少数派地图的几何形态在<em>完全不使用任何选举数据</em>的情况下,跨越了五项预先注册的结构性阈值中的四项。第五项(锚定)为中性。多数派地图在已触发的四项测试中跨越了零项。这些测试测量的是边界线本身的属性——选区形状、市政锚定、人口分散度——它们在任何选票被计算之前就得出结论。`,can_2:`另外,当引入选举数据时,少数派地图位于按相同法定规则算法生成的 101 万张比较地图的第 99.99 百分位。在那 101 万张中立地图中,达到相同议席不平衡的不到 100 张。在中立绘图过程下,综合统计信号约为 1450 万分之一。两个独立工具——几何和统计——得出相同结论。`,can_3:`少数派提议中包含的三种配置,曾被委员会主席 Miller 法官在多数派报告 §5.8.2 和附录 C 中以书面形式标记。本次审计的测试在不了解他的标记的情况下运行,并浮现出相同的区域。第三个独立工具——司法——汇合到相同的边界上。`,cant_1:`本次审计<strong>未能</strong>证明任何委员有意制造其所测量的党派效应。边界几何无法揭示意图。`,cant_2:`本次审计<strong>不</strong>预测 Lunty 委员会会做出什么选择,2026 年 11 月投票结果如何,或阿尔伯塔人会如何反应。`,cant_3:`本次审计<strong>不</strong>预测如果对任一提议提起《宪章》诉讼,法院将如何裁决。`,cant_4:`本次审计<strong>不</strong>主张 1450 万分之一这一数字是发生选区不公划分的概率。该数字是少数派几何形态在中立算法零假设下的尾部概率。它是中立零假设不可信的证据。它不是党派意图的后验概率——那个问题需要几何无法提供的证据。`,cant_5:`本次审计<strong>不</strong>告诉任何选民应采取什么立场或如何处理这些信息。这是你自己的选择。`},editorial_intro:{heading:`什么是选区重划,以及为什么它重要`,p1:`阿尔伯塔的每一位选民都生活在一个<em>选区</em>中——省份的一个切片,负责选出一位省议会议员。共有 87 个选区。每个选区选出一位 MLA。当你在省级选举中投票时,你是在为你所居住的选区选 MLA。对于大多数阿尔伯塔人来说,这就是与立法机构的全部联系:一位 MLA,一个选区,一张选票。`,p2:`这些选区界线并非永久。人会搬家,社区会扩大,乡村人口会变少,城市会扩张。每隔八到十年,阿尔伯塔应当重新划界,以使每个选区大致大小合适,并反映阿尔伯塔人现在的实际居住情况。负责重新划界的机构是<em>选举边界委员会</em>——一个由法官、律师和公众成员组成的独立委员会,而非政客。`,p3:`这就是标准程序。这一次,标准程序产生了不寻常的结果。委员会的五名成员就地图应是什么样子分裂成了 3 比 2,他们没有达成一项建议,而是提出了两份:一份<em>多数派提议</em>(由三位委员支持)和一份<em>少数派提议</em>(由两位支持)。两份都摆在桌上——而立法机构已将两份都搁置。一个由 Brandon Lunty 主持的独立 MLA 委员会——由省长为此特定决定任命——现监督一个依据政府第 37 号议案(2026 年 4 月 21 日通过)组建的四人独立咨询小组,负责制定一份全新的 91 席选区地图。立法机构必须在 2026 年 11 月之前批准该委员会提交的方案。`,p4:`为什么这对你重要:这些界线决定了谁是你的 MLA。它们决定了哪些社区、城镇和关切被一起代表。如果你的城市被切分到四位 MLA 而不是一位,没有任何一位代表对整个城市负责。如果你的利益共同体——一个小镇、一个乡村地区、一个市中心——被划分到不同的选区,你在省级决策中的声音就会被稀释。这张地图还塑造了哪个政党能组建政府、以何种边际差距执政。本次审计的具体发现(少数派提议处于结构性极端)是你正在阅读本网站的原因,但更广泛的问题更古老,适用于每一个选区重划周期:这些界线反映了阿尔伯塔人的实际居住方式,还是塑造了之后的政治?`,p5:`本页的其余部分将讲解这两份提议地图实际上做了什么。`,key_terms_lead:`本节关键术语——点击阅读:`},editorial_reflect:{heading:`间章:这对你和你的社区意味着什么`,intro_p1:`暂时把哪个政党赢得或失去议席的问题放在一边。政客和政党往往将其框定为立法机关权力集中的争斗,在立法层面确实如此。但立法机关的权力集中并不是你体验这些地图的地方。你体验这些地图,是通过关于你自己选区的三个具体问题:`,intro_q1:`你的 MLA 住在哪里?`,intro_q2:`他们是否投身于你的社区?`,intro_q3:`中心的诉求是否会压过末梢的诉求?`,intro_p2:`其他所有框架——党派优势、超级多数门槛、统计极端——最终都指向这三个问题。下方的五个层级讲解了每份提议地图如何在五个尺度上回答这些问题。`,you_h:`你。`,you_p:`你的选区决定了谁在立法机关代表你。目前你居住在 87 个选区中的一个。在两份提议地图下,你可能居住在另一个选区——可能有一位不同的 MLA,可能与不同的邻近社区绑定。如果你不知道自己目前在哪个选区,或者谁是你的 MLA,你并不孤单:大多数阿尔伯塔人都说不出自己 MLA 的名字。但边界线并不抽象。它们决定了谁的电话挂在你当地代表的办公室墙上、谁的社区请愿书上会附上你的名字、你的 MLA 首先听到谁的关切。本网站上的邮编查询会显示你在每份提议下所属的选区。如果你的选区变了,你的代表就变了——而你的代表与你社区的关系也会随之改变。`,community_h:`你的社区。`,community_p:`社区也并不抽象。一所高中的学区、一个商会、一个信仰团体、一个邻里协会——这些都是有共同地方关切的真实人群。当一条边界线穿过它们时,没有任何一位 MLA 对整体负责。以少数派提议下的 Airdrie 为例:一座约 85,800 人的城市被切成四个选区,每个选区都与不同的乡村腹地绑定。没有任何一位代表对整个 Airdrie 作为一座城市负责。同样的动力出现在任何被分割的城镇、社区或公认利益共同体上——分割越严重,代表性就越弱。审计测量<em>市政锚定</em>(每个选区的周界中有多少比例沿着现有市政界线),少数派提议在锚定测试上的得分明显低于多数派。`,municipality_h:`你的市政当局。`,municipality_p:`当一座城市被分散在多位代表之间时,它在省级决策中谈判的能力就会削弱。一个市议会请求公共交通资金、一个学校董事会就新学校进行谈判、一位市长游说高速公路延伸——当城市能指出几位对整个城市负责的 MLA 时,这些事情都会进行得更顺利。少数派提议将 Calgary 西北象限拆分到多个选区,其得票模式提示在<em>分散</em>(将一方选民散布在多个低差距议席中)之上叠加了<em>集中</em>(将另一方选民集中到几个高差距议席中)。这一模式是否有意为之,是本次审计无法回答的问题——边界几何不揭示意图。它能说明的是,四项统计指标标记的选区与结构性测试标记的选区相同,而替代提议并未产生相同的指纹。`,region_h:`你的区域。`,region_p1:`如果你住在阿尔伯塔的城市之外,你可能注意到关于边界的政治讨论似乎总是以城市为中心。这是合理的抱怨,所以让我们直接说明本次审计对乡村阿尔伯塔说了什么和没说什么。`,region_p2:`它<strong>没有</strong>说:乡村阿尔伯塔议席太多。EBCA 允许选区人口浮动最高达 25%,这样一位乡村 MLA 就不必代表南法国那么大的地理区域。加拿大法院将这种差异视为合法。两份提议地图都保留了这一点。本次审计中的任何内容都不会改变它。`,region_p3:`它<strong>确实</strong>说:在少数派提议的几个地方,乡村社区作为<em>末梢</em>被连接到人口中心位于城市的选区上。看看少数派提议如何处理 Airdrie——一座约 85,800 人的城市,被切成四个选区,每一个都延伸到一段不同的乡村腹地。每个新选区的人口中心是城市切片,而不是乡村末梢。从这种选区当选的 MLA 最有可能在选票所在地居住、竞选并优先考虑那里——这意味着以前由专门的乡村 MLA 代表的乡村社区,变成了一个以城市为主导的议席的后半段。这种模式在少数派提议中反复出现,而在多数派提议中并非如此。`,region_p4:`本次审计并未提议从乡村阿尔伯塔夺走议席。它质疑的是,这些线条是否尊重这些议席本应代表的乡村社区,或者乡村地理是否被用作压舱物,将城市选票吸收到中心位于他处的选区中。如果你住在那些乡村末梢之一,哪份地图被采用就决定了你的 MLA 是代表你实际居住的乡村社区,还是代表一个其线条恰好包含你土地的城市选区。`,province_h:`你的省份。`,province_p:`立法机关是你将每个选区对上述三个问题的回答加总后得到的结果。如果大多数选区都锚定于其 MLA 实际居住的社区,立法机关就代表这些社区。如果大多数选区都将乡村末梢连接到城市中心,立法机关就代表中心——而末梢得到的只是剩余的关注。党派问题——哪个党赢得多数——是它的下游。超级多数问题——一个政党是否在 87 席中跨过 58 席并解锁程序捷径,如免除通知期或在单一天内加速法案通过多个阶段——是<em>那个</em>问题的下游。在假设的 50/50 省级分歧下,审计的测量将少数派提议置于结构性极端:在 101 万张中立比较地图中,产生相同议席不平衡的不到 100 张。这种不平衡是否会在阿尔伯塔人实际投出的票数下将一个政党推过 58 席,这是本次审计尚未直接测试的问题;本页顶部的开篇问题对这一空白做出了诚实的说明。这些问题的答案是否重要到值得采取行动,再一次,是属于你自己的问题。`},editorial_history:{heading:`背景:选区不公划分简史`,p1:`这个词来自 1812 年。马萨诸塞州州长 Elbridge Gerry 签署批准了一份州参议院地图,其中的选区因严重偏袒他所在的政党而极度扭曲,以至于波士顿的一位漫画家把其中一个画成了蝾螈——有翅膀、爪子和分叉的舌头。漫画家的双关语 <em>Gerry-mander</em>(杰利蝾螈)就此流传下来。这种形状也流传下来:两个世纪后,这个词仍然意味着划定选举界线以制造党派性结果。`,p2:`这一术语持续存在,是因为问题持续存在。在任何选民从地理选区中选出代表的地方,都得有人划线,而线可以以多种方式划出。不同国家对谁该划线、以及什么应当约束他们,得出了不同的答案。`,p3:`<strong>美国</strong>将党派性选区不公划分视为联邦法院在大多数情况下无法解决的问题。在 <em>Rucho v. Common Cause</em>(2019 年)案中,美国最高法院裁定党派性选区不公划分是其管辖之外的"政治问题"。一些州(加利福尼亚、密歇根)的回应是创设独立公民委员会以自行划线;另一些州(德克萨斯、北卡罗来纳)则继续公开地划出党派性地图,并以 <em>Rucho</em> 允许此举为由进行辩护。`,p4:`<strong>英国</strong>使用四个常设边界委员会——英格兰、苏格兰、威尔士和北爱尔兰各一个——由法官和高级公务员组成。它们大约每八年依固定规则(人口平等、地理连贯性、尊重地方政府边界)重新划线。理论上议会可以拒绝委员会的建议,但实际上几乎从不这样做;按惯例,委员会的判断居于主导地位。`,p5:`<strong>澳大利亚</strong>将这项工作委托给澳大利亚选举委员会,这是一个对选举管理和边界拥有完全权力的联邦独立机构。当一个州的议席数发生变化或距上次划界已过去七年时,自动进行重新划分。专员的决定可在程序理由上被复审,但不能在党派理由上被复审。如在英国一样,美国人所知的选区不公划分在这里几乎闻所未闻。`,p6:`这三种情况划定了光谱:法院不介入(美国)、有强力议会尊重的独立委员会(英国)、以及拥有完全权力的常设独立机构(澳大利亚)。加拿大处于另一种不同的位置——这是下一节的主题。`},glossary:{more_link:`了解更多 →`,"electoral-district":{term:`选区(ED)`,definition:`选出一位省议会议员的地理区域。首次使用后通常简写为 "ED"。每个 ED 有一位 MLA。("riding" 一词通常指联邦选区;在省级语境中,正确的术语是选区(electoral district)。)`},riding:{term:`Riding`,definition:`在加拿大用语中,这通常指联邦选区。阿尔伯塔省级的对应概念称为"选区"(electoral district, ED)。本次审计始终使用省级术语。`},mla:{term:`MLA(省议员)`,definition:`立法议会成员(Member of the Legislative Assembly)——从一个选区选出、在阿尔伯塔立法机构代表该选区的人。`},ucp:{term:`UCP`,definition:`United Conservative Party(联合保守党)——阿尔伯塔现任执政省级政党。2017 年由进步保守党与野玫瑰党合并而成;自 2019 年起执政。`},ndp:{term:`NDP`,definition:`New Democratic Party(新民主党,阿尔伯塔 NDP)——阿尔伯塔现任正式反对党。阿尔伯塔 NDP 曾于 2015 年至 2019 年执政。`},gerrymander:{term:`Gerrymander(选区不公划分)`,definition:`划定的地图使一个政党赢得的议席多于其得票份额所示。该词源自 1812 年马萨诸塞州一个形似蝾螈的选区。它在加拿大不是法律术语,但其概念被广泛研究。`},cracking:{term:`Cracking(分散)`,definition:`一种选区不公划分技巧,将一个投票群体分散到多个选区,使其在任何一个选区都无法达到多数。例如,将一座城市分散到四个选区,使其选民在每个选区中都处于少数。`},packing:{term:`Packing(集中)`,definition:`一种选区不公划分技巧,将一个政党的选民集中到少数几个选区。该党在这些选区压倒性获胜,但"浪费"了许多选票——使其可在其他选区竞争的选民减少。`},draining:{term:`Draining(排空)`,definition:`本次审计用来描述分散与集中的后续效应的一个术语:这些技巧产生的浪费选票被推到战略性选择的位置,改变邻近选区的政治特征。这是审计自己的框架,而非选区重划文献中既有的概念——审计测试了这种效应并发现了与之一致的结果,但将其视为探索性的,而非已确立的方法论。`},anchoring:{term:`Anchoring(锚定)`,definition:`提议的边界沿现有市政界线(市界、镇界)的紧密程度。高度锚定的地图大体上尊重这些线;松散锚定的地图经常偏离它们——尤其在具有政治意义的位置偏离,这是一种结构性警示信号。`},"charter-s3":{term:`《宪章》第 3 条`,definition:`《加拿大权利与自由宪章》中保障公民投票权的条款。加拿大法院将其解释为不是严格的"一人一票"规则,而是"有效代表权"的权利。`},"effective-representation":{term:`有效代表权(Effective representation)`,definition:`加拿大法院在判断选举边界时适用的标准。它意味着选民应有有意义的声音——不只是选区人口数字上的平等,还包括对社区联系、地理和少数派代表的承认。主要表述来自加拿大最高法院 1991 年的《Saskatchewan Reference》(萨斯喀彻温省判例)。`},ebc:{term:`选举边界委员会(EBC)`,definition:`根据 EBCA 划定阿尔伯塔省级选举边界的机构。2026 年委员会由 Miller 法官主持,委员中以 3 比 2 分裂,产生了两份相互竞争的提议(多数派与少数派提议),而非单一建议。`},"lunty-committee":{term:`Lunty 委员会`,definition:`由 Brandon Lunty(由省长任命的 MLA)主持的五人 MLA 选举边界特别专责委员会,根据立法议会的第 19 号议案(2026 年 4 月 16 日)成立,该议案将两份委员会报告均搁置。该委员会监督一个独立的四人独立咨询小组,后者根据政府第 37 号议案(2026 年 4 月 21 日通过)组建,实际负责绘制地图;委员会随后须在 2026 年 11 月截止日期前向立法机关报告。这两个机构均与 EBC 分离,且不属于标准的 EBCA 程序。`},"advisory-panel":{term:`独立咨询小组`,definition:`根据政府第 37 号议案 C(d)(ii) 条款由 Lunty 委员会任命的四人小组,负责绘制 91 席的边界建议。省长提名 Monte Solberg 阁下和 Darwin Durnie;反对党领袖提名 Gerard Kennedy 博士和 Brent Robinson。第五个席位——一位在职或退休法官担任主席——在阿尔伯塔代理首席大法官拒绝提名后空缺。`},ebca:{term:`EBCA`,definition:`《Electoral Boundaries Commission Act》(阿尔伯塔选举边界委员会法)——管理该省选举边界如何划定的法律。它设立委员会、公开听证程序以及新地图生效的规则。`},fsa:{term:`前置分拣区(FSA)`,definition:`加拿大邮政编码的前三个字符(字母-数字-字母部分)。阿尔伯塔境内约有 270 个 FSA。大多数完全落在单个选区内。`}},body:{section_link_aria:`链接到该节`,the_map:{heading:`1:地图`,p1:`封面地图是本次审计中最好的一张图。下面说明如何阅读它。`,p2:`阿尔伯塔被划分为 4,765 个投票区——Elections Alberta 用于点算投票站选票的小地理区域。每一个都按 2023 年其中选民的实际投票情况上色:NDP 票集中的地方为橙色,UCP 票集中的地方为蓝色。但颜色只在大量人口居住的地方才会变深变饱和。一个覆盖数百平方公里草原或农田的投票区会保持淡色——几乎不可见。地图在有人的地方点亮,在没人的地方淡出。`,p3:`这与你在选举之夜看到的阿尔伯塔非常不同。大多数选举地图根据谁获胜将整个选区涂成纯蓝或纯橙。乡村选区地理面积大,UCP 赢得大多数,所以选举之夜的阿尔伯塔看起来像一片蓝墙,在 Edmonton 和 Calgary 有几个橙色小口袋。封面地图使用相同的选票和相同的地理——但将它们按人们实际居住的位置加权显示。出现的是一个大部分人口集中在密集城市弧线中的省份,而这些城市的投票方式与通常代表它们的乡村地图非常不同。`,p4:`颜色之上绘制的边界线是少数派委员会提议的 89 个选区——这是本次审计最终批评的地图。审计的工作是询问这些线条对它们下方的人民做了什么。`,p5:`这张图使利害关系变得清晰。一个在标准地图上看起来以一种方式投票的省份,实际上是一个大多数人口居住在以另一种方式投票的区域的省份。一旦人口在边界选择下变得可见,这些选择就不再看起来是随机的。`},structural_results:{heading:`结构审计结果——在任何统计之前:`,body:`多数派地图跨越了<strong>五项中的零项</strong>预先注册结构性阈值。少数派地图跨越了<strong>五项中的四项</strong>;第五项(锚定)为中性——两份地图均落在 70–85% 的加拿大常态范围内。这些是几何测量——人口分散度、<button class="vocab-term" data-def="选区边界沿现有市政与城市界线而不切穿它们的紧密程度" aria-expanded="false">市政锚定</button>、Airdrie 拆分数、Calgary 西北人口超出量,以及委员会主席 Miller 法官本人在书面中(多数派报告 §5.8.2 与附录 C)标记的七个边界配置——不需要选举数据、也不需要统计抽样器。下一节针对 1,010,000 张计算机生成的中立地图测试两份地图,通过完全不同的工具得出相同结论。三个独立工具——几何、司法和统计——汇合。`},clean:{heading:`6:当一张看起来公平的地图其实不公平`,legal_label:`关于法律术语的说明`,legal_body:`"Gerrymandering"在加拿大法律中没有法律定义。本报告通篇在其日常政治意义上使用该词——即为党派优势操纵选举边界。加拿大实际适用的法律检验不同:边界是否在《加拿大权利与自由宪章》第 3 条之下提供"有效代表权"(加拿大最高法院在 1991 年《Reference re Provincial Electoral Boundaries (Saskatchewan)》中设定的宪法标准),以及委员会是否遵循了阿尔伯塔《Electoral Boundaries Commission Act》(EBCA)的规则。审计的发现是与这些法律问题相关的证据。它们不是对法律定义违法行为的证明,本报告也不以此种术语描述它们。`,intro_p1:`对任何选举地图最干净的单一问题是:如果该省的选票在两大主要政党之间恰好平分,该地图会产生什么样的议席数?这保持选民基数不变,只问地图本身做了什么。`,intro_p2:`为了回答这个问题,审计生成了 1,010,000 张计算机模拟、数学上中立的阿尔伯塔地图。模拟使用 Elections Alberta 官方 shapefile,并遵守委员会所使用的完全相同的法定规则和地理边界。然后将委员会的两份 2026 年地图放入该分布,以查看它们的常态程度。模拟运行四条独立链,每条 252,500 步,基础种子取自 Cloudflare drand 信标,并在执行前在 OSF 预先注册。`,howmcmc_label:`模拟如何工作`,howmcmc_mcmc:`<strong>MCMC(马尔可夫链蒙特卡罗)</strong>是一种通过从起点随机步进探索大空间的方法——这里是所有合法阿尔伯塔地图的空间。每一步在相邻选区之间提出一次小的交换;如果结果仍在法定规则内,它就成为新的起点。足够步数后,访问过的地图形成合法方案的代表性样本。模拟从 Cloudflare drand 公共随机性信标获取种子,以防止对起始条件的任何择优挑选。`,howmcmc_recom:`<strong>ReCom(选区重划编译器)</strong>是这里使用的具体算法。每一步将两个相邻选区合并为一个区域,并随机重新分割为两个新的有效选区,通过结构保留连通性和人口平衡——因此该算法从不需要拒绝无效提案。`,prereg_label:`预先注册`,prereg_body:`预先注册意味着在查看任何数据之前,写下确切的测试、阈值和预期方向,并将这些承诺锁定在公开的带时间戳记录中。开放科学框架(OSF)是本次审计的承诺存放的公共仓库。它防止事后拟合:如果结果未能干净地呈现,阈值不能事后被改变并被呈现为一直就是检验。本次审计中所有五项结构性测试和四项党派公平性指标在任何模拟运行之前都在 OSF 注册。`,neutral_p:`在阿尔伯塔,中立答案不是 50/50。<em>在 1,010,000 张计算机模拟的合法阿尔伯塔地图中,中位地图在 50/50 选票下只给 UCP 44.8% 的议席</em>——在中立选票下,典型的阿尔伯塔地图会给予 NDP 微弱的议席多数。这与直觉相反,但是机械性的:乡村 UCP 选民以 60-40 的差距赢得选区(浪费了许多"多余"的 UCP 票),而城市 NDP 选民以更紧的 51-49 差距赢得选区(每次胜利浪费的 NDP 票更少)。在中立情况下,NDP 在议席效率上占优。`,full_dist:`来自标准 1,010,000 张地图模拟的完整分布:`,t1_col_a:`地图位置`,t1_col_b:`50/50 选票下 UCP 议席`,t1_r1_a:`中位阿尔伯塔地图`,t1_r1_b:`44.8% —— NDP 微弱议席多数`,t1_r2_a:`第 95 百分位地图`,t1_r2_b:`47.1%`,t1_r3_a:`第 99 百分位地图`,t1_r3_b:`48.4%`,t1_r4_a:`<strong>1,010,000 张地图中的最大值</strong>`,t1_r4_b:`<strong>低于 51.7%(不到 100 个方案达到此值)</strong>`,seat_count_note:`关于议席数的说明。2026 年委员会的两份地图各有 <strong>89</strong> 个选区;审计的计算机模拟在 <strong>87</strong> 个选区的 2019 年地图上运行(其起始基底);11 月的 Lunty 委员会将提出 <strong>91</strong> 个。所有百分比都是议席<em>份额</em>,在这些分母之间可比较。模拟使用 2019 年地图作为起点,因为 ReCom 算法需要一份合法颁布的地图来提议交换——2019 年地图是阿尔伯塔最后颁布的选举地图。使用任一委员会提议作为基底将是循环论证:我们将测量一张地图与从其自身派生的地图相比是否极端。`,pattern_intro:`结果——将三份真实地图放入这一分布——指向一种特定的、外科手术般的边界绘制模式。`,sub1_h:`四项统计指标同时发出警报`,sub1_p:`当使用 Elections Alberta 官方 shapefile 时,少数派地图在每一项党派公平性指标上都是统计离群——不只是临界点指标。`,t2_col_a:`地图`,t2_col_b:`效率差`,t2_col_c:`均值-中位差`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Declination 衡量每个政党议席-选票曲线之间的角度差。负值有利于 UCP;正值有利于 NDP。">Declination</a>`,t2_col_e:`50/50 下议席`,t2_r1_a:`多数派 2026`,t2_r1_b:`+0.04% (p15.5)`,t2_r1_c:`−3.6% (p2)`,t2_r1_d:`+0.027 (p81)`,t2_r1_e:`46.1% (p83)`,t2_r2_a:`少数派 2026`,t2_r2_b:`<strong>+3.96% (p94.4)</strong>`,t2_r2_c:`<strong>+1.0% (p99.98)</strong>`,t2_r2_d:`<strong>−0.077 (p1.2)</strong>`,t2_r2_e:`<strong>51.7% (p99.99)</strong>`,sub1_close:`多数派地图在四项指标中的三项上舒适地位于正常范围内。它的均值-中位差位于 p2,方向有利于 NDP——这是一个不寻常的结果,但方向上对帮助 UCP 是错的。多数派地图紧贴市政边界,将 NDP 集中的城市核心放入它们自己紧凑的选区,NDP 票以高效差距获胜,而 UCP 乡村获胜往往以更大差距取得;这种轻微的结构性 NDP 效率优势就是均值-中位指标中显现的内容。少数派地图在所有四项中都处于尾部,每一项都指向同一党派方向。`,sub2_h:`50/50 临界点:1,010,000 张中立地图中不到 100 张达到`,sub2_p:`上文介绍的临界点指标——50/50 省级投票下的 UCP 议席——是比较三份地图最直观的方法。`,t3_col_a:`地图`,t3_col_b:`50/50 选票下 UCP 议席`,t3_col_c:`所处位置`,t3_r1_a:`2019 颁布`,t3_r1_b:`46.0%`,t3_r1_c:`第 83 百分位——正常范围内`,t3_r2_a:`<strong>多数派 2026</strong>`,t3_r2_b:`<strong>46.1%</strong>`,t3_r2_c:`<strong>第 83 百分位——稳稳处于范围内</strong>`,t3_r3_a:`<strong>少数派 2026</strong>`,t3_r3_b:`<strong>51.7%(46 席)</strong>`,t3_r3_c:`<strong>第 99.99 百分位——1,010,000 张中立抽样中不到 100 张达到</strong>`,sub2_close:`1,010,000 张计算机模拟的中立阿尔伯塔地图中,不到 100 张产生了与少数派提议一样高的 <code>seats@50/50</code> 值。根据近期实际投票模式,它会给 UCP 60 席(相比多数派提议的 55 席)。多数派提议是中立程序常规产生的那种地图。少数派提议是你必须刻意瞄准才能划出的那种地图。`,sub3_h:`用通俗语言说明`,sub3_p:`官方 shapefile 揭示一份在所有四项指标上同时朝同一党派方向统计极端的地图。中立绘图过程同时在所有四项指标上产生如此极端地图的联合概率约为 1500 万分之一(p&nbsp;=&nbsp;6.87×10<sup>−8</sup>,<a href="https://osf.io/6pt83" rel="noopener">预先注册的 Fisher 合并检验</a>)。这不是舍入误差或测量伪迹——而是来自同一房间内四个独立统计工具的相同答案。`,details_summary:`这个 p 值意味着什么——以及不意味着什么`,details_p1:`p 值回答一个问题:如果地图由中立程序绘制,我们会多大频率看到这种或更极端的结果?在 p&nbsp;=&nbsp;6.87×10<sup>−8</sup> 下,答案约为 1450 万次试验中一次。`,details_p2:`这是一种频率主义假设检验,而不是对意图的测量。它不是说委员会有意进行选区不公划分,也不量化该地图在实际意义上有多不公平。它说的是,边界模式在统计上与中立绘图过程不一致——这与任何随机化审计将得出的结论相同,无论谁绘制地图或为何绘制。`,details_p3:`该检验在数据被分析之前已预先注册(<a href="https://osf.io/w2s8k" rel="noopener">OSF 注册 w2s8k</a>)。预先注册预先指定了零假设、指标和拒绝阈值,因此该结果不能归因于在看到数字后选择有利的框架。`,szat_label:`摆动区分配测试(SZAT)`,szat_body:`SZAT 是审计的第二项独立测试,它问的问题与模拟不同:不是"这张地图整体是否极端?"而是"具体的线条选择是否党派中立?"它的工作方式是只隔离少数派地图与多数派地图不同的投票区——有争议的重绘——并测试这些特定选择整体上是否使投票效率朝一个党派方向倾斜。因为它只比较分歧点,它会自动控制两份地图共享的一切:相同的地理、人口目标和法定规则。<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">技术细节和自助法结果 →</a>`,two_q:`<strong>两个问题,一个答案。</strong>1,010,000 张地图模拟问:<em>这份地图与同一阿尔伯塔地理上绘制的中立地图相比是否极端?</em>另一项单独测试——称为<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">摆动区分配测试</a>——问一个不同的问题:<em>地图上的具体线条是否党派中立?</em>它只观察少数派绘制与多数派不同的投票区,并询问这些特定选择整体上是否使投票效率朝一个党派方向倾斜。因为它只比较两份地图不同的地方,它会自动控制它们共享的一切——相同的省级地理、相同的人口目标、相同的法定规则。两个问题给出相同的答案。这就是 1500 万分之一这一数字是合并结果而不是单一测试的原因:这是两条独立证据线的汇合。`,super_lead:`这解释了为什么少数派提议必须在 1,010,000 次中立模拟中是如此极端的统计离群(p99.99)。在 89 席的立法机关中,三分之二超级多数恰好需要 60 席。中立程序在中立选票下不会在阿尔伯塔地理上产生 60 席结果;达到该门槛需要刻意偏离中立基线的边界选择。`,super_label:`为什么超级多数重要`,super_body:`在加拿大威斯敏斯特议会制下,简单多数(45 席)足以通过常规法律和预算。三分之二超级多数(60 席)的作用更大。它允许执政党援引"截止辩论"以关闭辩论,无需反对党同意即可改写程序规则,并控制每个立法委员会的组成。它也使政府免受内部异议:即便有六七位后排议员跨过过道,政府仍持有可工作的多数。简单多数让你开车;60 席超级多数让你改写交通规则。`,super_close:`通过有策略地将城市选民稀释到周围的乡村边缘选区(在路径 2 中识别为"城市混合"模式),少数派提议设计了确保这 60 席所需的精确结构性防火墙。路径 2 的结构性发现和路径 1 的统计发现在同一份提议、同一方向、同一些社区上汇合。`,sub4_h:`来自定向程序测试的确认`,sub4_p:`为了确保这不是中立模拟已知紧凑性偏好的怪癖,审计在两个方向上运行了定向爬山程序(<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon 等人 2022 年——在技术报告中引用并描述</a>):最大化 UCP 议席与最大化 NDP 议席。每个方向相同的步数(40,000),相同的法定约束,相同的省级几何。`,t4_col_a:`程序`,t4_col_b:`达到的最极端值`,t4_col_c:`它告诉我们什么`,t4_r1_a:`中立 MCMC,产生的最大值`,t4_r1_b:`@ 50/50 下低于 51.7% UCP 议席`,t4_r1_c:`中立绘图下的自然上限`,t4_r2_a:`中立 MCMC,产生的最小值`,t4_r2_b:`@ 50/50 下约 39% UCP 议席`,t4_r2_c:`中立绘图下的自然下限`,t4_r3_a:`定向爬山,最大化 UCP`,t4_r3_b:`<strong>52.9%</strong>`,t4_r3_c:`刻意瞄准 UCP 优势的程序所能达到的值`,t4_r4_a:`定向爬山,最大化 NDP`,t4_r4_b:`<strong>37.9%</strong>`,t4_r4_c:`刻意瞄准 NDP 优势的程序所能达到的值(低于中立下限)`,sub4_close:`少数派地图的 51.7% 更接近定向 UCP 上限(52.9%)而非中立中位数(44.8%)。多数派地图的 46.1% 位于中立中位数。2019 年颁布地图和 2026 多数派都舒适地落在中立程序常规产生的范围内——不同的得票份额,相同的不显眼结果区域。多数派在党派公平性轴上延续 2019 年阿尔伯塔实践,与它在市政锚定上延续 2019 年实践(80.0% 对 2019 年的 75.2%)的方式相同。两份地图,由同一五位委员在同一房间内,在相同的阿尔伯塔规则下绘制:一份落在中立程序常规产生的位置,另一份落在你必须刻意瞄准才能落入的位置。`,sub4_quote:`<em>这</em>就是发现的形状,也是法院实际会应用的框架。`,sub5_h:`排除其他解释`,sub5_p:`面对如此规模的统计离群,严谨审计必须先排除无辜解释,然后才能将这些模式归因于刻意设计。结构性数据(路径 2)系统性地拆解了标准的替代辩护:`,defense1:`<strong>"自然政治地理"辩护:</strong><em>("城市选民天然集中;地图只是反映阿尔伯塔的地理。")</em>1,010,000 次模拟已经考虑了阿尔伯塔的自然地理。模拟证明:虽然地理给 UCP 一个基线效率优势,它天然在第 83 至 90 百分位左右见顶。少数派地图位于第 99.99 百分位——<em>即便相比阿尔伯塔天然倾斜的基线</em>也是极端离群。`,defense2:`<strong>"利益共同体"辩护:</strong><em>("绘制奇怪形状是为了将特定社区保留在一起。")</em>如果你试图把社区保留在一起,你会沿着市政边界绘制。多数派地图 80% 的时间沿着现有市界绘制。少数派地图沿之绘制的比例为 72%——两者均处于 70–85% 的加拿大常态范围内。少数派地图所做的,是积极将统一的 Airdrie 切成四块,并将其三个边界决策恰恰放置在委员会主席标记为几何异常的城市边缘区域——这些选择无法用利益共同体逻辑解释。`,defense3:`<strong>"人口平等"辩护:</strong><em>("他们必须绘制奇怪的边界以确保每个选区有完全相同的人口。")</em>少数派地图在人口平等上其实<em>差得多</em>。它的人口平均绝对偏差(MAD)为 4,707——比多数派地图的 3,180 宽 48%——使其处于标准集合的第 99 百分位(100 张中立地图中只有 1 张产生更差的分布)。它牺牲了人口平等来实现它的形状。`,defense4:`<strong>"无能或运气不好"辩护:</strong><em>("他们只是绘制了一张草率的地图,运气不好碰上了这些数字。")</em>恰好达到 60 席的超级多数,同时将 Airdrie 切成四块,并将三条边界放置在委员会自己主席标记为异常的精确区域,需要外科手术般的精确度。在四项独立党派指标上同时意外击中统计极端尾部的联合概率约为 <strong>1500 万分之一</strong>(p&nbsp;=&nbsp;6.87×10<sup>−8</sup>)。你不可能跌跌撞撞地达到第 99.99 百分位。`,sub5_close:`数据显示,少数派提议在与同一五位委员同时在相同法定规则下产生的成果相比,在人口平等和社区连贯性两方面都恶化了。审计不判断少数派委员的意图——边界几何无法揭示意图——但与中立集合和多数派提议输出之间的结构性偏离,无论意图如何都成立。`,sub6_h:`关于 R 交叉验证的说明`,sub6_p1:`本次审计的早期版本(使用近似而非官方 shapefile)将 Python ReCom 集合与 R <code>redist</code> 包的序贯蒙特卡罗采样器进行交叉验证。交叉检查产生了不稳定的结果:在使用相同名义种子的三次运行中,达到旧少数派值(在近似几何上为 48.3%)的方案比例分别为 5.6%、28%、58%——这是采样器收敛失败,而非发现。完整说明在 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>。`,sub6_p2:`使用 Elections Alberta 官方 shapefile,少数派地图的 <code>seats@50/50</code> 升至 51.7%——这是 1,010,000 张中立方案中不到 100 张达到的值。R 交叉验证问题变得无关紧要:在可比样本量下,两种采样器均无方案达到标准值。`,sub6_asymm:`<strong>围绕 50/50 的不对称性比反转本身更具说明性。</strong>对议席-选票曲线以 0.01 个百分点分辨率进行的精度扫描发现,少数派地图将 UCP 保持在或高于 45 席立法多数门槛,直至 UCP 省级得票份额约为 <strong>49.7%</strong>。从技术上讲这是一种选票-议席反转——UCP 将在少数派地图上组建政府,而在普选中以 0.3 个百分点落败——但 0.3 个百分点完全在普通民调噪声范围内,所以本身不是戏剧性发现。<em>戏剧性</em>的是对比:在<strong>多数派</strong>地图上,UCP 需要在普选中<em>赢</em>约 4 个百分点才能达到相同的 45 席门槛。两份地图面对相同的阿尔伯塔地理和相同的法定规则;它们之间的差距——0.3pp 对 +4pp——是结构性差异,不是噪声。`,sub6_close:`这就是审计有信心持有的结构性偏倚发现。它只与几何相关;它不依赖任何选举结果;它不会随民调而变。`,sub6_caveat:`<strong>审计认真对待一个限定条件。</strong>真实选民并非一致的 50/50。选民可以以足够的摆动压倒任何地图的结构性倾斜——一个特别愤怒或特别受激励的选民群体会无视边界如何绘制而决定结果。50/50 测试隔离的是<em>地图对结果的贡献</em>,而不是结果本身。它显示的是当选民不为其决定时,地图所做的事。`,sub7_h:`底线`,sub7_p1:`审计的核心发现是几何性的。<strong>路径 2——结构性不规则评分卡——是基础;路径 1 是几何在做党派工作的证明。</strong>`,sub7_p2:`下方的图将两条路径放在一张图上。横轴是路径 1(党派公平性的效率差,越靠右越有利于 UCP);纵轴是路径 2(提议未通过的结构性公平测试数,五项中,越高表示结构性问题越多)。`,stakes_fig_alt:`散点图,横轴为效率差,纵轴为未通过的结构性测试数。2019 颁布地图和多数派 2026 地图集中在左下角的安全区域。少数派 2026 地图出现在右上角的离群区域。`,stakes_fig_caption:`同时绘出两种衡量两份委员会提议的方式。从左到右:提议在党派公平性数值上的偏斜程度——越靠右,越有利于 UCP。从下到上:提议未通过的五项结构公平性测试数——越高越糟。2019 颁布地图位于安全角落:两项都低。多数派 2026 提议保持在零结构性问题和接近零党派偏斜(+0.1%)。少数派 2026 提议在区分两份地图的每一项测试上都是结构性离群(5 项中的 4 项;第五项锚定对两者均为中性);其效率差(+4.0%)恰好低于阿尔伯塔阈值线。`,stakes_table_intro:`相同的发现以简明摘要形式呈现,首先列出结构性发现,因为交叉验证的证据对它最有力地支持:`,t5_col_b:`路径 2:结构(仅几何,无选票)`,t5_col_c:`路径 1:数字(依赖选票)`,t5_r1_a:`<strong>多数派 2026</strong>`,t5_r1_b:`干净——<em>未</em>跨越任何结构性阈值`,t5_r1_c:`在每一项指标上都位于正常范围内(<code>seats@50/50</code> 46.1%——p83;效率差 +0.04%)`,t5_r2_a:`<strong>少数派 2026</strong>`,t5_r2_b:`<strong>跨越 5 项中的 4 项结构性阈值</strong>且差距很大(锚定中性——两份地图均在加拿大常态范围内)`,t5_r2_c:`在所有四项党派公平性指标上同时为统计离群——<code>seats@50/50</code> 51.7%(p99.99,1,010,000 中不到 100 张达到);效率差 +3.96%(p94.4);四项均预先注册;Fisher 合并 p&nbsp;=&nbsp;6.87×10<sup>−8</sup>`,details2_summary:`为什么路径 2 是核心证据——技术细节`,details2_p:`审计于 2026 年 4 月 24 日在最终模拟结果汇编之前预先注册了五项结构性不规则测试。锚定对两份地图均为中性;在剩余四项测试中,少数派全部跨越,多数派一项也未跨越。这些测量是几何性的——它们不依赖任何统计采样器或任何选票归属。路径 1(党派公平性数字)在标准官方 shapefile 下强烈印证路径 2:少数派在所有四项预先注册指标上同时为统计离群,联合中立零假设概率为 p&nbsp;=&nbsp;6.87×10<sup>−8</sup>(预先注册的 Fisher 合并检验——一种通过相乘各自尾部概率将四项独立测试结果合并为单一概率的方法;合并值远小于任何单一测试,因为四项都指向同一方向;OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>)。关于路径 2 的不寻常几何是否是路径 1 数字背后的具体<em>机制</em>这一问题已被测试,答案是否——参见 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>。摆动区分配测试显示有争议的边界选择存在党派偏斜,但被测试的问题是边界形状本身——套索走廊、公园延伸——是否是议席摆动的直接原因;答案是否。议席效应来自重绘投票区分配如何在选区间转移投票效率,而非形状本身。两条路径都标记少数派地图;它们通过独立工具达到这一结论。路径 2 是核心发现。路径 1 印证而不承担。`},impact:{heading:`5:对代表权的影响`,lanes_label:`路径 1 和路径 2`,lanes_body:`<strong>路径 1(数字)</strong>使用选举结果测试地图是否公平地将选票转化为议席——它询问地图在不同得票分配下的表现。<strong>路径 2(结构)</strong>仅检验所绘线条——城市分割、人口分散、边界形状——完全不使用选举数据。每条路径都是独立的:一份地图可以在一条路径上失败而在另一条路径上通过。少数派提议在两者上都失败;多数派在两者上都通过。`,intro:`路径 1 取决于你以哪个选举结果为地图打分。路径 2 不取决于此。结构性证据就在地图本身——所绘线条、被分割的城市、边界沿着或不沿着由其他原因存在的行政线之处。在这些测试上,两份地图差距不小。`,fig_alt:`并排比较五项结构公平性测试的条形图。多数派地图条柱位于零或安全范围深处。少数派地图条柱在五项中的四项上以较大差距跨越阈值;第五项(锚定)对两份地图均为中性。`,fig_caption:`五项结构公平性测试并排比较。青色条柱是多数派地图;紫色条柱是少数派地图。每行虚线标记失败阈值。少数派条柱在五项中的四项上以较大差距跨越阈值;第五项(锚定)对两份地图均为中性。多数派条柱平稳地位于零或安全范围深处。`,table_intro:`相同的五项测试以表格形式呈现,每项测试的阈值与结果并列。底行是审计的<em>摘要</em>——每份地图在五项中未通过的测试数。`,table_col_test:`测试`,table_col_majority:`多数派地图`,table_col_minority:`少数派地图`,table_col_direction:`方向 / 受益方`,table_r1_a:`边界沿现有市政线(70–85% 加拿大常态)`,table_r1_b:`80% —— 常态范围内`,table_r1_c:`72% —— 常态范围内`,table_r1_d:`不适用——两者均在加拿大常态范围内`,table_r2_a:`人口分散度(越紧越好)`,table_r2_b:`3,180`,table_r2_c:`4,707 —— 宽 48%`,table_r2_d:`结构性(降低选票平等)`,table_r3_a:`Calgary 西北人口超出平均水平`,table_r3_b:`2.8%`,table_r3_c:`11.5%`,table_r3_d:`<strong>UCP</strong>(集中城市 NDP 选票)`,table_r4_a:`委员会主席本人标记的边界`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`不适用`,table_r5_a:`Airdrie 分割(约束最小值:2)`,table_r5_b:`2 块`,table_r5_c:`4 块`,table_r5_d:`<strong>UCP</strong>(分散城市/郊区力量)`,table_r6_a:`<strong>预先注册摘要</strong>(5 项中 ≥ 4 项 = 离群)`,table_r6_b:`<strong>5 项中 0 项触发</strong>`,table_r6_c:`<strong>5 项中 4 项触发</strong>(锚定测试中性——两份地图均在加拿大常态范围内;其余 4 项全部触发)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`一项单独发现,仅适用于少数派:<strong>少数派委员发表的六项理由中有五项在独立检查下不成立</strong>。该测试仅对少数派运行,因为多数派未发表有争议重绘理由清单——审计无法对称地应用它,并在此报告为单一标记,而非作为结构性不规则计数的额外行。(审计先前列出的第七处重绘最终基于一项无法在少数派报告中追溯到的联邦边界主张;它已被移除,而不是作为弱主张保留。)`,chair_appendix_p:`审计还测试了主席在附录 C 中关于少数派七个有争议混合配置在 1,140+ 份公众意见中<strong>没有公众支持</strong>的另一项笼统断言。对完整意见档案的关键词搜索(94% 由机器解析,6% 纯图像被排除;方法和按配置证据见 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>)返回的图景比主席的笼统主张或笼统反驳更微妙:主席在七项中的三项上是对的(Airdrie 四向分割、Calgary–Nolan-Hill–Cochrane 混合,以及 St. Albert 少数派替代方案各自缺乏任何有记录的支持),在七项中的三项上是错的(Rocky Mountain House–Banff Park 来自至少一份 Clearwater 地区意见及若干一致意见的明确详细提议;Olds–Three-Hills–Didsbury 得到 Beiseker 居民的书面支持;Chestermere 得到多份反对与 Calgary 合并的意见,这些意见与少数派意图实质上一致),并在一项上部分错误(Red Deer 混合得到了一位在任 Red Deer 议员关于围绕 Red Deer 的混合提议,方向上一致但配置上不完全一致)。因此主席在附录 C 中的"没有公众支持"的笼统说法可证明过于宽泛——七项中的三项可证明错误——但并非凭空捏造,因为七项中的三项确实成立。<strong>这一发现不利于主席,而非不利于少数派。</strong>`,summary_p:`<strong>在路径 2 上,多数派未跨越任何结构性阈值。少数派每一项都跨越,且差距很大。</strong>`},cpd:{heading:`4:分散、集中与排空`,vocab_label:`三种手段,一本剧本`,vocab_packing:`<strong>集中(Packing)</strong>意味着把一个政党的选民塞进该党以压倒性优势获胜的选区——每张被集中的选票仍然计数,但它在胜利之外没有任何贡献。大规模、悬殊的胜利。被浪费的选票。`,vocab_cracking:`<strong>分散(Cracking)</strong>意味着将一个社区分散到多个选区,使其无法直接赢得任何一个。一个本足以拿下两个议席的城市被切成四块,每块都与不同的乡村地区挂钩。被稀释的选票。任何人都没有议席。`,vocab_draining:`<strong>排空(Draining)</strong>是空间上的伴随效应:被集中和被分散的选区被放置在彼此相邻的位置,使一侧过度集中的支持者将投票力"排空"出附近有争议的选区。这种相邻模式放大了两种效应——集中和分散在选区线之间相互强化。`,vocab_disclaimer:`三者都可以在没有任何明显党派意图的情况下发生。审计衡量的是这种模式——及其统计规模——是否与中立绘图过程所产生的一致。<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">完整方法见技术报告 §5。</a>`,fig_alt:`显示少数派地图下 Airdrie 被划分为四个独立选区的地图`,fig_caption:`少数派地图下 Airdrie 被划分为四个独立选区,稀释其城市投票力量。`,intro:`五位委员根据相同的法定规则、相同的省级地理、相同的 1,140 份公众意见档案和相同的人口统计数据进行工作。他们两份相互竞争的草案在阿尔伯塔大部分地区一致。它们分歧的地方,源于房间内某人必须做出的选择。其中三项选择值得作为选择来看,而不是作为数字。`,airdrie_p:`<strong>它将 Airdrie 市分成四块。</strong>法律将每个选区的人口上限设定为省级平均水平的 1.25 倍,因此 Airdrie 至少需要两个选区。多数派地图给它两个。少数派给它四个——北部归 Calgary-Nolan Hill-Cochrane,东部归 Airdrie East,西部归 Calgary-Foothills-Airdrie West,中南部归 Calgary-Airdrie——每一个都与不同的乡村或 Calgary 边缘选区拼接在一起。一位 Airdrie 居民如果有问题想问她的 MLA,她必须先知道自己住在城市的哪个四分之一,才能打对办公室的电话。两个街区外的邻居会给她三个不同的答案。她孩子学校的家长会无法就学校资助问题派出一支代表团去见一位 MLA;他们必须协调四支代表团去见四个办公室,每位 MLA 主要对不同的乡村或郊区选区负责。少儿冰球协会、食物银行、商会——每一个全市运营的组织现在都跨越四个省级选区运营。`,airdrie_callout_label:`为什么 Airdrie 重要`,airdrie_callout_p1:`Airdrie 是阿尔伯塔最大的没有自己 MLA 的城市。以 85,805 人(2024 年市政人口普查)它比 Red Deer 还大;它有一个市议会、一份税单、一个学区——每一个民事系统都将它视为一个单位。`,airdrie_callout_p2:`将它分散到四个省级选区——Calgary-Airdrie、Calgary-Foothills-Airdrie West、Calgary-Nolan Hill-Cochrane 和 Airdrie East——每一个主要与不同的周边司法管辖区认同,使 Airdrie 在划定它的政府层级上从政治地图上消失。这座城市有 85,805 名居民,而在多数选民称之为家的立法机关中没有任何议席。`,airdrie_callout_p3:`除了一个问题——选民能否找到他们的 MLA?——四向分割对每一项党派公平性测试都是不可见的。`,airdrie_callout_summary:`两份地图都合法。四向分割是一种选择。`,airdrie_btn:`在地图上显示被标记的选区`,anchoring_p:`<strong>当它偏离市政线时,它在战略上重要的位置偏离。</strong>当选举地图沿着城市或镇的边缘时,选民认得自己所在选区的起止——地产税线、学区线、地方选举选区线和省级选举线全部重合。Statistics Canada 免费发布这些边界。在 Elections Alberta 官方 shapefile 上,两份地图沿市政线的整体比例相当:多数派 80%,少数派 72%,均在加拿大 70–85% 常态范围内(魁北克:78%,安大略:82%,卑诗:71%;比较委员会在专著中有记录)。(审计最初的临时分析显示少数派锚定仅 15%;该数字在官方 shapefile 重算后未能存留——见下方更正说明。)显著的观察不在于整体比例,而在于少数派偏离的集中位置:委员会自己主席标记为异常的三条边界——Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">查看 ↗</button>延伸进无人居住的国家公园土地、Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">查看 ↗</button>套索走廊,以及 Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">查看 ↗</button>延伸——每一处都是在城市边缘区精确偏离既有民事地理的地方,而在这些位置把城市与乡村选民配对最直接地影响哪个党赢得议席。`,anchoring_followup:`少数派委员为这三条被标记的边界各自给出了理由。对于 Rocky Mountain House–Banff Park,他们引用了地理面积、22 号公路走廊和 Rocky Mountain House 附近的原住民保留地;委员会主席称延伸进无人居住的国家公园土地是"恶意行为",这一措辞出现在委员会的官方最终报告中。对于 Nolan Hill–Cochrane,他们引用了 Calgary 西北部与 Cochrane 之间共享的交通和就业联系;Statistics Canada 通勤数据显示仅 35.8% 的 Cochrane 工作者前往 Calgary,大多数人在 Cochrane 本地工作。对于 Olds–North Airdrie 延伸,他们引用了 2 号公路走廊的连续性;审计发现具体的 Airdrie 延伸在人口理由上不成立。独立检查发现少数派六项发表子理由中有五项相对于第一手数据不成立或仅部分成立。`,packing_p:`<strong>Calgary 一个区域被切分以将 NDP 选民集中到大于平均规模的选区中。</strong>在 Calgary 的西北象限 <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">查看 ↗</button>,少数派地图的选区平均比省级平均人口高 11.5%——而多数派为 2.8%。同一地理区域,由同一委员会在相同约束下绘制,在一份地图上产生的选区比另一份大四分之一。这符合<em>集中</em>的结构性特征:将一个政党的选民集中到更少、更大的选区中,使其每张选票分量更轻。集中与<em>分散</em>(将一个政党的选民稀释到他们勉强失败的选区中)是经典的两种选区不公划分手段;两者都使一个政党的议席数低于其得票份额。`,chair_p:`委员会主席——根据同一法律任命,基于相同意见工作——将少数派地图上的三条边界标记为地理异常:Rocky Mountain House–Banff Park 延伸进无人居住的国家公园土地;Calgary-Nolan Hill–Cochrane 套索状走廊;Olds–Three Hills–Didsbury 延伸至 Airdrie 北部。多数派从同一主席处收到零个此类标记。(主席发表的批评共覆盖七处边界配置——主报告中四个几何标记,附录 C 中三个。本次审计独立确认四个几何标记中的三个存在异常几何;第四个 Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">查看 ↗</button>未达到审计的确认阈值。)`},litmus:{heading:`3:1,010,000 张地图试金石测试`,fig_alt:`直方图,显示 250,000 张中立阿尔伯塔地图的效率差分布。大多数地图集中在零附近。少数派委员会地图(紫线)位于第 94 百分位(+3.96%),在阴影右尾。多数派地图(青线)位于 +0.04%,稳稳处于正常范围内。`,fig_caption:`从同一地理绘制的 250,000 张中立阿尔伯塔地图的<button class="vocab-term" data-def="衡量选票转化为议席的偏斜程度——正值有利于 UCP,负值有利于 NDP" aria-expanded="false">效率差</button>分布。大多数中立地图集中在零附近;阴影右尾标记前 10%。少数派提议的 +3.96% 位于第 94<button class="vocab-term" data-def="得分较低的地图百分比——p94 意味着 100 张中立地图中有 94 张的党派性低于这张" aria-expanded="false">百分位</button>——一个 100 张中立地图中不到 6 张能到达的区域。多数派提议的 +0.04% 与中立程序通常产生的结果无法区分。`,table_intro:`该表比较两份地图。前五行不使用选举结果——它们是线条本身的属性。后两项依赖于选票如何归属到各选区。`,table_col_measured:`所测量的内容`,table_col_majority:`多数派地图`,table_col_minority:`少数派地图`,table_col_direction:`方向 / 受益方`,table_r1_a:`跨选区的人口分散度(越紧越好)`,table_r1_b:`3,180`,table_r1_c:`4,707 —— 宽 48%`,table_r1_d:`结构性(降低选票平等)`,table_r2_a:`Calgary 西北人口超出平均水平`,table_r2_b:`2.8%`,table_r2_c:`11.5%`,table_r2_d:`<strong>UCP</strong>(集中城市 NDP 选票)`,table_r3_a:`Airdrie 分割`,table_r3_b:`2 个选区`,table_r3_c:`4 个选区`,table_r3_d:`<strong>UCP</strong>(分散城市/郊区力量)`,table_r4_a:`沿现有市政线的边界`,table_r4_b:`80% —— 常态范围内`,table_r4_c:`72% —— 常态范围内`,table_r4_d:`不适用——两者均在加拿大常态(70–85%)内`,table_r5_a:`委员会主席标记的边界`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`不适用`,table_r6_a:`50/50 选票下议席(在 1,010,000 张地图模拟中的百分位)`,table_r6_b:`46.1% —— p83(正常范围)`,table_r6_c:`51.7% —— p99.99(1,010,000 中不到 100 张达到)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`效率差(在 1,010,000 张地图模拟中的百分位)`,table_r7_b:`+0.04% —— p15.5(正常范围)`,table_r7_c:`+3.96% —— p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`集中-分散邻域模式`,table_r8_b:`6 个耦合链信号`,table_r8_c:`2(预先注册通过)`,table_r8_d:`中性——少数派通过混合而非相邻排空达到党派效果(§5.3.5)`,vocab_label:`词汇`,vocab_eg:`<strong>效率差。</strong>一个测量一个政党的选票如何不对称地转化为议席的单一数字。正数有利于 UCP;负数有利于 NDP。审计使用约 5% 作为阿尔伯塔的离群线——即 1,010,000 次中立阿尔伯塔特定模拟中仅 5% 超过的值。该阈值不是从美国或一般文献借用的;为另一管辖区校准的阈值是错误的,因为阿尔伯塔的天然地理产生不同的中立范围。`,vocab_mm:`<strong>均值-中位差。</strong>一个政党的中位选区得票率与平均选区得票率之间的差距。当一个政党赢得许多接近的比赛时,中位高于均值——那些选票被高效分配。当一个政党以大差距赢得许多比赛时,均值高于中位——选票被浪费。某一方向的较大均值-中位差距标志着一方选票在选区间分布的结构性低效。`,vocab_percentile:`<strong>百分位排名。</strong>在本次审计中,"百分位"是在 1,010,000 张中立模拟地图中的排名。"p94"意味着 94% 的中立地图得分更低——真实地图比 94% 的中立抽样更极端。"p99.99"意味着 10,000 张中立地图中不到 1 张达到该水平。`,vocab_anchoring:`<strong>锚定。</strong>选举边界中位于既有行政线(市界、学区边界、Statistics Canada 普查线)上的部分所占比例。`,closing_p1:`最后几行依赖于选举结果。<em>seats@50/50</em> 测试将选民保持完美对等(UCP 和 NDP 在全省得票恰好各占一半),并询问地图给 UCP 分配多少议席。中立阿尔伯塔地图产生约 44.8% UCP 议席的中位数。阿尔伯塔的地理——NDP 选民集中在城市核心,UCP 选民分布在乡村选区——在中立情况下给 NDP 一个微弱的效率优势。多数派地图的 46.1% 位于 1,010,000 张地图模拟的第 83 百分位,稳稳处于正常范围内。少数派地图的 51.7% 位于第 99.99 百分位:1,010,000 张中立抽样中不到 100 张达到该值。<em>效率差</em>数字衡量每个政党的选票如何不对称地转化为议席。在 Elections Alberta 官方 shapefile 上,少数派的效率差为 +3.96%,使其位于第 94.4 百分位——恰好低于审计的第 95 百分位离群线。本页顶部的开篇问题展开了其后果。`,closing_p2:`最后一行是少数派地图在邻居排空测试上耦合链信号少于多数派的地方:2 对多数派的 6(以及 2019 年颁布地图的 5)。审计在测量之前预先注册了此测试,少数派较低的计数是真正的预先注册通过——少数派未显示典型的集中-排空相邻模式。这是少数派在数值上优于多数派的唯一测试。学术报告 §5.3.5 解释了原因:少数派通过混合(城市分割,在个别 ED 内部内化集中和分散)实现其党派效果,这对一个只测量被集中的选区是否聚集在被分散的选区旁边的相邻链测试是不可见的。`},commission_split:{heading:`2:委员会如何分裂`,intro:`阿尔伯塔选举边界委员会于 2026 年 3 月 23 日完成工作,且未能达成一致。三位委员产生了一份地图;另外两位产生了不同的一份。委员会主席 Dallas K. Miller 法官和两位反对党提名委员撰写了多数派报告;两位政府提名委员——Julian Martin 博士和 John D. Evans——撰写了少数派报告。分裂集中在如何在快速增长的城市边缘社区中划界。多数派给 Airdrie 两个选区;少数派给四个。多数派将 Calgary 西北的选区绘制得接近省级平均水平;少数派将它们绘制得高出 11.5%。两份地图都遵循同一法规。两份在《Electoral Boundaries Commission Act》下都合法。分歧在于哪种具体地理配置最能服务被划界的社区。阿尔伯塔的执政党是联合保守党(UCP);其主要反对党是新民主党(NDP)。较小政党——阿尔伯塔党、阿尔伯塔自由党及其他——也争夺议席,但它们近期选举的合计省级得票份额低到足以不实质性影响审计的党派公平性计算,这些计算基于 2023 年 UCP–NDP 分裂。本次审计使用相同方法、同等应用,对两份地图都进行了测量。有三项发现突出。`,finding1:`<strong>两份地图在六件不需要查看任何选举结果就能测量的事情上不同:</strong>人在选区间分布的均匀程度、选民是否被集中、城市被切割的严重程度、边界是否沿市界、选区的形状,以及委员会主席 Miller 法官本人在书面中(多数派报告 §5.8.2 和附录 C)标记为异常的边界数。少数派地图在每一件上都与多数派不同。`,finding2:`<strong>每一项被测量的差异都朝同一方向移动。</strong>两份地图分歧的每一处——Calgary 西北、Airdrie、有清晰市界的城市地区——少数派地图绘制的边界都把 NDP 选票摊薄,让 UCP 选票更高效地计数。被少数派地图重塑最多的社区,正是 NDP 最强的社区。审计无法判断意图。它可以衡量效果。`,finding3:`<strong>目前推动少数派地图的程序在加拿大没有先例。</strong>没有其他省份允许内阁在选区重划周期途中将选区重划交给自己政党控制的委员会。大多数省份要么要求立法机关首先辩论委员会的地图,要么除非被否决,委员会的地图自动生效。阿尔伯塔两者都不做。4 月 16 日,政府将两份委员会地图都搁置,并将工作分配给一个 MLA 委员会,其多数成员来自执政的联合保守党(UCP);该委员会的完整组成和职权范围在 §7 中详述。阿尔伯塔的《Electoral Boundaries Commission Act》要求立法机关通过一项单独的《Electoral Districts Act》才能赋予委员会报告法律效力——委员会报告本身不改变任何事情。大多数其他省份使委员会的报告除非立法机关积极否决否则法律生效;阿尔伯塔的默认相反,意味着执政党控制任何委员会地图是否成为法律。政府声称的理由是执行委员会主席 Miller 法官的建议 5。但 Miller 撰写该建议是专门为了劝阻立法机关接受少数派地图,而他的多数派同事并未支持它。建议 5 在地理上也是特定的:在 Edmonton 以南增加一个乡村议席,并在 Clearwater 县和 Mountain View 县西部各增加一个——两者都远离委员会实际分裂的快速增长 Calgary 和 Edmonton 城市边缘社区。它不是邀请重新设计那些有争议的边界。政府采用了议席数,同时将权力交给它控制的委员会去管理委员会分歧的那些线条。`,closing:`<strong>程序本身就是一项发现,与地图分开。</strong>`},november:{heading:`7:Lunty 委员会`,context_label:`背景`,context_body:` —— 本节描述替代委员会的程序及适用于它的法律框架。它不是统计发现的一部分。发现见上文 §3–§6。`,intro:`两份委员会地图都未生效。2026 年 4 月 16 日,立法议会通过第 19 号议案,将两份均搁置,并将选区重划交予一个由五位 MLA 组成的特别专责委员会——三位 UCP、两位 NDP——由 Brandon Lunty(UCP,Leduc-Beaumont)主持。委员会本身不绘制地图。它监督一个独立咨询小组,该小组根据政府第 37 号议案(2026 年 4 月 21 日通过)组建,负责制定一份 91 席的边界提议。第 37 号议案设想了五位小组成员——一位在职或退休法官担任主席、两位由省长提名、两位由反对党领袖提名——但阿尔伯塔代理首席大法官拒绝向主席提名一位法官,小组现在以委员会确认的四位被任命者运作:Monte Solberg 阁下和 Darwin Durnie(省长提名)以及 Gerard Kennedy 博士和 Brent Robinson(反对党提名)。委员会必须在 2026 年 11 月 2 日之前将报告交给立法机关。与原委员会不同,委员会和小组都不需要举行公开听证;小组依据原委员会收集的意见进行工作。当委员会的地图发布时,本次审计将应用相同方法对其进行评估。`,h_anomalous:`为什么该委员会是反常的`,anomalous_p1:`自 1960 年代以来,加拿大选区重划实践确立了一种单一模式:一个与政府指令隔离的独立委员会产生边界建议;立法机关可以辩论,但不能在没有正式立法表决的情况下轻易否决。阿尔伯塔《Electoral Boundaries Commission Act》下的法定程序遵循这一模板——但与大多数省份相比有一个结构性差异:阿尔伯塔的委员会报告没有自动法律效力。根据该法,必须由立法机关通过一项单独的《Electoral Districts Act》才能赋予任何委员会地图法律强制力。这意味着当时的政府不仅控制委员会地图是否被辩论,还控制它是否成为法律。其他加拿大管辖区采用相反的默认:委员会的建议生效,除非立法机关明确投票否决。`,anomalous_p2:`政府在 2026 年 4 月所做的事情在后建国选区重划中没有记录在案的先例:它允许一个已完成、已发布的委员会程序结束——多数派与少数派报告均已提交——然后将选区重划任务交给一个由五位 MLA 组成的委员会,其多数(五分之三)由执政党持有,且未将任何委员会报告提交表决。Lunty 委员会不是委员会(commission)。它没有相对于政府立法指令的法定独立性。其三人 UCP 多数反映了政府对立法机关的控制。在独立委员会完成工作后,没有其他加拿大省份在周期途中将选区重划权力转交给政府控制的立法委员会。`,h_framework:`宪法框架`,framework_p1:`《加拿大权利与自由宪章》第 3 条——"加拿大每个公民有权在下议院或立法议会成员的选举中投票"——已被加拿大最高法院解释为不仅保障投票行为本身,而且保障<em>有效代表权</em>。主要权威是《Reference re Provincial Electoral Boundaries (Saskatchewan)》[1991] 2 SCR 158,其中 McLachlin 法官(当时身份)代表多数意见写道,第 3 条的目的"不是投票力本身的平等,而是有效代表权的权利"。人口平等是首要考虑;在受到利益共同体、地理、历史或少数派代表权目标证明合理时,允许偏离。`,framework_p2:`萨斯喀彻温框架并未绝对禁止选区重划中的党派考量。它确立的是,边界地图整体上必须为选民提供有效代表权——以及对一个可识别群体选出比例代表的能力的系统性损害,正是第 3 条挑战所针对的模式。审计的统计和结构性发现——少数派地图位于 1,010,000 次中立抽样的第 99.99 百分位、其跨越五项结构阈值中的四项(第五项锚定对两份地图均为中性)、所识别的受影响社区——是第 3 条申请人需要汇集的证据记录。在该记录的利益共同体一面,联邦法院在《Raîche v. Canada》(2004 FC 679)中的裁决是主要的加拿大权威:法院在该案中要求联邦选举边界委员会重新审视忽视新不伦瑞克阿卡迪亚人利益共同体的边界。审计的市政锚定测量及其具体社区发现——Airdrie 被分成四个选区、Calgary 西北主席标记的城市边缘异常——是联邦法院视为法律上可认知的同类证据。该记录是否达到宪法门槛是本次审计不决定的法律问题;审计报告的是测量。`,framework_p3:`委员会作为程序的合法性是另一个问题。阿尔伯塔《Electoral Boundaries Commission Act》并未明确禁止立法机关组建平行选区重划机构,因为该法预设立法机关无论如何将通过普通立法颁布最终边界。委员会程序如果产生一份具有少数派提议结构和统计特征的地图,是否能经受第 3 条《宪章》挑战,取决于在所产生的边界下是否能实现有效代表权——这与适用于任何委员会产生地图的检验相同。`,h_quebec:`魁北克对照`,quebec_p1:`魁北克提供了与阿尔伯塔情况最相关的比较。魁北克的 Commission de la représentation électorale(CRE)是一个永久性、独立的选举边界机构,而非每个重划周期设立的临时委员会。CRE 持续运作,内阁行动无法解散或绕过它。根据魁北克《Loi électorale》,国民议会必须采纳 CRE 的建议,除非它投票偏离——且偏离需要议会全体成员的三分之二多数,而非简单的立法多数。实际效果是,执政党不能独自以其多数将其偏好的地图替代委员会的。要否决独立机构的判断,宪法上要求跨党派协议。`,quebec_p2:`魁北克的模式部分源自有关当选区重划未与党派控制隔离时会发生什么的教训。与阿尔伯塔当前程序的对比——多数控制的委员会在立法机关对任何委员会报告投票之前已替代委员会的工作——说明了假定党派压力并针对其设计的选区重划制度,与那种压力有更清晰路径达到结果的制度之间的结构性差异。`,closing:`当 Lunty 委员会的地图发布时,审计将对其应用相同的测试。上述宪法和比较观察是背景性的;方法不变。`},references:{heading:`10:参考资料和方法论`,heading_aria:`链接到参考资料`,intro:`底层方法论借鉴了已确立的政治学、统计学和法律文献。完整引用遵循美国政治科学协会(APSA)风格;法院案件遵循加拿大法律惯例。完整参考列表见<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">技术报告</a>。主要来源列出如下。`,h_academic:`学术文献`,h_cases:`法院案件`,h_statutes:`法规`},resources:{heading:`11:技术附录`,heading_aria:`链接到技术资料`,tag_plain:`通俗版`,plain_label:`完整公开报告`,plain_desc:`长文形式,附地图,面向普通读者`,tag_summary:`摘要`,summary_label:`发现摘要`,summary_desc:`通俗概述,从头解释每个概念`,tag_academic:`学术版`,academic_label:`技术报告`,academic_desc:`面向研究者的完整方法和引用`,tag_notebook:`Notebook`,notebook_label:`交互式 Notebook`,notebook_desc:`在浏览器中自己运行图表,无需安装`,tag_code:`代码`},about_me:{heading:`关于我`,p1:`我是 Mount Royal University 的一名学生。我独自完成了这项研究——它不是课程作业,大学也没有委托。我的观点是我自己的,不代表学校。我与 Elections Alberta、委员会或任何政党都没有关联。`,p2:`我在不同选举中投过不同政党,跨越政治光谱。我告诉你这一点,是因为我的政治履历可能影响我如何看待这个问题。对此最主要的保护是方法:我用相同的方式测试两份地图,在查看结果之前写下我的预测,并将一切放在网上以便任何人检查我的工作。这项研究的费用是我自己支付的。如果你发现我有错的地方,我真的很想知道。`,p3:`预先注册记录(在结果被检查之前写下):<a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>、AsPredicted:#289,469、AsPredicted:#289,451。`,p4:`问题或更正:<a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9:撤回与更正`,heading_aria:`链接到撤回`,conditions_label:`撤回条件`,conditions_intro:`每项发现都预先承诺一个具体的反驳条件。如果下列任何条件成为事实,所命名的发现将在 30 天内被公开撤回。整体方向性结论——少数派地图在多个独立测试中位于中立范围之外——仅在五项测试中至少三项失败时才撤回。`,c1_title:`条件 1 —— 存在一份反例地图`,c1_what:`<em>会被撤回的内容:</em>结构性发现,即 Airdrie 四向分割和主席标记的三条边界无法由少数派自己声称的利益共同体理由解释。`,c1_cond:`条件:有人产生一份合法的阿尔伯塔地图,满足少数派自己声称的理由——Airdrie、Cochrane、Nolan Hill、Rocky Mountain House–Banff Park——并以与多数派相当的比例锚定到市政线。公开挑战见 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>。`,c2_title:`条件 2 —— 邻居排空预先注册通过被反转`,c2_what:`<em>会被撤回的内容:</em>第 3 节表中将少数派地图记录为在邻居排空相邻测试上预先注册通过的条目。`,c2_cond:`条件:v2 连续排空分数落入固定连通图随机排列的极端上尾(p &lt; 0.05),意味着通过是 v1 二元评分方法的测量伪迹,而不是真正的零结果。`,c3_title:`条件 3 —— 2026 年前的委员会文件浮出水面`,c3_what:`<em>会被撤回的内容:</em>推断少数派的边界选择是起草决策,而不是对有记录社区意见的回应。`,c3_cond:`条件:一份日期早于少数派最终边界选择的内部委员会文件显示,这些选择由审计未见过的社区意见明确驱动——而不是由审计测试的六项发表子理由驱动。`,c4_title:`条件 4 —— 2027 年选举结果与模拟矛盾`,c4_what:`<em>会被撤回的内容:</em>路径 1 发现——即少数派地图的 seats@50/50 分数位于 1,010,000 次中立抽样的第 99.99 百分位。`,c4_cond:`条件:如果 2027 年省级选举在任一委员会地图上进行,且实际党派议席分裂与 2023 年选票的方向性预测矛盾,则路径 1 的百分位发现将根据实际结果重新审视。`,c5_title:`条件 5 —— 阿尔伯塔法院将魁北克最高法院裁决加以区分`,c5_what:`<em>会被撤回的内容:</em>第 7 节程序论证,即 4 月 16 日用 Lunty 委员会替代委员会的议案与魁北克 2024 年选区重划冻结处于同一宪法类别。`,c5_cond:`背景:2026 年 4 月 22 日——阿尔伯塔 4 月 16 日议案之后六天——加拿大最高法院以 7 比 2 当庭裁决维持魁北克上诉法院的裁决,即 Legault 政府对其选区重划委员会的立法冻结违反了《宪章》第 3 条民主代表权保障。条件:审查阿尔伯塔议案的法院发现它在宪法上有所不同——例如,将工作重新分配给 MLA 委员会与立法冻结在结构上不同,或阿尔伯塔在第 3 条下的有效代表权分析与魁北克的不同。`,corr_label:`已记录更正(标准重算,2026-05-11)`,corr_intro:`以下早期发现在针对 Elections Alberta 官方 shapefile(于 2026-05-06 收到)的重新分析中未能存留。按照审计永不删除失败发现的预先承诺政策,它在此保留。`,corr_municipal:`<strong>市政锚定(已撤回)。</strong>使用临时地图边界的早期分析显示少数派地图只有 15% 的时间锚定到市政线——比 70–85% 的加拿大常态低 4.9&times;。该数字是临时(DPG 时代)边界重建的伪迹。在 Elections Alberta 官方标准 shapefile 上,两份地图都在加拿大常态范围内锚定:多数派 80%,少数派 72%。两份地图之间的市政锚定<em>差异</em>不是经标准重算后存留的信号。委员会主席标记的三处边界异常(Rocky Mountain House–Banff Park、Nolan Hill–Cochrane、Olds–North Airdrie)仍然存在,不受此更正影响。`},suggestions:{heading:`8:建议`,heading_aria:`链接到第 8 节`,intro:`本次审计遇到了两个数据问题,它们与委员会的工作无关,而与阿尔伯塔选举制度的设计完全有关。两个都可以解决。`,advance_p1:`<strong>现在大约一半的阿尔伯塔选票在选举日之前到达</strong>——预先投票、流动投票、特别选票。Elections Alberta 将这些结果以每个选区的总数报告,而不是按具体投票区。这意味着 2023 年投出的大约 395,000 张 NDP 和 UCP 选票无法定位到地图上的任何街区。它们被计数;只是无法被定位。每位预先投票者在收到选票之前都对照选民名单核对,而该名单将每位选民与其具体投票区关联。发布 VA 级别的预先投票总数不需要改变投票过程——只需改变 EA 报告的内容。`,advance_p2:`这也影响委员会,不仅是外部分析者。当委员会决定是否保持 Airdrie 完整或分割它、两个社区之间的走廊是否合理、提议的边界是否分裂一个自然选区——这些都是依赖于知道选民住在哪里的判断。委员会从与其他人相同的公开数据集工作。他们正在划界的社区的一半地理信号对他们也是缺失的。`,lesser_slave_p1:`阿尔伯塔北部至少有一个社区,这一缺口是完全的。在 Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">查看 ↗</button>选区的北部,有一个覆盖 4,832 km&#178; 的投票区——比爱德华王子岛还大——其中 2023 年的每一张选票都是通过 Elections Alberta 的流动投票队投出的。那 844 位居民的选择被计入选区总数,但无法定位到地图上的任何位置。该社区在已发布的选举结果中完全不可见。`,lesser_slave_p2:`当委员会最初考虑取消 Lesser Slave Lake 选区并将其合并到一个更大选区时,它在没有那些社区地理投票数据的情况下工作。委员会最终保留了该选区——在 80 多份公众意见之后,其中许多来自选区北部的原住民社区——援引了一项允许包含原住民和 M&#233;tis 社区的选区可以比省级平均水平人口更少的省级法律。他们做到了。但他们工作的数据没有向他们显示谁在他们决定保护的社区中投票。`,ebca_label:`EBCA 第 15(2) 节`,ebca_body:`阿尔伯塔《Electoral Boundaries Commission Act》第 15(2) 节是一项自由裁量条款,允许委员会保护小型选区——那些比省级人口平均水平低 25% 以上的选区——当选区满足五项具体标准中的至少三项时:(a) 地理面积超过 20,000 km²,(b) 通过最直接公路距 Legislature Building 超过 150 km,(c) 没有居民超过 8,000 人的城镇,(d) 存在原住民保留地或 M&#233;tis 定居点,以及 (e) 选区是否与阿尔伯塔省的边界一致。该条款不是自动的;委员会必须判断是否满足标准。Lesser Slave Lake 独立满足五项中的四项。`,rationale_p1:`取消该选区的临时理由是人口:约 27,000 居民,Lesser Slave Lake 比省级平均水平低约 45%,接近法律底线。这看起来像是规则的直接应用。它不是。阿尔伯塔法律给予委员会明确自由裁量权,以在五项具体标准中的至少三项适用时保护小型选区,Lesser Slave Lake 独立满足其中四项。其面积为 69,566 km²(标准 a,阈值 20,000 km²)。其最近边界距 Legislature 超过 150 km 公路(标准 b)。选区内没有人口超过 8,000 的城镇(标准 c)。该选区包含十四个原住民保留地和 M&#233;tis 定居点,这些社区共享共同的北部地理、共同依赖流动投票才能投票,以及拥有一位主要对阿尔伯塔北部负责的代表的集体利益(标准 d)。`,rationale_p2:`在所提议的 Mackenzie 合并下,集体声音将永久被吸收到一个对方政党以二比一以上获胜的选区,这不是因为那些社区改变了,而是因为周围的线条改变了。这四项标准每一项都是关于选区地理的客观事实,而不是判断。它们共同描述了该条款所要保护的选区:偏远、广阔、人口稀少,包含那些代表权利益无法从原始人口数字读出的社区。你需要三项才能符合资格;Lesser Slave Lake 有四项。把人口不足当作迫使取消的理由,是对法规的误读。委员会的反转是法律的正确应用,而不是对政治压力的让步。`,banff_p:`下面是故事的另一面:当 Lesser Slave Lake 的原住民社区在为被计数而争取时,异议委员们提议通过 Banff 国家公园(没有人居住的地方)划定边界来保护一个不同的选区。委员会自己的主席称之为"恶意行为",意在主张这一法律保护。这一措辞出现在委员会的官方最终报告中。为有原住民人口的偏远社区设计的保护,在少数派的地图中被用来辩护一条穿过无人居住荒野的边界。它本应帮助的社区不得不通过公众意见为它而战。Lunty 委员会将在 11 月面临相同的 §&#x2009;15(2) 决定——没有举行公开听证的法定要求,也没有保证 80 份意见反转委员会临时立场会第二次具有同样的份量。`,census_p1:`<strong>阿尔伯塔应在绘制下一份地图之前等待 2026 年人口普查。</strong>加拿大每十年普查其人口。2026 年人口普查在 2026 年春季进行;Statistics Canada 大约两年后(在 2027 年或 2028 年)发布可用的省以下数据。绘制本次审计评估地图的委员会不得不使用 2021 年人口普查——在绘制地图时已经四年了,而到这些边界退役时可能已经十四年了。像 Airdrie 和 Chestermere 这样快速增长的城市将在那段时间内变化 40% 或更多。乡村社区将缩小。该地图从被使用的那天起就是错的。对《Electoral Boundaries Commission Act》的简单修改可以要求任何新委员会仅在 Statistics Canada 发布前一次人口普查最新散布区数据后才被任命。结果:反映阿尔伯塔人实际居住地的地图,而不是他们十年前居住的地方。`,census_p2:`Lunty 委员会在现行法规下运作,该法规不设人口普查时间要求,且无法单方面推迟其 2026 年 11 月截止日期。本建议适用于将来对《Electoral Boundaries Commission Act》的修正,而不是当前程序。紧张是真实的:一个必须在 11 月前交付地图的委员会正在使用到那时已五年的数据——指出约束比假装它不存在更有用。`,closing:`两者都不是关于当前委员会地图的发现。它们是关于一种使准确选举分析比必要更难的制度的观察。它们在此作为实用建议,而不是结论。两者都真正可以解决,而解决它们将使每一个未来的委员会——以及每一次未来的审计——从更好的基础上工作。`}},editorial_canada:{heading:`背景:加拿大的不同——以及相似`,p1:`加拿大与美国、英国和澳大利亚属于同一家族。我们在简单多数制下从地理选区选举单一议员。我们定期重新划线——联邦层面每十年人口普查后,省级层面按错开的时间表。我们继承了与威斯敏斯特同根的基本机制。到目前为止,没有意外。`,p2:`加拿大不同的地方,在于线条必须通过的检验。`,p3:`在美国宪法中,具有约束力的规则是<em>一人一票</em>——选区必须在实际可能范围内人口尽可能相等,较大偏离需要严格的正当理由。在加拿大宪法中,具有约束力的规则不同。《加拿大权利与自由宪章》第 3 条保障每位公民投票权。在《Reference re Provincial Electoral Boundaries (Sask.)》中——1991 年的萨斯喀彻温判例,主要案例——加拿大最高法院将该权利解释为<em>有效代表权</em>的权利,而不是选区人口数学平等的权利。`,p4:`这一区别很重要。有效代表权允许选区人口在有充分理由时发生变化,有时是相当大的变化:辽阔的乡村地理一位 MLA 在标准人口密度下无法合理地服务、应被保留在一起的利益共同体、数学平等会稀释的少数派代表权。萨斯喀彻温判例使这种灵活性具有宪法地位。EBCA 的 25% 人口差异——保护乡村阿尔伯塔议席的规则——直接源自它。`,p5:`问题在于灵活性是双刃的。如果委员会能为正确的理由合法地偏离人口平等,它也能为错误的理由偏离人口平等。加拿大法律没有美国式的数学底线作为后盾。它有有效代表权检验,由法官事后在诉讼中应用。大多数司法管辖区通过结构性保护防范错误的理由:联邦选区重划委员会受法规隔离,如果议会在截止日期内不采取行动,其建议自动生效。魁北克使用一个永久性独立委员会,国民议会只能以三分之二超级多数否决其工作。不列颠哥伦比亚在类似的默认采纳规则下运作。`,p6:`阿尔伯塔是例外。根据《Electoral Boundaries Commission Act》,委员会的报告仅是建议——立法机关必须投票通过它。批准通常是形式。在 2026 年周期中,委员会以 3 比 2 分裂并产生两份相互竞争的提议;立法机关创设了一个由省长任命的 MLA 主持的单独 MLA 委员会,以在两者之间选择。加拿大宪法中没有任何东西要求该委员会存在。没有任何东西要求其选择遵循委员会的程序。这就是本次审计正在审视的结构性空缺。`,p7:`所以当加拿大法院说"gerrymander"不是它们的法律词汇时,它们不是说基础概念在这里不适用。它们在说检验不同——是有效代表权,而不是数学平等。少数派提议是否符合该检验,正是本次审计将几何形态与之比较所测量的问题,也正是只有法官才能确定地回答的问题。完整的《Saskatchewan Reference》推理、与其他省份的对比、起诉资格问题以及可用的改革路径在<a href="#references">下方参考资料部分</a>中处理。`},chrome:{back_to_top:`返回顶部`,license_title:`知识共享 署名-非商业性使用-相同方式共享 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`知识共享 BY-NC-SA 4.0`,back_to_stakes:`↑ 返回利害关系`,lightbox:{fig_aria:`图表放大视图`,fig_close_aria:`关闭放大图表(Esc)`,map_aria:`地图缩放查看器`,map_close_aria:`关闭地图查看器`,close_title:`关闭(Esc)`},participation:{heading:`帮助我们改进 MapExplorer`,body:`当你探索时,我们追踪你访问哪些地图和选区,并定期将数据发送到我们的研究数据库。共享视图也会保存你结束时的位置。目标:了解什么有用,并使工具变得更好。`,no_collect:`我们从不收集你的姓名、IP 地址或精确位置。一切在离开你的浏览器之前都被匿名化。即使被命令我们也无法从数据中识别你。`,dnt:`你的浏览器已启用 Do Not Track。已替你预选"否"。你仍然可以选择"是"。`,no_thanks:`不,谢谢`,yes_help:`是的,我愿意帮忙`,privacy_policy:`隐私政策`},share:{button:`分享`,button_title:`分享或加载地图配置`,dialog_aria:`分享地图配置`,close_aria:`关闭分享面板`,share_label:`分享此配置`,share_hint:`在运行审计的任何浏览器中输入此代码即可加载此配置。该代码绝不放入 URL 中。`,load_label:`加载配置`,load_btn:`加载`,load_placeholder:`alpine-eagle-banff`,copy:`复制`,copied:`已复制!`,copy_failed:`失败`,unrecognised:`无法识别的代码——请检查拼写。`},map:{minority:`少数派`,majority:`多数派`,current:`现行`,wasted:`浪费`,wasted_title:`每个选区的效率差贡献`,partisan:`党派`,partisan_title:`按党派结果为每个选区上色(UCP 蓝 / NDP 橙)`,borders:`边界`,flagged:`已标记`,flagged_title:`委员会主席 Miller 法官标记的全部 7 个配置——自动切换到少数派地图`,help_aria:`地图帮助`,help_title:`如何使用地图`,pin_aria:`固定地图`,pin_title:`固定地图——防止点击选区时自动平移`,search_placeholder:`查找选区…`,zoom_aria:`地图缩放`,clear_aria:`清除选区选择`,clear_title:`清除选择`,va_hint:`点击此选区内部以查看投票站结果`,va_close_aria:`关闭投票站详情`,va_close_title:`关闭`,object_title:`阿尔伯塔选区地图——完整分辨率`,ea_credit:`地图数据:`,cc_title:`文本内容:CC BY-NC-SA 4.0`,cc_alt:`知识共享 BY-NC-SA 4.0`},map_intro:{heading:`如何使用地图`,click_district:`点击任意选区`,click_district_desc:`查看 2023 年选举结果并定位到该选区`,click_within:`点击已选中的选区内部`,click_within_desc:`查看单个投票站结果(颜色 = 得票分布)`,dblclick:`双击选区`,dblclick_desc:`缩放至填满屏幕;双击空白处缩小`,layers_primary:`少数派 / 多数派 / 现行`,layers_primary_desc:`切换活动边界地图`,layers_data:`党派 / 浪费 / 边界`,layers_data_desc:`切换数据图层`,search:`查找选区`,search_desc:`按名称跳转;方向键平移,+ / − 缩放`,escape:`Escape`,escape_desc:`关闭此查看器`,s4_tip:`在 §4 中,点击<em>在地图上显示被标记的选区</em>以突出显示 Airdrie 分割和 Calgary 西北区。`,got_it:`知道了`},footer:{title:`阿尔伯塔选举边界审计——2026 年 5 月`,copyright:`© Will Conner 2026 ——`,text_label:`文本:`,code_label:`代码:`}}},"zh-Hant":{selector:{label:`選擇語言`},disclaimer:{text:`本網站由 AI 翻譯。在翻譯進行期間,部分內容可能仍以英文顯示。如果您發現錯誤或希望幫助翻譯本項目,請%s。`,link_label:`聯絡我們`},opener:{heading:`這是為誰準備的?`,body:`為我們。為我們所有人。無論你是鄉村居民、城市居民、好奇者、政治愛好者、記者、律師、學者還是政治人物——我們所有人。因為這影響著我們所有人。無論你是否喜歡執政黨,分裂的委員會所產生的結果是前所未有的。它給了我們一個前所未有的機會,得以窺視這台機器的內部運作。現在我們可以建立一個基準——一系列測試,之後的一切都可以以此為標準進行評估。讓我向你展示我所發現的。`},stakes:{q1:{heading:`所提議的地圖是否構成選區不公?`,body:`「Gerrymander」(選區不公劃分)並非加拿大法院使用的術語。但如果以普通人理解的日常意義來衡量——本次審計的證據合理地支持將<em>少數派提議</em>(若被採納)稱為一份嚴重經過黨派劃分的地圖。本次審計運行的五項結構性測試中有四項標記了<em>少數派提議</em>,沒有任何一項標記另一份提議(<em>多數派提議</em>);第五項測試對兩份地圖均為中性。`,footnote:`「多數派」和「少數派」的稱謂源自選舉邊界委員會(由 Miller 法官主持)內部 3 比 2 的分裂——該委員會未能形成單一建議,而是提出了兩份相互競爭的提議。立法機構此後已將兩份提議均擱置,並將選區重劃事宜交予一個由 Brandon Lunty(由省長任命的 MLA)主持的五人 MLA 委員會;該委員會監督一個獨立的四人諮詢小組——兩名由省長提名(Monte Solberg 閣下和 Darwin Durnie),兩名由反對黨領袖提名(Gerard Kennedy 博士和 Brent Robinson)——負責在 2026 年 11 月截止日期前提出一份全新的 91 席選區方案。`},q2:{heading:`「Gerrymander」在加拿大法律中是什麼意思?`,body:`沒有意義。加拿大的檢驗標準不同:即邊界是否在《憲章》第 3 條之下給予選民<em>有效代表權</em>。少數派提議在該標準下提出了嚴重問題;只有法官才能給出確定性的回答,而目前尚無人提起訴訟。`},q3:{heading:`這對阿爾伯塔人意味著什麼?`,body:`在 50/50 的省級投票情況下,審計的測量將少數派提議置於結構性極端——在 101 萬張中立比較地圖中,產生類似議席不平衡的不到 100 張。這種不平衡之所以重要,是因為在 87 席中獲得 58 席——即三分之二的超級多數——執政黨便解鎖了非常規的程序權力:它可以免除標準通知期,並在一天內將公共法案推過多個立法階段,繞過通常約束它的審議性檢查。少數派提議的傾斜是否大到足以在<em>非</em> 50/50 的投票比例下將一個政黨推過 58 席門檻,這是本次審計尚未測試的問題。這種不平衡本身是否可接受,這是屬於阿爾伯塔人的問題,而非本次審計的問題。`},cta_law:`閱讀法律背景 →`,cta_methods:`查看我們如何測試 →`,scorecard_h:`計分表`,scorecard_fig_alt:`散點圖:橫軸為效率差距,縱軸為未通過的結構性測試數量。2019 年實施地圖與 2026 年多數派地圖聚集在安全的左下角。2026 年少數派地圖獨自出現在右上方的離群區域。`,scorecard_fig_caption:`兩條評估路徑合於一圖。橫軸:黨派公平性數值的偏斜程度(越靠右 = 越有利於 UCP)。縱軸:該地圖在五項結構性公平測試中失敗的數量。左下角是中立程序通常落入的安全區域;右上方則是離群區域。2019 年實施地圖與 2026 年多數派地圖位於安全區域。2026 年少數派地圖獨自位於離群區域。`,scorecard_intro:`兩項獨立測量,使用相同的預先註冊閾值同時應用於兩份地圖。「結構」路徑只看邊界線的形狀——不涉及任何選舉結果。「數字」路徑則檢驗邊界線如何將選票轉換為議席。兩條路徑得出同樣的結論。`,scorecard_close:`兩項獨立測量,一個答案。這種一致性是本次審計最強的單一信號。`},head:{title:`阿爾伯塔選舉邊界審計`,meta_description:`對阿爾伯塔 2026 年選舉邊界委員會的統計審計——101 萬張中立地圖、Elections Alberta 官方 shapefile、預先註冊的測試。`},nav:{skip_to_content:`跳至內容`,home_aria:`返回頂部`,theme_aria:`切換深色 / 淺色模式`,theme_title:`切換深色模式`,nav_aria:`開啟目錄`,drawer_top:`↑ 頂部`,stakes:`結論`,findings:`發現`,history:`歷史`,reform:`改革`,notes:`註記`,group_overview:`概覽`,group_audit:`本次審計`,group_context:`背景`,group_forward:`展望未來`,group_apparatus:`附錄`,why:`為什麼這很重要?`,map:`地圖一覽`,split:`委員會如何分裂`,litmus:`101 萬張地圖試金石測試`,crack_pack:`分散、集中、抽乾`,for_you:`這對你意味著什麼`,impact:`對基層的影響`,gerrymanders:`乾淨的選區操控`,history_full:`選區操控簡史`,canada:`加拿大的不同之處`,november:`十一月`,lunty:`Lunty`,invisible:`隱形`,suggestions:`改革建議`,retractions:`撤回`,references:`參考資料`,resources:`資源`,technical:`技術資源`},hero:{h1:`阿爾伯塔選舉邊界審計`,subtitle:`阿爾伯塔的委員會在 2026 年提出了兩份選區地圖。本次審計對它們進行了比較——使用相同的測試,平等地應用於兩者——以詢問它們是否以同樣的方式對待選民。`,badge:`Elections Alberta 官方地圖——2026 年 5 月發佈`,cover_note:`點擊可同時縮放和探索所有三份邊界提議。固定視口並在地圖之間切換——邊界移動,選民保持不變。向下捲動查看分析。`,cover_note_1:`這張地圖是最好的入口。點擊它即可縮放和探索。頂部按鈕可在少數派地圖、多數派地圖和 2019 年頒布的邊界之間切換——或疊加三者以查看它們的分歧之處。<strong>Detail</strong> 根據 2023 年人們的投票情況為每個投票區上色;<strong>Trend</strong> 按選區添加黨派色調(藍色 UCP,橙色 NDP);<strong>Lines</strong> 切換邊界的開關。<strong>Find</strong> 按名稱跳轉到任何選區。`,cover_note_2:`嘗試鎖定視圖並在地圖之間切換——觀察一條邊界如何移動,而下方的選民保持不動。這就是整個問題,用一個動作表達。`,cover_note_3:`當你探索完畢後,向下捲動查看摘要。如需完整的技術分析,請參閱「資源」部分。所有資料均來自 Elections Alberta 官方 shapefile 以及其他政府和開源記錄。`,image_alt:`阿爾伯塔選區地圖——委員會少數派提議,按 2023 年投票上色`,map_hint:`點擊進行互動式探索`,btn_title:`點擊打開互動式地圖`,btn_aria:`點擊進行互動式探索`},boundary:{heading:`本次審計能告訴你什麼,不能告訴你什麼`,can_1:`少數派地圖的幾何形狀在<em>完全不使用任何選舉資料</em>的情況下,越過了 5 項預先註冊的結構性閾值中的 4 項。第 5 項(錨定)為中性。多數派地圖在觸發的 4 項中越過 0 項。這些測試只測量邊界線本身的屬性——選區形狀、市政錨定、人口分布——並在計算任何選票之前就得出結論。`,can_2:`另外,當引入選舉資料時,少數派地圖在依照相同法定規則所繪製的 101 萬張演算法中立比較地圖中位居第 99.99 百分位。在這 101 萬張中立地圖中,達到相同議席不平衡的不到 100 張。在中立繪製程序之下,兩項聯合統計信號的機率約為 1450 萬分之一。兩項獨立工具——幾何與統計——得出相同結論。`,can_3:`少數派提議所包含的三種配置,曾被委員會主席 Miller 法官在多數派報告的 §5.8.2 和附錄 C 中以書面形式提出質疑。本次審計的測試是在不知道他質疑的情況下進行的,卻發現了相同的區域。第三項獨立工具——司法——也匯聚到相同的邊界上。`,cant_1:`本次審計<strong>未能</strong>證明任何委員有意製造其所測量的黨派效應。邊界幾何無法揭示意圖。`,cant_2:`本次審計<strong>不</strong>預測 Lunty 委員會會做出什麼選擇,2026 年 11 月投票結果如何,或阿爾伯塔人會如何反應。`,cant_3:`本次審計<strong>不</strong>預測如果對任一提議提起《憲章》訴訟,法院將如何裁決。`,cant_4:`本次審計<strong>不</strong>主張 1450 萬分之一這個數字就是發生選區操控的機率。該數字是少數派地圖幾何在中立演算法虛無假設下的尾部機率。它是中立虛無假設不可信的證據。它不是黨派意圖的後驗機率——後一問題需要幾何無法提供的證據。`,cant_5:`本次審計<strong>不</strong>告訴任何選民應採取什麼立場或如何處理這些資訊。這由你決定。`},editorial_intro:{heading:`什麼是選區劃分,以及為什麼這很重要`,p1:`阿爾伯塔的每位選民都生活在一個<em>選區</em>中——省份的一個切片,負責選出一位省議會議員。共有 87 個選區。每個選區選出一位 MLA。當你在省級選舉中投票時,你是在為你所居住的選區選出 MLA。這就是大多數阿爾伯塔人與立法機構的全部聯繫:一位 MLA,一個選區,一票。`,p2:`這些選區界線並非永久。人會搬家,社區會擴大,鄉村會變少,城市會擴張。每隔八到十年,阿爾伯塔應該重新劃界,使每個選區大致大小合適,並反映阿爾伯塔人現在實際的居住情況。負責重新劃界的機構是<em>選舉邊界委員會</em>——一個由法官、律師和公眾成員組成的獨立委員會,而非政客。`,p3:`那是標準程序。這一次,標準程序產生了不尋常的結果。委員會的五名成員就地圖應是什麼樣子分裂成了 3 比 2,他們未能形成單一建議,而是提出了兩份:一份<em>多數派提議</em>(由三位委員支持)和一份<em>少數派提議</em>(由兩位支持)。兩份都擺在桌上——但立法機構已將兩份都擱置。一個由 Brandon Lunty 主持的獨立 MLA 委員會——由省長為此特定決定任命——現監督一個依據政府第 37 號議案(2026 年 4 月 21 日通過)組建的四人獨立諮詢小組,負責制定一份全新的 91 席選區地圖。立法機構必須在 2026 年 11 月之前批准該委員會提交的方案。`,p4:`為什麼這對你重要:這些界線決定了誰是你的 MLA。它們決定了哪些社區、城鎮和關切被一起代表。如果你的城市被切分到四位 MLA 而不是一位,沒有任何一位代表對整個城市負責。如果你的利益共同體——一個小鎮、一個鄉村地區、一個市中心——被劃分到不同的選區,你在省級決策中的聲音便被稀釋。這張地圖還塑造了哪個政黨能組建政府,以及以何種邊際。本次審計的具體發現(少數派提議處於結構性極端)是你正在閱讀本網站的原因,但更廣泛的問題更古老,適用於每一個選區重劃週期:這些界線反映了阿爾伯塔人的實際居住方式,還是塑造了之後的政治?`,p5:`本頁的其餘部分將講解這兩份提議地圖實際上做了什麼。`,key_terms_lead:`本節關鍵術語——點擊閱讀:`},editorial_reflect:{heading:`插曲:這對你和你的社區意味著什麼`,intro_p1:`暫時把哪一黨贏得或失去議席的問題擱在一邊。政治人物和政黨往往把這件事框定為立法機關內權力集中的爭奪,而在立法尺度上確實如此。但立法機關的權力集中並不是你體驗這些地圖的地方。你是透過關於自己選區的三個具體問題來體驗它們的:`,intro_q1:`你的 MLA 住在哪裡?`,intro_q2:`他們是否投入於你的社區?`,intro_q3:`主體的需求是否會壓倒尾端的需求?`,intro_p2:`其他每一種框架——黨派優勢、超級多數門檻、統計極端——最終都指向這三個問題。下面的五個層級在五種尺度上,分別講解每份提議地圖如何回答這些問題。`,you_h:`你。`,you_p:`你的選區決定誰在立法機構中代表你。目前你住在 87 個選區中的一個。在兩份提議地圖之下,你可能會住在不同的選區——可能換了一位 MLA,可能錨定到不同的鄰近社區。如果你不知道自己現在屬於哪個選區、或誰是你的 MLA,你並不孤單:大多數阿爾伯塔人說不出自己的 MLA 是誰。但邊界線並不抽象。它們決定了你當地代表辦公室牆上掛的電話號碼是誰的、誰的鄰里請願書上有你的名字、你的 MLA 最先聽到誰的關切。本網站上的郵編查詢可以告訴你,在每份提議下你屬於哪個選區。如果你的選區改變,你的代表也會改變——而你代表與你社區的關係也會隨之改變。`,community_h:`你的社區。`,community_p:`社區同樣不是抽象的。一所高中的學區範圍、一個商會、一個信仰社群、一個社區協會——這些都是擁有共同地方關切的真實人群。當一條邊界從中間切過,沒有任何一位 MLA 對整體負責。以少數派提議下的 Airdrie 為例:一個約 85,800 人的城市被切成四個選區,每一個都錨定到不同的鄉村腹地。沒有任何一位代表對 Airdrie 作為一座城市負責。同樣的動態出現在任何一個被分割的城鎮、鄰里或公認的利益共同體上——分割越大,代表性越弱。本次審計測量了<em>市政錨定</em>(每個選區邊界中沿用既有市政界線的比例),少數派提議在錨定測試上的得分明顯低於多數派。`,municipality_h:`你的市政府。`,municipality_p:`當一個城市被分裂給許多代表時,它在省級決策上的議價能力就會減弱。一個議會爭取交通基建資金、一個學校董事會協商新校舍、一位市長為公路延伸遊說——當城市能指向幾位對整體負責的 MLA 時,這些事情都會更順利。少數派提議將 Calgary 的西北區劃分成多個選區,其投票模式顯示出<em>集中</em>(將某黨選民集中到少數高票差席位)疊加<em>分散</em>(將另一黨選民分散到許多低票差席位)的特徵。這種模式是否出於有意,本次審計無法回答——邊界幾何不揭示意圖。但能說的是,四項統計指標所標記的選區與結構性測試所標記的選區相同,而另一份提議並未產生相同的指紋。`,region_h:`你的地區。`,region_p1:`如果你住在阿爾伯塔的城市之外,你大概已經注意到關於邊界的政治討論似乎總以城市為中心。這是個合理的抱怨,所以讓我們直接說明本次審計對鄉村阿爾伯塔的說法和未說法。`,region_p2:`本次審計<strong>並未</strong>說:鄉村阿爾伯塔的議席太多。EBCA 允許選區人口最多偏離平均值 25%,以免某位鄉村 MLA 代表一個相當於法國南部那麼大的地理區域。加拿大法院視這種偏差為合法。兩份提議地圖都保留了這一點。本次審計也未改變這一點。`,region_p3:`本次審計<strong>確實</strong>說:在少數派提議的多處地方,鄉村社區被當作某個人口中心位於城市的選區的<em>尾端</em>。看看少數派提議如何處理 Airdrie——一個約 85,800 人的城市被切成四個選區,每一個都延伸到不同的鄉村地區。每個新選區的人口中心都是其城市部分,而不是鄉村尾端。在這類選區當選的 MLA 最可能在選民集中的地方居住、競選、設定優先事項——這意味著原先由專門的鄉村 MLA 代表的鄉村社區,變成了由城市主導席位的後半段。這種模式在少數派提議中反覆出現,而多數派提議則沒有。`,region_p4:`本次審計並不建議從鄉村阿爾伯塔取走議席。它問的是,這些邊界線是否尊重這些議席應代表的鄉村社區,還是把鄉村地理當作壓艙物,用以吸收進入中心位於別處的選區的城市選票。如果你住在這些鄉村尾端中的一處,究竟哪份地圖被通過,將決定你的 MLA 究竟代表你實際居住的鄉村社區,還是其邊界線恰好把你的土地包括在內的城市選區。`,province_h:`你的省份。`,province_p:`立法機構就是把每個選區對上述三個問題的答案加總後的結果。如果大多數選區都錨定於由實際住在當地的 MLA 所代表的社區,立法機構便代表這些社區。如果大多數選區都把鄉村尾端附在城市主體之上,立法機構就代表主體——而尾端只能得到剩下的注意力。黨派問題——哪個政黨贏得多數——是這個結構的下游問題。超級多數問題——某黨能否在 87 席中拿下 58 席,進而解鎖免除通知期或在一天內加速法案通過多個階段等程序捷徑——又是<em>那個</em>問題的下游。在假設的 50/50 省級分割下,本次審計的測量將少數派提議置於結構性極端:在 101 萬張中立比較地圖中,產生相同種類議席不平衡的不到 100 張。這種不平衡是否會在阿爾伯塔選民實際投出的票比之下將某黨推過 58 席,本次審計尚未直接測試;本頁頂部的開場問題對此差距是誠實的。這些問題中的任何一個答案是否重要到值得行動,同樣由你決定。`},editorial_history:{heading:`背景:選區操控簡史`,p1:`「gerrymander」這個詞源自 1812 年。麻州州長 Elbridge Gerry 簽署了一份對其政黨有利、選區形狀扭曲得離奇的州參議院地圖,以致一位波士頓漫畫家把其中一個選區畫成了一隻火蜥蜴——有翅膀、爪子、分叉的舌頭。這位漫畫家的雙關語 <em>Gerry-mander</em> 流傳了下來。形狀也流傳了下來:兩個世紀後,這個詞仍然意味著為了製造黨派結果而劃定的選舉邊界。`,p2:`這個詞之所以延續,是因為問題仍在延續。任何選民從地理區域選出代表的地方,都得有人來劃線,而線可以以許多種方式劃。不同國家對於由誰來劃、應受何種約束,得出了不同的答案。`,p3:`<strong>美國</strong>把黨派選區操控視為聯邦法院基本上無法解決的問題。在 <em>Rucho v. Common Cause</em>(2019 年)中,美國最高法院裁定黨派選區操控屬於其管轄之外的「政治問題」。一些州(加州、密西根州)的回應是設立獨立公民委員會來劃線;其他州(德州、北卡州)則繼續繪製公開黨派化的地圖,並以 <em>Rucho</em> 容許此舉為據加以辯護。`,p4:`<strong>英國</strong>使用四個常設邊界委員會——英格蘭、蘇格蘭、威爾斯、北愛爾蘭各一——由法官和高階公務員組成。它們大約每八年依固定規則(人口平等、地理連貫、尊重地方政府邊界)重新劃線。國會理論上可以拒絕委員會的建議,但實際上幾乎從未這樣做;依慣例,委員會的判斷成立。`,p5:`<strong>澳洲</strong>把這項工作交給澳洲選舉委員會,一個對選舉行政和邊界都具有完全權力的聯邦獨立機構。當某州的議席數量改變,或上次重新分配後過了七年,重新分配就自動發生。委員的決定可在程序上被審查,但在黨派上不可。如同英國,在美國人所知的意義上,選區操控幾乎聞所未聞。`,p6:`這三個案例界定了光譜:法院迴避(美國)、獨立委員會搭配強烈的議會尊重(英國)、以及具完全權力的常設獨立機構(澳洲)。加拿大的位置又不同——這正是下一節要談的。`},glossary:{more_link:`了解更多 →`,"electoral-district":{term:`選區 (ED)`,definition:`選出一位省議會議員的地理區域。首次使用後常縮寫為「ED」。每個 ED 有一位 MLA。(「riding」一詞通常指聯邦選區;在省級脈絡中,正確的用語是 electoral district。)`},riding:{term:`Riding`,definition:`在加拿大用法中,這通常指聯邦選區。阿爾伯塔省級的對應稱為 electoral district (ED)。本次審計通篇使用省級用語。`},mla:{term:`MLA (省議員)`,definition:`立法議會議員(Member of the Legislative Assembly)——從某個選區當選、在阿爾伯塔立法機構中代表該選區的人。`},ucp:{term:`UCP`,definition:`聯合保守黨(United Conservative Party)——阿爾伯塔現任執政黨。2017 年由進步保守黨和野玫瑰黨合併而成;自 2019 年起執政。`},ndp:{term:`NDP`,definition:`新民主黨(阿爾伯塔 NDP)——阿爾伯塔現任官方反對黨。阿爾伯塔 NDP 曾於 2015 年至 2019 年執政。`},gerrymander:{term:`Gerrymander(選區不公劃分)`,definition:`被繪製成讓某個政黨贏得議席數高於其得票份額所暗示的地圖。此詞源於 1812 年麻州一個形似火蜥蜴的選區。在加拿大這不是法律術語,但此概念被廣泛研究。`},cracking:{term:`Cracking(分散)`,definition:`一種選區操控技術,將某個投票群體分散到許多選區,使其在任何單一選區都無法達到多數。例如將一座城市切分到四個 riding,使其選民在每個選區中都處於少數。`},packing:{term:`Packing(集中)`,definition:`一種選區操控技術,將某黨選民集中到少數選區。該黨壓倒性地贏得這些選區,但「浪費」了許多選票——使其選民在其他選區中可資爭奪的人數減少。`},draining:{term:`Draining(抽乾)`,definition:`本次審計用來描述 cracking 與 packing 後續效應的術語:這些技術產生的浪費選票被推向策略性選定的地點,改變了鄰近選區的政治屬性。這是本次審計自己的框架,而非選區重劃文獻中既有的概念——本次審計對該效應進行了測試並發現結果與其一致,但將其視為探索性的,而非已定論的方法。`},anchoring:{term:`Anchoring(錨定)`,definition:`提議邊界沿用既有市政界線(市界、鎮界)的緊密程度。高度錨定的地圖大致尊重這些界線;鬆散錨定的地圖則經常偏離——特別是在政治意義重大的地點,這是一個結構性警訊。`},"charter-s3":{term:`《憲章》第 3 條`,definition:`加拿大《權利與自由憲章》中保障公民投票權的條款。加拿大法院並未將其解讀為嚴格的「一人一票」原則,而是視為「有效代表權」的權利。`},"effective-representation":{term:`有效代表權`,definition:`加拿大法院在判斷選舉邊界時所適用的標準。它意味著選民應有實質的聲音——不僅是選區人口的數字平等,還包括對社區聯繫、地理和少數群體代表性的認可。主要表述來自加拿大最高法院 1991 年的薩斯喀徹溫省判例。`},ebc:{term:`選舉邊界委員會 (EBC)`,definition:`依 EBCA 繪製阿爾伯塔省級選舉邊界的機構。2026 年委員會由 Miller 法官主持,其委員以 3 比 2 分裂,提出了兩份相互競爭的提議(多數派與少數派提議)而非單一建議。`},"lunty-committee":{term:`Lunty 委員會`,definition:`由 Brandon Lunty(省長任命的 MLA)主持的五人 MLA 選舉邊界特別委員會,依立法議會第 19 號議案(2026 年 4 月 16 日)成立,該議案擱置了兩份委員會報告。該委員會監督一個依據政府第 37 號議案(2026 年 4 月 21 日通過)組建的獨立四人諮詢小組,後者繪製實際地圖;接著由委員會在 2026 年 11 月截止日期前向立法機構提交報告。這兩個機構都獨立於 EBC,也不屬於標準 EBCA 程序。`},"advisory-panel":{term:`獨立諮詢小組`,definition:`由 Lunty 委員會依據政府第 37 號議案 C(d)(ii) 款任命的四人小組,負責提出 91 席邊界建議。省長提名 Monte Solberg 閣下和 Darwin Durnie;反對黨領袖提名 Gerard Kennedy 博士和 Brent Robinson。第五個席位——擔任主席的現任或退休法官——在阿爾伯塔代理首席法官拒絕提名後懸缺。`},ebca:{term:`EBCA`,definition:`《Alberta Electoral Boundaries Commission Act》(阿爾伯塔選舉邊界委員會法)——規範本省選舉邊界如何劃定的法律。它建立了委員會、公聽程序,以及新地圖何時生效的規則。`},fsa:{term:`前向分揀區 (FSA)`,definition:`加拿大郵編的前三個字符(字母-數字-字母部分)。約有 270 個 FSA 覆蓋阿爾伯塔。大多數完全落在單一選區內。`}},body:{section_link_aria:`連結至本節`,the_map:{heading:`1:地圖`,p1:`封面地圖是本次審計中最佳的單張圖像。以下是如何閱讀它。`,p2:`阿爾伯塔被劃分為 4,765 個投票區——Elections Alberta 用以計算投票站選票的小型地理區域。每一個都按照 2023 年其中人們實際的投票情況上色:NDP 選票集中之處呈橙色,UCP 選票集中之處呈藍色。但只有在人口眾多之處,顏色才會變深變飽和。一個覆蓋數百平方公里林地或農田的投票區會保持淺色——幾乎看不見。地圖在有人的地方點亮,在沒人的地方褪色。`,p3:`這與你在選舉之夜看到的阿爾伯塔很不一樣。大多數選舉地圖根據誰勝出將整個 riding 塗成純藍或純橙。鄉村 riding 在地理上很大,UCP 贏得其中大多數,所以選舉之夜的阿爾伯塔看起來像一面藍色之牆,只在 Edmonton 和 Calgary 有小塊橙色。封面地圖使用相同的選票和相同的地理——但按照人們實際居住的地方加權呈現。所呈現的是一個大多數人口集中在城市密集弧形帶上的省份,而這些城市的投票方式與通常代表它們的鄉村地圖大相徑庭。`,p4:`繪在顏色之上的邊界線是少數派委員會提議的 89 個選區——這正是本次審計最後批判的地圖。本次審計的工作是去問,這些線對它們下方的人們做了什麼。`,p5:`這幅圖像讓利害關係一目了然。一個在標準地圖上看起來投向某一方的省份,實際上是一個大多數人口居住在投向另一方的地區的省份。一旦邊界選擇下方的人口可見,這些選擇就不再看起來隨機。`},structural_results:{heading:`結構性審計結果——在任何統計之前:`,body:`多數派地圖越過<strong>零項</strong>預先註冊的結構性閾值(共五項)。少數派地圖越過<strong>四項</strong>;第五項(錨定)為中性——兩份地圖都落在 70–85% 的加拿大常態範圍內。這些是幾何測量——人口分布、<button class="vocab-term" data-def="某選區邊界沿用既有市政與市界的緊密程度,而非從中切過" aria-expanded="false">市政錨定</button>、Airdrie 切分數、Calgary 西北人口過剩、以及委員會主席 Miller 法官自己以書面形式提出質疑的七種邊界配置(多數派報告 §5.8.2 和附錄 C)——不需要任何選舉資料和任何統計取樣器。下一節將兩份地圖與 1,010,000 張電腦生成的中立地圖進行對照,並透過完全不同的工具得出相同結論。三項獨立工具——幾何、司法、統計——匯聚在一起。`},clean:{heading:`6:當一份看似公平的地圖並不公平`,legal_label:`關於法律術語的說明`,legal_body:`「Gerrymandering」在加拿大法律中沒有定義。本報告通篇以日常政治意義使用該詞——為黨派優勢操縱選舉邊界。實際在加拿大適用的法律檢驗有所不同:即邊界是否依《Charter of Rights and Freedoms》(加拿大權利與自由憲章)第 3 條提供「有效代表權」(加拿大最高法院於 1991 年《Saskatchewan Reference》中所確立的憲法標準),以及委員會是否遵守了阿爾伯塔《Electoral Boundaries Commission Act》(選舉邊界委員會法,EBCA)的規則。本次審計的發現是與這些法律問題相關的證據。它們不是法律上界定錯誤的證明,本報告也不以這種方式描述它們。`,intro_p1:`對任何選舉地圖最乾淨的單一問題是:如果本省的投票在兩大主要政黨之間恰好平均分配,這張地圖會產生什麼樣的議席分布?這固定了選民群體,並單獨問地圖本身做了什麼。`,intro_p2:`為了回答這個問題,本次審計生成了 1,010,000 張電腦模擬、數學上中立的阿爾伯塔地圖。模擬使用了 Elections Alberta 官方 shapefile,並嚴格遵守委員會所使用的相同法定規則和地理邊界。然後將委員會的兩份 2026 年地圖放入該分布,以查看它們有多麼正常。模擬執行了四條獨立的鏈,每條 252,500 步,基礎種子來自 Cloudflare drand 信標,並在執行前於 OSF 預先註冊。`,howmcmc_label:`模擬如何運作`,howmcmc_mcmc:`<strong>MCMC(馬可夫鏈蒙地卡羅)</strong>是一種探索大空間的方法——在此即所有合法阿爾伯塔地圖的空間——透過從起點隨機地一步步走。每一步提議在相鄰選區之間進行小規模交換;如果結果仍在法定規則之內,它就成為新的起點。足夠多的步驟之後,所訪問的地圖構成合法方案的代表性樣本。模擬以 Cloudflare drand 公共隨機性信標作為種子,以防止任何起始條件被擇優挑選。`,howmcmc_recom:`<strong>ReCom(選區重劃編譯器)</strong>是這裡使用的具體演算法。每一步將兩個相鄰選區合併為一個區域,並隨機重新切分為兩個有效的新選區,從建構上保留連通性與人口平衡——演算法因此從不需要拒絕無效的提議。`,prereg_label:`預先註冊`,prereg_body:`預先註冊指在查看任何資料之前,先把確切的測試、閾值和預期方向寫下來,並把這些承諾鎖入一個帶有時間戳的公開記錄中。Open Science Framework(OSF)是本次審計承諾被登錄的公共儲存庫。它防止事後調整:如果結果無法乾淨地出現,事後也不能修改閾值再聲稱它一直就是這個測試。本次審計的五項結構性測試和四項黨派公平性指標都在任何模擬執行前於 OSF 註冊。`,neutral_p:`在阿爾伯塔,中立的答案不是 50/50。<em>在 1,010,000 張電腦模擬的合法阿爾伯塔地圖中,中位地圖在 50/50 票分配下只給 UCP 44.8% 的議席</em>——在中立投票下,典型的阿爾伯塔地圖會給 NDP 微小的議席多數。這在直覺上違反常理但屬於機械結果:鄉村 UCP 選民以 60-40 的差距贏得 riding(浪費許多「多餘」的 UCP 選票),而都市 NDP 選民則以較緊的 51-49 差距贏得 riding(每次勝利浪費的 NDP 選票較少)。在中立情況下,NDP 在議席效率上領先。`,full_dist:`來自規範的 1,010,000 張地圖模擬的完整分布:`,t1_col_a:`地圖位置`,t1_col_b:`50/50 票下的 UCP 議席`,t1_r1_a:`中位阿爾伯塔地圖`,t1_r1_b:`44.8% — NDP 微小議席多數`,t1_r2_a:`第 95 百分位地圖`,t1_r2_b:`47.1%`,t1_r3_a:`第 99 百分位地圖`,t1_r3_b:`48.4%`,t1_r4_a:`<strong>1,010,000 張地圖中的最大值</strong>`,t1_r4_b:`<strong>低於 51.7%(達到此值的方案不到 100 份)</strong>`,seat_count_note:`關於議席數的說明。2026 年委員會地圖各有 <strong>89</strong> 個選區;本次審計的電腦模擬基於 <strong>87</strong> 席的 2019 年地圖(其起始基底)執行;十一月的 Lunty 委員會將產出 <strong>91</strong> 席。所有百分比都是議席<em>份額</em>,在這些分母間可比較。模擬以 2019 年地圖作為起點,是因為 ReCom 演算法需要一份合法實施的地圖以便提議交換——2019 年地圖是最近一份依法實施的阿爾伯塔選舉地圖。以任一委員會提議作為基底會造成循環論證:我們將會以衍生自自身的地圖去衡量地圖是否極端。`,pattern_intro:`結果——將三張真實地圖放入此分布——指向一種具體、外科手術式的邊界繪製模式。`,sub1_h:`四項統計指標同時觸發`,sub1_p:`當使用 Elections Alberta 官方 shapefile 時,少數派地圖在每一項黨派公平性指標上都是統計離群值——不僅僅是「臨界點」指標。`,t2_col_a:`地圖`,t2_col_b:`效率差距`,t2_col_c:`均值-中位數`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Declination 衡量各黨議席-得票曲線之間的角度差。負值偏向 UCP;正值偏向 NDP。">Declination</a>`,t2_col_e:`50/50 下的議席`,t2_r1_a:`2026 多數派`,t2_r1_b:`+0.04% (p15.5)`,t2_r1_c:`−3.6% (p2)`,t2_r1_d:`+0.027 (p81)`,t2_r1_e:`46.1% (p83)`,t2_r2_a:`2026 少數派`,t2_r2_b:`<strong>+3.96% (p94.4)</strong>`,t2_r2_c:`<strong>+1.0% (p99.98)</strong>`,t2_r2_d:`<strong>−0.077 (p1.2)</strong>`,t2_r2_e:`<strong>51.7% (p99.99)</strong>`,sub1_close:`多數派地圖在四項指標中的三項上舒適地落在正常範圍內。其均值-中位數位於 p2,方向偏向 NDP——一個不尋常的結果,但方向不利於 UCP。多數派地圖緊密遵循市政邊界,使 NDP 占優勢的都市核心被放入各自緊湊的選區,NDP 選票以高效的差距獲勝,而 UCP 在鄉村的勝利則往往以更大差距獲得;這種輕微的結構性 NDP 效率優勢就反映在均值-中位數測量上。少數派地圖在四項指標上都處於尾端,且每一項都指向相同的黨派方向。`,sub2_h:`50/50 臨界點:1,010,000 張中立地圖中不到 100 張達到該值`,sub2_p:`上述介紹的臨界點指標——50/50 省級投票下的 UCP 議席——是比較三張地圖最直觀的方式。`,t3_col_a:`地圖`,t3_col_b:`50/50 票下的 UCP 議席`,t3_col_c:`位置`,t3_r1_a:`2019 已實施`,t3_r1_b:`46.0%`,t3_r1_c:`第 83 百分位——正常範圍內`,t3_r2_a:`<strong>2026 多數派</strong>`,t3_r2_b:`<strong>46.1%</strong>`,t3_r2_c:`<strong>第 83 百分位——遠在邊界內</strong>`,t3_r3_a:`<strong>2026 少數派</strong>`,t3_r3_b:`<strong>51.7%(46 席)</strong>`,t3_r3_c:`<strong>第 99.99 百分位——1,010,000 張中立樣本中不到 100 張達到此值</strong>`,sub2_close:`在 1,010,000 張電腦模擬的中立阿爾伯塔地圖中,不到 100 張產生了與少數派提議一樣高的 <code>seats@50/50</code> 值。根據實際近期的投票模式,它會給予 UCP 60 席(相較之下多數派提議為 55 席)。多數派提議是中立程序常規生成的那種地圖。少數派提議則是你必須有意瞄準才能繪製出來的地圖。`,sub3_h:`這在白話中的意義`,sub3_p:`官方 shapefile 揭示了一份在四項指標上同時、同一黨派方向上都極端的統計地圖。中立繪圖程序在所有四項指標上同時產生如此極端地圖的聯合機率約為 1500 萬分之一(p&nbsp;=&nbsp;6.87×10<sup>−8</sup>,<a href="https://osf.io/6pt83" rel="noopener">預先註冊的 Fisher 合併檢驗</a>)。這不是四捨五入誤差或測量假象——這是四項獨立統計工具在同一個房間裡讀到的同一個答案。`,details_summary:`這個 p 值意味著什麼——以及它不意味著什麼`,details_p1:`p 值回答一個問題:如果這張地圖是由中立程序所繪,我們多久會看到一個如此極端或更極端的結果?在 p&nbsp;=&nbsp;6.87×10<sup>−8</sup> 之下,答案是在大約 1450 萬次試驗中發生一次。`,details_p2:`這是頻率主義的假設檢驗,而非對意圖的測量。它並未說委員會意圖進行選區操控,也未量化這張地圖在實際意義上有多不公。它說的是,邊界模式在統計上與中立繪圖程序不一致——隨機審計無論誰繪製此地圖或出於什麼原因都會得出相同結論。`,details_p3:`此檢驗在資料分析前已預先註冊(<a href="https://osf.io/w2s8k" rel="noopener">OSF 註冊 w2s8k</a>)。預先註冊預先指定了虛無假設、指標和拒絕閾值,因此結果不能歸因於在看到數字之後選擇有利的框架。`,szat_label:`搖擺區分配測試 (SZAT)`,szat_body:`SZAT 是本次審計的第二項獨立測試,它提出一個與模擬不同的問題:不是「這張地圖整體是否極端?」而是「具體的劃線選擇是否黨派中立?」它的運作方式是只孤立出少數派地圖與多數派地圖不同的投票區——那些有爭議的重劃——並測試這些特定的選擇加總起來是否將投票效率向某一黨方向推移。因為它只比較分歧之點,所以自動控制了兩張地圖共享的一切:相同的地理、人口目標和法定規則。<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">技術細節與 bootstrap 結果 →</a>`,two_q:`<strong>兩個問題,一個答案。</strong>1,010,000 張地圖的模擬問:<em>這張地圖相較於在同一阿爾伯塔地理上繪製的中立地圖是否極端?</em>另一項獨立測試——稱為<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">搖擺區分配測試</a>——問另一個問題:<em>地圖上具體的線條是否黨派中立?</em>它的運作方式是只查看少數派與多數派劃法不同的投票區,並詢問這些特定選擇加總起來是否將投票效率向某一黨方向推移。因為它只比較兩張地圖不同之處,所以自動控制了它們共享的一切——相同的省級地理、相同的人口目標、相同的法定規則。兩個問題得出相同答案。這正是為什麼 1500 萬分之一這個數字是一個合併結果而非單一檢驗:它是兩條獨立的證據線匯聚在一起。`,super_lead:`這解釋了為什麼少數派提議必須在 1,010,000 次中立模擬中成為如此極端的統計離群值 (p99.99)。在 89 席的立法機構中,三分之二超級多數恰好需要 60 席。在中立投票下,中立程序不會在阿爾伯塔的地理上產出 60 席的結果;達到此門檻需要刻意偏離中立基準的邊界選擇。`,super_label:`為什麼超級多數很重要`,super_body:`在加拿大的西敏寺議會制下,簡單多數(45 席)足以通過例行法律和預算。三分之二超級多數(60 席)能做得更多。它允許執政黨援引「終止辯論」以中止辯論、未經反對黨同意便重寫程序規則,並控制每一個立法委員會的組成。它也讓政府免於內部異議:即使有六、七位後座議員跨界投票,政府仍握有可運作的多數。簡單多數讓你開車;60 席超級多數讓你重寫交通法規。`,super_close:`透過策略性地將都市選民稀釋進周邊的鄉村邊緣選區(在路徑 2 中辨識出的「都市混合化」模式),少數派提議精準工程化出取得這 60 席所需的結構性防火牆。路徑 2 的結構性發現與路徑 1 的統計發現匯聚於同一份提議、同一個方向、同一些社區之上。`,sub4_h:`針對性程序測試的確認`,sub4_p:`為了確保這不是中立模擬已知的緊湊性偏好造成的怪象,本次審計在兩個方向上執行了一個針對性的爬山程序(<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et al. 2022——已在技術報告中引用並描述</a>):最大化 UCP 議席與最大化 NDP 議席。每個方向相同的步數(40,000)、相同的法定約束、相同的省級幾何。`,t4_col_a:`程序`,t4_col_b:`達到的最極端值`,t4_col_c:`告訴我們什麼`,t4_r1_a:`中立 MCMC,所產生的最大值`,t4_r1_b:`低於 51.7% UCP 議席 @ 50/50`,t4_r1_c:`中立繪圖下的自然上限`,t4_r2_a:`中立 MCMC,所產生的最小值`,t4_r2_b:`~39% UCP 議席 @ 50/50`,t4_r2_c:`中立繪圖下的自然下限`,t4_r3_a:`針對性爬山,最大化 UCP`,t4_r3_b:`<strong>52.9%</strong>`,t4_r3_c:`刻意瞄準 UCP 優勢的程序所能達到的值`,t4_r4_a:`針對性爬山,最大化 NDP`,t4_r4_b:`<strong>37.9%</strong>`,t4_r4_c:`刻意瞄準 NDP 優勢的程序所能達到的值(低於中立下限)`,sub4_close:`少數派地圖的 51.7% 更接近針對性 UCP 上限(52.9%)而非中立中位數(44.8%)。多數派地圖的 46.1% 位於中立中位數。2019 已實施地圖和 2026 多數派地圖都舒適地落在中立程序常規產生的範圍內——不同的得票份額,相同的不顯眼結果區域。多數派在黨派公平軸上延續了 2019 年阿爾伯塔的做法,正如它在市政錨定上延續了 2019 年的做法一樣(80.0% 相對於 2019 年的 75.2%)。同樣的阿爾伯塔規則之下、同樣五位委員、同一個房間裡繪製的兩張地圖:一張落在中立程序常規所產生之處,另一張落在你必須刻意瞄準才能到達之處。`,sub4_quote:`<em>這</em>就是發現的形狀,也是法院實際上會採用的框架。`,sub5_h:`排除其他解釋`,sub5_p:`面對如此規模的統計離群值,一份嚴謹的審計必須在將這些模式歸因於刻意設計之前排除無辜的解釋。結構資料(路徑 2)系統性地拆解了標準替代辯護:`,defense1:`<strong>「自然政治地理」辯護:</strong><em>(「都市選民天然就被集中;地圖只是反映阿爾伯塔的地理。」)</em>1,010,000 次模擬已經將阿爾伯塔的自然地理納入考量。模擬證明:雖然地理給了 UCP 一個基線效率優勢,但它自然地封頂在第 83 至第 90 百分位附近。少數派地圖位於第 99.99 百分位——<em>即使與阿爾伯塔自然偏斜的基線相比</em>仍是極端離群值。`,defense2:`<strong>「利益共同體」辯護:</strong><em>(「奇怪的形狀是為了讓特定社區保持在一起。」)</em>如果你想讓社區保持在一起,你會沿著市政邊界。多數派地圖有 80% 的時間遵循既有市界。少數派地圖則為 72%——兩者都在加拿大 70–85% 的常態範圍內。少數派地圖實際做的是主動將統一的 Airdrie 切成四個獨立部分,並將其三項邊界決定精準地放在委員會主席標記為幾何異常的都市邊緣區——這些選擇無法以利益共同體邏輯來解釋。`,defense3:`<strong>「人口平等」辯護:</strong><em>(「他們必須繪製奇怪的邊界,才能確保每個選區人口完全相同。」)</em>少數派地圖實際上在人口平等上<em>更差</em>。其人口平均絕對偏差(MAD)為 4,707——比多數派地圖的 3,180 寬 48%——位於規範整體的第 99 百分位(每 100 張中立地圖中只有 1 張產生更差的分布)。它為了達到自己的形狀而犧牲了人口平等。`,defense4:`<strong>「無能或運氣不好」辯護:</strong><em>(「他們只是繪了一張草率的地圖,卻運氣不好碰上了這些數字。」)</em>恰好命中 60 席的超級多數,同時又把 Airdrie 切成四塊,並把三條邊界放在委員會自家主席標記為異常的精確區域,這需要外科手術般的精確。在四項獨立黨派指標上同時意外觸及極端統計尾部的聯合機率約為 <strong>1500 萬分之一</strong>(p&nbsp;=&nbsp;6.87×10<sup>−8</sup>)。你不可能跌跌撞撞地進入第 99.99 百分位。`,sub5_close:`資料所顯示的是,少數派提議在同樣五位委員依相同法定規則同時產出的成果中,使人口平等和社區一致性都變得更差。本次審計並未判定少數派委員意圖為何——邊界幾何無法揭示意圖——但相較於中立整體和多數派提議的輸出,結構性的偏離無論意圖如何均成立。`,sub6_h:`關於 R 交叉驗證的說明`,sub6_p1:`本次審計的早期版本(使用近似而非官方 shapefile)曾將 Python ReCom 整體與 R <code>redist</code> 套件的循序蒙地卡羅取樣器進行交叉驗證。該交叉檢查產生了不穩定的結果:在相同名義種子的三次執行中,達到舊少數派值(近似幾何上 48.3%)的方案比例分別為 5.6%、28%、58%——這是取樣器收斂失敗,而非發現。完整說明見 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>。`,sub6_p2:`使用 Elections Alberta 官方 shapefile 後,少數派地圖的 <code>seats@50/50</code> 升至 51.7%——在 1,010,000 張中立方案中達到此值的不到 100 張。R 交叉驗證問題因此變得無關緊要:在可比較的樣本量下,兩個取樣器的零份方案達到規範值。`,sub6_asymm:`<strong>50/50 附近的不對稱性比反轉本身更具說明性。</strong>對議席-得票曲線以 0.01 個百分點解析度進行的精度掃描發現,少數派地圖將 UCP 維持在 45 席立法多數門檻或以上,直至 UCP 省級得票份額降至約 <strong>49.7%</strong>。這在技術上是一個票-席反轉——UCP 將在丟掉普選票 0.3 個百分點的情況下憑少數派地圖組建政府——但 0.3 個百分點完全在普通民調誤差範圍內,所以單獨來看這不是戲劇性的發現。<em>真正</em>戲劇性的是對比:在<strong>多數派</strong>地圖上,UCP 需要以約 4 個百分點<em>贏得</em>普選票才能達到相同的 45 席門檻。兩張地圖面對相同的阿爾伯塔地理和相同的法定規則;它們之間的差距——0.3pp 對 +4pp——是結構性差異,而非噪音。`,sub6_close:`這就是本次審計有信心持有的結構性偏差發現。它只涉及幾何;不依賴任何選舉結果;不會隨民調而變動。`,sub6_caveat:`<strong>本次審計鄭重看待的一個保留意見。</strong>真實的選民並非統一的 50/50。選民可以以足夠的搖擺淹沒任何地圖的結構性傾斜——特別憤怒或受激勵的選民群體將不論邊界如何劃定都會翻轉結果。50/50 測試所孤立的是<em>地圖對結果的貢獻</em>,而非結果本身。它所顯示的是,當選民群體不為結果做決定時,地圖會做什麼。`,sub7_h:`結論`,sub7_p1:`本次審計的核心發現是幾何的。<strong>路徑 2——結構性違規計分表——是基礎;路徑 1 則是幾何在做黨派工作的證明。</strong>`,sub7_p2:`下面的圖表將兩條路徑放在一張圖上。橫軸是路徑 1(黨派公平性效率差距,越靠右意味著越有利於 UCP);縱軸是路徑 2(該提議在五項結構性公平測試中失敗的數量,越高意味著越多結構性問題)。`,stakes_fig_alt:`散點圖,橫軸為效率差距,縱軸為未通過的結構性測試數量。2019 年實施地圖和 2026 年多數派地圖聚集在安全的左下角。2026 年少數派地圖出現在右上方的離群區域。`,stakes_fig_caption:`兩種測量兩份委員會提議的方式合於一圖。左到右:該提議在黨派公平性數字上的偏斜程度——越靠右越有利於 UCP。下到上:該提議在五項結構性公平測試中失敗的數量——越高越糟。2019 年實施地圖位於安全角落:兩軸都低。2026 年多數派提議在結構性問題上停留在零、在黨派偏斜上接近零(+0.1%)。2026 年少數派提議在每一項區分兩張地圖的測試上都是結構性離群值(5 項中的 4 項;第 5 項——錨定——對兩者均為中性);其效率差距(+4.0%)恰好位於阿爾伯塔閾值線之下。`,stakes_table_intro:`同樣的發現以白話摘要形式呈現,首先列出結構性發現,因為交叉驗證的證據對其支持最強:`,t5_col_b:`路徑 2:結構(僅幾何,無選票)`,t5_col_c:`路徑 1:數字(依賴選票)`,t5_r1_a:`<strong>2026 多數派</strong>`,t5_r1_b:`乾淨——<em>未</em>越過任何結構性閾值`,t5_r1_c:`在每一項指標上都在正常範圍內(<code>seats@50/50</code> 46.1% — p83;效率差距 +0.04%)`,t5_r2_a:`<strong>2026 少數派</strong>`,t5_r2_b:`<strong>越過 5 項結構性閾值中的 4 項</strong>,且差距很大(錨定中性——兩張地圖都在加拿大常態範圍內)`,t5_r2_c:`在四項黨派公平性指標上同時為統計離群值——<code>seats@50/50</code> 51.7%(p99.99,1,010,000 張中不到 100 張達到);效率差距 +3.96%(p94.4);四項皆預先註冊;Fisher 合併 p&nbsp;=&nbsp;6.87×10<sup>−8</sup>`,details2_summary:`為什麼由路徑 2 承擔論證——技術細節`,details2_p:`本次審計於 2026 年 4 月 24 日在最終模擬結果彙整之前預先註冊了五項結構性違規測試。錨定對兩張地圖均為中性;在其餘四項測試上,少數派全部越過,而多數派全部未越過。這些測量是幾何的——它們不依賴任何統計取樣器或任何選票歸屬。路徑 1(黨派公平性數字)在規範官方 shapefile 下強烈印證路徑 2:少數派在所有四項預先註冊指標上同時為統計離群值,聯合中立虛無機率為 p&nbsp;=&nbsp;6.87×10<sup>−8</sup>(預先註冊的 Fisher 合併檢驗——一種將四項獨立檢驗結果以其各自尾部機率相乘以合併為單一機率的方法;合併數值遠小於任一單項檢驗,因為四項都指向相同方向;OSF <a href="https://osf.io/6pt83" rel="noopener">6pt83</a>)。路徑 2 異常幾何是否就是路徑 1 數字背後的特定<em>機制</em>已經過測試,答案為否——見 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>。搖擺區分配測試顯示有爭議的邊界選擇是黨派偏斜的,但所測試的問題是:邊界形狀本身——套索走廊、公園延伸——是否是議席轉移的直接原因;它們不是。議席效應來自重劃投票區歸屬如何在各選區間轉移投票效率,而非形狀本身。兩條路徑都標記了少數派地圖;它們透過獨立工具達到此結論。路徑 2 是核心發現。路徑 1 印證但不承擔。`},impact:{heading:`5:對代表權的影響`,lanes_label:`路徑 1 與路徑 2`,lanes_body:`<strong>路徑 1(數字)</strong>使用選舉結果來檢驗地圖是否公平地將選票轉換為議席——它詢問地圖在不同票分配下的表現。<strong>路徑 2(結構)</strong>只檢視已繪製的線條——城市切分、人口分布、邊界形狀——完全不使用任何選舉資料。兩條路徑相互獨立:一張地圖可以在其中一條失敗、另一條通過。少數派提議兩條都失敗;多數派提議兩條都通過。`,intro:`路徑 1 取決於你拿哪次選舉結果去評估這些地圖。路徑 2 則不取決於此。結構性證據在地圖本身——已繪製的線條、被切分的城市、邊界在哪些地方沿用或不沿用因其他原因而存在的行政界線。在這些測試上,兩份地圖差距並不接近。`,fig_alt:`長條圖並排比較五項結構性公平測試。多數派地圖的長條落在零或安全範圍深處。少數派地圖的長條在五項中的四項上以大幅差距越過閾值;第五項(錨定)對兩張地圖均為中性。`,fig_caption:`五項結構性公平測試並排。藍綠色長條為多數派地圖;紫色長條為少數派地圖。每列的虛線標記失敗閾值。少數派長條在五項中的四項上以大幅差距越過閾值;第五項(錨定)對兩張地圖均為中性。多數派長條平整地停在零或安全範圍深處。`,table_intro:`相同的五項測試以表格形式呈現,每項測試的閾值與結果並列。底部一列為本次審計的<em>摘要</em>——每張地圖在五項中失敗的數量。`,table_col_test:`測試`,table_col_majority:`多數派地圖`,table_col_minority:`少數派地圖`,table_col_direction:`方向 / 受益者`,table_r1_a:`邊界沿用既有市政線(加拿大常態 70–85%)`,table_r1_b:`80% — 在常態內`,table_r1_c:`72% — 在常態內`,table_r1_d:`不適用——兩者都在加拿大常態內`,table_r2_a:`人口分布(越緊密越好)`,table_r2_b:`3,180`,table_r2_c:`4,707 — 寬 48%`,table_r2_d:`結構性(降低選票平等)`,table_r3_a:`Calgary 西北人口超出平均`,table_r3_b:`2.8%`,table_r3_c:`11.5%`,table_r3_d:`<strong>UCP</strong>(集中都市 NDP 選票)`,table_r4_a:`委員會自家主席標記的邊界`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`不適用`,table_r5_a:`Airdrie 切分(約束最小值:2)`,table_r5_b:`2 塊`,table_r5_c:`4 塊`,table_r5_d:`<strong>UCP</strong>(分散都市/郊區力量)`,table_r6_a:`<strong>預先註冊摘要</strong>(&ge; 5 項中 4 項 = 離群值)`,table_r6_b:`<strong>5 項中觸發 0 項</strong>`,table_r6_c:`<strong>5 項中觸發 4 項</strong>(錨定測試中性——兩張地圖都在加拿大常態內;其餘 4 項全部觸發)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`一項僅針對少數派的獨立發現:<strong>少數派委員所發表的六項理由中有五項在獨立檢驗下未能成立</strong>。此測試僅針對少數派執行,因為多數派未發表有爭議重劃的理由清單——本次審計無法對稱應用,在此以單一標記而非結構性違規計數中的額外列來報告。(本次審計先前列出的第七項重劃被發現建立在少數派報告中無法溯源的聯邦邊界主張之上;它已被移除,而非保留為弱主張。)`,chair_appendix_p:`本次審計也測試了主席在附錄 C 中另一個全面性主張,即少數派的七種有爭議混合配置在 1,140+ 份公眾意見書中<strong>沒有公眾支持</strong>。對完整意見書檔案的關鍵字搜尋(94% 機器解析,6% 僅有圖像故予排除;方法論和逐項配置證據見 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>)返回的圖像比主席的全面主張或全面駁斥都更加細緻:主席在七項中的三項上是對的(Airdrie 四方切分、Calgary–Nolan-Hill–Cochrane 混合,以及 St. Albert 少數派替代方案均缺乏任何記錄在案的支持),在七項中的三項上是錯的(Rocky Mountain House–Banff Park 從至少一份 Clearwater 區意見書並數份相符意見書中得到明確、詳細的提議;Olds–Three-Hills–Didsbury 得到 Beiseker 居民書面支持;Chestermere 得到多份反對與 Calgary 合併、在實質上與少數派意圖相符的意見書),在一項上部分有誤(Red Deer 混合得到一位現任 Red Deer 議員提出的環 Red Deer 混合提議,方向一致但配置不完全對應)。因此,主席附錄 C「無公眾支持」的全面結論在七項中有三項明顯為偽——是可證偽地過於寬泛——但並非完全憑空捏造,因為七項中確有三項成立。<strong>此發現對主席不利,而非對少數派不利。</strong>`,summary_p:`<strong>在路徑 2 上,多數派越過零項結構性閾值。少數派則以大幅差距越過每一項。</strong>`},cpd:{heading:`4:分散、集中與抽乾`,vocab_label:`三招,一本劇本`,vocab_packing:`<strong>Packing(集中)</strong>意味著把某黨選民塞進該黨以壓倒性差距獲勝的選區——每一張被集中的選票仍會計入,但除了勝利之外毫無貢獻。大幅、不對稱的勝利。浪費掉的選票。`,vocab_cracking:`<strong>Cracking(分散)</strong>意味著把一個社區切分到多個選區,以致它一個也無法直接贏得。一個原本足以拿下兩席的城市被切成四塊,每一塊都拴在不同的鄉村地區。被稀釋的選票。誰也得不到席位。`,vocab_draining:`<strong>Draining(抽乾)</strong>是空間上的伴生物:被集中和被分散的選區彼此相鄰,以致一邊過度集中的支持者「抽乾」附近競爭選區的投票力量。鄰接模式放大兩種效應——集中與分散在選區之間相互強化。`,vocab_disclaimer:`三者都可能在沒有任何明確黨派意圖的情況下發生。本次審計衡量的是,該模式及其統計幅度是否與中立繪圖程序所產生的相符。<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">完整方法論見技術報告 §5。</a>`,fig_alt:`顯示少數派地圖下 Airdrie 被分割為四個獨立選區的地圖`,fig_caption:`在少數派地圖下,Airdrie 被分割為四個獨立選區,稀釋了其都市投票力量。`,intro:`五位委員從相同的法定規則、相同的省級地理、相同的 1,140 份公眾意見書檔案、相同的人口資料出發。他們相互競爭的兩份草案在阿爾伯塔大多數地方達成一致。在它們分歧之處,分歧出於房間裡某人必須做出的選擇。其中三項選擇值得被視為選擇,而非數字。`,airdrie_p:`<strong>它將 Airdrie 市切成四塊。</strong>法律規定每個選區人口上限為省級平均的 1.25 倍,因此 Airdrie 至少需要兩個選區。多數派地圖給了兩個。少數派給了四個——北至 Calgary-Nolan Hill-Cochrane,東至 Airdrie East,西至 Calgary-Foothills-Airdrie West,中南至 Calgary-Airdrie——每一個都釘在不同的鄉村或 Calgary 邊緣選區。一位 Airdrie 居民如果想找她的 MLA,得先知道自己住在城市的哪四分之一,才能撥打正確的辦公室。兩個街區外的鄰居會給她三個不同的答案。她孩子學校的家教會無法就學校資金問題向一位 MLA 派出單一代表團;他們必須協調四個代表團到四個辦公室,每位 MLA 主要對不同的鄉村或郊區選區負責。少棒協會、食物銀行、商會——所有跨整座城市運作的組織現在都跨四個省級 riding 運作。`,airdrie_callout_label:`為什麼 Airdrie 很重要`,airdrie_callout_p1:`Airdrie 是阿爾伯塔最大、沒有自己 MLA 的城市。人口 85,805(2024 市政普查)比 Red Deer 大;它有一個議會、一張稅單、一個學區——每個民政系統都把它當作一個整體。`,airdrie_callout_p2:`將它切分到四個省級選區——Calgary-Airdrie、Calgary-Foothills-Airdrie West、Calgary-Nolan Hill-Cochrane 和 Airdrie East——每一個都主要與不同的周邊行政區掛鉤,使得 Airdrie 在繪製地圖的那一級政府中,從政治地圖上消失。這個城市有 85,805 居民,卻在多數選民以此為家的立法機構中擁有零席位。`,airdrie_callout_p3:`四方切分對所有黨派公平性測試都是隱形的,除了一個:選民找得到自己的 MLA 嗎?`,airdrie_callout_summary:`兩張地圖都合法。四方切分是一個選擇。`,airdrie_btn:`在地圖上顯示標記的選區`,anchoring_p:`<strong>在它偏離市政線之處,它在策略性重要地點偏離。</strong>當選舉地圖沿用市鎮邊緣時,選民可以辨識出自己的選區從哪裡開始、哪裡結束——財產稅線、學區線、地方選舉行政區線和省級選舉線都重合。Statistics Canada 免費發布這些邊界。在 Elections Alberta 官方 shapefile 上,兩張地圖以可比的整體比例遵循市政線:多數派 80%,少數派 72%,兩者皆在加拿大 70–85% 的常態內(魁北克:78%,安大略:82%,卑詩省:71%;對照委員會的詳情見專著)。(本次審計最初的暫定分析顯示少數派錨定僅為 15%;此數值在以官方 shapefile 重新計算後未能存活——見下方修正說明。)真正令人矚目的觀察不是整體比例,而是少數派的偏離集中在何處:委員會自家主席標記為異常的三條邊界——Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">查看 ↗</button> 延伸進無人居住的國家公園土地、Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">查看 ↗</button> 套索走廊,以及 Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">查看 ↗</button> 延伸——每一項都是在配對都市與鄉村選民最直接影響哪個政黨贏得議席的都市邊緣地帶,對既有民政地理的偏離。`,anchoring_followup:`少數派委員對這三條標記邊界各自給出了理由。對 Rocky Mountain House–Banff Park,他們援引地理規模、22 號公路走廊,以及第一民族保留區與 Rocky Mountain House 的鄰近性;委員會主席稱這項延伸到無人居住的國家公園土地的做法為「不誠信的努力」以滿足面積條件,該措辭出現在委員會官方最終報告中。對 Nolan Hill–Cochrane,他們援引 Calgary 西北與 Cochrane 之間共享的交通和就業聯繫;Statistics Canada 通勤資料顯示只有 35.8% 的 Cochrane 員工會通勤至 Calgary,大多數在 Cochrane 本地工作。對 Olds–North Airdrie 延伸,他們援引 2 號公路走廊連續性;本次審計發現特定的 Airdrie 延伸在人口理由上不成立。獨立檢驗發現少數派六項已發表子理由中有五項對照原始資料失敗或僅部分成立。`,packing_p:`<strong>Calgary 的一個區域被切分以將 NDP 選民集中到大於平均的選區。</strong>在 Calgary 的西北象限 <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">查看 ↗</button>,少數派地圖的選區平均比省內人口高 11.5%——相較之下多數派為 2.8%。同樣的地理區域,由同一委員會在同樣約束下繪製,在一張地圖上選區比另一張大四分之一。這符合<em>集中</em>(packing)的結構性簽名:將某黨選民集中到較少、較大的選區,使其每張選票權重減少。Packing 與<em>cracking</em>(將某黨選民薄薄分散到他們以微弱差距落敗的選區)是兩種經典選區操控手法;兩者都使一個政黨的議席數低於其得票份額。`,chair_p:`委員會主席——依同一法律任命、從相同意見書工作——將少數派地圖上的三條邊界標記為地理異常:Rocky Mountain House–Banff Park 延伸到無人居住的國家公園土地;Calgary-Nolan Hill–Cochrane 套索狀走廊;Olds–Three Hills–Didsbury 延伸到北 Airdrie。多數派從同一主席處收到零項此類標記。(主席發表的批評共涵蓋七種邊界配置——主報告中四項幾何標記,附錄 C 中三項。本次審計獨立確認四項幾何標記中三項的異常幾何;第四項 Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">查看 ↗</button> 未達本次審計的確認閾值。)`},litmus:{heading:`3:1,010,000 張地圖試金石測試`,fig_alt:`顯示 250,000 張中立阿爾伯塔地圖效率差距分布的直方圖。大多數地圖聚集在零附近。少數派委員會地圖(紫線)位於第 94 百分位(+3.96%),在右側陰影尾部。多數派地圖(藍綠線)位於 +0.04%,在正常範圍內。`,fig_caption:`繪自同一地理的 250,000 張中立阿爾伯塔地圖中<button class="vocab-term" data-def="衡量選票轉換為議席的不對稱程度——正值偏向 UCP,負值偏向 NDP" aria-expanded="false">效率差距</button>的分布。大多數中立地圖聚集在零附近;右側陰影尾部標記前 10%。少數派提議的 +3.96% 位於第 94<button class="vocab-term" data-def="得分較低的地圖百分比——p94 意味著 100 張中立地圖中有 94 張比這張地圖的黨派性更低" aria-expanded="false">百分位</button>——一個 100 張中立地圖中不到 6 張曾達到的區域。多數派提議的 +0.04% 與中立程序通常產生的結果無法區分。`,table_intro:`此表比較兩張地圖。前五列不使用任何選舉結果——它們是線條本身的屬性。最後兩列取決於選票如何歸屬到每個選區。`,table_col_measured:`所測量的項目`,table_col_majority:`多數派地圖`,table_col_minority:`少數派地圖`,table_col_direction:`方向 / 受益者`,table_r1_a:`各選區間的人口分布(越緊密越好)`,table_r1_b:`3,180`,table_r1_c:`4,707 — 寬 48%`,table_r1_d:`結構性(降低選票平等)`,table_r2_a:`Calgary 西北人口超出平均`,table_r2_b:`2.8%`,table_r2_c:`11.5%`,table_r2_d:`<strong>UCP</strong>(集中都市 NDP 選票)`,table_r3_a:`Airdrie 切分`,table_r3_b:`2 個選區`,table_r3_c:`4 個選區`,table_r3_d:`<strong>UCP</strong>(分散都市/郊區力量)`,table_r4_a:`沿用既有市政線的邊界`,table_r4_b:`80% — 在常態內`,table_r4_c:`72% — 在常態內`,table_r4_d:`不適用——兩者皆在加拿大常態 (70–85%) 內`,table_r5_a:`委員會主席標記的邊界`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`不適用`,table_r6_a:`50/50 票下的議席(1,010,000 張地圖模擬中的百分位)`,table_r6_b:`46.1% — p83(正常範圍)`,table_r6_c:`51.7% — p99.99(1,010,000 張中不到 100 張達到此值)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`效率差距(1,010,000 張地圖模擬中的百分位)`,table_r7_b:`+0.04% — p15.5(正常範圍)`,table_r7_c:`+3.96% — p94.4`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`集中-分散鄰里模式`,table_r8_b:`6 個耦合鏈訊號`,table_r8_c:`2(預先註冊通過)`,table_r8_d:`中性——少數派透過混合化而非鄰接抽乾達成黨派效應(§5.3.5)`,vocab_label:`詞彙`,vocab_eg:`<strong>效率差距。</strong>一個衡量某黨選票如何不對稱地轉化為議席的單一數字。正數有利於 UCP;負數有利於 NDP。本次審計使用約 5% 作為阿爾伯塔的離群線——只有 5% 的 1,010,000 張阿爾伯塔專屬中立模擬地圖超過此值。此閾值並非借自美國或一般文獻;為其他司法區校準的閾值在此處將是錯的,因為阿爾伯塔的自然地理產生不同的中立範圍。`,vocab_mm:`<strong>均值-中位數差。</strong>某黨選區得票份額中位數與平均數之間的差距。當一個政黨贏得許多接近的選區時,中位數會高於平均數——這些選票被高效地分配。當一個政黨以大幅差距贏得許多選區時,平均數會高於中位數——選票被浪費。某一方向的大幅均值-中位數差距標記了一方選票在各選區間分布上的結構性低效。`,vocab_percentile:`<strong>百分位排名。</strong>在本次審計中,「百分位」是 1,010,000 張中立模擬地圖中的排名。「p94」意味著 94% 的中立地圖得分較低——真實地圖比 94% 的中立樣本更極端。「p99.99」意味著少於 10,000 張中立地圖中的 1 張達到該水平。`,vocab_anchoring:`<strong>錨定。</strong>一條選舉邊界中沿用既有行政線——市界、學區界、Statistics Canada 普查線——的比例。`,closing_p1:`底部幾列依賴於選舉結果。<em>seats@50/50</em> 測試將選民群體維持在完美對等(UCP 和 NDP 在省內各贏得恰好一半選票),並詢問該地圖授予 UCP 多少席。一張中立的阿爾伯塔地圖產生大約 44.8% UCP 議席的中位數。阿爾伯塔的地理——NDP 選民集中於城市核心、UCP 選民分散於鄉村 riding——在中立情況下給予 NDP 微小的效率優勢。多數派地圖以 46.1% 位於 1,010,000 張地圖模擬的第 83 百分位,深在正常範圍內。少數派地圖以 51.7% 位於第 99.99 百分位:1,010,000 張中立樣本中不到 100 張達到該值。<em>效率差距</em>數字衡量每黨選票如何不對稱地被轉化為議席。在 Elections Alberta 官方 shapefile 上,少數派的效率差距為 +3.96%,將其置於第 94.4 百分位——剛剛低於本次審計的第 95 百分位離群線。本頁頂部的開場問題闡述了後果。`,closing_p2:`最後一列是少數派地圖在鄰里抽乾測試上耦合鏈訊號少於多數派之處:2 對多數派的 6(以及 2019 年實施地圖的 5)。本次審計在測量前預先註冊了此測試,而少數派較低的計數是真正的預先註冊通過——少數派並未顯示經典的集中-抽乾鄰接模式。這是唯一在數字上少數派優於多數派的測試。學術報告 §5.3.5 解釋了原因:少數派透過混合化(將集中與分散在個別 ED 內部化的城市切分)達成其黨派效應,這對只測量被集中選區與被分散選區如何聚集的鄰接鏈測試是隱形的。`},commission_split:{heading:`2:委員會如何分裂`,intro:`阿爾伯塔的選舉邊界委員會於 2026 年 3 月 23 日完成其工作,卻無法達成一致。三位委員產出一張地圖;另外兩位產出不同的一張。委員會主席 Dallas K. Miller 法官與兩位由反對黨提名的委員撰寫了多數派報告;兩位由政府提名的委員——Julian Martin 博士和 John D. Evans——撰寫了少數派報告。分歧的核心在於如何在快速增長的都市邊緣社區劃定邊界。多數派給了 Airdrie 兩個選區;少數派給了四個。多數派將 Calgary 西北的選區劃近省級平均;少數派則將其劃高 11.5%。兩張地圖都遵守同一法規。兩者在《Electoral Boundaries Commission Act》下均屬合法。分歧在於哪種具體的地理配置最能服務所劃定的社區。阿爾伯塔的執政黨是聯合保守黨 (UCP);其主要反對黨是新民主黨 (NDP)。較小的政黨——阿爾伯塔黨、阿爾伯塔自由黨等——也爭奪議席,但其合計省級得票份額在近期選舉中已低到不會實質影響本次審計的黨派公平性計算,後者以 2023 年 UCP–NDP 之分為基礎。本次審計以相同方法、相同地應用,測量了兩張地圖。三項發現特別突出。`,finding1:`<strong>兩張地圖在六件無需查看任何選舉結果就能測量的事情上不同:</strong>人口在各選區間分布的均勻程度、選民是否被集中、城市被切分的嚴重程度、邊界是否沿用市界、選區的形狀,以及委員會主席 Miller 法官自己以書面形式(多數派報告 §5.8.2 和附錄 C)標記為異常的邊界數量。少數派地圖在每一項上都與多數派不同。`,finding2:`<strong>每一項所測量的差異都朝同一方向移動。</strong>在兩張地圖分歧之處——Calgary 西北、Airdrie、有清晰市界的都市區——少數派地圖所劃定的邊界使 NDP 選票分布更稀薄,並使 UCP 選票計入更高效。被少數派地圖重塑最多的社區,正是 NDP 最強的社區。本次審計無法判定意圖。它能測量效應。`,finding3:`<strong>目前推動少數派地圖的程序在加拿大沒有先例。</strong>沒有其他省份允許內閣在重劃週期中途將選區重劃交給一個由其自己政黨所控制的委員會。大多數省份要麼要求立法機構先辯論委員的地圖,要麼讓委員會的地圖自動生效,除非被否決。阿爾伯塔哪個都不做。4 月 16 日,政府將兩張委員會地圖都擱置,並將工作交給一個 MLA 委員會,其多數成員來自執政的聯合保守黨 (UCP);該委員會的完整組成和授權詳見 §7。阿爾伯塔的《Electoral Boundaries Commission Act》要求立法機構通過一部單獨的《Electoral Districts Act》才能賦予委員會報告法律效力——委員會報告本身不改變任何事。其他大多數省份使委員會的報告除非立法機構主動否決否則具法律效力;阿爾伯塔的預設與此相反,意味著執政黨控制是否有任何委員會地圖會成為法律。政府陳述的理由是為了實施委員會主席 Miller 法官的第 5 號建議。但 Miller 撰寫該建議的具體目的就是勸阻立法機構接受少數派地圖,而其多數派同僚也未予背書。第 5 號建議在地理上也很具體:Edmonton 以南額外增加一個鄉村席位,以及在 Clearwater County 和 Mountain View County 西部增加一個——兩者都遠離委員會實際分裂所在的快速增長的 Calgary 和 Edmonton 都市邊緣社區。它並非邀請重新設計這些有爭議的邊界。政府接受了議席數,卻將控制權交給一個其所控制的委員會,讓其決定恰好是委員會分歧之處的邊界線。`,closing:`<strong>該程序本身就是一項與地圖無關的發現。</strong>`},november:{heading:`7:Lunty 委員會`,context_label:`背景`,context_body:`——本節描述取代委員會的程序及其所適用的法律框架。它不屬於統計發現。發現在上述 §3–§6 中。`,intro:`兩張委員會地圖均未生效。2026 年 4 月 16 日,立法議會通過第 19 號議案,將兩者擱置並將選區重劃事宜交予一個五人 MLA 特別委員會——三 UCP、兩 NDP——由 Brandon Lunty(UCP,Leduc-Beaumont)主持。委員會本身不繪製地圖。它監督一個依政府第 37 號議案(2026 年 4 月 21 日通過)組建的獨立諮詢小組,負責提出 91 席邊界方案。第 37 號議案構想有五位小組成員——一位現任或退休法官擔任主席、兩位由省長提名、兩位由反對黨領袖提名——但阿爾伯塔代理首席法官拒絕提名一位法官擔任主席,小組現在以委員會所確認的四位被任命者運作:Monte Solberg 閣下和 Darwin Durnie(省長提名)以及 Gerard Kennedy 博士和 Brent Robinson(反對黨提名)。委員會必須在 2026 年 11 月 2 日前向立法機構提交其報告。與最初的委員會不同,委員會和小組均不被要求舉辦公聽會;小組依靠最初委員會所收集的意見書。當委員會的地圖發布時,本次審計將以相同方法論進行評估。`,h_anomalous:`為什麼此委員會異常`,anomalous_p1:`自 1960 年代以來,加拿大選區重劃實務已定於單一模式:一個獨立委員會,與政府指令隔絕,產出邊界建議;立法機構可加以辯論但不能輕易在未經正式立法投票下推翻。阿爾伯塔依《Electoral Boundaries Commission Act》之法定程序遵循此模板——但與大多數省份有一項結構性差異:阿爾伯塔的委員會報告沒有自動法律效力。依該法,必須由立法機構通過單獨的《Electoral Districts Act》才能賦予任何委員會地圖以法律效力。這意味著當時的政府不僅控制委員會地圖是否被辯論,還控制它是否能成為法律。其他加拿大司法區採取相反的預設:除非立法機構積極投票推翻,否則委員會的建議生效。`,anomalous_p2:`政府在 2026 年 4 月所做之事在聯邦成立後的選區重劃中沒有有記載的先例:它讓一個已完成、已發表的委員會程序終結——多數派和少數派報告均已歸檔——然後將選區重劃任務交付一個五人 MLA 委員會,其多數(五人中三人)由執政黨持有,且未將任一委員會報告付諸表決。Lunty 委員會不是委員會。它在法定上對政府的立法指令沒有獨立性。其三人 UCP 多數反映政府對立法機構的控制。沒有其他加拿大省份在獨立委員會完成工作後、週期中途將選區重劃權威轉移給一個由政府控制的立法委員會。`,h_framework:`憲法框架`,framework_p1:`《Charter of Rights and Freedoms》第 3 條——「加拿大每位公民都有權在下議院或立法議會議員的選舉中投票」——已被加拿大最高法院解讀為不僅保障投票行為,還保障<em>有效代表權</em>。主要判例是 <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158,McLachlin J.(時任)代表多數寫道,第 3 條的目的「不是投票權力本身的平等,而是有效代表的權利」。人口對等是首要考量;當有社區利益、地理、歷史或少數群體代表性目標的合理理由時,允許偏離。`,framework_p2:`薩斯喀徹溫框架並未絕對禁止在選區重劃中考量黨派因素。它所確立的是,邊界地圖整體必須為選民提供有效代表權——而對某可識別群體選出與比例相符的代表能力的系統性削弱,正是第 3 條挑戰所針對的模式。本次審計的統計和結構性發現——少數派地圖位於 1,010,000 次中立樣本的第 99.99 百分位、越過 5 項結構性閾值中的 4 項(第 5 項——錨定——對兩張地圖均為中性)、所辨識出的受影響社區——是第 3 條申請人所需整理的證據紀錄。在該紀錄的社區利益面上,聯邦法院在 <em>Raîche v. Canada</em>(2004 FC 679)中的判決是主要的加拿大判例:該案法院要求聯邦選舉邊界委員會重新審視忽略了 New Brunswick 阿卡迪亞社區利益的邊界。本次審計的市政錨定測量和具體社區發現——Airdrie 切分為四個選區、主席標記的 Calgary 西北都市邊緣異常——正是聯邦法院所視為在法律上可認知的證據類型。該紀錄是否達到憲法門檻,是本次審計不予裁定的法律問題;本次審計報告的是測量結果。`,framework_p3:`委員會作為程序的合法性是另一個問題。阿爾伯塔的《Electoral Boundaries Commission Act》並未明文禁止立法機構設立並行的選區重劃機構,因為該法構想立法機構無論如何都將透過普通立法制定最終邊界。委員會程序,若產出一份具有少數派提議結構性和統計性側寫的地圖,能否在第 3 條《憲章》挑戰下存活,取決於在所產生的邊界下是否可實現有效代表權——這與適用於任何委員會所產地圖的測試相同。`,h_quebec:`魁北克對比`,quebec_p1:`魁北克提供了與阿爾伯塔處境最相關的比較。魁北克的 Commission de la représentation électorale (CRE) 是一個常設、獨立的選舉邊界機構,而非依每個重劃週期設立的臨時委員會。CRE 持續運作,不能由內閣行動解散或繞過。在魁北克《Loi électorale》下,國民議會必須採納 CRE 的建議,除非投票偏離——而偏離需要議會全體成員的三分之二多數,而非簡單立法多數。實際效果是執政黨無法獨自憑己方多數以其偏好地圖取代委員會。憲法上要求跨黨派同意才能推翻獨立機構的判斷。`,quebec_p2:`魁北克的模式部分源於關於選區重劃未與黨派控制隔絕時會發生什麼的教訓。與阿爾伯塔當前程序的對比——立法機構尚未對任一委員會報告投票,一個由多數派控制的委員會就已取代委員會的工作——闡明了一個結構性差異:選區重劃系統假設黨派壓力並設計以對抗之,與系統中該壓力有更清晰路徑通向結果之間的差異。`,closing:`當 Lunty 委員會的地圖發布時,本次審計將對其應用相同的測試。上述憲法和比較觀察是脈絡性的;方法論不會改變。`},references:{heading:`10:參考文獻與方法論`,heading_aria:`連結至參考文獻`,intro:`底層方法論借鑒既有的政治學、統計學和法律文獻。完整引用遵循美國政治學會 (APSA) 格式;法院案件遵循加拿大法律慣例。完整參考文獻清單見<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">技術報告</a>。關鍵來源列於此處。`,h_academic:`學術文獻`,h_cases:`法院案件`,h_statutes:`法規`},resources:{heading:`11:技術附錄`,heading_aria:`連結至技術`,tag_plain:`白話版本`,plain_label:`完整公開報告`,plain_desc:`長篇,附地圖,供一般讀者閱讀`,tag_summary:`摘要`,summary_label:`發現摘要`,summary_desc:`白話概覽,從零開始解釋每個概念`,tag_academic:`學術`,academic_label:`技術報告`,academic_desc:`完整方法與引用,供研究人員參考`,tag_notebook:`Notebook`,notebook_label:`互動式 notebook`,notebook_desc:`在瀏覽器中自行執行圖表,無需安裝`,tag_code:`代碼`},about_me:{heading:`關於我`,p1:`我是 Mount Royal University 的學生。這項研究是我自己做的——並非作為課業指派,大學也未委託。我的觀點是我自己的,不代表大學。我與 Elections Alberta、委員會或任何政黨都沒有關聯。`,p2:`我在不同選舉中投過不同政黨的票,跨越政治光譜。我告訴你這些,是因為我的政治歷史可能影響我看待這個議題的方式。對此的主要防範是方法:我以相同方式測試兩張地圖,在查看結果前寫下我的預測,並將一切放上網以便任何人檢查我的工作。我自費進行這項研究。如果你發現我什麼地方搞錯了,我真心希望知道。`,p3:`預先註冊紀錄(在檢視結果之前撰寫):<a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>、AsPredicted:#289,469、AsPredicted:#289,451。`,p4:`問題或更正:<a href="mailto:wconn161@mtroyal.ca">wconn161@mtroyal.ca</a>`},retractions:{heading:`9:撤回與更正`,heading_aria:`連結至撤回`,conditions_label:`撤回條件`,conditions_intro:`每一項發現都預先承諾於特定的可證偽條件。如果下列任一條件實現,所指名的發現將於 30 天內公開撤回。整體方向性結論——少數派地圖在多項獨立測試上位於中立範圍之外——僅當五項測試中至少三項失敗時才會被撤回。`,c1_title:`條件 1——存在反例地圖`,c1_what:`<em>所撤回者:</em>關於 Airdrie 四方切分和三條主席標記邊界無法以少數派所述社區利益理由解釋的結構性發現。`,c1_cond:`條件:有人產出一張合法的阿爾伯塔地圖,滿足少數派自己所陳述的理由——Airdrie、Cochrane、Nolan Hill、Rocky Mountain House–Banff Park——並以與多數派可比的比例錨定於市政線。公開挑戰見 <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>。`,c2_title:`條件 2——鄰里抽乾預先註冊通過被推翻`,c2_what:`<em>所撤回者:</em>第 3 節表格中記錄少數派地圖在鄰里抽乾鄰接測試上預先註冊通過的條目。`,c2_cond:`條件:v2 連續抽乾分數在固定連通圖上的隨機置換中落於極端上尾 (p &lt; 0.05),意味著該通過是 v1 二元評分方法的測量假象,而非真正的零結果。`,c3_title:`條件 3——2026 年之前的委員會文件浮現`,c3_what:`<em>所撤回者:</em>少數派的邊界選擇是起草決定而非對記錄在案社區意見書的回應之推論。`,c3_cond:`條件:一份日期早於少數派最終邊界選擇的委員會內部文件顯示,這些選擇是由本次審計未見過的社區意見書明確驅動的——而非由本次審計所測試的六項已發表子理由驅動。`,c4_title:`條件 4——2027 年選舉結果與模擬相牴觸`,c4_what:`<em>所撤回者:</em>路徑 1 發現——少數派地圖的 seats@50/50 分數位於 1,010,000 次中立樣本的第 99.99 百分位。`,c4_cond:`條件:若 2027 年省級選舉以任一委員會地圖進行,且實際黨派議席分裂與 2023 年選票的方向性預測相牴觸,則路徑 1 百分位發現將對照實際結果重新審視。`,c5_title:`條件 5——阿爾伯塔法院將魁北克最高法院裁決區分開來`,c5_what:`<em>所撤回者:</em>第 7 節的程序性論點,即 4 月 16 日以 Lunty 委員會取代委員會的議案與魁北克 2024 年選區重劃凍結屬於同一憲法類別。`,c5_cond:`背景:2026 年 4 月 22 日——即阿爾伯塔 4 月 16 日議案後六天——加拿大最高法院以 7 比 2、當庭維持魁北克上訴法院的裁決,即 Legault 政府對其選區重劃委員會的立法凍結違反了《憲章》第 3 條的民主代表保障。條件:審查阿爾伯塔議案的法院發現它在憲法上有別——例如,因為將工作重新指派給 MLA 委員會在結構上不同於立法凍結,或因為阿爾伯塔的有效代表權分析在第 3 條下的結果與魁北克不同。`,corr_label:`已記錄的更正(規範重新計算,2026-05-11)`,corr_intro:`下述早期發現未在對照 Elections Alberta 官方 shapefile(2026-05-06 收到)的重新分析中存活。依本次審計從不刪除失敗發現的預先承諾政策,在此保留。`,corr_municipal:`<strong>市政錨定(已撤回)。</strong>使用暫定地圖邊界的早期分析顯示少數派地圖僅 15% 的時間錨定於市政線——比 70–85% 的加拿大常態低 4.9&times;。此數字是暫定(DPG 時期)邊界重建的假象。在 Elections Alberta 官方規範 shapefile 上,兩張地圖都在加拿大常態內錨定:多數派 80%,少數派 72%。兩張地圖之間的市政錨定<em>分歧</em>並非在規範重新計算中存活的訊號。委員會主席標記的三處邊界異常(Rocky Mountain House–Banff Park、Nolan Hill–Cochrane、Olds–North Airdrie)仍然存在,且不受此更正影響。`},suggestions:{heading:`8:建議`,heading_aria:`連結至第 8 節`,intro:`本次審計遇到了兩個與委員會工作無關、與阿爾伯塔選舉系統設計有關的資料問題。兩者都可以修復。`,advance_p1:`<strong>目前阿爾伯塔約半數的選票都在選舉日之前投出</strong>——預先投票、流動投票、特別投票。Elections Alberta 將這些結果以選區為單位匯總,而非按特定投票區。這意味著 2023 年投出的約 395,000 張 NDP 和 UCP 選票無法在地圖上釘到任何鄰里。它們被計算了;只是無法被定位。每位預先投票者在領取選票前都會對選民名冊進行核對,而名冊將每位選民連結至其特定投票區。發布投票區層級的預先投票總數無需改變投票流程——只需改變 EA 所報告的內容。`,advance_p2:`這不僅影響外部分析師,也影響委員。當一個委員會決定是否保持 Airdrie 完整或將其切分、兩個社區之間的走廊是否合理、提議的邊界是否分割了一個自然選區時——這些都是依賴於知道選民住在哪裡的判斷。委員從與其他人相同的已發布資料集工作。關於他們所劃邊界周邊社區的地理訊號,有一半對他們而言也是缺失的。`,lesser_slave_p1:`阿爾伯塔北部至少有一個社區,這項缺口完全存在。在 Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">查看 ↗</button> 選區的北部,有一個覆蓋 4,832 平方公里的投票區——比愛德華王子島還大——其中 2023 年的每一張選票都透過 Elections Alberta 的流動投票團隊投出。這 844 位居民的選擇被計入選區總數,但無法在地圖上釘至任何位置。這個社區在已發布的選舉結果中完全隱形。`,lesser_slave_p2:`當委員會最初考慮取消 Lesser Slave Lake 選區並將其併入更大的 riding 時,它在沒有來自這些社區地理投票資料的情況下工作。委員會最終保留了該選區——在 80 份以上公眾意見書、其中許多來自該 riding 北部的原住民社區之後——援引一條允許含有第一民族和梅蒂斯社區的 riding 擁有低於省級平均人口的省級法律。他們達到了目的。但他們所工作的資料並未顯示哪些人在他們決定保護的社區中投票。`,ebca_label:`EBCA §15(2)`,ebca_body:`阿爾伯塔《Electoral Boundaries Commission Act》第 15(2) 條是一項裁量性規定,允許委員會在某個 riding 符合五項特定標準中至少三項時保護人口低於省級平均 25% 以上的 riding:(a) 地理面積超過 20,000 平方公里、(b) 距立法大樓直行公路距離超過 150 公里、(c) 不存在任何居民超過 8,000 人的城鎮、(d) 存在印第安保留區或梅蒂斯定居點,以及 (e) 該 riding 是否與阿爾伯塔省界重合。該條並非自動適用;委員會必須判斷標準是否符合。Lesser Slave Lake 獨立地符合五項中的四項。`,rationale_p1:`取消該 riding 的暫定理由是人口:Lesser Slave Lake 擁有約 27,000 居民,比省級平均低約 45%,接近法律下限。這讀起來像規則的直截了當應用。實際並非如此。阿爾伯塔法律明確賦予委員會裁量權,當至少符合五項特定標準中的三項時保護人口不足的 riding,而 Lesser Slave Lake 獨立地符合其中的四項。其面積為 69,566 平方公里(條件 a,門檻 20,000 平方公里)。其最近邊界距立法大樓直行公路超過 150 公里(條件 b)。該 riding 內沒有任何城鎮人口超過 8,000(條件 c)。且該 riding 包含十四個印第安保留區和梅蒂斯定居點,其社區共享共同的北部地理、共同對流動投票才能投票的依賴,以及對主要對北阿爾伯塔負責的代表的集體利益(條件 d)。`,rationale_p2:`在所提議的 Mackenzie 合併下,集體聲音將被永久吸收進一個對方政黨以二比一以上差距獲勝的 riding 中,並非因為這些社區改變了,而是因為其周邊的線條改變了。這四項條件中的每一項都是關於該 riding 地理的客觀事實,不是判斷性的呼喚。它們共同描述了該條款所要保護的選區:偏遠、廣大、人口稀少,且包含其代表利益無法從原始人口數字中讀出的社區。需要三項才能符合;Lesser Slave Lake 有四項。把人口短缺視為足以強制取消,是錯讀了法規。委員會的反轉是對法律的正確應用,而非對政治壓力的讓步。`,banff_p:`故事的另一面是:當 Lesser Slave Lake 的原住民社區在為被計入而奮鬥時,反對的委員提議以將其邊界延伸過 Banff 國家公園無人居住之處的方式來保護另一個 riding。委員會自家主席稱其為「不誠信的努力」以主張該法律保護。該措辭出現在委員會官方最終報告中。為含有原住民群體的偏遠社區所設計的保護,在少數派地圖上被用來捍衛一條穿過無人居住荒野的邊界。它原本被設計來幫助的社區則不得不透過公眾意見書為它而戰。Lunty 委員會將在 11 月面對相同的 §&#x2009;15(2) 決定——沒有舉辦公聽會的法定要求,也無法保證推翻委員會暫定立場的 80 份意見書會在第二次承載相同的份量。`,census_p1:`<strong>阿爾伯塔應該在繪製下一張地圖前等待 2026 年人口普查。</strong>加拿大每十年計算其人口。2026 年人口普查於 2026 年春季進行;Statistics Canada 大約兩年後,於 2027 或 2028 年,發布可用的省以下資料。本次審計所評估地圖的繪製委員會不得不使用 2021 年人口普查——地圖繪製時已四年舊,在這些邊界退役時可能已十四年舊。Airdrie 和 Chestermere 等快速增長城市在該窗口期內將變化 40% 或更多。鄉村社區將縮小。地圖從使用之日起就會是錯的。對《Electoral Boundaries Commission Act》的一項直接修改可以要求任何新委員會僅在 Statistics Canada 發布前次人口普查中最新的散布區資料之後才能任命。結果:反映阿爾伯塔人實際居住地的地圖,而非他們十年前居住地的地圖。`,census_p2:`Lunty 委員會在現行法規下運作,該法規未設定任何人口普查時間要求,且無法單方面延遲其 2026 年 11 月期限。本建議適用於對《Electoral Boundaries Commission Act》未來的修訂,而非當前程序。此張力是真實的:一個必須在 11 月前交付地圖的委員會所工作的資料屆時已五年舊——指明約束比假裝它不存在更有用。`,closing:`這兩項都不是關於當前委員會地圖的發現。它們是對一個使精準選舉分析比所需要的更困難的系統的觀察。它們在此作為實用建議,而非結論。兩者都真正可以修復,修復它們將使每個未來委員會——以及每次未來審計——從更好的基礎開始工作。`}},editorial_canada:{heading:`背景:加拿大不同——也相似`,p1:`加拿大與美國、英國、澳洲屬於同一家族。我們在簡單多數決下從地理區域選出單一成員。我們定期重劃線條——聯邦層級在每十年的人口普查之後,省級層級則依錯開的時程。我們從相同的西敏寺根源繼承了基本機制。目前為止,沒有意外。`,p2:`使加拿大與眾不同的是這些線條必須通過的測試。`,p3:`在美國憲法中,具約束力的規則是<em>一人一票</em>——選區人口必須盡可能相等,大幅偏離需要嚴格的理由。在加拿大憲法中,具約束力的規則不同。《Canadian Charter of Rights and Freedoms》第 3 條保障每位公民投票的權利。在 <em>Reference re Provincial Electoral Boundaries (Sask.)</em>——1991 年薩斯喀徹溫判例,主要的判例——中,加拿大最高法院將該權利解讀為<em>有效代表權</em>,而非選區人口數學平等的權利。`,p4:`此區別很重要。有效代表權允許選區人口在有合理理由時變動,有時相當大幅:一位 MLA 在標準人口密度下無法合理服務的廣大鄉村地理、應保持在一起的利益共同體、數學平等將稀釋的少數群體代表性。薩斯喀徹溫判例使這種彈性合憲。EBCA 的 25% 人口變異——保護阿爾伯塔鄉村席位的規則——直接源自於此。`,p5:`關鍵在於這種彈性是雙刃劍。如果一個委員會可以為了正確的理由合法地偏離人口平等,它也可以為了錯誤的理由偏離人口平等。加拿大法律沒有美式的數學底線可資依靠。它只有有效代表權測試,由法官在事後訴訟中應用。大多數司法區以結構性保護來防範錯誤的理由:聯邦選區重劃委員會依法律隔絕,如果國會在期限內未對其建議採取行動,其建議自動生效。魁北克使用一個常設獨立委員會,國民議會只能以三分之二超級多數加以推翻。卑詩省也在類似的預設採納規則下運作。`,p6:`阿爾伯塔是例外。依《Electoral Boundaries Commission Act》,委員會的報告只是一項建議——立法機構必須投票通過才能實施。批准通常是形式上的。在 2026 年週期中,委員會以 3 比 2 分裂並提出兩份相互競爭的提議;立法機構成立了一個獨立的 MLA 委員會,由省長任命的 MLA 主持,以在兩者之間做出選擇。加拿大憲法中沒有任何條文要求該委員會存在。沒有任何條文要求其選擇遵循委員會的程序。這就是本次審計所檢視的結構性缺口。`,p7:`所以當加拿大法院說「gerrymander」不是它們的法律詞彙時,它們並不是說底層概念在這裡不適用。它們是說測試不同——有效代表權,而非數學平等。少數派提議是否符合該測試,正是本次審計用幾何衡量的問題,也正是只有法官才能確定回答的問題。完整的<em>薩斯喀徹溫判例</em>推理、與其他省份的對比、訴訟資格問題,以及可行的改革路徑,在<a href="#references">下方參考文獻部分</a>中處理。`},chrome:{back_to_top:`回到頂部`,license_title:`Creative Commons 署名-非商業性-相同方式分享 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ 回到結論`,lightbox:{fig_aria:`圖片放大檢視`,fig_close_aria:`關閉放大圖片 (Esc)`,map_aria:`地圖縮放檢視器`,map_close_aria:`關閉地圖檢視器`,close_title:`關閉 (Esc)`},participation:{heading:`幫助我們改善 MapExplorer`,body:`在你探索時,我們會追蹤你造訪了哪些地圖和選區,並定期將資料傳送至我們的研究資料庫。分享一個檢視也會儲存你停留的位置。目的是了解什麼是有用的,並使工具變得更好。`,no_collect:`我們從不收集你的姓名、IP 位址或精確位置。一切都在離開你的瀏覽器之前被匿名化。即使被命令也無法從資料識別出你。`,dnt:`你的瀏覽器啟用了 Do Not Track。已代你預先選擇「否」。你仍可以選擇「是」。`,no_thanks:`不,謝謝`,yes_help:`是的,我願意幫忙`,privacy_policy:`隱私政策`},share:{button:`分享`,button_title:`分享或載入地圖配置`,dialog_aria:`分享地圖配置`,close_aria:`關閉分享面板`,share_label:`分享此配置`,share_hint:`將此代碼鍵入任何執行本審計的瀏覽器以載入此配置。代碼絕不會放入網址中。`,load_label:`載入配置`,load_btn:`載入`,load_placeholder:`alpine-eagle-banff`,copy:`複製`,copied:`已複製!`,copy_failed:`失敗`,unrecognised:`無法識別的代碼——請檢查拼寫。`},map:{minority:`少數派`,majority:`多數派`,current:`現行`,wasted:`浪費`,wasted_title:`每個選區的效率差距貢獻`,partisan:`黨派`,partisan_title:`按黨派結果為每個選區上色(UCP 藍 / NDP 橙)`,borders:`邊界`,flagged:`標記`,flagged_title:`委員會主席 Miller 法官標記的全部 7 種配置——自動切換至少數派地圖`,help_aria:`地圖說明`,help_title:`如何使用地圖`,pin_aria:`固定地圖`,pin_title:`固定地圖——防止點擊選區時自動平移`,search_placeholder:`尋找選區…`,zoom_aria:`地圖縮放`,clear_aria:`清除選區選擇`,clear_title:`清除選擇`,va_hint:`點擊此選區內部以查看投票站結果`,va_close_aria:`關閉投票站詳情`,va_close_title:`關閉`,object_title:`阿爾伯塔選區地圖——全解析度`,ea_credit:`地圖資料:`,cc_title:`文字內容:CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`},map_intro:{heading:`如何使用地圖`,click_district:`點擊任一選區`,click_district_desc:`查看 2023 年選舉結果並縮放至該選區`,click_within:`在已選定的選區內點擊`,click_within_desc:`查看個別投票站結果(顏色 = 票數分布)`,dblclick:`雙擊一個選區`,dblclick_desc:`縮放至填滿螢幕;雙擊空白處以縮小`,layers_primary:`少數派 / 多數派 / 現行`,layers_primary_desc:`切換活動邊界地圖`,layers_data:`黨派 / 浪費 / 邊界`,layers_data_desc:`切換資料圖層`,search:`尋找選區`,search_desc:`按名稱跳轉;方向鍵平移、+ / − 縮放`,escape:`Escape`,escape_desc:`關閉此檢視器`,s4_tip:`在 §4 中,點擊<em>在地圖上顯示標記的選區</em>以高亮 Airdrie 切分和 Calgary 西北區域。`,got_it:`明白了`},footer:{title:`阿爾伯塔選舉邊界審計——2026 年 5 月`,copyright:`© Will Conner 2026 —`,text_label:`文字:`,code_label:`代碼:`}}}};function h(e,t){let n=e;for(let e of t.split(`.`))if(n&&typeof n==`object`&&e in n)n=n[e];else return;return n}function g(e,t){let n=h(m[e],t);if(typeof n==`string`)return n;let r=h(m.en,t);return typeof r==`string`?r:`[missing:${t}]`}export{f as a,r as i,p as n,d as o,i as r,g as t};